window.AUDIO_INDEX = {"L1-nj-0": [{"f": "audio/63/L1-nj-0__0.mp3", "t": "上古之人，"}, {"f": "audio/63/L1-nj-0__1.mp3", "t": "其知道者，"}, {"f": "audio/63/L1-nj-0__2.mp3", "t": "法于阴阳，"}, {"f": "audio/63/L1-nj-0__3.mp3", "t": "和于术数，"}, {"f": "audio/63/L1-nj-0__4.mp3", "t": "食饮有节，"}, {"f": "audio/63/L1-nj-0__5.mp3", "t": "起居有常，"}, {"f": "audio/63/L1-nj-0__6.mp3", "t": "不妄作劳，"}, {"f": "audio/63/L1-nj-0__7.mp3", "t": "故能形与神俱，"}, {"f": "audio/63/L1-nj-0__8.mp3", "t": "而尽终其天年，"}, {"f": "audio/63/L1-nj-0__9.mp3", "t": "度百岁乃去。"}], "L1-nj-1": [{"f": "audio/27/L1-nj-1__0.mp3", "t": "虚邪贼风，"}, {"f": "audio/27/L1-nj-1__1.mp3", "t": "避之有时，"}, {"f": "audio/27/L1-nj-1__2.mp3", "t": "恬淡虚无，"}, {"f": "audio/27/L1-nj-1__3.mp3", "t": "真气从之，"}, {"f": "audio/27/L1-nj-1__4.mp3", "t": "精神内守，"}, {"f": "audio/27/L1-nj-1__5.mp3", "t": "病安从来。"}], "L1-nj-2": [{"f": "audio/e0/L1-nj-2__0.mp3", "t": "女子七岁肾气盛，"}, {"f": "audio/e0/L1-nj-2__1.mp3", "t": "齿更发长。"}, {"f": "audio/e0/L1-nj-2__2.mp3", "t": "二七而天癸至，"}, {"f": "audio/e0/L1-nj-2__3.mp3", "t": "任脉通，"}, {"f": "audio/e0/L1-nj-2__4.mp3", "t": "太冲脉盛，"}, {"f": "audio/e0/L1-nj-2__5.mp3", "t": "月事以时下，"}, {"f": "audio/e0/L1-nj-2__6.mp3", "t": "故有子。"}, {"f": "audio/e0/L1-nj-2__7.mp3", "t": "三七肾气平均，"}, {"f": "audio/e0/L1-nj-2__8.mp3", "t": "故真牙生而长极。"}, {"f": "audio/e0/L1-nj-2__9.mp3", "t": "四七筋骨坚，"}, {"f": "audio/e0/L1-nj-2__10.mp3", "t": "发长极，"}, {"f": "audio/e0/L1-nj-2__11.mp3", "t": "身体盛壮。"}, {"f": "audio/e0/L1-nj-2__12.mp3", "t": "五七阳明脉衰，"}, {"f": "audio/e0/L1-nj-2__13.mp3", "t": "面始焦，"}, {"f": "audio/e0/L1-nj-2__14.mp3", "t": "发始堕。"}, {"f": "audio/e0/L1-nj-2__15.mp3", "t": "六七三阳脉衰于上，"}, {"f": "audio/e0/L1-nj-2__16.mp3", "t": "面皆焦，"}, {"f": "audio/e0/L1-nj-2__17.mp3", "t": "发始白。"}, {"f": "audio/e0/L1-nj-2__18.mp3", "t": "七七任脉虚，"}, {"f": "audio/e0/L1-nj-2__19.mp3", "t": "太冲脉衰少，"}, {"f": "audio/e0/L1-nj-2__20.mp3", "t": "天癸竭，"}, {"f": "audio/e0/L1-nj-2__21.mp3", "t": "地道不通，"}, {"f": "audio/e0/L1-nj-2__22.mp3", "t": "故形坏而无子也。"}, {"f": "audio/e0/L1-nj-2__23.mp3", "t": "丈夫八岁肾气实，"}, {"f": "audio/e0/L1-nj-2__24.mp3", "t": "发长齿更。"}, {"f": "audio/e0/L1-nj-2__25.mp3", "t": "二八肾气盛，"}, {"f": "audio/e0/L1-nj-2__26.mp3", "t": "天癸至，"}, {"f": "audio/e0/L1-nj-2__27.mp3", "t": "精气溢泻，"}, {"f": "audio/e0/L1-nj-2__28.mp3", "t": "阴阳和，"}, {"f": "audio/e0/L1-nj-2__29.mp3", "t": "故能有子。"}, {"f": "audio/e0/L1-nj-2__30.mp3", "t": "三八肾气平均，"}, {"f": "audio/e0/L1-nj-2__31.mp3", "t": "筋骨劲强，"}, {"f": "audio/e0/L1-nj-2__32.mp3", "t": "故真牙生而长极。"}, {"f": "audio/e0/L1-nj-2__33.mp3", "t": "四八筋骨隆盛，"}, {"f": "audio/e0/L1-nj-2__34.mp3", "t": "肌肉满壮。"}, {"f": "audio/e0/L1-nj-2__35.mp3", "t": "五八肾气衰，"}, {"f": "audio/e0/L1-nj-2__36.mp3", "t": "发堕齿槁。"}, {"f": "audio/e0/L1-nj-2__37.mp3", "t": "六八阳气衰竭于上，"}, {"f": "audio/e0/L1-nj-2__38.mp3", "t": "面焦，"}, {"f": "audio/e0/L1-nj-2__39.mp3", "t": "发鬓颁白。"}, {"f": "audio/e0/L1-nj-2__40.mp3", "t": "七八肝气衰，"}, {"f": "audio/e0/L1-nj-2__41.mp3", "t": "筋不能动，"}, {"f": "audio/e0/L1-nj-2__42.mp3", "t": "天癸竭，"}, {"f": "audio/e0/L1-nj-2__43.mp3", "t": "精少，"}, {"f": "audio/e0/L1-nj-2__44.mp3", "t": "肾脏衰，"}, {"f": "audio/e0/L1-nj-2__45.mp3", "t": "形体皆极。"}, {"f": "audio/e0/L1-nj-2__46.mp3", "t": "八八则齿发去。"}, {"f": "audio/e0/L1-nj-2__47.mp3", "t": "肾者主水，"}, {"f": "audio/e0/L1-nj-2__48.mp3", "t": "受五脏六腑之精而藏之，"}, {"f": "audio/e0/L1-nj-2__49.mp3", "t": "故五脏盛，"}, {"f": "audio/e0/L1-nj-2__50.mp3", "t": "乃能泻。"}, {"f": "audio/e0/L1-nj-2__51.mp3", "t": "今五脏皆衰，"}, {"f": "audio/e0/L1-nj-2__52.mp3", "t": "筋骨解堕，"}, {"f": "audio/e0/L1-nj-2__53.mp3", "t": "天癸尽矣，"}, {"f": "audio/e0/L1-nj-2__54.mp3", "t": "故发鬓白，"}, {"f": "audio/e0/L1-nj-2__55.mp3", "t": "身体重，"}, {"f": "audio/e0/L1-nj-2__56.mp3", "t": "行步不正，"}, {"f": "audio/e0/L1-nj-2__57.mp3", "t": "而无子耳。"}], "L1-nj-3": [{"f": "audio/cd/L1-nj-3__0.mp3", "t": "夫四时阴阳者，"}, {"f": "audio/cd/L1-nj-3__1.mp3", "t": "万物之根本也。"}, {"f": "audio/cd/L1-nj-3__2.mp3", "t": "所以圣人春夏养阳，"}, {"f": "audio/cd/L1-nj-3__3.mp3", "t": "秋冬养阴，"}, {"f": "audio/cd/L1-nj-3__4.mp3", "t": "以从其根。"}], "L1-nj-4": [{"f": "audio/f0/L1-nj-4__0.mp3", "t": "是故圣人不治已病治未病，"}, {"f": "audio/f0/L1-nj-4__1.mp3", "t": "不治已乱治未乱，"}, {"f": "audio/f0/L1-nj-4__2.mp3", "t": "此之谓也。"}, {"f": "audio/f0/L1-nj-4__3.mp3", "t": "夫病已成而后药之，"}, {"f": "audio/f0/L1-nj-4__4.mp3", "t": "乱已成而后治之，"}, {"f": "audio/f0/L1-nj-4__5.mp3", "t": "譬犹渴而穿井，"}, {"f": "audio/f0/L1-nj-4__6.mp3", "t": "斗而铸锥，"}, {"f": "audio/f0/L1-nj-4__7.mp3", "t": "不亦晚乎？"}], "L1-nj-5": [{"f": "audio/4d/L1-nj-5__0.mp3", "t": "阳气者，"}, {"f": "audio/4d/L1-nj-5__1.mp3", "t": "若天与日，"}, {"f": "audio/4d/L1-nj-5__2.mp3", "t": "失其所则折寿而不彰，"}, {"f": "audio/4d/L1-nj-5__3.mp3", "t": "故天运当以日光明。"}], "L1-nj-6": [{"f": "audio/3f/L1-nj-6__0.mp3", "t": "因于露风，"}, {"f": "audio/3f/L1-nj-6__1.mp3", "t": "乃生寒热。"}, {"f": "audio/3f/L1-nj-6__2.mp3", "t": "是以春伤于风，"}, {"f": "audio/3f/L1-nj-6__3.mp3", "t": "邪气留连，"}, {"f": "audio/3f/L1-nj-6__4.mp3", "t": "乃为洞泄；"}, {"f": "audio/3f/L1-nj-6__5.mp3", "t": "夏伤于暑，"}, {"f": "audio/3f/L1-nj-6__6.mp3", "t": "秋为痎疟；"}, {"f": "audio/3f/L1-nj-6__7.mp3", "t": "秋伤于湿，"}, {"f": "audio/3f/L1-nj-6__8.mp3", "t": "冬逆而咳，"}, {"f": "audio/3f/L1-nj-6__9.mp3", "t": "发为痿厥；"}, {"f": "audio/3f/L1-nj-6__10.mp3", "t": "冬伤于寒，"}, {"f": "audio/3f/L1-nj-6__11.mp3", "t": "春必温病。"}], "L1-nj-7": [{"f": "audio/d5/L1-nj-7__0.mp3", "t": "阳气者，"}, {"f": "audio/d5/L1-nj-7__1.mp3", "t": "烦劳则张，"}, {"f": "audio/d5/L1-nj-7__2.mp3", "t": "精绝，"}, {"f": "audio/d5/L1-nj-7__3.mp3", "t": "辟积于夏，"}, {"f": "audio/d5/L1-nj-7__4.mp3", "t": "使人煎厥；"}, {"f": "audio/d5/L1-nj-7__5.mp3", "t": "目盲不可以视，"}, {"f": "audio/d5/L1-nj-7__6.mp3", "t": "耳闭不可以听，"}, {"f": "audio/d5/L1-nj-7__7.mp3", "t": "溃溃乎若坏都，"}, {"f": "audio/d5/L1-nj-7__8.mp3", "t": "汩汩乎不可止。"}], "L1-nj-8": [{"f": "audio/70/L1-nj-8__0.mp3", "t": "阳气者，"}, {"f": "audio/70/L1-nj-8__1.mp3", "t": "精则养神，"}, {"f": "audio/70/L1-nj-8__2.mp3", "t": "柔则养筋。"}], "L1-nj-9": [{"f": "audio/16/L1-nj-9__0.mp3", "t": "故病久则传化，"}, {"f": "audio/16/L1-nj-9__1.mp3", "t": "上下不并，"}, {"f": "audio/16/L1-nj-9__2.mp3", "t": "良医弗为。"}], "L1-nj-10": [{"f": "audio/84/L1-nj-10__0.mp3", "t": "故阳气者，"}, {"f": "audio/84/L1-nj-10__1.mp3", "t": "一日而主外，"}, {"f": "audio/84/L1-nj-10__2.mp3", "t": "平旦人气生，"}, {"f": "audio/84/L1-nj-10__3.mp3", "t": "日中而阳气隆，"}, {"f": "audio/84/L1-nj-10__4.mp3", "t": "日西而阳气已虚，"}, {"f": "audio/84/L1-nj-10__5.mp3", "t": "气门乃闭。"}, {"f": "audio/84/L1-nj-10__6.mp3", "t": "是故暮而收拒，"}, {"f": "audio/84/L1-nj-10__7.mp3", "t": "无扰筋骨，"}, {"f": "audio/84/L1-nj-10__8.mp3", "t": "无见雾露，"}, {"f": "audio/84/L1-nj-10__9.mp3", "t": "反此三时，"}, {"f": "audio/84/L1-nj-10__10.mp3", "t": "形乃困薄。"}], "L1-nj-11": [{"f": "audio/dc/L1-nj-11__0.mp3", "t": "阴者，"}, {"f": "audio/dc/L1-nj-11__1.mp3", "t": "藏精而起亟也；"}, {"f": "audio/dc/L1-nj-11__2.mp3", "t": "阳者，"}, {"f": "audio/dc/L1-nj-11__3.mp3", "t": "卫外而为固也。"}], "L1-nj-12": [{"f": "audio/52/L1-nj-12__0.mp3", "t": "凡阴阳之要，"}, {"f": "audio/52/L1-nj-12__1.mp3", "t": "阳密乃固。"}, {"f": "audio/52/L1-nj-12__2.mp3", "t": "两者不和，"}, {"f": "audio/52/L1-nj-12__3.mp3", "t": "若春无秋，"}, {"f": "audio/52/L1-nj-12__4.mp3", "t": "若冬无夏。"}, {"f": "audio/52/L1-nj-12__5.mp3", "t": "因而和之，"}, {"f": "audio/52/L1-nj-12__6.mp3", "t": "是谓圣度。"}], "L1-nj-13": [{"f": "audio/55/L1-nj-13__0.mp3", "t": "阴之所生，"}, {"f": "audio/55/L1-nj-13__1.mp3", "t": "本在五味；"}, {"f": "audio/55/L1-nj-13__2.mp3", "t": "阴之五宫，"}, {"f": "audio/55/L1-nj-13__3.mp3", "t": "伤在五味。"}], "L1-nj-14": [{"f": "audio/22/L1-nj-14__0.mp3", "t": "是故谨和五味，"}, {"f": "audio/22/L1-nj-14__1.mp3", "t": "骨正筋柔，"}, {"f": "audio/22/L1-nj-14__2.mp3", "t": "气血以流，"}, {"f": "audio/22/L1-nj-14__3.mp3", "t": "腠理以密，"}, {"f": "audio/22/L1-nj-14__4.mp3", "t": "如是则骨气以精，"}, {"f": "audio/22/L1-nj-14__5.mp3", "t": "谨道如法，"}, {"f": "audio/22/L1-nj-14__6.mp3", "t": "长有天命。"}], "L1-nj-15": [{"f": "audio/21/L1-nj-15__0.mp3", "t": "夫精者，"}, {"f": "audio/21/L1-nj-15__1.mp3", "t": "身之本也。"}, {"f": "audio/21/L1-nj-15__2.mp3", "t": "故藏于精者，"}, {"f": "audio/21/L1-nj-15__3.mp3", "t": "春不病温。"}], "L1-nj-16": [{"f": "audio/8c/L1-nj-16__0.mp3", "t": "阴阳者，"}, {"f": "audio/8c/L1-nj-16__1.mp3", "t": "天地之道也，"}, {"f": "audio/8c/L1-nj-16__2.mp3", "t": "万物之纲纪，"}, {"f": "audio/8c/L1-nj-16__3.mp3", "t": "变化之父母，"}, {"f": "audio/8c/L1-nj-16__4.mp3", "t": "生杀之本始，"}, {"f": "audio/8c/L1-nj-16__5.mp3", "t": "神明之府也。"}, {"f": "audio/8c/L1-nj-16__6.mp3", "t": "治病必求于本。"}], "L1-nj-17": [{"f": "audio/50/L1-nj-17__0.mp3", "t": "清气在下，"}, {"f": "audio/50/L1-nj-17__1.mp3", "t": "则生飧泄；"}, {"f": "audio/50/L1-nj-17__2.mp3", "t": "浊气在上，"}, {"f": "audio/50/L1-nj-17__3.mp3", "t": "则生䐜胀。"}, {"f": "audio/50/L1-nj-17__4.mp3", "t": "此阴阳反作，"}, {"f": "audio/50/L1-nj-17__5.mp3", "t": "病之逆从也。"}], "L1-nj-18": [{"f": "audio/eb/L1-nj-18__0.mp3", "t": "故清阳出上窍，"}, {"f": "audio/eb/L1-nj-18__1.mp3", "t": "浊阴出下窍；"}, {"f": "audio/eb/L1-nj-18__2.mp3", "t": "清阳发腠理，"}, {"f": "audio/eb/L1-nj-18__3.mp3", "t": "浊阴走五脏；"}, {"f": "audio/eb/L1-nj-18__4.mp3", "t": "清阳实四肢，"}, {"f": "audio/eb/L1-nj-18__5.mp3", "t": "浊阴归六腑。"}], "L1-nj-19": [{"f": "audio/4e/L1-nj-19__0.mp3", "t": "壮火之气衰，"}, {"f": "audio/4e/L1-nj-19__1.mp3", "t": "少火之气壮。"}, {"f": "audio/4e/L1-nj-19__2.mp3", "t": "壮火食气，"}, {"f": "audio/4e/L1-nj-19__3.mp3", "t": "气食少火。"}, {"f": "audio/4e/L1-nj-19__4.mp3", "t": "壮火散气，"}, {"f": "audio/4e/L1-nj-19__5.mp3", "t": "少火生气。"}], "L1-nj-20": [{"f": "audio/4a/L1-nj-20__0.mp3", "t": "风胜则动，"}, {"f": "audio/4a/L1-nj-20__1.mp3", "t": "热胜则肿，"}, {"f": "audio/4a/L1-nj-20__2.mp3", "t": "燥胜则干，"}, {"f": "audio/4a/L1-nj-20__3.mp3", "t": "寒胜则浮，"}, {"f": "audio/4a/L1-nj-20__4.mp3", "t": "湿胜则濡泻。"}], "L1-nj-21": [{"f": "audio/6e/L1-nj-21__0.mp3", "t": "天有四时五行，"}, {"f": "audio/6e/L1-nj-21__1.mp3", "t": "以生长收藏，"}, {"f": "audio/6e/L1-nj-21__2.mp3", "t": "以生寒暑燥湿风。"}, {"f": "audio/6e/L1-nj-21__3.mp3", "t": "人有五脏化五气，"}, {"f": "audio/6e/L1-nj-21__4.mp3", "t": "以生喜怒悲忧恐。"}], "L1-nj-22": [{"f": "audio/73/L1-nj-22__0.mp3", "t": "天地者，"}, {"f": "audio/73/L1-nj-22__1.mp3", "t": "万物之上下也；"}, {"f": "audio/73/L1-nj-22__2.mp3", "t": "阴阳者，"}, {"f": "audio/73/L1-nj-22__3.mp3", "t": "血气之男女也；"}, {"f": "audio/73/L1-nj-22__4.mp3", "t": "左右者，"}, {"f": "audio/73/L1-nj-22__5.mp3", "t": "阴阳之道路也；"}, {"f": "audio/73/L1-nj-22__6.mp3", "t": "水火者，"}, {"f": "audio/73/L1-nj-22__7.mp3", "t": "阴阳之征兆也；"}, {"f": "audio/73/L1-nj-22__8.mp3", "t": "阴阳者，"}, {"f": "audio/73/L1-nj-22__9.mp3", "t": "万物之能始也。"}], "L1-nj-23": [{"f": "audio/ff/L1-nj-23__0.mp3", "t": "故邪风之至，"}, {"f": "audio/ff/L1-nj-23__1.mp3", "t": "疾如风雨，"}, {"f": "audio/ff/L1-nj-23__2.mp3", "t": "故善治者治皮毛，"}, {"f": "audio/ff/L1-nj-23__3.mp3", "t": "其次治肌肤，"}, {"f": "audio/ff/L1-nj-23__4.mp3", "t": "其次治筋脉，"}, {"f": "audio/ff/L1-nj-23__5.mp3", "t": "其次治六腑，"}, {"f": "audio/ff/L1-nj-23__6.mp3", "t": "其次治五脏。"}], "L1-nj-24": [{"f": "audio/c0/L1-nj-24__0.mp3", "t": "故善用针者，"}, {"f": "audio/c0/L1-nj-24__1.mp3", "t": "从阴引阳，"}, {"f": "audio/c0/L1-nj-24__2.mp3", "t": "从阳引阴，"}, {"f": "audio/c0/L1-nj-24__3.mp3", "t": "以右治左，"}, {"f": "audio/c0/L1-nj-24__4.mp3", "t": "以左治右。"}], "L1-nj-25": [{"f": "audio/df/L1-nj-25__0.mp3", "t": "善诊者，"}, {"f": "audio/df/L1-nj-25__1.mp3", "t": "察色按脉，"}, {"f": "audio/df/L1-nj-25__2.mp3", "t": "先别阴阳。"}], "L1-nj-26": [{"f": "audio/7b/L1-nj-26__0.mp3", "t": "其高者，"}, {"f": "audio/7b/L1-nj-26__1.mp3", "t": "因而越之；"}, {"f": "audio/7b/L1-nj-26__2.mp3", "t": "其下者，"}, {"f": "audio/7b/L1-nj-26__3.mp3", "t": "引而竭之；"}, {"f": "audio/7b/L1-nj-26__4.mp3", "t": "中满者，"}, {"f": "audio/7b/L1-nj-26__5.mp3", "t": "泻之于内；"}, {"f": "audio/7b/L1-nj-26__6.mp3", "t": "其有邪者，"}, {"f": "audio/7b/L1-nj-26__7.mp3", "t": "渍形以为汗；"}, {"f": "audio/7b/L1-nj-26__8.mp3", "t": "其在皮者，"}, {"f": "audio/7b/L1-nj-26__9.mp3", "t": "汗而发之。"}], "L1-nj-27": [{"f": "audio/62/L1-nj-27__0.mp3", "t": "心者，"}, {"f": "audio/62/L1-nj-27__1.mp3", "t": "君主之官也，"}, {"f": "audio/62/L1-nj-27__2.mp3", "t": "神明出焉。"}, {"f": "audio/62/L1-nj-27__3.mp3", "t": "肺者，"}, {"f": "audio/62/L1-nj-27__4.mp3", "t": "相傅之官，"}, {"f": "audio/62/L1-nj-27__5.mp3", "t": "治节出焉。"}, {"f": "audio/62/L1-nj-27__6.mp3", "t": "肝者，"}, {"f": "audio/62/L1-nj-27__7.mp3", "t": "将军之官，"}, {"f": "audio/62/L1-nj-27__8.mp3", "t": "谋虑出焉。"}, {"f": "audio/62/L1-nj-27__9.mp3", "t": "胆者，"}, {"f": "audio/62/L1-nj-27__10.mp3", "t": "中正之官，"}, {"f": "audio/62/L1-nj-27__11.mp3", "t": "决断出焉。"}, {"f": "audio/62/L1-nj-27__12.mp3", "t": "膻中者，"}, {"f": "audio/62/L1-nj-27__13.mp3", "t": "臣使之官，"}, {"f": "audio/62/L1-nj-27__14.mp3", "t": "喜乐出焉。"}, {"f": "audio/62/L1-nj-27__15.mp3", "t": "脾胃者，"}, {"f": "audio/62/L1-nj-27__16.mp3", "t": "仓廪之官，"}, {"f": "audio/62/L1-nj-27__17.mp3", "t": "五味出焉。"}, {"f": "audio/62/L1-nj-27__18.mp3", "t": "大肠者，"}, {"f": "audio/62/L1-nj-27__19.mp3", "t": "传道之官，"}, {"f": "audio/62/L1-nj-27__20.mp3", "t": "变化出焉。"}, {"f": "audio/62/L1-nj-27__21.mp3", "t": "小肠者，"}, {"f": "audio/62/L1-nj-27__22.mp3", "t": "受盛之官，"}, {"f": "audio/62/L1-nj-27__23.mp3", "t": "化物出焉。"}, {"f": "audio/62/L1-nj-27__24.mp3", "t": "肾者，"}, {"f": "audio/62/L1-nj-27__25.mp3", "t": "作强之官，"}, {"f": "audio/62/L1-nj-27__26.mp3", "t": "伎巧出焉。"}, {"f": "audio/62/L1-nj-27__27.mp3", "t": "三焦者，"}, {"f": "audio/62/L1-nj-27__28.mp3", "t": "决渎之官，"}, {"f": "audio/62/L1-nj-27__29.mp3", "t": "水道出焉。"}, {"f": "audio/62/L1-nj-27__30.mp3", "t": "膀胱者，"}, {"f": "audio/62/L1-nj-27__31.mp3", "t": "州都之官，"}, {"f": "audio/62/L1-nj-27__32.mp3", "t": "津液藏焉，"}, {"f": "audio/62/L1-nj-27__33.mp3", "t": "气化则能出矣。"}], "L1-nj-28": [{"f": "audio/d9/L1-nj-28__0.mp3", "t": "心者，"}, {"f": "audio/d9/L1-nj-28__1.mp3", "t": "生之本，"}, {"f": "audio/d9/L1-nj-28__2.mp3", "t": "神之变也，"}, {"f": "audio/d9/L1-nj-28__3.mp3", "t": "其华在面，"}, {"f": "audio/d9/L1-nj-28__4.mp3", "t": "其充在血脉，"}, {"f": "audio/d9/L1-nj-28__5.mp3", "t": "为阳中之太阳，"}, {"f": "audio/d9/L1-nj-28__6.mp3", "t": "通于夏气。"}, {"f": "audio/d9/L1-nj-28__7.mp3", "t": "肺者，"}, {"f": "audio/d9/L1-nj-28__8.mp3", "t": "气之本，"}, {"f": "audio/d9/L1-nj-28__9.mp3", "t": "魄之处也，"}, {"f": "audio/d9/L1-nj-28__10.mp3", "t": "其华在毛，"}, {"f": "audio/d9/L1-nj-28__11.mp3", "t": "其充在皮，"}, {"f": "audio/d9/L1-nj-28__12.mp3", "t": "为阳中之太阴，"}, {"f": "audio/d9/L1-nj-28__13.mp3", "t": "通于秋气。"}, {"f": "audio/d9/L1-nj-28__14.mp3", "t": "肾者，"}, {"f": "audio/d9/L1-nj-28__15.mp3", "t": "主蛰，"}, {"f": "audio/d9/L1-nj-28__16.mp3", "t": "封藏之本，"}, {"f": "audio/d9/L1-nj-28__17.mp3", "t": "精之处也，"}, {"f": "audio/d9/L1-nj-28__18.mp3", "t": "其华在发，"}, {"f": "audio/d9/L1-nj-28__19.mp3", "t": "其充在骨，"}, {"f": "audio/d9/L1-nj-28__20.mp3", "t": "为阴中之少阴，"}, {"f": "audio/d9/L1-nj-28__21.mp3", "t": "通于冬气。"}, {"f": "audio/d9/L1-nj-28__22.mp3", "t": "肝者，"}, {"f": "audio/d9/L1-nj-28__23.mp3", "t": "罢极之本，"}, {"f": "audio/d9/L1-nj-28__24.mp3", "t": "魂之居也，"}, {"f": "audio/d9/L1-nj-28__25.mp3", "t": "其华在爪，"}, {"f": "audio/d9/L1-nj-28__26.mp3", "t": "其充在筋，"}, {"f": "audio/d9/L1-nj-28__27.mp3", "t": "以生血气，"}, {"f": "audio/d9/L1-nj-28__28.mp3", "t": "其味酸，"}, {"f": "audio/d9/L1-nj-28__29.mp3", "t": "其色苍，"}, {"f": "audio/d9/L1-nj-28__30.mp3", "t": "此为阳中之少阳，"}, {"f": "audio/d9/L1-nj-28__31.mp3", "t": "通于春气。"}, {"f": "audio/d9/L1-nj-28__32.mp3", "t": "脾胃大肠小肠三焦膀胱者，"}, {"f": "audio/d9/L1-nj-28__33.mp3", "t": "仓廪之本，"}, {"f": "audio/d9/L1-nj-28__34.mp3", "t": "营之居也，"}, {"f": "audio/d9/L1-nj-28__35.mp3", "t": "名曰器，"}, {"f": "audio/d9/L1-nj-28__36.mp3", "t": "能化糟粕，"}, {"f": "audio/d9/L1-nj-28__37.mp3", "t": "转味而入出者也，"}, {"f": "audio/d9/L1-nj-28__38.mp3", "t": "其华在唇四白，"}, {"f": "audio/d9/L1-nj-28__39.mp3", "t": "其充在肌，"}, {"f": "audio/d9/L1-nj-28__40.mp3", "t": "其味甘，"}, {"f": "audio/d9/L1-nj-28__41.mp3", "t": "其色黄，"}, {"f": "audio/d9/L1-nj-28__42.mp3", "t": "此至阴之类，"}, {"f": "audio/d9/L1-nj-28__43.mp3", "t": "通于土气。"}, {"f": "audio/d9/L1-nj-28__44.mp3", "t": "凡十一脏取决于胆也。"}], "L1-nj-29": [{"f": "audio/93/L1-nj-29__0.mp3", "t": "所谓五脏者，"}, {"f": "audio/93/L1-nj-29__1.mp3", "t": "藏精气而不泻也，"}, {"f": "audio/93/L1-nj-29__2.mp3", "t": "故满而不能实。"}, {"f": "audio/93/L1-nj-29__3.mp3", "t": "六腑者，"}, {"f": "audio/93/L1-nj-29__4.mp3", "t": "传化物而不藏，"}, {"f": "audio/93/L1-nj-29__5.mp3", "t": "故实而不能满也。"}], "L1-nj-30": [{"f": "audio/c3/L1-nj-30__0.mp3", "t": "气口何以独为五脏主？"}, {"f": "audio/c3/L1-nj-30__1.mp3", "t": "曰："}, {"f": "audio/c3/L1-nj-30__2.mp3", "t": "胃者，"}, {"f": "audio/c3/L1-nj-30__3.mp3", "t": "水谷之海，"}, {"f": "audio/c3/L1-nj-30__4.mp3", "t": "六腑之大源也。"}, {"f": "audio/c3/L1-nj-30__5.mp3", "t": "五味入口，"}, {"f": "audio/c3/L1-nj-30__6.mp3", "t": "藏于胃，"}, {"f": "audio/c3/L1-nj-30__7.mp3", "t": "以养五脏气，"}, {"f": "audio/c3/L1-nj-30__8.mp3", "t": "气口亦太阴也，"}, {"f": "audio/c3/L1-nj-30__9.mp3", "t": "是以五脏六腑之气味，"}, {"f": "audio/c3/L1-nj-30__10.mp3", "t": "皆出于胃，"}, {"f": "audio/c3/L1-nj-30__11.mp3", "t": "变见于气口。"}], "L1-nj-31": [{"f": "audio/da/L1-nj-31__0.mp3", "t": "病为本，"}, {"f": "audio/da/L1-nj-31__1.mp3", "t": "工为标，"}, {"f": "audio/da/L1-nj-31__2.mp3", "t": "标本不得，"}, {"f": "audio/da/L1-nj-31__3.mp3", "t": "邪气不服，"}, {"f": "audio/da/L1-nj-31__4.mp3", "t": "此之谓也。"}], "L1-nj-32": [{"f": "audio/bd/L1-nj-32__0.mp3", "t": "帝曰："}, {"f": "audio/bd/L1-nj-32__1.mp3", "t": "其有不从毫毛而生，"}, {"f": "audio/bd/L1-nj-32__2.mp3", "t": "五脏阳以竭也。"}, {"f": "audio/bd/L1-nj-32__3.mp3", "t": "津液充郭，"}, {"f": "audio/bd/L1-nj-32__4.mp3", "t": "其魄独居，"}, {"f": "audio/bd/L1-nj-32__5.mp3", "t": "孤精于内，"}, {"f": "audio/bd/L1-nj-32__6.mp3", "t": "气耗于外，"}, {"f": "audio/bd/L1-nj-32__7.mp3", "t": "形不可与衣相保，"}, {"f": "audio/bd/L1-nj-32__8.mp3", "t": "此四极急而动中，"}, {"f": "audio/bd/L1-nj-32__9.mp3", "t": "是气拒于内而形施于外，"}, {"f": "audio/bd/L1-nj-32__10.mp3", "t": "治之奈何？"}, {"f": "audio/bd/L1-nj-32__11.mp3", "t": "岐伯曰："}, {"f": "audio/bd/L1-nj-32__12.mp3", "t": "平治于权衡，"}, {"f": "audio/bd/L1-nj-32__13.mp3", "t": "去宛陈莝，"}, {"f": "audio/bd/L1-nj-32__14.mp3", "t": "微动四极，"}, {"f": "audio/bd/L1-nj-32__15.mp3", "t": "温衣，"}, {"f": "audio/bd/L1-nj-32__16.mp3", "t": "缪刺其处，"}, {"f": "audio/bd/L1-nj-32__17.mp3", "t": "以复其形。"}, {"f": "audio/bd/L1-nj-32__18.mp3", "t": "开鬼门，"}, {"f": "audio/bd/L1-nj-32__19.mp3", "t": "洁净府，"}, {"f": "audio/bd/L1-nj-32__20.mp3", "t": "精以时服，"}, {"f": "audio/bd/L1-nj-32__21.mp3", "t": "五阳以布，"}, {"f": "audio/bd/L1-nj-32__22.mp3", "t": "疏涤五脏。"}, {"f": "audio/bd/L1-nj-32__23.mp3", "t": "故精自生，"}, {"f": "audio/bd/L1-nj-32__24.mp3", "t": "形自盛，"}, {"f": "audio/bd/L1-nj-32__25.mp3", "t": "骨肉相保，"}, {"f": "audio/bd/L1-nj-32__26.mp3", "t": "巨气乃平。"}], "L1-nj-33": [{"f": "audio/65/L1-nj-33__0.mp3", "t": "诊法常以平旦，"}, {"f": "audio/65/L1-nj-33__1.mp3", "t": "阴气未动，"}, {"f": "audio/65/L1-nj-33__2.mp3", "t": "阳气未散，"}, {"f": "audio/65/L1-nj-33__3.mp3", "t": "饮食未进，"}, {"f": "audio/65/L1-nj-33__4.mp3", "t": "经脉未盛，"}, {"f": "audio/65/L1-nj-33__5.mp3", "t": "络脉调匀，"}, {"f": "audio/65/L1-nj-33__6.mp3", "t": "气血未乱，"}, {"f": "audio/65/L1-nj-33__7.mp3", "t": "故乃可诊有过之脉。"}], "L1-nj-34": [{"f": "audio/2b/L1-nj-34__0.mp3", "t": "切脉动静而视精明，"}, {"f": "audio/2b/L1-nj-34__1.mp3", "t": "察五色，"}, {"f": "audio/2b/L1-nj-34__2.mp3", "t": "观五脏有余不足，"}, {"f": "audio/2b/L1-nj-34__3.mp3", "t": "六腑强弱，"}, {"f": "audio/2b/L1-nj-34__4.mp3", "t": "形之盛衰，"}, {"f": "audio/2b/L1-nj-34__5.mp3", "t": "以此参伍，"}, {"f": "audio/2b/L1-nj-34__6.mp3", "t": "决死生之分。"}], "L1-nj-35": [{"f": "audio/f0/L1-nj-35__0.mp3", "t": "长则气治，"}, {"f": "audio/f0/L1-nj-35__1.mp3", "t": "短则气病，"}, {"f": "audio/f0/L1-nj-35__2.mp3", "t": "数则烦心，"}, {"f": "audio/f0/L1-nj-35__3.mp3", "t": "大则病进，"}, {"f": "audio/f0/L1-nj-35__4.mp3", "t": "上盛则气高，"}, {"f": "audio/f0/L1-nj-35__5.mp3", "t": "下盛则气胀，"}, {"f": "audio/f0/L1-nj-35__6.mp3", "t": "代则气衰，"}, {"f": "audio/f0/L1-nj-35__7.mp3", "t": "细则气少，"}, {"f": "audio/f0/L1-nj-35__8.mp3", "t": "涩则心痛。"}], "L1-nj-36": [{"f": "audio/7f/L1-nj-36__0.mp3", "t": "夫精明五色者，"}, {"f": "audio/7f/L1-nj-36__1.mp3", "t": "气之华也。"}], "L1-nj-37": [{"f": "audio/ea/L1-nj-37__0.mp3", "t": "头者精明之府，"}, {"f": "audio/ea/L1-nj-37__1.mp3", "t": "头倾视深，"}, {"f": "audio/ea/L1-nj-37__2.mp3", "t": "精神将夺矣；"}, {"f": "audio/ea/L1-nj-37__3.mp3", "t": "背者胸中之府，"}, {"f": "audio/ea/L1-nj-37__4.mp3", "t": "背曲肩随，"}, {"f": "audio/ea/L1-nj-37__5.mp3", "t": "府将坏矣；"}, {"f": "audio/ea/L1-nj-37__6.mp3", "t": "腰者肾之府，"}, {"f": "audio/ea/L1-nj-37__7.mp3", "t": "转摇不能，"}, {"f": "audio/ea/L1-nj-37__8.mp3", "t": "肾将惫矣；"}, {"f": "audio/ea/L1-nj-37__9.mp3", "t": "膝者筋之府，"}, {"f": "audio/ea/L1-nj-37__10.mp3", "t": "屈伸不能，"}, {"f": "audio/ea/L1-nj-37__11.mp3", "t": "行则偻附，"}, {"f": "audio/ea/L1-nj-37__12.mp3", "t": "筋将惫矣；"}, {"f": "audio/ea/L1-nj-37__13.mp3", "t": "骨者髓之府，"}, {"f": "audio/ea/L1-nj-37__14.mp3", "t": "不能久立，"}, {"f": "audio/ea/L1-nj-37__15.mp3", "t": "行则振掉，"}, {"f": "audio/ea/L1-nj-37__16.mp3", "t": "骨将惫矣。"}, {"f": "audio/ea/L1-nj-37__17.mp3", "t": "得强则生，"}, {"f": "audio/ea/L1-nj-37__18.mp3", "t": "失强则死。"}], "L1-nj-38": [{"f": "audio/84/L1-nj-38__0.mp3", "t": "四变之动，"}, {"f": "audio/84/L1-nj-38__1.mp3", "t": "脉与之上下，"}, {"f": "audio/84/L1-nj-38__2.mp3", "t": "以春应中规，"}, {"f": "audio/84/L1-nj-38__3.mp3", "t": "夏应中矩，"}, {"f": "audio/84/L1-nj-38__4.mp3", "t": "秋应中衡，"}, {"f": "audio/84/L1-nj-38__5.mp3", "t": "冬应中权。"}], "L1-nj-39": [{"f": "audio/80/L1-nj-39__0.mp3", "t": "持脉有道，"}, {"f": "audio/80/L1-nj-39__1.mp3", "t": "虚静为保。"}], "L1-nj-40": [{"f": "audio/3c/L1-nj-40__0.mp3", "t": "平人之常气禀于胃，"}, {"f": "audio/3c/L1-nj-40__1.mp3", "t": "胃者平人之常气也，"}, {"f": "audio/3c/L1-nj-40__2.mp3", "t": "人无胃气曰逆，"}, {"f": "audio/3c/L1-nj-40__3.mp3", "t": "逆者死。"}], "L1-nj-41": [{"f": "audio/01/L1-nj-41__0.mp3", "t": "浆粥入胃，"}, {"f": "audio/01/L1-nj-41__1.mp3", "t": "泄注止，"}, {"f": "audio/01/L1-nj-41__2.mp3", "t": "则虚者活；"}, {"f": "audio/01/L1-nj-41__3.mp3", "t": "身汗得后利，"}, {"f": "audio/01/L1-nj-41__4.mp3", "t": "则实者活。"}], "L1-nj-42": [{"f": "audio/0b/L1-nj-42__0.mp3", "t": "诊病之道，"}, {"f": "audio/0b/L1-nj-42__1.mp3", "t": "观人勇怯、"}, {"f": "audio/0b/L1-nj-42__2.mp3", "t": "骨肉、"}, {"f": "audio/0b/L1-nj-42__3.mp3", "t": "皮肤，"}, {"f": "audio/0b/L1-nj-42__4.mp3", "t": "能知其情，"}, {"f": "audio/0b/L1-nj-42__5.mp3", "t": "以为诊法也。"}], "L1-nj-43": [{"f": "audio/f4/L1-nj-43__0.mp3", "t": "故春秋冬夏，"}, {"f": "audio/f4/L1-nj-43__1.mp3", "t": "四时阴阳，"}, {"f": "audio/f4/L1-nj-43__2.mp3", "t": "生病起于过用，"}, {"f": "audio/f4/L1-nj-43__3.mp3", "t": "此为常也。"}], "L1-nj-44": [{"f": "audio/d7/L1-nj-44__0.mp3", "t": "饮入于胃，"}, {"f": "audio/d7/L1-nj-44__1.mp3", "t": "游溢精气，"}, {"f": "audio/d7/L1-nj-44__2.mp3", "t": "上输于脾，"}, {"f": "audio/d7/L1-nj-44__3.mp3", "t": "脾气散精，"}, {"f": "audio/d7/L1-nj-44__4.mp3", "t": "上归于肺，"}, {"f": "audio/d7/L1-nj-44__5.mp3", "t": "通调水道，"}, {"f": "audio/d7/L1-nj-44__6.mp3", "t": "下输膀胱，"}, {"f": "audio/d7/L1-nj-44__7.mp3", "t": "水精四布，"}, {"f": "audio/d7/L1-nj-44__8.mp3", "t": "五经并行。"}], "L1-nj-45": [{"f": "audio/b0/L1-nj-45__0.mp3", "t": "久视伤血，"}, {"f": "audio/b0/L1-nj-45__1.mp3", "t": "久卧伤气，"}, {"f": "audio/b0/L1-nj-45__2.mp3", "t": "久坐伤肉，"}, {"f": "audio/b0/L1-nj-45__3.mp3", "t": "久立伤骨，"}, {"f": "audio/b0/L1-nj-45__4.mp3", "t": "久行伤筋，"}, {"f": "audio/b0/L1-nj-45__5.mp3", "t": "是谓五劳所伤。"}], "L1-nj-46": [{"f": "audio/3c/L1-nj-46__0.mp3", "t": "凡刺之真，"}, {"f": "audio/3c/L1-nj-46__1.mp3", "t": "必先治神，"}, {"f": "audio/3c/L1-nj-46__2.mp3", "t": "五脏已定，"}, {"f": "audio/3c/L1-nj-46__3.mp3", "t": "九候已备，"}, {"f": "audio/3c/L1-nj-46__4.mp3", "t": "后乃存针……经气已至，"}, {"f": "audio/3c/L1-nj-46__5.mp3", "t": "慎守勿失，"}, {"f": "audio/3c/L1-nj-46__6.mp3", "t": "深浅在志，"}, {"f": "audio/3c/L1-nj-46__7.mp3", "t": "远近若一，"}, {"f": "audio/3c/L1-nj-46__8.mp3", "t": "如临深渊，"}, {"f": "audio/3c/L1-nj-46__9.mp3", "t": "手如握虎，"}, {"f": "audio/3c/L1-nj-46__10.mp3", "t": "神无营于众物。"}], "L1-nj-47": [{"f": "audio/34/L1-nj-47__0.mp3", "t": "邪气盛则实，"}, {"f": "audio/34/L1-nj-47__1.mp3", "t": "精气夺则虚。"}], "L1-nj-48": [{"f": "audio/84/L1-nj-48__0.mp3", "t": "脾与胃以膜相连耳，"}, {"f": "audio/84/L1-nj-48__1.mp3", "t": "而能为之行其津液，"}, {"f": "audio/84/L1-nj-48__2.mp3", "t": "何也？"}, {"f": "audio/84/L1-nj-48__3.mp3", "t": "曰："}, {"f": "audio/84/L1-nj-48__4.mp3", "t": "足太阴者三阴也，"}, {"f": "audio/84/L1-nj-48__5.mp3", "t": "其脉贯胃属脾络嗌，"}, {"f": "audio/84/L1-nj-48__6.mp3", "t": "故太阴为之行气于三阴。"}, {"f": "audio/84/L1-nj-48__7.mp3", "t": "阳明者表也，"}, {"f": "audio/84/L1-nj-48__8.mp3", "t": "五脏六腑之海也，"}, {"f": "audio/84/L1-nj-48__9.mp3", "t": "亦为之行气于三阳。"}], "L1-nj-49": [{"f": "audio/b1/L1-nj-49__0.mp3", "t": "阳道实，"}, {"f": "audio/b1/L1-nj-49__1.mp3", "t": "阴道虚。"}, {"f": "audio/b1/L1-nj-49__2.mp3", "t": "故犯贼风虚邪者，"}, {"f": "audio/b1/L1-nj-49__3.mp3", "t": "阳受之；"}, {"f": "audio/b1/L1-nj-49__4.mp3", "t": "食饮不节，"}, {"f": "audio/b1/L1-nj-49__5.mp3", "t": "起居不时者，"}, {"f": "audio/b1/L1-nj-49__6.mp3", "t": "阴受之。"}, {"f": "audio/b1/L1-nj-49__7.mp3", "t": "阳受之则入六腑，"}, {"f": "audio/b1/L1-nj-49__8.mp3", "t": "阴受之则入五脏。"}], "L1-nj-50": [{"f": "audio/a8/L1-nj-50__0.mp3", "t": "四肢皆禀气于胃而不得至经，"}, {"f": "audio/a8/L1-nj-50__1.mp3", "t": "必因于脾乃得禀也。"}, {"f": "audio/a8/L1-nj-50__2.mp3", "t": "今脾病不能为胃行其津液，"}, {"f": "audio/a8/L1-nj-50__3.mp3", "t": "四肢不得禀水谷气，"}, {"f": "audio/a8/L1-nj-50__4.mp3", "t": "气日以衰，"}, {"f": "audio/a8/L1-nj-50__5.mp3", "t": "脉道不利，"}, {"f": "audio/a8/L1-nj-50__6.mp3", "t": "筋骨肌肉皆无气以生，"}, {"f": "audio/a8/L1-nj-50__7.mp3", "t": "故不用焉。"}], "L1-nj-51": [{"f": "audio/b2/L1-nj-51__0.mp3", "t": "脾者土也，"}, {"f": "audio/b2/L1-nj-51__1.mp3", "t": "治中央，"}, {"f": "audio/b2/L1-nj-51__2.mp3", "t": "常以四时长四脏，"}, {"f": "audio/b2/L1-nj-51__3.mp3", "t": "各十八日寄治，"}, {"f": "audio/b2/L1-nj-51__4.mp3", "t": "不得独主于时也。"}], "L1-nj-52": [{"f": "audio/81/L1-nj-52__0.mp3", "t": "今夫热病者，"}, {"f": "audio/81/L1-nj-52__1.mp3", "t": "皆伤寒之类也，"}, {"f": "audio/81/L1-nj-52__2.mp3", "t": "或愈或死，"}, {"f": "audio/81/L1-nj-52__3.mp3", "t": "其死皆以六七日之间，"}, {"f": "audio/81/L1-nj-52__4.mp3", "t": "其愈皆以十日以上者，"}, {"f": "audio/81/L1-nj-52__5.mp3", "t": "何也？"}, {"f": "audio/81/L1-nj-52__6.mp3", "t": "不知其解，"}, {"f": "audio/81/L1-nj-52__7.mp3", "t": "愿闻其故。"}, {"f": "audio/81/L1-nj-52__8.mp3", "t": "岐伯对曰："}, {"f": "audio/81/L1-nj-52__9.mp3", "t": "巨阳者，"}, {"f": "audio/81/L1-nj-52__10.mp3", "t": "诸阳之属也，"}, {"f": "audio/81/L1-nj-52__11.mp3", "t": "其脉连于风府，"}, {"f": "audio/81/L1-nj-52__12.mp3", "t": "故为诸阳主气也。"}, {"f": "audio/81/L1-nj-52__13.mp3", "t": "人之伤于寒也，"}, {"f": "audio/81/L1-nj-52__14.mp3", "t": "则为病热，"}, {"f": "audio/81/L1-nj-52__15.mp3", "t": "热虽甚不死；"}, {"f": "audio/81/L1-nj-52__16.mp3", "t": "其两感于寒而病者，"}, {"f": "audio/81/L1-nj-52__17.mp3", "t": "必不免于死。"}], "L1-nj-53": [{"f": "audio/e5/L1-nj-53__0.mp3", "t": "伤寒一日，"}, {"f": "audio/e5/L1-nj-53__1.mp3", "t": "巨阳受之，"}, {"f": "audio/e5/L1-nj-53__2.mp3", "t": "故头项痛腰脊强。"}, {"f": "audio/e5/L1-nj-53__3.mp3", "t": "二日阳明受之，"}, {"f": "audio/e5/L1-nj-53__4.mp3", "t": "阳明主肉，"}, {"f": "audio/e5/L1-nj-53__5.mp3", "t": "其脉侠鼻络于目，"}, {"f": "audio/e5/L1-nj-53__6.mp3", "t": "故身热目疼而鼻干，"}, {"f": "audio/e5/L1-nj-53__7.mp3", "t": "不得卧也。"}, {"f": "audio/e5/L1-nj-53__8.mp3", "t": "三日少阳受之，"}, {"f": "audio/e5/L1-nj-53__9.mp3", "t": "少阳主胆，"}, {"f": "audio/e5/L1-nj-53__10.mp3", "t": "其脉循胁络于耳，"}, {"f": "audio/e5/L1-nj-53__11.mp3", "t": "故胸胁痛而耳聋。"}, {"f": "audio/e5/L1-nj-53__12.mp3", "t": "三阳经络皆受其病，"}, {"f": "audio/e5/L1-nj-53__13.mp3", "t": "而未入于脏者，"}, {"f": "audio/e5/L1-nj-53__14.mp3", "t": "故可汗而已。"}, {"f": "audio/e5/L1-nj-53__15.mp3", "t": "四日太阴受之，"}, {"f": "audio/e5/L1-nj-53__16.mp3", "t": "太阴脉布胃中络于嗌，"}, {"f": "audio/e5/L1-nj-53__17.mp3", "t": "故腹满而嗌干。"}, {"f": "audio/e5/L1-nj-53__18.mp3", "t": "五日少阴受之，"}, {"f": "audio/e5/L1-nj-53__19.mp3", "t": "少阴脉贯肾络于肺，"}, {"f": "audio/e5/L1-nj-53__20.mp3", "t": "系舌本，"}, {"f": "audio/e5/L1-nj-53__21.mp3", "t": "故口燥舌干而渴。"}, {"f": "audio/e5/L1-nj-53__22.mp3", "t": "六日厥阴受之，"}, {"f": "audio/e5/L1-nj-53__23.mp3", "t": "厥阴脉循阴器而络于肝，"}, {"f": "audio/e5/L1-nj-53__24.mp3", "t": "故烦满而囊缩。"}, {"f": "audio/e5/L1-nj-53__25.mp3", "t": "三阴三阳、"}, {"f": "audio/e5/L1-nj-53__26.mp3", "t": "五脏六腑皆受病，"}, {"f": "audio/e5/L1-nj-53__27.mp3", "t": "荣卫不行，"}, {"f": "audio/e5/L1-nj-53__28.mp3", "t": "五脏不通，"}, {"f": "audio/e5/L1-nj-53__29.mp3", "t": "则死矣。"}], "L1-nj-54": [{"f": "audio/88/L1-nj-54__0.mp3", "t": "其未满三日者，"}, {"f": "audio/88/L1-nj-54__1.mp3", "t": "可汗而已；"}, {"f": "audio/88/L1-nj-54__2.mp3", "t": "其满三日者，"}, {"f": "audio/88/L1-nj-54__3.mp3", "t": "可泄而已。"}], "L1-nj-55": [{"f": "audio/a2/L1-nj-55__0.mp3", "t": "两感于寒者，"}, {"f": "audio/a2/L1-nj-55__1.mp3", "t": "病一日则巨阳与少阴俱病，"}, {"f": "audio/a2/L1-nj-55__2.mp3", "t": "则头痛口干而烦满；"}, {"f": "audio/a2/L1-nj-55__3.mp3", "t": "二日则阳明与太阴俱病，"}, {"f": "audio/a2/L1-nj-55__4.mp3", "t": "则腹满身热，"}, {"f": "audio/a2/L1-nj-55__5.mp3", "t": "不欲食，"}, {"f": "audio/a2/L1-nj-55__6.mp3", "t": "谵言；"}, {"f": "audio/a2/L1-nj-55__7.mp3", "t": "三日则少阳与厥阴俱病，"}, {"f": "audio/a2/L1-nj-55__8.mp3", "t": "则耳聋囊缩而厥，"}, {"f": "audio/a2/L1-nj-55__9.mp3", "t": "水浆不入，"}, {"f": "audio/a2/L1-nj-55__10.mp3", "t": "不知人，"}, {"f": "audio/a2/L1-nj-55__11.mp3", "t": "六日死。"}, {"f": "audio/a2/L1-nj-55__12.mp3", "t": "帝曰："}, {"f": "audio/a2/L1-nj-55__13.mp3", "t": "五脏已伤，"}, {"f": "audio/a2/L1-nj-55__14.mp3", "t": "六腑不通，"}, {"f": "audio/a2/L1-nj-55__15.mp3", "t": "荣卫不行，"}, {"f": "audio/a2/L1-nj-55__16.mp3", "t": "如是之后，"}, {"f": "audio/a2/L1-nj-55__17.mp3", "t": "三日乃死何也？"}, {"f": "audio/a2/L1-nj-55__18.mp3", "t": "岐伯曰："}, {"f": "audio/a2/L1-nj-55__19.mp3", "t": "阳明者，"}, {"f": "audio/a2/L1-nj-55__20.mp3", "t": "十二经脉之长也，"}, {"f": "audio/a2/L1-nj-55__21.mp3", "t": "其血气盛，"}, {"f": "audio/a2/L1-nj-55__22.mp3", "t": "故不知人，"}, {"f": "audio/a2/L1-nj-55__23.mp3", "t": "三日其气乃尽，"}, {"f": "audio/a2/L1-nj-55__24.mp3", "t": "故死矣。"}, {"f": "audio/a2/L1-nj-55__25.mp3", "t": "凡病伤寒而成温者，"}, {"f": "audio/a2/L1-nj-55__26.mp3", "t": "先夏至日者为病温，"}, {"f": "audio/a2/L1-nj-55__27.mp3", "t": "后夏至日者为病暑，"}, {"f": "audio/a2/L1-nj-55__28.mp3", "t": "暑当与汗皆出，"}, {"f": "audio/a2/L1-nj-55__29.mp3", "t": "勿止。"}], "L1-nj-56": [{"f": "audio/50/L1-nj-56__0.mp3", "t": "邪之所凑，"}, {"f": "audio/50/L1-nj-56__1.mp3", "t": "其气必虚。"}], "L1-nj-57": [{"f": "audio/e0/L1-nj-57__0.mp3", "t": "五脏六腑皆令人咳，"}, {"f": "audio/e0/L1-nj-57__1.mp3", "t": "非独肺也。"}, {"f": "audio/e0/L1-nj-57__2.mp3", "t": "帝曰："}, {"f": "audio/e0/L1-nj-57__3.mp3", "t": "愿闻其状。"}, {"f": "audio/e0/L1-nj-57__4.mp3", "t": "岐伯曰："}, {"f": "audio/e0/L1-nj-57__5.mp3", "t": "皮毛者，"}, {"f": "audio/e0/L1-nj-57__6.mp3", "t": "肺之合也，"}, {"f": "audio/e0/L1-nj-57__7.mp3", "t": "皮毛先受邪气，"}, {"f": "audio/e0/L1-nj-57__8.mp3", "t": "邪气以从其合也。"}, {"f": "audio/e0/L1-nj-57__9.mp3", "t": "其寒饮食入胃，"}, {"f": "audio/e0/L1-nj-57__10.mp3", "t": "从肺脉上至于肺，"}, {"f": "audio/e0/L1-nj-57__11.mp3", "t": "则肺寒，"}, {"f": "audio/e0/L1-nj-57__12.mp3", "t": "肺寒则外内合邪，"}, {"f": "audio/e0/L1-nj-57__13.mp3", "t": "因而客之，"}, {"f": "audio/e0/L1-nj-57__14.mp3", "t": "则为肺咳。"}, {"f": "audio/e0/L1-nj-57__15.mp3", "t": "五脏各以其时受病，"}, {"f": "audio/e0/L1-nj-57__16.mp3", "t": "非其时，"}, {"f": "audio/e0/L1-nj-57__17.mp3", "t": "各传以与之。"}], "L1-nj-58": [{"f": "audio/f2/L1-nj-58__0.mp3", "t": "经脉流行不止，"}, {"f": "audio/f2/L1-nj-58__1.mp3", "t": "环周不休，"}, {"f": "audio/f2/L1-nj-58__2.mp3", "t": "寒气入经而稽迟，"}, {"f": "audio/f2/L1-nj-58__3.mp3", "t": "泣而不行，"}, {"f": "audio/f2/L1-nj-58__4.mp3", "t": "客于脉外则血少，"}, {"f": "audio/f2/L1-nj-58__5.mp3", "t": "客于脉中则气不通，"}, {"f": "audio/f2/L1-nj-58__6.mp3", "t": "故卒然而痛。"}], "L1-nj-59": [{"f": "audio/e0/L1-nj-59__0.mp3", "t": "怒则气上，"}, {"f": "audio/e0/L1-nj-59__1.mp3", "t": "喜则气缓，"}, {"f": "audio/e0/L1-nj-59__2.mp3", "t": "悲则气消，"}, {"f": "audio/e0/L1-nj-59__3.mp3", "t": "恐则气下，"}, {"f": "audio/e0/L1-nj-59__4.mp3", "t": "寒则气收，"}, {"f": "audio/e0/L1-nj-59__5.mp3", "t": "炅则气泄，"}, {"f": "audio/e0/L1-nj-59__6.mp3", "t": "惊则气乱，"}, {"f": "audio/e0/L1-nj-59__7.mp3", "t": "劳则气耗，"}, {"f": "audio/e0/L1-nj-59__8.mp3", "t": "思则气结。"}], "L1-nj-60": [{"f": "audio/b9/L1-nj-60__0.mp3", "t": "风者，"}, {"f": "audio/b9/L1-nj-60__1.mp3", "t": "善行而数变。"}, {"f": "audio/b9/L1-nj-60__2.mp3", "t": "故风者百病之长也，"}, {"f": "audio/b9/L1-nj-60__3.mp3", "t": "至其变化，"}, {"f": "audio/b9/L1-nj-60__4.mp3", "t": "乃为他病也，"}, {"f": "audio/b9/L1-nj-60__5.mp3", "t": "无常方，"}, {"f": "audio/b9/L1-nj-60__6.mp3", "t": "然致有风气也。"}], "L1-nj-61": [{"f": "audio/ad/L1-nj-61__0.mp3", "t": "风寒湿三气杂至，"}, {"f": "audio/ad/L1-nj-61__1.mp3", "t": "合而为痹也。"}, {"f": "audio/ad/L1-nj-61__2.mp3", "t": "其风气胜者为行痹，"}, {"f": "audio/ad/L1-nj-61__3.mp3", "t": "寒气胜者为痛痹，"}, {"f": "audio/ad/L1-nj-61__4.mp3", "t": "湿气胜者为著痹也。"}], "L1-nj-62": [{"f": "audio/1b/L1-nj-62__0.mp3", "t": "荣者，"}, {"f": "audio/1b/L1-nj-62__1.mp3", "t": "水谷之精气也，"}, {"f": "audio/1b/L1-nj-62__2.mp3", "t": "和调于五脏，"}, {"f": "audio/1b/L1-nj-62__3.mp3", "t": "洒陈于六腑，"}, {"f": "audio/1b/L1-nj-62__4.mp3", "t": "乃能入于脉也，"}, {"f": "audio/1b/L1-nj-62__5.mp3", "t": "故循脉上下，"}, {"f": "audio/1b/L1-nj-62__6.mp3", "t": "贯五脏，"}, {"f": "audio/1b/L1-nj-62__7.mp3", "t": "络六腑也。"}, {"f": "audio/1b/L1-nj-62__8.mp3", "t": "卫者，"}, {"f": "audio/1b/L1-nj-62__9.mp3", "t": "水谷之悍气也，"}, {"f": "audio/1b/L1-nj-62__10.mp3", "t": "其气慓疾滑利，"}, {"f": "audio/1b/L1-nj-62__11.mp3", "t": "不能入于脉也，"}, {"f": "audio/1b/L1-nj-62__12.mp3", "t": "故循皮肤之中，"}, {"f": "audio/1b/L1-nj-62__13.mp3", "t": "分肉之间，"}, {"f": "audio/1b/L1-nj-62__14.mp3", "t": "熏于肓膜，"}, {"f": "audio/1b/L1-nj-62__15.mp3", "t": "散于胸腹。"}, {"f": "audio/1b/L1-nj-62__16.mp3", "t": "逆其气则病，"}, {"f": "audio/1b/L1-nj-62__17.mp3", "t": "从其气则愈，"}, {"f": "audio/1b/L1-nj-62__18.mp3", "t": "不与风寒湿气合，"}, {"f": "audio/1b/L1-nj-62__19.mp3", "t": "故不为痹。"}], "L1-nj-63": [{"f": "audio/d5/L1-nj-63__0.mp3", "t": "五脏因肺热叶焦，"}, {"f": "audio/d5/L1-nj-63__1.mp3", "t": "发为痿躄。"}], "L1-nj-64": [{"f": "audio/6f/L1-nj-64__0.mp3", "t": "阳明者，"}, {"f": "audio/6f/L1-nj-64__1.mp3", "t": "五脏六腑之海，"}, {"f": "audio/6f/L1-nj-64__2.mp3", "t": "主润宗筋，"}, {"f": "audio/6f/L1-nj-64__3.mp3", "t": "宗筋主束骨而利机关也。"}, {"f": "audio/6f/L1-nj-64__4.mp3", "t": "冲脉者，"}, {"f": "audio/6f/L1-nj-64__5.mp3", "t": "经脉之海也，"}, {"f": "audio/6f/L1-nj-64__6.mp3", "t": "主渗灌溪谷，"}, {"f": "audio/6f/L1-nj-64__7.mp3", "t": "与阳明合于宗筋，"}, {"f": "audio/6f/L1-nj-64__8.mp3", "t": "阴阳总宗筋之会，"}, {"f": "audio/6f/L1-nj-64__9.mp3", "t": "会于气街，"}, {"f": "audio/6f/L1-nj-64__10.mp3", "t": "而阳明为之长，"}, {"f": "audio/6f/L1-nj-64__11.mp3", "t": "皆属于带脉，"}, {"f": "audio/6f/L1-nj-64__12.mp3", "t": "而络于督脉。"}, {"f": "audio/6f/L1-nj-64__13.mp3", "t": "故阳明虚，"}, {"f": "audio/6f/L1-nj-64__14.mp3", "t": "则宗筋纵，"}, {"f": "audio/6f/L1-nj-64__15.mp3", "t": "带脉不引，"}, {"f": "audio/6f/L1-nj-64__16.mp3", "t": "故足痿不用也。"}], "L1-nj-65": [{"f": "audio/62/L1-nj-65__0.mp3", "t": "肾者，"}, {"f": "audio/62/L1-nj-65__1.mp3", "t": "胃之关也，"}, {"f": "audio/62/L1-nj-65__2.mp3", "t": "关门不利，"}, {"f": "audio/62/L1-nj-65__3.mp3", "t": "故聚水而从其类也。"}, {"f": "audio/62/L1-nj-65__4.mp3", "t": "上下溢于皮肤，"}, {"f": "audio/62/L1-nj-65__5.mp3", "t": "故为胕肿。"}], "L1-nj-66": [{"f": "audio/2f/L1-nj-66__0.mp3", "t": "肾者，"}, {"f": "audio/2f/L1-nj-66__1.mp3", "t": "牝脏也，"}, {"f": "audio/2f/L1-nj-66__2.mp3", "t": "地气上者属于肾，"}, {"f": "audio/2f/L1-nj-66__3.mp3", "t": "而生水液也，"}, {"f": "audio/2f/L1-nj-66__4.mp3", "t": "故曰至阴。"}], "L1-nj-67": [{"f": "audio/eb/L1-nj-67__0.mp3", "t": "五脏之道，"}, {"f": "audio/eb/L1-nj-67__1.mp3", "t": "皆出于经隧，"}, {"f": "audio/eb/L1-nj-67__2.mp3", "t": "以行血气，"}, {"f": "audio/eb/L1-nj-67__3.mp3", "t": "血气不和，"}, {"f": "audio/eb/L1-nj-67__4.mp3", "t": "百病乃变化而生，"}, {"f": "audio/eb/L1-nj-67__5.mp3", "t": "是故守经隧焉。"}], "L1-nj-68": [{"f": "audio/c0/L1-nj-68__0.mp3", "t": "气血以并，"}, {"f": "audio/c0/L1-nj-68__1.mp3", "t": "阴阳相倾，"}, {"f": "audio/c0/L1-nj-68__2.mp3", "t": "气乱于卫，"}, {"f": "audio/c0/L1-nj-68__3.mp3", "t": "血逆于经，"}, {"f": "audio/c0/L1-nj-68__4.mp3", "t": "血气离居，"}, {"f": "audio/c0/L1-nj-68__5.mp3", "t": "一实一虚。"}], "L1-nj-69": [{"f": "audio/f7/L1-nj-69__0.mp3", "t": "夫邪之生也，"}, {"f": "audio/f7/L1-nj-69__1.mp3", "t": "或生于阴，"}, {"f": "audio/f7/L1-nj-69__2.mp3", "t": "或生于阳。"}, {"f": "audio/f7/L1-nj-69__3.mp3", "t": "其生于阳者，"}, {"f": "audio/f7/L1-nj-69__4.mp3", "t": "得之风雨寒暑；"}, {"f": "audio/f7/L1-nj-69__5.mp3", "t": "其生于阴者，"}, {"f": "audio/f7/L1-nj-69__6.mp3", "t": "得之饮食居处，"}, {"f": "audio/f7/L1-nj-69__7.mp3", "t": "阴阳喜怒。"}], "L1-nj-70": [{"f": "audio/24/L1-nj-70__0.mp3", "t": "亢则害，"}, {"f": "audio/24/L1-nj-70__1.mp3", "t": "承乃制，"}, {"f": "audio/24/L1-nj-70__2.mp3", "t": "制则生化，"}, {"f": "audio/24/L1-nj-70__3.mp3", "t": "外列盛衰，"}, {"f": "audio/24/L1-nj-70__4.mp3", "t": "害则败乱，"}, {"f": "audio/24/L1-nj-70__5.mp3", "t": "生化大病。"}], "L1-nj-71": [{"f": "audio/6d/L1-nj-71__0.mp3", "t": "出入废则神机化灭，"}, {"f": "audio/6d/L1-nj-71__1.mp3", "t": "升降息则气立孤危。"}, {"f": "audio/6d/L1-nj-71__2.mp3", "t": "故非出入，"}, {"f": "audio/6d/L1-nj-71__3.mp3", "t": "则无以生长壮老已；"}, {"f": "audio/6d/L1-nj-71__4.mp3", "t": "非升降，"}, {"f": "audio/6d/L1-nj-71__5.mp3", "t": "则无以生长化收藏。"}], "L1-nj-72": [{"f": "audio/67/L1-nj-72__0.mp3", "t": "化不可代，"}, {"f": "audio/67/L1-nj-72__1.mp3", "t": "时不可违……无代化，"}, {"f": "audio/67/L1-nj-72__2.mp3", "t": "无违时，"}, {"f": "audio/67/L1-nj-72__3.mp3", "t": "必养必和，"}, {"f": "audio/67/L1-nj-72__4.mp3", "t": "待其来复。"}], "L1-nj-73": [{"f": "audio/e0/L1-nj-73__0.mp3", "t": "用寒远寒，"}, {"f": "audio/e0/L1-nj-73__1.mp3", "t": "用凉远凉，"}, {"f": "audio/e0/L1-nj-73__2.mp3", "t": "用温远温，"}, {"f": "audio/e0/L1-nj-73__3.mp3", "t": "用热远热，"}, {"f": "audio/e0/L1-nj-73__4.mp3", "t": "食宜同法，"}, {"f": "audio/e0/L1-nj-73__5.mp3", "t": "有假者反常，"}, {"f": "audio/e0/L1-nj-73__6.mp3", "t": "反是者病。"}], "L1-nj-74": [{"f": "audio/0f/L1-nj-74__0.mp3", "t": "谨察阴阳所在而调之，"}, {"f": "audio/0f/L1-nj-74__1.mp3", "t": "以平为期。"}], "L1-nj-75": [{"f": "audio/29/L1-nj-75__0.mp3", "t": "审察病机，"}, {"f": "audio/29/L1-nj-75__1.mp3", "t": "无失气宜。"}], "L1-nj-76": [{"f": "audio/fe/L1-nj-76__0.mp3", "t": "诸风掉眩，"}, {"f": "audio/fe/L1-nj-76__1.mp3", "t": "皆属于肝。"}, {"f": "audio/fe/L1-nj-76__2.mp3", "t": "诸寒收引，"}, {"f": "audio/fe/L1-nj-76__3.mp3", "t": "皆属于肾。"}, {"f": "audio/fe/L1-nj-76__4.mp3", "t": "诸气膹郁，"}, {"f": "audio/fe/L1-nj-76__5.mp3", "t": "皆属于肺。"}, {"f": "audio/fe/L1-nj-76__6.mp3", "t": "诸湿肿满，"}, {"f": "audio/fe/L1-nj-76__7.mp3", "t": "皆属于脾。"}, {"f": "audio/fe/L1-nj-76__8.mp3", "t": "诸热瞀瘛，"}, {"f": "audio/fe/L1-nj-76__9.mp3", "t": "皆属于火。"}, {"f": "audio/fe/L1-nj-76__10.mp3", "t": "诸痛痒疮，"}, {"f": "audio/fe/L1-nj-76__11.mp3", "t": "皆属于心。"}, {"f": "audio/fe/L1-nj-76__12.mp3", "t": "诸厥固泄，"}, {"f": "audio/fe/L1-nj-76__13.mp3", "t": "皆属于下。"}, {"f": "audio/fe/L1-nj-76__14.mp3", "t": "诸痿喘呕，"}, {"f": "audio/fe/L1-nj-76__15.mp3", "t": "皆属于上。"}, {"f": "audio/fe/L1-nj-76__16.mp3", "t": "诸禁鼓栗，"}, {"f": "audio/fe/L1-nj-76__17.mp3", "t": "如丧神守，"}, {"f": "audio/fe/L1-nj-76__18.mp3", "t": "皆属于火。"}, {"f": "audio/fe/L1-nj-76__19.mp3", "t": "诸痉项强，"}, {"f": "audio/fe/L1-nj-76__20.mp3", "t": "皆属于湿。"}, {"f": "audio/fe/L1-nj-76__21.mp3", "t": "诸逆冲上，"}, {"f": "audio/fe/L1-nj-76__22.mp3", "t": "皆属于火。"}, {"f": "audio/fe/L1-nj-76__23.mp3", "t": "诸胀腹大，"}, {"f": "audio/fe/L1-nj-76__24.mp3", "t": "皆属于热。"}, {"f": "audio/fe/L1-nj-76__25.mp3", "t": "诸躁狂越，"}, {"f": "audio/fe/L1-nj-76__26.mp3", "t": "皆属于火。"}, {"f": "audio/fe/L1-nj-76__27.mp3", "t": "诸暴强直，"}, {"f": "audio/fe/L1-nj-76__28.mp3", "t": "皆属于风。"}, {"f": "audio/fe/L1-nj-76__29.mp3", "t": "诸病有声，"}, {"f": "audio/fe/L1-nj-76__30.mp3", "t": "鼓之如鼓，"}, {"f": "audio/fe/L1-nj-76__31.mp3", "t": "皆属于热。"}, {"f": "audio/fe/L1-nj-76__32.mp3", "t": "诸病胕肿，"}, {"f": "audio/fe/L1-nj-76__33.mp3", "t": "疼酸惊骇，"}, {"f": "audio/fe/L1-nj-76__34.mp3", "t": "皆属于火。"}, {"f": "audio/fe/L1-nj-76__35.mp3", "t": "诸转反戾，"}, {"f": "audio/fe/L1-nj-76__36.mp3", "t": "水液浑浊，"}, {"f": "audio/fe/L1-nj-76__37.mp3", "t": "皆属于热。"}, {"f": "audio/fe/L1-nj-76__38.mp3", "t": "诸病水液，"}, {"f": "audio/fe/L1-nj-76__39.mp3", "t": "澄澈清冷，"}, {"f": "audio/fe/L1-nj-76__40.mp3", "t": "皆属于寒。"}, {"f": "audio/fe/L1-nj-76__41.mp3", "t": "诸呕吐酸，"}, {"f": "audio/fe/L1-nj-76__42.mp3", "t": "暴注下迫，"}, {"f": "audio/fe/L1-nj-76__43.mp3", "t": "皆属于热。"}], "L1-nj-77": [{"f": "audio/99/L1-nj-77__0.mp3", "t": "谨守病机，"}, {"f": "audio/99/L1-nj-77__1.mp3", "t": "各司其属，"}, {"f": "audio/99/L1-nj-77__2.mp3", "t": "有者求之，"}, {"f": "audio/99/L1-nj-77__3.mp3", "t": "无者求之，"}, {"f": "audio/99/L1-nj-77__4.mp3", "t": "盛者责之，"}, {"f": "audio/99/L1-nj-77__5.mp3", "t": "虚者责之。"}], "L1-nj-78": [{"f": "audio/30/L1-nj-78__0.mp3", "t": "寒者热之，"}, {"f": "audio/30/L1-nj-78__1.mp3", "t": "热者寒之，"}, {"f": "audio/30/L1-nj-78__2.mp3", "t": "微者逆之，"}, {"f": "audio/30/L1-nj-78__3.mp3", "t": "甚者从之。"}], "L1-nj-79": [{"f": "audio/bd/L1-nj-79__0.mp3", "t": "热因寒用，"}, {"f": "audio/bd/L1-nj-79__1.mp3", "t": "寒因热用，"}, {"f": "audio/bd/L1-nj-79__2.mp3", "t": "塞因塞用，"}, {"f": "audio/bd/L1-nj-79__3.mp3", "t": "通因通用。"}], "L1-nj-80": [{"f": "audio/23/L1-nj-80__0.mp3", "t": "诸寒之而热者取之阴，"}, {"f": "audio/23/L1-nj-80__1.mp3", "t": "热之而寒者取之阳。"}], "L1-nj-81": [{"f": "audio/6f/L1-nj-81__0.mp3", "t": "肺合大肠……心合小肠……肝合胆……脾合胃……肾合膀胱……三焦者，"}, {"f": "audio/6f/L1-nj-81__1.mp3", "t": "中渎之腑也，"}, {"f": "audio/6f/L1-nj-81__2.mp3", "t": "水道出焉，"}, {"f": "audio/6f/L1-nj-81__3.mp3", "t": "属膀胱，"}, {"f": "audio/6f/L1-nj-81__4.mp3", "t": "是孤之腑也。"}], "L1-nj-82": [{"f": "audio/e4/L1-nj-82__0.mp3", "t": "故生之来谓之精，"}, {"f": "audio/e4/L1-nj-82__1.mp3", "t": "两精相搏谓之神，"}, {"f": "audio/e4/L1-nj-82__2.mp3", "t": "随神往来者谓之魂，"}, {"f": "audio/e4/L1-nj-82__3.mp3", "t": "并精而出入者谓之魄，"}, {"f": "audio/e4/L1-nj-82__4.mp3", "t": "所以任物者谓之心，"}, {"f": "audio/e4/L1-nj-82__5.mp3", "t": "心有所忆谓之意，"}, {"f": "audio/e4/L1-nj-82__6.mp3", "t": "意之所存谓之志，"}, {"f": "audio/e4/L1-nj-82__7.mp3", "t": "因志而存变谓之思，"}, {"f": "audio/e4/L1-nj-82__8.mp3", "t": "因思而远慕谓之虑，"}, {"f": "audio/e4/L1-nj-82__9.mp3", "t": "因虑而处物谓之智。"}], "L1-nj-83": [{"f": "audio/dc/L1-nj-83__0.mp3", "t": "故智者之养生也，"}, {"f": "audio/dc/L1-nj-83__1.mp3", "t": "必顺四时而适寒暑，"}, {"f": "audio/dc/L1-nj-83__2.mp3", "t": "和喜怒而安居处，"}, {"f": "audio/dc/L1-nj-83__3.mp3", "t": "节阴阳而调刚柔，"}, {"f": "audio/dc/L1-nj-83__4.mp3", "t": "如是则僻邪不至，"}, {"f": "audio/dc/L1-nj-83__5.mp3", "t": "长生久视。"}], "L1-nj-84": [{"f": "audio/7f/L1-nj-84__0.mp3", "t": "肝藏血，"}, {"f": "audio/7f/L1-nj-84__1.mp3", "t": "血舍魂，"}, {"f": "audio/7f/L1-nj-84__2.mp3", "t": "肝气虚则恐，"}, {"f": "audio/7f/L1-nj-84__3.mp3", "t": "实则怒。"}, {"f": "audio/7f/L1-nj-84__4.mp3", "t": "脾藏营，"}, {"f": "audio/7f/L1-nj-84__5.mp3", "t": "营舍意，"}, {"f": "audio/7f/L1-nj-84__6.mp3", "t": "脾气虚则四肢不用，"}, {"f": "audio/7f/L1-nj-84__7.mp3", "t": "五脏不安，"}, {"f": "audio/7f/L1-nj-84__8.mp3", "t": "实则腹胀，"}, {"f": "audio/7f/L1-nj-84__9.mp3", "t": "泾溲不利。"}, {"f": "audio/7f/L1-nj-84__10.mp3", "t": "心藏脉，"}, {"f": "audio/7f/L1-nj-84__11.mp3", "t": "脉舍神，"}, {"f": "audio/7f/L1-nj-84__12.mp3", "t": "心气虚则悲，"}, {"f": "audio/7f/L1-nj-84__13.mp3", "t": "实则笑不休。"}, {"f": "audio/7f/L1-nj-84__14.mp3", "t": "肺藏气，"}, {"f": "audio/7f/L1-nj-84__15.mp3", "t": "气舍魄，"}, {"f": "audio/7f/L1-nj-84__16.mp3", "t": "肺气虚则鼻塞不利，"}, {"f": "audio/7f/L1-nj-84__17.mp3", "t": "少气，"}, {"f": "audio/7f/L1-nj-84__18.mp3", "t": "实则喘喝，"}, {"f": "audio/7f/L1-nj-84__19.mp3", "t": "胸盈仰息。"}, {"f": "audio/7f/L1-nj-84__20.mp3", "t": "肾藏精，"}, {"f": "audio/7f/L1-nj-84__21.mp3", "t": "精舍志，"}, {"f": "audio/7f/L1-nj-84__22.mp3", "t": "肾气虚则厥，"}, {"f": "audio/7f/L1-nj-84__23.mp3", "t": "实则胀，"}, {"f": "audio/7f/L1-nj-84__24.mp3", "t": "五脏不安。"}], "L1-nj-85": [{"f": "audio/8d/L1-nj-85__0.mp3", "t": "人受气于谷，"}, {"f": "audio/8d/L1-nj-85__1.mp3", "t": "谷入于胃，"}, {"f": "audio/8d/L1-nj-85__2.mp3", "t": "以传与肺，"}, {"f": "audio/8d/L1-nj-85__3.mp3", "t": "五脏六腑皆以受气，"}, {"f": "audio/8d/L1-nj-85__4.mp3", "t": "其清者为营，"}, {"f": "audio/8d/L1-nj-85__5.mp3", "t": "浊者为卫，"}, {"f": "audio/8d/L1-nj-85__6.mp3", "t": "营在脉中，"}, {"f": "audio/8d/L1-nj-85__7.mp3", "t": "卫在脉外。"}], "L1-nj-86": [{"f": "audio/7e/L1-nj-86__0.mp3", "t": "上焦如雾，"}, {"f": "audio/7e/L1-nj-86__1.mp3", "t": "中焦如沤，"}, {"f": "audio/7e/L1-nj-86__2.mp3", "t": "下焦如渎。"}], "L1-nj-87": [{"f": "audio/05/L1-nj-87__0.mp3", "t": "两神相搏，"}, {"f": "audio/05/L1-nj-87__1.mp3", "t": "合而成形，"}, {"f": "audio/05/L1-nj-87__2.mp3", "t": "常先身生，"}, {"f": "audio/05/L1-nj-87__3.mp3", "t": "是谓精。"}, {"f": "audio/05/L1-nj-87__4.mp3", "t": "上焦开发，"}, {"f": "audio/05/L1-nj-87__5.mp3", "t": "宣五谷味，"}, {"f": "audio/05/L1-nj-87__6.mp3", "t": "熏肤充身泽毛，"}, {"f": "audio/05/L1-nj-87__7.mp3", "t": "若雾露之溉，"}, {"f": "audio/05/L1-nj-87__8.mp3", "t": "是谓气。"}, {"f": "audio/05/L1-nj-87__9.mp3", "t": "腠理发泄，"}, {"f": "audio/05/L1-nj-87__10.mp3", "t": "汗出溱溱，"}, {"f": "audio/05/L1-nj-87__11.mp3", "t": "是谓津。"}, {"f": "audio/05/L1-nj-87__12.mp3", "t": "谷入气满，"}, {"f": "audio/05/L1-nj-87__13.mp3", "t": "淖泽注于骨，"}, {"f": "audio/05/L1-nj-87__14.mp3", "t": "骨属屈伸，"}, {"f": "audio/05/L1-nj-87__15.mp3", "t": "泄泽补益脑髓，"}, {"f": "audio/05/L1-nj-87__16.mp3", "t": "皮肤润泽，"}, {"f": "audio/05/L1-nj-87__17.mp3", "t": "是谓液。"}, {"f": "audio/05/L1-nj-87__18.mp3", "t": "中焦受气取汁，"}, {"f": "audio/05/L1-nj-87__19.mp3", "t": "变化而赤，"}, {"f": "audio/05/L1-nj-87__20.mp3", "t": "是谓血。"}, {"f": "audio/05/L1-nj-87__21.mp3", "t": "壅遏营气，"}, {"f": "audio/05/L1-nj-87__22.mp3", "t": "令无所避，"}, {"f": "audio/05/L1-nj-87__23.mp3", "t": "是谓脉。"}], "L1-nj-88": [{"f": "audio/a5/L1-nj-88__0.mp3", "t": "精脱者，"}, {"f": "audio/a5/L1-nj-88__1.mp3", "t": "耳聋；"}, {"f": "audio/a5/L1-nj-88__2.mp3", "t": "气脱者，"}, {"f": "audio/a5/L1-nj-88__3.mp3", "t": "目不明；"}, {"f": "audio/a5/L1-nj-88__4.mp3", "t": "津脱者，"}, {"f": "audio/a5/L1-nj-88__5.mp3", "t": "腠理开，"}, {"f": "audio/a5/L1-nj-88__6.mp3", "t": "汗大泄；"}, {"f": "audio/a5/L1-nj-88__7.mp3", "t": "液脱者，"}, {"f": "audio/a5/L1-nj-88__8.mp3", "t": "骨属屈伸不利，"}, {"f": "audio/a5/L1-nj-88__9.mp3", "t": "色夭，"}, {"f": "audio/a5/L1-nj-88__10.mp3", "t": "脑髓消，"}, {"f": "audio/a5/L1-nj-88__11.mp3", "t": "胫酸，"}, {"f": "audio/a5/L1-nj-88__12.mp3", "t": "耳数鸣；"}, {"f": "audio/a5/L1-nj-88__13.mp3", "t": "血脱者，"}, {"f": "audio/a5/L1-nj-88__14.mp3", "t": "色白，"}, {"f": "audio/a5/L1-nj-88__15.mp3", "t": "夭然不泽，"}, {"f": "audio/a5/L1-nj-88__16.mp3", "t": "其脉空虚。"}], "L1-nj-89": [{"f": "audio/2a/L1-nj-89__0.mp3", "t": "胃者，"}, {"f": "audio/2a/L1-nj-89__1.mp3", "t": "五脏六腑之海也，"}, {"f": "audio/2a/L1-nj-89__2.mp3", "t": "水谷皆入于胃，"}, {"f": "audio/2a/L1-nj-89__3.mp3", "t": "五脏六腑皆禀气于胃。"}], "L1-nj-90": [{"f": "audio/34/L1-nj-90__0.mp3", "t": "人之血气精神者，"}, {"f": "audio/34/L1-nj-90__1.mp3", "t": "所以奉生而周于性命者也。"}, {"f": "audio/34/L1-nj-90__2.mp3", "t": "经脉者，"}, {"f": "audio/34/L1-nj-90__3.mp3", "t": "所以行血气而营阴阳，"}, {"f": "audio/34/L1-nj-90__4.mp3", "t": "濡筋骨，"}, {"f": "audio/34/L1-nj-90__5.mp3", "t": "利关节者也。"}, {"f": "audio/34/L1-nj-90__6.mp3", "t": "卫气者，"}, {"f": "audio/34/L1-nj-90__7.mp3", "t": "所以温分肉，"}, {"f": "audio/34/L1-nj-90__8.mp3", "t": "充皮肤，"}, {"f": "audio/34/L1-nj-90__9.mp3", "t": "肥腠理，"}, {"f": "audio/34/L1-nj-90__10.mp3", "t": "司开阖者也。"}, {"f": "audio/34/L1-nj-90__11.mp3", "t": "志意者，"}, {"f": "audio/34/L1-nj-90__12.mp3", "t": "所以御精神，"}, {"f": "audio/34/L1-nj-90__13.mp3", "t": "收魂魄，"}, {"f": "audio/34/L1-nj-90__14.mp3", "t": "适寒温，"}, {"f": "audio/34/L1-nj-90__15.mp3", "t": "和喜怒者也。"}], "L1-nj-91": [{"f": "audio/81/L1-nj-91__0.mp3", "t": "五色各见其部，"}, {"f": "audio/81/L1-nj-91__1.mp3", "t": "察其浮沉，"}, {"f": "audio/81/L1-nj-91__2.mp3", "t": "以知浅深；"}, {"f": "audio/81/L1-nj-91__3.mp3", "t": "察其泽夭，"}, {"f": "audio/81/L1-nj-91__4.mp3", "t": "以观成败；"}, {"f": "audio/81/L1-nj-91__5.mp3", "t": "察其散抟，"}, {"f": "audio/81/L1-nj-91__6.mp3", "t": "以知远近；"}, {"f": "audio/81/L1-nj-91__7.mp3", "t": "视色上下，"}, {"f": "audio/81/L1-nj-91__8.mp3", "t": "以知病处。"}], "L1-nj-92": [{"f": "audio/14/L1-nj-92__0.mp3", "t": "以母为基，"}, {"f": "audio/14/L1-nj-92__1.mp3", "t": "以父为楯，"}, {"f": "audio/14/L1-nj-92__2.mp3", "t": "失神者死，"}, {"f": "audio/14/L1-nj-92__3.mp3", "t": "得神者生也。"}], "L1-nj-93": [{"f": "audio/09/L1-nj-93__0.mp3", "t": "喜怒不节则伤脏，"}, {"f": "audio/09/L1-nj-93__1.mp3", "t": "风雨则伤上，"}, {"f": "audio/09/L1-nj-93__2.mp3", "t": "清湿则伤下。"}, {"f": "audio/09/L1-nj-93__3.mp3", "t": "三部之气，"}, {"f": "audio/09/L1-nj-93__4.mp3", "t": "所伤异类。"}], "L1-nj-94": [{"f": "audio/c7/L1-nj-94__0.mp3", "t": "两虚相得，"}, {"f": "audio/c7/L1-nj-94__1.mp3", "t": "乃客其形，"}, {"f": "audio/c7/L1-nj-94__2.mp3", "t": "两实相逢，"}, {"f": "audio/c7/L1-nj-94__3.mp3", "t": "众人肉坚。"}], "L1-nj-95": [{"f": "audio/25/L1-nj-95__0.mp3", "t": "卒然外中于寒，"}, {"f": "audio/25/L1-nj-95__1.mp3", "t": "若内伤于忧愁，"}, {"f": "audio/25/L1-nj-95__2.mp3", "t": "则气上逆，"}, {"f": "audio/25/L1-nj-95__3.mp3", "t": "气上逆则六输不通，"}, {"f": "audio/25/L1-nj-95__4.mp3", "t": "温气不行，"}, {"f": "audio/25/L1-nj-95__5.mp3", "t": "凝血蕴里而不散，"}, {"f": "audio/25/L1-nj-95__6.mp3", "t": "津液涩渗，"}, {"f": "audio/25/L1-nj-95__7.mp3", "t": "著而不去，"}, {"f": "audio/25/L1-nj-95__8.mp3", "t": "而积皆成矣。"}], "L1-nj-96": [{"f": "audio/82/L1-nj-96__0.mp3", "t": "真气者，"}, {"f": "audio/82/L1-nj-96__1.mp3", "t": "所受于天，"}, {"f": "audio/82/L1-nj-96__2.mp3", "t": "与谷气并而充身者也。"}], "L1-nj-97": [{"f": "audio/0b/L1-nj-97__0.mp3", "t": "五脏六腑之精气，"}, {"f": "audio/0b/L1-nj-97__1.mp3", "t": "皆上注于目而为之精。"}, {"f": "audio/0b/L1-nj-97__2.mp3", "t": "精之窠为眼，"}, {"f": "audio/0b/L1-nj-97__3.mp3", "t": "骨之精为瞳子，"}, {"f": "audio/0b/L1-nj-97__4.mp3", "t": "筋之精为黑眼，"}, {"f": "audio/0b/L1-nj-97__5.mp3", "t": "血之精为络，"}, {"f": "audio/0b/L1-nj-97__6.mp3", "t": "其窠气之精为白眼，"}, {"f": "audio/0b/L1-nj-97__7.mp3", "t": "肌肉之精为约束。"}], "L1-sh-0": [{"f": "audio/6f/L1-sh-0__0.mp3", "t": "太阳之为病，"}, {"f": "audio/6f/L1-sh-0__1.mp3", "t": "脉浮，"}, {"f": "audio/6f/L1-sh-0__2.mp3", "t": "头项强痛而恶寒。"}], "L1-sh-1": [{"f": "audio/c2/L1-sh-1__0.mp3", "t": "太阳病，"}, {"f": "audio/c2/L1-sh-1__1.mp3", "t": "发热，"}, {"f": "audio/c2/L1-sh-1__2.mp3", "t": "汗出，"}, {"f": "audio/c2/L1-sh-1__3.mp3", "t": "恶风，"}, {"f": "audio/c2/L1-sh-1__4.mp3", "t": "脉缓者，"}, {"f": "audio/c2/L1-sh-1__5.mp3", "t": "名为中风。"}], "L1-sh-2": [{"f": "audio/7f/L1-sh-2__0.mp3", "t": "太阳病，"}, {"f": "audio/7f/L1-sh-2__1.mp3", "t": "或已发热，"}, {"f": "audio/7f/L1-sh-2__2.mp3", "t": "或未发热，"}, {"f": "audio/7f/L1-sh-2__3.mp3", "t": "必恶寒，"}, {"f": "audio/7f/L1-sh-2__4.mp3", "t": "体痛，"}, {"f": "audio/7f/L1-sh-2__5.mp3", "t": "呕逆，"}, {"f": "audio/7f/L1-sh-2__6.mp3", "t": "脉阴阳俱紧者，"}, {"f": "audio/7f/L1-sh-2__7.mp3", "t": "名为伤寒。"}], "L1-sh-3": [{"f": "audio/e9/L1-sh-3__0.mp3", "t": "太阳病，"}, {"f": "audio/e9/L1-sh-3__1.mp3", "t": "发热而渴，"}, {"f": "audio/e9/L1-sh-3__2.mp3", "t": "不恶寒者，"}, {"f": "audio/e9/L1-sh-3__3.mp3", "t": "为温病。"}], "L1-sh-4": [{"f": "audio/7f/L1-sh-4__0.mp3", "t": "病有发热恶寒者，"}, {"f": "audio/7f/L1-sh-4__1.mp3", "t": "发于阳也；"}, {"f": "audio/7f/L1-sh-4__2.mp3", "t": "无热恶寒者，"}, {"f": "audio/7f/L1-sh-4__3.mp3", "t": "发于阴也。"}], "L1-sh-5": [{"f": "audio/46/L1-sh-5__0.mp3", "t": "病人身大热，"}, {"f": "audio/46/L1-sh-5__1.mp3", "t": "反欲得衣者，"}, {"f": "audio/46/L1-sh-5__2.mp3", "t": "热在皮肤，"}, {"f": "audio/46/L1-sh-5__3.mp3", "t": "寒在骨髓也；"}, {"f": "audio/46/L1-sh-5__4.mp3", "t": "身大寒，"}, {"f": "audio/46/L1-sh-5__5.mp3", "t": "反不欲近衣者，"}, {"f": "audio/46/L1-sh-5__6.mp3", "t": "寒在皮肤，"}, {"f": "audio/46/L1-sh-5__7.mp3", "t": "热在骨髓也。"}], "L1-sh-6": [{"f": "audio/14/L1-sh-6__0.mp3", "t": "太阳中风，"}, {"f": "audio/14/L1-sh-6__1.mp3", "t": "阳浮而阴弱。"}, {"f": "audio/14/L1-sh-6__2.mp3", "t": "阳浮者，"}, {"f": "audio/14/L1-sh-6__3.mp3", "t": "热自发；"}, {"f": "audio/14/L1-sh-6__4.mp3", "t": "阴弱者，"}, {"f": "audio/14/L1-sh-6__5.mp3", "t": "汗自出。"}, {"f": "audio/14/L1-sh-6__6.mp3", "t": "啬啬恶寒，"}, {"f": "audio/14/L1-sh-6__7.mp3", "t": "淅淅恶风，"}, {"f": "audio/14/L1-sh-6__8.mp3", "t": "翕翕发热，"}, {"f": "audio/14/L1-sh-6__9.mp3", "t": "鼻鸣干呕者，"}, {"f": "audio/14/L1-sh-6__10.mp3", "t": "桂枝汤主之。"}], "L1-sh-7": [{"f": "audio/bd/L1-sh-7__0.mp3", "t": "太阳病，"}, {"f": "audio/bd/L1-sh-7__1.mp3", "t": "项背强几几，"}, {"f": "audio/bd/L1-sh-7__2.mp3", "t": "反汗出恶风者，"}, {"f": "audio/bd/L1-sh-7__3.mp3", "t": "桂枝加葛根汤主之。"}], "L1-sh-8": [{"f": "audio/cf/L1-sh-8__0.mp3", "t": "太阳病三日，"}, {"f": "audio/cf/L1-sh-8__1.mp3", "t": "已发汗，"}, {"f": "audio/cf/L1-sh-8__2.mp3", "t": "若吐、"}, {"f": "audio/cf/L1-sh-8__3.mp3", "t": "若下、"}, {"f": "audio/cf/L1-sh-8__4.mp3", "t": "若温针，"}, {"f": "audio/cf/L1-sh-8__5.mp3", "t": "仍不解者，"}, {"f": "audio/cf/L1-sh-8__6.mp3", "t": "此为坏病，"}, {"f": "audio/cf/L1-sh-8__7.mp3", "t": "桂枝不中与之也。"}, {"f": "audio/cf/L1-sh-8__8.mp3", "t": "观其脉证，"}, {"f": "audio/cf/L1-sh-8__9.mp3", "t": "知犯何逆，"}, {"f": "audio/cf/L1-sh-8__10.mp3", "t": "随证治之。"}], "L1-sh-9": [{"f": "audio/a6/L1-sh-9__0.mp3", "t": "喘家，"}, {"f": "audio/a6/L1-sh-9__1.mp3", "t": "作桂枝汤，"}, {"f": "audio/a6/L1-sh-9__2.mp3", "t": "加厚朴杏子佳。"}], "L1-sh-10": [{"f": "audio/3b/L1-sh-10__0.mp3", "t": "太阳病，"}, {"f": "audio/3b/L1-sh-10__1.mp3", "t": "发汗，"}, {"f": "audio/3b/L1-sh-10__2.mp3", "t": "遂漏不止，"}, {"f": "audio/3b/L1-sh-10__3.mp3", "t": "其人恶风，"}, {"f": "audio/3b/L1-sh-10__4.mp3", "t": "小便难，"}, {"f": "audio/3b/L1-sh-10__5.mp3", "t": "四肢微急，"}, {"f": "audio/3b/L1-sh-10__6.mp3", "t": "难以屈伸者，"}, {"f": "audio/3b/L1-sh-10__7.mp3", "t": "桂枝加附子汤主之。"}], "L1-sh-11": [{"f": "audio/cb/L1-sh-11__0.mp3", "t": "太阳病，"}, {"f": "audio/cb/L1-sh-11__1.mp3", "t": "下之后，"}, {"f": "audio/cb/L1-sh-11__2.mp3", "t": "脉促胸满者，"}, {"f": "audio/cb/L1-sh-11__3.mp3", "t": "桂枝去芍药汤主之。"}, {"f": "audio/cb/L1-sh-11__4.mp3", "t": "若微寒者，"}, {"f": "audio/cb/L1-sh-11__5.mp3", "t": "桂枝去芍药加附子汤主之。"}], "L1-sh-12": [{"f": "audio/22/L1-sh-12__0.mp3", "t": "服桂枝汤，"}, {"f": "audio/22/L1-sh-12__1.mp3", "t": "或下之，"}, {"f": "audio/22/L1-sh-12__2.mp3", "t": "仍头项强痛，"}, {"f": "audio/22/L1-sh-12__3.mp3", "t": "翕翕发热，"}, {"f": "audio/22/L1-sh-12__4.mp3", "t": "无汗，"}, {"f": "audio/22/L1-sh-12__5.mp3", "t": "心下满微痛，"}, {"f": "audio/22/L1-sh-12__6.mp3", "t": "小便不利者，"}, {"f": "audio/22/L1-sh-12__7.mp3", "t": "桂枝去桂加茯苓白术汤主之。"}], "L1-sh-13": [{"f": "audio/2e/L1-sh-13__0.mp3", "t": "太阳病，"}, {"f": "audio/2e/L1-sh-13__1.mp3", "t": "项背强几几，"}, {"f": "audio/2e/L1-sh-13__2.mp3", "t": "无汗恶风，"}, {"f": "audio/2e/L1-sh-13__3.mp3", "t": "葛根汤主之。"}], "L1-sh-14": [{"f": "audio/e2/L1-sh-14__0.mp3", "t": "太阳与阳明合病者，"}, {"f": "audio/e2/L1-sh-14__1.mp3", "t": "必自下利，"}, {"f": "audio/e2/L1-sh-14__2.mp3", "t": "葛根汤主之。"}], "L1-sh-15": [{"f": "audio/74/L1-sh-15__0.mp3", "t": "太阳病，"}, {"f": "audio/74/L1-sh-15__1.mp3", "t": "桂枝证，"}, {"f": "audio/74/L1-sh-15__2.mp3", "t": "医反下之，"}, {"f": "audio/74/L1-sh-15__3.mp3", "t": "利遂不止，"}, {"f": "audio/74/L1-sh-15__4.mp3", "t": "脉促者，"}, {"f": "audio/74/L1-sh-15__5.mp3", "t": "表未解也；"}, {"f": "audio/74/L1-sh-15__6.mp3", "t": "喘而汗出者，"}, {"f": "audio/74/L1-sh-15__7.mp3", "t": "葛根黄芩黄连汤主之。"}], "L1-sh-16": [{"f": "audio/87/L1-sh-16__0.mp3", "t": "太阳病，"}, {"f": "audio/87/L1-sh-16__1.mp3", "t": "头痛发热，"}, {"f": "audio/87/L1-sh-16__2.mp3", "t": "身疼腰痛，"}, {"f": "audio/87/L1-sh-16__3.mp3", "t": "骨节疼痛，"}, {"f": "audio/87/L1-sh-16__4.mp3", "t": "恶风无汗而喘者，"}, {"f": "audio/87/L1-sh-16__5.mp3", "t": "麻黄汤主之。"}], "L1-sh-17": [{"f": "audio/1f/L1-sh-17__0.mp3", "t": "太阳中风，"}, {"f": "audio/1f/L1-sh-17__1.mp3", "t": "脉浮紧，"}, {"f": "audio/1f/L1-sh-17__2.mp3", "t": "发热恶寒，"}, {"f": "audio/1f/L1-sh-17__3.mp3", "t": "身疼痛，"}, {"f": "audio/1f/L1-sh-17__4.mp3", "t": "不汗出而烦躁者，"}, {"f": "audio/1f/L1-sh-17__5.mp3", "t": "大青龙汤主之。"}, {"f": "audio/1f/L1-sh-17__6.mp3", "t": "若脉微弱，"}, {"f": "audio/1f/L1-sh-17__7.mp3", "t": "汗出恶风者，"}, {"f": "audio/1f/L1-sh-17__8.mp3", "t": "不可服之。"}], "L1-sh-18": [{"f": "audio/5b/L1-sh-18__0.mp3", "t": "伤寒表不解，"}, {"f": "audio/5b/L1-sh-18__1.mp3", "t": "心下有水气，"}, {"f": "audio/5b/L1-sh-18__2.mp3", "t": "干呕发热而咳，"}, {"f": "audio/5b/L1-sh-18__3.mp3", "t": "或渴，"}, {"f": "audio/5b/L1-sh-18__4.mp3", "t": "或利，"}, {"f": "audio/5b/L1-sh-18__5.mp3", "t": "或噎，"}, {"f": "audio/5b/L1-sh-18__6.mp3", "t": "或小便不利少腹满，"}, {"f": "audio/5b/L1-sh-18__7.mp3", "t": "或喘者，"}, {"f": "audio/5b/L1-sh-18__8.mp3", "t": "小青龙汤主之。"}], "L1-sh-19": [{"f": "audio/9d/L1-sh-19__0.mp3", "t": "太阳病，"}, {"f": "audio/9d/L1-sh-19__1.mp3", "t": "下之微喘者，"}, {"f": "audio/9d/L1-sh-19__2.mp3", "t": "表未解故也，"}, {"f": "audio/9d/L1-sh-19__3.mp3", "t": "桂枝加厚朴杏子汤主之。"}], "L1-sh-20": [{"f": "audio/83/L1-sh-20__0.mp3", "t": "病常自汗出，"}, {"f": "audio/83/L1-sh-20__1.mp3", "t": "此为荣气和。"}, {"f": "audio/83/L1-sh-20__2.mp3", "t": "荣气和者，"}, {"f": "audio/83/L1-sh-20__3.mp3", "t": "外不谐，"}, {"f": "audio/83/L1-sh-20__4.mp3", "t": "以卫气不共荣气和谐故尔。"}, {"f": "audio/83/L1-sh-20__5.mp3", "t": "以荣行脉中，"}, {"f": "audio/83/L1-sh-20__6.mp3", "t": "卫行脉外，"}, {"f": "audio/83/L1-sh-20__7.mp3", "t": "复发其汗，"}, {"f": "audio/83/L1-sh-20__8.mp3", "t": "荣卫和则愈，"}, {"f": "audio/83/L1-sh-20__9.mp3", "t": "宜桂枝汤。"}], "L1-sh-21": [{"f": "audio/ec/L1-sh-21__0.mp3", "t": "病人脏无他病，"}, {"f": "audio/ec/L1-sh-21__1.mp3", "t": "时发热自汗出而不愈者，"}, {"f": "audio/ec/L1-sh-21__2.mp3", "t": "此卫气不和也。"}, {"f": "audio/ec/L1-sh-21__3.mp3", "t": "先其时发汗则愈，"}, {"f": "audio/ec/L1-sh-21__4.mp3", "t": "宜桂枝汤。"}], "L1-sh-22": [{"f": "audio/b2/L1-sh-22__0.mp3", "t": "凡病，"}, {"f": "audio/b2/L1-sh-22__1.mp3", "t": "若发汗、"}, {"f": "audio/b2/L1-sh-22__2.mp3", "t": "若吐、"}, {"f": "audio/b2/L1-sh-22__3.mp3", "t": "若下、"}, {"f": "audio/b2/L1-sh-22__4.mp3", "t": "若亡血、"}, {"f": "audio/b2/L1-sh-22__5.mp3", "t": "亡津液，"}, {"f": "audio/b2/L1-sh-22__6.mp3", "t": "阴阳自和者，"}, {"f": "audio/b2/L1-sh-22__7.mp3", "t": "必自愈。"}], "L1-sh-23": [{"f": "audio/72/L1-sh-23__0.mp3", "t": "下之后，"}, {"f": "audio/72/L1-sh-23__1.mp3", "t": "复发汗，"}, {"f": "audio/72/L1-sh-23__2.mp3", "t": "昼日烦躁不得眠，"}, {"f": "audio/72/L1-sh-23__3.mp3", "t": "夜而安静，"}, {"f": "audio/72/L1-sh-23__4.mp3", "t": "不呕不渴，"}, {"f": "audio/72/L1-sh-23__5.mp3", "t": "无表证，"}, {"f": "audio/72/L1-sh-23__6.mp3", "t": "脉沉微，"}, {"f": "audio/72/L1-sh-23__7.mp3", "t": "身无大热者，"}, {"f": "audio/72/L1-sh-23__8.mp3", "t": "干姜附子汤主之。"}], "L1-sh-24": [{"f": "audio/35/L1-sh-24__0.mp3", "t": "发汗后，"}, {"f": "audio/35/L1-sh-24__1.mp3", "t": "身疼痛，"}, {"f": "audio/35/L1-sh-24__2.mp3", "t": "脉沉迟者，"}, {"f": "audio/35/L1-sh-24__3.mp3", "t": "桂枝加芍药生姜各一两人参三两新加汤主之。"}], "L1-sh-25": [{"f": "audio/4a/L1-sh-25__0.mp3", "t": "发汗后，"}, {"f": "audio/4a/L1-sh-25__1.mp3", "t": "不可更行桂枝汤，"}, {"f": "audio/4a/L1-sh-25__2.mp3", "t": "汗出而喘，"}, {"f": "audio/4a/L1-sh-25__3.mp3", "t": "无大热者，"}, {"f": "audio/4a/L1-sh-25__4.mp3", "t": "可与麻黄杏仁甘草石膏汤。"}], "L1-sh-26": [{"f": "audio/a1/L1-sh-26__0.mp3", "t": "发汗过多，"}, {"f": "audio/a1/L1-sh-26__1.mp3", "t": "其人叉手自冒心，"}, {"f": "audio/a1/L1-sh-26__2.mp3", "t": "心下悸，"}, {"f": "audio/a1/L1-sh-26__3.mp3", "t": "欲得按者，"}, {"f": "audio/a1/L1-sh-26__4.mp3", "t": "桂枝甘草汤主之。"}], "L1-sh-27": [{"f": "audio/b6/L1-sh-27__0.mp3", "t": "发汗后，"}, {"f": "audio/b6/L1-sh-27__1.mp3", "t": "其人脐下悸者，"}, {"f": "audio/b6/L1-sh-27__2.mp3", "t": "欲作奔豚，"}, {"f": "audio/b6/L1-sh-27__3.mp3", "t": "茯苓桂枝甘草大枣汤主之。"}], "L1-sh-28": [{"f": "audio/1f/L1-sh-28__0.mp3", "t": "发汗后，"}, {"f": "audio/1f/L1-sh-28__1.mp3", "t": "腹胀满者，"}, {"f": "audio/1f/L1-sh-28__2.mp3", "t": "厚朴生姜半夏甘草人参汤主之。"}], "L1-sh-29": [{"f": "audio/1f/L1-sh-29__0.mp3", "t": "伤寒，"}, {"f": "audio/1f/L1-sh-29__1.mp3", "t": "若吐若下后，"}, {"f": "audio/1f/L1-sh-29__2.mp3", "t": "心下逆满，"}, {"f": "audio/1f/L1-sh-29__3.mp3", "t": "气上冲胸，"}, {"f": "audio/1f/L1-sh-29__4.mp3", "t": "起则头眩，"}, {"f": "audio/1f/L1-sh-29__5.mp3", "t": "脉沉紧，"}, {"f": "audio/1f/L1-sh-29__6.mp3", "t": "发汗则动经，"}, {"f": "audio/1f/L1-sh-29__7.mp3", "t": "身为振振摇者，"}, {"f": "audio/1f/L1-sh-29__8.mp3", "t": "茯苓桂枝白术甘草汤主之。"}], "L1-sh-30": [{"f": "audio/77/L1-sh-30__0.mp3", "t": "太阳病，"}, {"f": "audio/77/L1-sh-30__1.mp3", "t": "发汗后，"}, {"f": "audio/77/L1-sh-30__2.mp3", "t": "大汗出，"}, {"f": "audio/77/L1-sh-30__3.mp3", "t": "胃中干，"}, {"f": "audio/77/L1-sh-30__4.mp3", "t": "烦躁不得眠，"}, {"f": "audio/77/L1-sh-30__5.mp3", "t": "欲得饮水者，"}, {"f": "audio/77/L1-sh-30__6.mp3", "t": "少少与饮之，"}, {"f": "audio/77/L1-sh-30__7.mp3", "t": "令胃气和则愈。"}, {"f": "audio/77/L1-sh-30__8.mp3", "t": "若脉浮，"}, {"f": "audio/77/L1-sh-30__9.mp3", "t": "小便不利，"}, {"f": "audio/77/L1-sh-30__10.mp3", "t": "微热消渴者，"}, {"f": "audio/77/L1-sh-30__11.mp3", "t": "五苓散主之。"}], "L1-sh-31": [{"f": "audio/fb/L1-sh-31__0.mp3", "t": "发汗吐下后，"}, {"f": "audio/fb/L1-sh-31__1.mp3", "t": "虚烦不得眠，"}, {"f": "audio/fb/L1-sh-31__2.mp3", "t": "若剧者，"}, {"f": "audio/fb/L1-sh-31__3.mp3", "t": "必反复颠倒，"}, {"f": "audio/fb/L1-sh-31__4.mp3", "t": "心中懊憹，"}, {"f": "audio/fb/L1-sh-31__5.mp3", "t": "栀子豉汤主之。"}], "L1-sh-32": [{"f": "audio/52/L1-sh-32__0.mp3", "t": "太阳病发汗，"}, {"f": "audio/52/L1-sh-32__1.mp3", "t": "汗出不解，"}, {"f": "audio/52/L1-sh-32__2.mp3", "t": "其人仍发热，"}, {"f": "audio/52/L1-sh-32__3.mp3", "t": "心下悸，"}, {"f": "audio/52/L1-sh-32__4.mp3", "t": "头眩，"}, {"f": "audio/52/L1-sh-32__5.mp3", "t": "身瞤动，"}, {"f": "audio/52/L1-sh-32__6.mp3", "t": "振振欲擗地者，"}, {"f": "audio/52/L1-sh-32__7.mp3", "t": "真武汤主之。"}], "L1-sh-33": [{"f": "audio/70/L1-sh-33__0.mp3", "t": "伤寒，"}, {"f": "audio/70/L1-sh-33__1.mp3", "t": "医下之，"}, {"f": "audio/70/L1-sh-33__2.mp3", "t": "续得下利清谷不止，"}, {"f": "audio/70/L1-sh-33__3.mp3", "t": "身疼痛者，"}, {"f": "audio/70/L1-sh-33__4.mp3", "t": "急当救里；"}, {"f": "audio/70/L1-sh-33__5.mp3", "t": "后身疼痛，"}, {"f": "audio/70/L1-sh-33__6.mp3", "t": "清便自调者，"}, {"f": "audio/70/L1-sh-33__7.mp3", "t": "急当救表。"}, {"f": "audio/70/L1-sh-33__8.mp3", "t": "救里宜四逆汤，"}, {"f": "audio/70/L1-sh-33__9.mp3", "t": "救表宜桂枝汤。"}], "L1-sh-34": [{"f": "audio/76/L1-sh-34__0.mp3", "t": "伤寒五六日，"}, {"f": "audio/76/L1-sh-34__1.mp3", "t": "中风，"}, {"f": "audio/76/L1-sh-34__2.mp3", "t": "往来寒热，"}, {"f": "audio/76/L1-sh-34__3.mp3", "t": "胸胁苦满，"}, {"f": "audio/76/L1-sh-34__4.mp3", "t": "嘿嘿不欲饮食，"}, {"f": "audio/76/L1-sh-34__5.mp3", "t": "心烦喜呕，"}, {"f": "audio/76/L1-sh-34__6.mp3", "t": "或胸中烦而不呕，"}, {"f": "audio/76/L1-sh-34__7.mp3", "t": "或渴，"}, {"f": "audio/76/L1-sh-34__8.mp3", "t": "或腹中痛，"}, {"f": "audio/76/L1-sh-34__9.mp3", "t": "或胁下痞硬，"}, {"f": "audio/76/L1-sh-34__10.mp3", "t": "或心下悸小便不利，"}, {"f": "audio/76/L1-sh-34__11.mp3", "t": "或不渴身有微热，"}, {"f": "audio/76/L1-sh-34__12.mp3", "t": "或咳者，"}, {"f": "audio/76/L1-sh-34__13.mp3", "t": "小柴胡汤主之。"}], "L1-sh-35": [{"f": "audio/1a/L1-sh-35__0.mp3", "t": "伤寒，"}, {"f": "audio/1a/L1-sh-35__1.mp3", "t": "阳脉涩，"}, {"f": "audio/1a/L1-sh-35__2.mp3", "t": "阴脉弦，"}, {"f": "audio/1a/L1-sh-35__3.mp3", "t": "法当腹中急痛，"}, {"f": "audio/1a/L1-sh-35__4.mp3", "t": "先与小建中汤，"}, {"f": "audio/1a/L1-sh-35__5.mp3", "t": "不差者，"}, {"f": "audio/1a/L1-sh-35__6.mp3", "t": "小柴胡汤主之。"}], "L1-sh-36": [{"f": "audio/21/L1-sh-36__0.mp3", "t": "伤寒中风，"}, {"f": "audio/21/L1-sh-36__1.mp3", "t": "有柴胡证，"}, {"f": "audio/21/L1-sh-36__2.mp3", "t": "但见一证便是，"}, {"f": "audio/21/L1-sh-36__3.mp3", "t": "不必悉具。"}, {"f": "audio/21/L1-sh-36__4.mp3", "t": "凡柴胡汤病证而下之，"}, {"f": "audio/21/L1-sh-36__5.mp3", "t": "若柴胡证不罢者，"}, {"f": "audio/21/L1-sh-36__6.mp3", "t": "复与柴胡汤，"}, {"f": "audio/21/L1-sh-36__7.mp3", "t": "必蒸蒸而振，"}, {"f": "audio/21/L1-sh-36__8.mp3", "t": "却发热汗出而解。"}], "L1-sh-37": [{"f": "audio/78/L1-sh-37__0.mp3", "t": "太阳病，"}, {"f": "audio/78/L1-sh-37__1.mp3", "t": "过经十余日，"}, {"f": "audio/78/L1-sh-37__2.mp3", "t": "反二三下之，"}, {"f": "audio/78/L1-sh-37__3.mp3", "t": "后四五日，"}, {"f": "audio/78/L1-sh-37__4.mp3", "t": "柴胡证仍在者，"}, {"f": "audio/78/L1-sh-37__5.mp3", "t": "先与小柴胡汤。"}, {"f": "audio/78/L1-sh-37__6.mp3", "t": "呕不止，"}, {"f": "audio/78/L1-sh-37__7.mp3", "t": "心下急，"}, {"f": "audio/78/L1-sh-37__8.mp3", "t": "郁郁微烦者，"}, {"f": "audio/78/L1-sh-37__9.mp3", "t": "为未解也，"}, {"f": "audio/78/L1-sh-37__10.mp3", "t": "与大柴胡汤下之则愈。"}], "L1-sh-38": [{"f": "audio/0d/L1-sh-38__0.mp3", "t": "太阳病不解，"}, {"f": "audio/0d/L1-sh-38__1.mp3", "t": "热结膀胱，"}, {"f": "audio/0d/L1-sh-38__2.mp3", "t": "其人如狂，"}, {"f": "audio/0d/L1-sh-38__3.mp3", "t": "血自下，"}, {"f": "audio/0d/L1-sh-38__4.mp3", "t": "下者愈。"}, {"f": "audio/0d/L1-sh-38__5.mp3", "t": "其外不解者，"}, {"f": "audio/0d/L1-sh-38__6.mp3", "t": "尚未可攻，"}, {"f": "audio/0d/L1-sh-38__7.mp3", "t": "当先解其外。"}, {"f": "audio/0d/L1-sh-38__8.mp3", "t": "外解已，"}, {"f": "audio/0d/L1-sh-38__9.mp3", "t": "但少腹急结者，"}, {"f": "audio/0d/L1-sh-38__10.mp3", "t": "乃可攻之，"}, {"f": "audio/0d/L1-sh-38__11.mp3", "t": "宜桃核承气汤。"}], "L1-sh-39": [{"f": "audio/8d/L1-sh-39__0.mp3", "t": "伤寒八九日，"}, {"f": "audio/8d/L1-sh-39__1.mp3", "t": "下之，"}, {"f": "audio/8d/L1-sh-39__2.mp3", "t": "胸满烦惊，"}, {"f": "audio/8d/L1-sh-39__3.mp3", "t": "小便不利，"}, {"f": "audio/8d/L1-sh-39__4.mp3", "t": "谵语，"}, {"f": "audio/8d/L1-sh-39__5.mp3", "t": "一身尽重，"}, {"f": "audio/8d/L1-sh-39__6.mp3", "t": "不可转侧者，"}, {"f": "audio/8d/L1-sh-39__7.mp3", "t": "柴胡加龙骨牡蛎汤主之。"}], "L1-sh-40": [{"f": "audio/78/L1-sh-40__0.mp3", "t": "烧针令其汗，"}, {"f": "audio/78/L1-sh-40__1.mp3", "t": "针处被寒，"}, {"f": "audio/78/L1-sh-40__2.mp3", "t": "核起而赤者，"}, {"f": "audio/78/L1-sh-40__3.mp3", "t": "必发奔豚。"}, {"f": "audio/78/L1-sh-40__4.mp3", "t": "气从少腹上冲心者，"}, {"f": "audio/78/L1-sh-40__5.mp3", "t": "灸其核上各一壮，"}, {"f": "audio/78/L1-sh-40__6.mp3", "t": "与桂枝加桂汤，"}, {"f": "audio/78/L1-sh-40__7.mp3", "t": "更加桂二两也。"}], "L1-sh-41": [{"f": "audio/5e/L1-sh-41__0.mp3", "t": "伤寒六七日，"}, {"f": "audio/5e/L1-sh-41__1.mp3", "t": "结胸热实，"}, {"f": "audio/5e/L1-sh-41__2.mp3", "t": "脉沉而紧，"}, {"f": "audio/5e/L1-sh-41__3.mp3", "t": "心下痛，"}, {"f": "audio/5e/L1-sh-41__4.mp3", "t": "按之石硬者，"}, {"f": "audio/5e/L1-sh-41__5.mp3", "t": "大陷胸汤主之。"}], "L1-sh-42": [{"f": "audio/49/L1-sh-42__0.mp3", "t": "小结胸病，"}, {"f": "audio/49/L1-sh-42__1.mp3", "t": "正在心下，"}, {"f": "audio/49/L1-sh-42__2.mp3", "t": "按之则痛，"}, {"f": "audio/49/L1-sh-42__3.mp3", "t": "脉浮滑者，"}, {"f": "audio/49/L1-sh-42__4.mp3", "t": "小陷胸汤主之。"}], "L1-sh-43": [{"f": "audio/a7/L1-sh-43__0.mp3", "t": "伤寒六七日，"}, {"f": "audio/a7/L1-sh-43__1.mp3", "t": "发热微恶寒，"}, {"f": "audio/a7/L1-sh-43__2.mp3", "t": "支节烦疼，"}, {"f": "audio/a7/L1-sh-43__3.mp3", "t": "微呕，"}, {"f": "audio/a7/L1-sh-43__4.mp3", "t": "心下支结，"}, {"f": "audio/a7/L1-sh-43__5.mp3", "t": "外证未去者，"}, {"f": "audio/a7/L1-sh-43__6.mp3", "t": "柴胡桂枝汤主之。"}], "L1-sh-44": [{"f": "audio/a9/L1-sh-44__0.mp3", "t": "伤寒五六日，"}, {"f": "audio/a9/L1-sh-44__1.mp3", "t": "已发汗而复下之，"}, {"f": "audio/a9/L1-sh-44__2.mp3", "t": "胸胁满微结，"}, {"f": "audio/a9/L1-sh-44__3.mp3", "t": "小便不利，"}, {"f": "audio/a9/L1-sh-44__4.mp3", "t": "渴而不呕，"}, {"f": "audio/a9/L1-sh-44__5.mp3", "t": "但头汗出，"}, {"f": "audio/a9/L1-sh-44__6.mp3", "t": "往来寒热，"}, {"f": "audio/a9/L1-sh-44__7.mp3", "t": "心烦者，"}, {"f": "audio/a9/L1-sh-44__8.mp3", "t": "此为未解也，"}, {"f": "audio/a9/L1-sh-44__9.mp3", "t": "柴胡桂枝干姜汤主之。"}], "L1-sh-45": [{"f": "audio/6e/L1-sh-45__0.mp3", "t": "伤寒五六日，"}, {"f": "audio/6e/L1-sh-45__1.mp3", "t": "呕而发热者，"}, {"f": "audio/6e/L1-sh-45__2.mp3", "t": "柴胡汤证具，"}, {"f": "audio/6e/L1-sh-45__3.mp3", "t": "而以他药下之，"}, {"f": "audio/6e/L1-sh-45__4.mp3", "t": "柴胡证仍在者，"}, {"f": "audio/6e/L1-sh-45__5.mp3", "t": "复与柴胡汤。"}, {"f": "audio/6e/L1-sh-45__6.mp3", "t": "此虽已下之，"}, {"f": "audio/6e/L1-sh-45__7.mp3", "t": "不为逆，"}, {"f": "audio/6e/L1-sh-45__8.mp3", "t": "必蒸蒸而振，"}, {"f": "audio/6e/L1-sh-45__9.mp3", "t": "却发热汗出而解。"}, {"f": "audio/6e/L1-sh-45__10.mp3", "t": "若心下满而硬痛者，"}, {"f": "audio/6e/L1-sh-45__11.mp3", "t": "此为结胸也，"}, {"f": "audio/6e/L1-sh-45__12.mp3", "t": "大陷胸汤主之。"}, {"f": "audio/6e/L1-sh-45__13.mp3", "t": "但满而不痛者，"}, {"f": "audio/6e/L1-sh-45__14.mp3", "t": "此为痞，"}, {"f": "audio/6e/L1-sh-45__15.mp3", "t": "柴胡不中与之，"}, {"f": "audio/6e/L1-sh-45__16.mp3", "t": "宜半夏泻心汤。"}], "L1-sh-46": [{"f": "audio/95/L1-sh-46__0.mp3", "t": "心下痞，"}, {"f": "audio/95/L1-sh-46__1.mp3", "t": "按之濡，"}, {"f": "audio/95/L1-sh-46__2.mp3", "t": "其脉关上浮者，"}, {"f": "audio/95/L1-sh-46__3.mp3", "t": "大黄黄连泻心汤主之。"}], "L1-sh-47": [{"f": "audio/f3/L1-sh-47__0.mp3", "t": "伤寒汗出，"}, {"f": "audio/f3/L1-sh-47__1.mp3", "t": "解之后，"}, {"f": "audio/f3/L1-sh-47__2.mp3", "t": "胃中不和，"}, {"f": "audio/f3/L1-sh-47__3.mp3", "t": "心下痞硬，"}, {"f": "audio/f3/L1-sh-47__4.mp3", "t": "干噫食臭，"}, {"f": "audio/f3/L1-sh-47__5.mp3", "t": "胁下有水气，"}, {"f": "audio/f3/L1-sh-47__6.mp3", "t": "腹中雷鸣下利者，"}, {"f": "audio/f3/L1-sh-47__7.mp3", "t": "生姜泻心汤主之。"}], "L1-sh-48": [{"f": "audio/37/L1-sh-48__0.mp3", "t": "伤寒中风，"}, {"f": "audio/37/L1-sh-48__1.mp3", "t": "医反下之，"}, {"f": "audio/37/L1-sh-48__2.mp3", "t": "其人下利日数十行，"}, {"f": "audio/37/L1-sh-48__3.mp3", "t": "谷不化，"}, {"f": "audio/37/L1-sh-48__4.mp3", "t": "腹中雷鸣，"}, {"f": "audio/37/L1-sh-48__5.mp3", "t": "心下痞硬而满，"}, {"f": "audio/37/L1-sh-48__6.mp3", "t": "干呕心烦不得安，"}, {"f": "audio/37/L1-sh-48__7.mp3", "t": "医见心下痞，"}, {"f": "audio/37/L1-sh-48__8.mp3", "t": "谓病不尽，"}, {"f": "audio/37/L1-sh-48__9.mp3", "t": "复下之，"}, {"f": "audio/37/L1-sh-48__10.mp3", "t": "其痞益甚，"}, {"f": "audio/37/L1-sh-48__11.mp3", "t": "此非结热，"}, {"f": "audio/37/L1-sh-48__12.mp3", "t": "但以胃中虚，"}, {"f": "audio/37/L1-sh-48__13.mp3", "t": "客气上逆，"}, {"f": "audio/37/L1-sh-48__14.mp3", "t": "故使硬也，"}, {"f": "audio/37/L1-sh-48__15.mp3", "t": "甘草泻心汤主之。"}], "L1-sh-49": [{"f": "audio/6a/L1-sh-49__0.mp3", "t": "伤寒发汗，"}, {"f": "audio/6a/L1-sh-49__1.mp3", "t": "若吐若下，"}, {"f": "audio/6a/L1-sh-49__2.mp3", "t": "解后，"}, {"f": "audio/6a/L1-sh-49__3.mp3", "t": "心下痞硬，"}, {"f": "audio/6a/L1-sh-49__4.mp3", "t": "噫气不除者，"}, {"f": "audio/6a/L1-sh-49__5.mp3", "t": "旋覆代赭汤主之。"}], "L1-sh-50": [{"f": "audio/29/L1-sh-50__0.mp3", "t": "太阳病，"}, {"f": "audio/29/L1-sh-50__1.mp3", "t": "外证未除，"}, {"f": "audio/29/L1-sh-50__2.mp3", "t": "而数下之，"}, {"f": "audio/29/L1-sh-50__3.mp3", "t": "遂协热而利，"}, {"f": "audio/29/L1-sh-50__4.mp3", "t": "利下不止，"}, {"f": "audio/29/L1-sh-50__5.mp3", "t": "心下痞硬，"}, {"f": "audio/29/L1-sh-50__6.mp3", "t": "表里不解者，"}, {"f": "audio/29/L1-sh-50__7.mp3", "t": "桂枝人参汤主之。"}], "L1-sh-51": [{"f": "audio/a4/L1-sh-51__0.mp3", "t": "伤寒若吐若下后，"}, {"f": "audio/a4/L1-sh-51__1.mp3", "t": "七八日不解，"}, {"f": "audio/a4/L1-sh-51__2.mp3", "t": "热结在里，"}, {"f": "audio/a4/L1-sh-51__3.mp3", "t": "表里俱热，"}, {"f": "audio/a4/L1-sh-51__4.mp3", "t": "时时恶风，"}, {"f": "audio/a4/L1-sh-51__5.mp3", "t": "大渴，"}, {"f": "audio/a4/L1-sh-51__6.mp3", "t": "舌上干燥而烦，"}, {"f": "audio/a4/L1-sh-51__7.mp3", "t": "欲饮水数升者，"}, {"f": "audio/a4/L1-sh-51__8.mp3", "t": "白虎加人参汤主之。"}], "L1-sh-52": [{"f": "audio/f5/L1-sh-52__0.mp3", "t": "太阳与少阳合病，"}, {"f": "audio/f5/L1-sh-52__1.mp3", "t": "自下利者，"}, {"f": "audio/f5/L1-sh-52__2.mp3", "t": "与黄芩汤；"}, {"f": "audio/f5/L1-sh-52__3.mp3", "t": "若呕者，"}, {"f": "audio/f5/L1-sh-52__4.mp3", "t": "黄芩加半夏生姜汤主之。"}], "L1-sh-53": [{"f": "audio/9c/L1-sh-53__0.mp3", "t": "伤寒胸中有热，"}, {"f": "audio/9c/L1-sh-53__1.mp3", "t": "胃中有邪气，"}, {"f": "audio/9c/L1-sh-53__2.mp3", "t": "腹中痛，"}, {"f": "audio/9c/L1-sh-53__3.mp3", "t": "欲呕吐者，"}, {"f": "audio/9c/L1-sh-53__4.mp3", "t": "黄连汤主之。"}], "L1-sh-54": [{"f": "audio/c3/L1-sh-54__0.mp3", "t": "伤寒脉结代，"}, {"f": "audio/c3/L1-sh-54__1.mp3", "t": "心动悸，"}, {"f": "audio/c3/L1-sh-54__2.mp3", "t": "炙甘草汤主之。"}], "L1-sh-55": [{"f": "audio/bc/L1-sh-55__0.mp3", "t": "阳明之为病，"}, {"f": "audio/bc/L1-sh-55__1.mp3", "t": "胃家实是也。"}], "L1-sh-56": [{"f": "audio/f9/L1-sh-56__0.mp3", "t": "问曰："}, {"f": "audio/f9/L1-sh-56__1.mp3", "t": "阳明病外证云何？"}, {"f": "audio/f9/L1-sh-56__2.mp3", "t": "答曰："}, {"f": "audio/f9/L1-sh-56__3.mp3", "t": "身热，"}, {"f": "audio/f9/L1-sh-56__4.mp3", "t": "汗自出，"}, {"f": "audio/f9/L1-sh-56__5.mp3", "t": "不恶寒，"}, {"f": "audio/f9/L1-sh-56__6.mp3", "t": "反恶热也。"}], "L1-sh-57": [{"f": "audio/74/L1-sh-57__0.mp3", "t": "阳明病，"}, {"f": "audio/74/L1-sh-57__1.mp3", "t": "脉迟，"}, {"f": "audio/74/L1-sh-57__2.mp3", "t": "虽汗出不恶寒者，"}, {"f": "audio/74/L1-sh-57__3.mp3", "t": "其身必重，"}, {"f": "audio/74/L1-sh-57__4.mp3", "t": "短气腹满而喘，"}, {"f": "audio/74/L1-sh-57__5.mp3", "t": "有潮热者，"}, {"f": "audio/74/L1-sh-57__6.mp3", "t": "此外欲解，"}, {"f": "audio/74/L1-sh-57__7.mp3", "t": "可攻里也。"}, {"f": "audio/74/L1-sh-57__8.mp3", "t": "手足濈然汗出者，"}, {"f": "audio/74/L1-sh-57__9.mp3", "t": "此大便已硬也，"}, {"f": "audio/74/L1-sh-57__10.mp3", "t": "大承气汤主之；"}, {"f": "audio/74/L1-sh-57__11.mp3", "t": "若汗多，"}, {"f": "audio/74/L1-sh-57__12.mp3", "t": "微发热恶寒者，"}, {"f": "audio/74/L1-sh-57__13.mp3", "t": "外未解也，"}, {"f": "audio/74/L1-sh-57__14.mp3", "t": "其热不潮，"}, {"f": "audio/74/L1-sh-57__15.mp3", "t": "未可与承气汤；"}, {"f": "audio/74/L1-sh-57__16.mp3", "t": "若腹大满不通者，"}, {"f": "audio/74/L1-sh-57__17.mp3", "t": "可与小承气汤，"}, {"f": "audio/74/L1-sh-57__18.mp3", "t": "微和胃气，"}, {"f": "audio/74/L1-sh-57__19.mp3", "t": "勿令至大泄下。"}], "L1-sh-58": [{"f": "audio/c4/L1-sh-58__0.mp3", "t": "阳明病，"}, {"f": "audio/c4/L1-sh-58__1.mp3", "t": "其人多汗，"}, {"f": "audio/c4/L1-sh-58__2.mp3", "t": "以津液外出，"}, {"f": "audio/c4/L1-sh-58__3.mp3", "t": "胃中燥，"}, {"f": "audio/c4/L1-sh-58__4.mp3", "t": "大便必硬，"}, {"f": "audio/c4/L1-sh-58__5.mp3", "t": "硬则谵语，"}, {"f": "audio/c4/L1-sh-58__6.mp3", "t": "小承气汤主之。"}], "L1-sh-59": [{"f": "audio/00/L1-sh-59__0.mp3", "t": "三阳合病，"}, {"f": "audio/00/L1-sh-59__1.mp3", "t": "腹满身重，"}, {"f": "audio/00/L1-sh-59__2.mp3", "t": "难以转侧，"}, {"f": "audio/00/L1-sh-59__3.mp3", "t": "口不仁，"}, {"f": "audio/00/L1-sh-59__4.mp3", "t": "面垢，"}, {"f": "audio/00/L1-sh-59__5.mp3", "t": "谵语遗尿。"}, {"f": "audio/00/L1-sh-59__6.mp3", "t": "发汗则谵语。"}, {"f": "audio/00/L1-sh-59__7.mp3", "t": "下之则额上生汗，"}, {"f": "audio/00/L1-sh-59__8.mp3", "t": "手足逆冷。"}, {"f": "audio/00/L1-sh-59__9.mp3", "t": "若自汗出者，"}, {"f": "audio/00/L1-sh-59__10.mp3", "t": "白虎汤主之。"}], "L1-sh-60": [{"f": "audio/2b/L1-sh-60__0.mp3", "t": "若脉浮发热，"}, {"f": "audio/2b/L1-sh-60__1.mp3", "t": "渴欲饮水，"}, {"f": "audio/2b/L1-sh-60__2.mp3", "t": "小便不利者，"}, {"f": "audio/2b/L1-sh-60__3.mp3", "t": "猪苓汤主之。"}], "L1-sh-61": [{"f": "audio/54/L1-sh-61__0.mp3", "t": "阳明病，"}, {"f": "audio/54/L1-sh-61__1.mp3", "t": "胁下硬满，"}, {"f": "audio/54/L1-sh-61__2.mp3", "t": "不大便而呕，"}, {"f": "audio/54/L1-sh-61__3.mp3", "t": "舌上白苔者，"}, {"f": "audio/54/L1-sh-61__4.mp3", "t": "可与小柴胡汤。"}, {"f": "audio/54/L1-sh-61__5.mp3", "t": "上焦得通，"}, {"f": "audio/54/L1-sh-61__6.mp3", "t": "津液得下，"}, {"f": "audio/54/L1-sh-61__7.mp3", "t": "胃气因和，"}, {"f": "audio/54/L1-sh-61__8.mp3", "t": "身濈然汗出而解。"}], "L1-sh-62": [{"f": "audio/f5/L1-sh-62__0.mp3", "t": "阳明病，"}, {"f": "audio/f5/L1-sh-62__1.mp3", "t": "发热汗出者，"}, {"f": "audio/f5/L1-sh-62__2.mp3", "t": "此为热越，"}, {"f": "audio/f5/L1-sh-62__3.mp3", "t": "不能发黄也。"}, {"f": "audio/f5/L1-sh-62__4.mp3", "t": "但头汗出，"}, {"f": "audio/f5/L1-sh-62__5.mp3", "t": "身无汗，"}, {"f": "audio/f5/L1-sh-62__6.mp3", "t": "剂颈而还，"}, {"f": "audio/f5/L1-sh-62__7.mp3", "t": "小便不利，"}, {"f": "audio/f5/L1-sh-62__8.mp3", "t": "渴饮水浆者，"}, {"f": "audio/f5/L1-sh-62__9.mp3", "t": "此为瘀热在里，"}, {"f": "audio/f5/L1-sh-62__10.mp3", "t": "身必发黄，"}, {"f": "audio/f5/L1-sh-62__11.mp3", "t": "茵陈蒿汤主之。"}], "L1-sh-63": [{"f": "audio/4e/L1-sh-63__0.mp3", "t": "阳明证，"}, {"f": "audio/4e/L1-sh-63__1.mp3", "t": "其人喜忘者，"}, {"f": "audio/4e/L1-sh-63__2.mp3", "t": "必有蓄血。"}, {"f": "audio/4e/L1-sh-63__3.mp3", "t": "所以然者，"}, {"f": "audio/4e/L1-sh-63__4.mp3", "t": "本有久瘀血，"}, {"f": "audio/4e/L1-sh-63__5.mp3", "t": "故令喜忘。"}, {"f": "audio/4e/L1-sh-63__6.mp3", "t": "屎虽硬，"}, {"f": "audio/4e/L1-sh-63__7.mp3", "t": "大便反易，"}, {"f": "audio/4e/L1-sh-63__8.mp3", "t": "其色必黑者，"}, {"f": "audio/4e/L1-sh-63__9.mp3", "t": "宜抵当汤下之。"}], "L1-sh-64": [{"f": "audio/65/L1-sh-64__0.mp3", "t": "食谷欲呕，"}, {"f": "audio/65/L1-sh-64__1.mp3", "t": "属阳明也，"}, {"f": "audio/65/L1-sh-64__2.mp3", "t": "吴茱萸汤主之。"}, {"f": "audio/65/L1-sh-64__3.mp3", "t": "得汤反剧者，"}, {"f": "audio/65/L1-sh-64__4.mp3", "t": "属上焦也。"}], "L1-sh-65": [{"f": "audio/3b/L1-sh-65__0.mp3", "t": "趺阳脉浮而涩，"}, {"f": "audio/3b/L1-sh-65__1.mp3", "t": "浮则胃气强，"}, {"f": "audio/3b/L1-sh-65__2.mp3", "t": "涩则小便数，"}, {"f": "audio/3b/L1-sh-65__3.mp3", "t": "浮涩相搏，"}, {"f": "audio/3b/L1-sh-65__4.mp3", "t": "大便则硬，"}, {"f": "audio/3b/L1-sh-65__5.mp3", "t": "其脾为约，"}, {"f": "audio/3b/L1-sh-65__6.mp3", "t": "麻子仁丸主之。"}], "L1-sh-66": [{"f": "audio/3e/L1-sh-66__0.mp3", "t": "太阳病三日，"}, {"f": "audio/3e/L1-sh-66__1.mp3", "t": "发汗不解，"}, {"f": "audio/3e/L1-sh-66__2.mp3", "t": "蒸蒸发热者，"}, {"f": "audio/3e/L1-sh-66__3.mp3", "t": "属胃也，"}, {"f": "audio/3e/L1-sh-66__4.mp3", "t": "调胃承气汤主之。"}], "L1-sh-67": [{"f": "audio/ad/L1-sh-67__0.mp3", "t": "伤寒瘀热在里，"}, {"f": "audio/ad/L1-sh-67__1.mp3", "t": "身必黄，"}, {"f": "audio/ad/L1-sh-67__2.mp3", "t": "麻黄连轺赤小豆汤主之。"}], "L1-sh-68": [{"f": "audio/b7/L1-sh-68__0.mp3", "t": "少阳之为病，"}, {"f": "audio/b7/L1-sh-68__1.mp3", "t": "口苦，"}, {"f": "audio/b7/L1-sh-68__2.mp3", "t": "咽干，"}, {"f": "audio/b7/L1-sh-68__3.mp3", "t": "目眩也。"}], "L1-sh-69": [{"f": "audio/91/L1-sh-69__0.mp3", "t": "太阴之为病，"}, {"f": "audio/91/L1-sh-69__1.mp3", "t": "腹满而吐，"}, {"f": "audio/91/L1-sh-69__2.mp3", "t": "食不下，"}, {"f": "audio/91/L1-sh-69__3.mp3", "t": "自利益甚，"}, {"f": "audio/91/L1-sh-69__4.mp3", "t": "时腹自痛。"}, {"f": "audio/91/L1-sh-69__5.mp3", "t": "若下之，"}, {"f": "audio/91/L1-sh-69__6.mp3", "t": "必胸下结硬。"}], "L1-sh-70": [{"f": "audio/a4/L1-sh-70__0.mp3", "t": "自利不渴者，"}, {"f": "audio/a4/L1-sh-70__1.mp3", "t": "属太阴，"}, {"f": "audio/a4/L1-sh-70__2.mp3", "t": "以其脏有寒故也，"}, {"f": "audio/a4/L1-sh-70__3.mp3", "t": "当温之，"}, {"f": "audio/a4/L1-sh-70__4.mp3", "t": "宜服四逆辈。"}], "L1-sh-71": [{"f": "audio/6f/L1-sh-71__0.mp3", "t": "本太阳病，"}, {"f": "audio/6f/L1-sh-71__1.mp3", "t": "医反下之，"}, {"f": "audio/6f/L1-sh-71__2.mp3", "t": "因而腹满时痛者，"}, {"f": "audio/6f/L1-sh-71__3.mp3", "t": "属太阴也，"}, {"f": "audio/6f/L1-sh-71__4.mp3", "t": "桂枝加芍药汤主之；"}, {"f": "audio/6f/L1-sh-71__5.mp3", "t": "大实痛者，"}, {"f": "audio/6f/L1-sh-71__6.mp3", "t": "桂枝加大黄汤主之。"}], "L1-sh-72": [{"f": "audio/b2/L1-sh-72__0.mp3", "t": "少阴之为病，"}, {"f": "audio/b2/L1-sh-72__1.mp3", "t": "脉微细，"}, {"f": "audio/b2/L1-sh-72__2.mp3", "t": "但欲寐也。"}], "L1-sh-73": [{"f": "audio/12/L1-sh-73__0.mp3", "t": "少阴病，"}, {"f": "audio/12/L1-sh-73__1.mp3", "t": "欲吐不吐，"}, {"f": "audio/12/L1-sh-73__2.mp3", "t": "心烦，"}, {"f": "audio/12/L1-sh-73__3.mp3", "t": "但欲寐，"}, {"f": "audio/12/L1-sh-73__4.mp3", "t": "五六日自利而渴者，"}, {"f": "audio/12/L1-sh-73__5.mp3", "t": "属少阴也，"}, {"f": "audio/12/L1-sh-73__6.mp3", "t": "虚故引水自救。"}, {"f": "audio/12/L1-sh-73__7.mp3", "t": "若小便色白者，"}, {"f": "audio/12/L1-sh-73__8.mp3", "t": "少阴病形悉具。"}, {"f": "audio/12/L1-sh-73__9.mp3", "t": "小便白者，"}, {"f": "audio/12/L1-sh-73__10.mp3", "t": "以下焦虚有寒，"}, {"f": "audio/12/L1-sh-73__11.mp3", "t": "不能制水，"}, {"f": "audio/12/L1-sh-73__12.mp3", "t": "故令色白也。"}], "L1-sh-74": [{"f": "audio/55/L1-sh-74__0.mp3", "t": "少阴病，"}, {"f": "audio/55/L1-sh-74__1.mp3", "t": "始得之，"}, {"f": "audio/55/L1-sh-74__2.mp3", "t": "反发热，"}, {"f": "audio/55/L1-sh-74__3.mp3", "t": "脉沉者，"}, {"f": "audio/55/L1-sh-74__4.mp3", "t": "麻黄细辛附子汤主之。"}], "L1-sh-75": [{"f": "audio/d5/L1-sh-75__0.mp3", "t": "少阴病，"}, {"f": "audio/d5/L1-sh-75__1.mp3", "t": "得之二三日以上，"}, {"f": "audio/d5/L1-sh-75__2.mp3", "t": "心中烦，"}, {"f": "audio/d5/L1-sh-75__3.mp3", "t": "不得卧，"}, {"f": "audio/d5/L1-sh-75__4.mp3", "t": "黄连阿胶汤主之。"}], "L1-sh-76": [{"f": "audio/3a/L1-sh-76__0.mp3", "t": "少阴病，"}, {"f": "audio/3a/L1-sh-76__1.mp3", "t": "身体痛，"}, {"f": "audio/3a/L1-sh-76__2.mp3", "t": "手足寒，"}, {"f": "audio/3a/L1-sh-76__3.mp3", "t": "骨节痛，"}, {"f": "audio/3a/L1-sh-76__4.mp3", "t": "脉沉者，"}, {"f": "audio/3a/L1-sh-76__5.mp3", "t": "附子汤主之。"}], "L1-sh-77": [{"f": "audio/cd/L1-sh-77__0.mp3", "t": "少阴病，"}, {"f": "audio/cd/L1-sh-77__1.mp3", "t": "下利便脓血者，"}, {"f": "audio/cd/L1-sh-77__2.mp3", "t": "桃花汤主之。"}], "L1-sh-78": [{"f": "audio/cd/L1-sh-78__0.mp3", "t": "少阴病，"}, {"f": "audio/cd/L1-sh-78__1.mp3", "t": "二三日不已，"}, {"f": "audio/cd/L1-sh-78__2.mp3", "t": "至四五日，"}, {"f": "audio/cd/L1-sh-78__3.mp3", "t": "腹痛，"}, {"f": "audio/cd/L1-sh-78__4.mp3", "t": "小便不利，"}, {"f": "audio/cd/L1-sh-78__5.mp3", "t": "四肢沉重疼痛，"}, {"f": "audio/cd/L1-sh-78__6.mp3", "t": "自下利者，"}, {"f": "audio/cd/L1-sh-78__7.mp3", "t": "此为有水气，"}, {"f": "audio/cd/L1-sh-78__8.mp3", "t": "其人或咳，"}, {"f": "audio/cd/L1-sh-78__9.mp3", "t": "或小便利，"}, {"f": "audio/cd/L1-sh-78__10.mp3", "t": "或下利，"}, {"f": "audio/cd/L1-sh-78__11.mp3", "t": "或呕者，"}, {"f": "audio/cd/L1-sh-78__12.mp3", "t": "真武汤主之。"}], "L1-sh-79": [{"f": "audio/76/L1-sh-79__0.mp3", "t": "少阴病，"}, {"f": "audio/76/L1-sh-79__1.mp3", "t": "四逆，"}, {"f": "audio/76/L1-sh-79__2.mp3", "t": "其人或咳，"}, {"f": "audio/76/L1-sh-79__3.mp3", "t": "或悸，"}, {"f": "audio/76/L1-sh-79__4.mp3", "t": "或小便不利，"}, {"f": "audio/76/L1-sh-79__5.mp3", "t": "或腹中痛，"}, {"f": "audio/76/L1-sh-79__6.mp3", "t": "或泄利下重者，"}, {"f": "audio/76/L1-sh-79__7.mp3", "t": "四逆散主之。"}], "L1-sh-80": [{"f": "audio/07/L1-sh-80__0.mp3", "t": "少阴病，"}, {"f": "audio/07/L1-sh-80__1.mp3", "t": "下利六七日，"}, {"f": "audio/07/L1-sh-80__2.mp3", "t": "咳而呕渴，"}, {"f": "audio/07/L1-sh-80__3.mp3", "t": "心烦不得眠者，"}, {"f": "audio/07/L1-sh-80__4.mp3", "t": "猪苓汤主之。"}], "L1-sh-81": [{"f": "audio/23/L1-sh-81__0.mp3", "t": "厥阴之为病，"}, {"f": "audio/23/L1-sh-81__1.mp3", "t": "消渴，"}, {"f": "audio/23/L1-sh-81__2.mp3", "t": "气上撞心，"}, {"f": "audio/23/L1-sh-81__3.mp3", "t": "心中疼热，"}, {"f": "audio/23/L1-sh-81__4.mp3", "t": "饥而不欲食，"}, {"f": "audio/23/L1-sh-81__5.mp3", "t": "食则吐蛔，"}, {"f": "audio/23/L1-sh-81__6.mp3", "t": "下之利不止。"}], "L1-sh-82": [{"f": "audio/35/L1-sh-82__0.mp3", "t": "凡厥者，"}, {"f": "audio/35/L1-sh-82__1.mp3", "t": "阴阳气不相顺接，"}, {"f": "audio/35/L1-sh-82__2.mp3", "t": "便为厥。"}, {"f": "audio/35/L1-sh-82__3.mp3", "t": "厥者，"}, {"f": "audio/35/L1-sh-82__4.mp3", "t": "手足逆冷者是也。"}], "L1-sh-83": [{"f": "audio/ca/L1-sh-83__0.mp3", "t": "伤寒脉微而厥，"}, {"f": "audio/ca/L1-sh-83__1.mp3", "t": "至七八日，"}, {"f": "audio/ca/L1-sh-83__2.mp3", "t": "肤冷，"}, {"f": "audio/ca/L1-sh-83__3.mp3", "t": "其人躁无暂安时者，"}, {"f": "audio/ca/L1-sh-83__4.mp3", "t": "此为脏厥，"}, {"f": "audio/ca/L1-sh-83__5.mp3", "t": "非蛔厥也。"}, {"f": "audio/ca/L1-sh-83__6.mp3", "t": "蛔厥者，"}, {"f": "audio/ca/L1-sh-83__7.mp3", "t": "其人当吐蛔。"}, {"f": "audio/ca/L1-sh-83__8.mp3", "t": "今病者静，"}, {"f": "audio/ca/L1-sh-83__9.mp3", "t": "而复时烦者，"}, {"f": "audio/ca/L1-sh-83__10.mp3", "t": "此为脏寒。"}, {"f": "audio/ca/L1-sh-83__11.mp3", "t": "蛔上入其膈，"}, {"f": "audio/ca/L1-sh-83__12.mp3", "t": "故烦，"}, {"f": "audio/ca/L1-sh-83__13.mp3", "t": "须臾复止，"}, {"f": "audio/ca/L1-sh-83__14.mp3", "t": "得食而呕，"}, {"f": "audio/ca/L1-sh-83__15.mp3", "t": "又烦者，"}, {"f": "audio/ca/L1-sh-83__16.mp3", "t": "蛔闻食臭出，"}, {"f": "audio/ca/L1-sh-83__17.mp3", "t": "其人常自吐蛔。"}, {"f": "audio/ca/L1-sh-83__18.mp3", "t": "蛔厥者，"}, {"f": "audio/ca/L1-sh-83__19.mp3", "t": "乌梅丸主之。"}, {"f": "audio/ca/L1-sh-83__20.mp3", "t": "又主久利。"}], "L1-sh-84": [{"f": "audio/e8/L1-sh-84__0.mp3", "t": "伤寒脉滑而厥者，"}, {"f": "audio/e8/L1-sh-84__1.mp3", "t": "里有热，"}, {"f": "audio/e8/L1-sh-84__2.mp3", "t": "白虎汤主之。"}], "L1-sh-85": [{"f": "audio/ff/L1-sh-85__0.mp3", "t": "手足厥寒，"}, {"f": "audio/ff/L1-sh-85__1.mp3", "t": "脉细欲绝者，"}, {"f": "audio/ff/L1-sh-85__2.mp3", "t": "当归四逆汤主之。"}], "L1-sh-86": [{"f": "audio/a3/L1-sh-86__0.mp3", "t": "热利下重者，"}, {"f": "audio/a3/L1-sh-86__1.mp3", "t": "白头翁汤主之。"}], "L1-sh-87": [{"f": "audio/ba/L1-sh-87__0.mp3", "t": "干呕，"}, {"f": "audio/ba/L1-sh-87__1.mp3", "t": "吐涎沫，"}, {"f": "audio/ba/L1-sh-87__2.mp3", "t": "头痛者，"}, {"f": "audio/ba/L1-sh-87__3.mp3", "t": "吴茱萸汤主之。"}], "L1-sh-88": [{"f": "audio/7a/L1-sh-88__0.mp3", "t": "呕而发热者，"}, {"f": "audio/7a/L1-sh-88__1.mp3", "t": "小柴胡汤主之。"}], "L1-sh-89": [{"f": "audio/59/L1-sh-89__0.mp3", "t": "霍乱，"}, {"f": "audio/59/L1-sh-89__1.mp3", "t": "头痛发热，"}, {"f": "audio/59/L1-sh-89__2.mp3", "t": "身疼痛，"}, {"f": "audio/59/L1-sh-89__3.mp3", "t": "热多欲饮水者，"}, {"f": "audio/59/L1-sh-89__4.mp3", "t": "五苓散主之；"}, {"f": "audio/59/L1-sh-89__5.mp3", "t": "寒多不用水者，"}, {"f": "audio/59/L1-sh-89__6.mp3", "t": "理中丸主之。"}], "L1-sh-90": [{"f": "audio/61/L1-sh-90__0.mp3", "t": "伤寒解后，"}, {"f": "audio/61/L1-sh-90__1.mp3", "t": "虚羸少气，"}, {"f": "audio/61/L1-sh-90__2.mp3", "t": "气逆欲吐，"}, {"f": "audio/61/L1-sh-90__3.mp3", "t": "竹叶石膏汤主之。"}], "L1-jg-0": [{"f": "audio/3a/L1-jg-0__0.mp3", "t": "夫治未病者，"}, {"f": "audio/3a/L1-jg-0__1.mp3", "t": "见肝之病，"}, {"f": "audio/3a/L1-jg-0__2.mp3", "t": "知肝传脾，"}, {"f": "audio/3a/L1-jg-0__3.mp3", "t": "当先实脾，"}, {"f": "audio/3a/L1-jg-0__4.mp3", "t": "四季脾旺不受邪，"}, {"f": "audio/3a/L1-jg-0__5.mp3", "t": "即勿补之。"}, {"f": "audio/3a/L1-jg-0__6.mp3", "t": "中工不晓相传，"}, {"f": "audio/3a/L1-jg-0__7.mp3", "t": "见肝之病，"}, {"f": "audio/3a/L1-jg-0__8.mp3", "t": "不解实脾，"}, {"f": "audio/3a/L1-jg-0__9.mp3", "t": "惟治肝也。"}, {"f": "audio/3a/L1-jg-0__10.mp3", "t": "夫肝之病，"}, {"f": "audio/3a/L1-jg-0__11.mp3", "t": "补用酸，"}, {"f": "audio/3a/L1-jg-0__12.mp3", "t": "助用焦苦，"}, {"f": "audio/3a/L1-jg-0__13.mp3", "t": "益用甘味之药调之。"}, {"f": "audio/3a/L1-jg-0__14.mp3", "t": "……肝虚则用此法，"}, {"f": "audio/3a/L1-jg-0__15.mp3", "t": "实则不在用之。"}], "L1-jg-1": [{"f": "audio/5c/L1-jg-1__0.mp3", "t": "问曰："}, {"f": "audio/5c/L1-jg-1__1.mp3", "t": "病有急当救里救表者，"}, {"f": "audio/5c/L1-jg-1__2.mp3", "t": "何谓也？"}, {"f": "audio/5c/L1-jg-1__3.mp3", "t": "师曰："}, {"f": "audio/5c/L1-jg-1__4.mp3", "t": "病，"}, {"f": "audio/5c/L1-jg-1__5.mp3", "t": "医下之，"}, {"f": "audio/5c/L1-jg-1__6.mp3", "t": "续得下利清谷不止，"}, {"f": "audio/5c/L1-jg-1__7.mp3", "t": "身体疼痛者，"}, {"f": "audio/5c/L1-jg-1__8.mp3", "t": "急当救里；"}, {"f": "audio/5c/L1-jg-1__9.mp3", "t": "后身体疼痛，"}, {"f": "audio/5c/L1-jg-1__10.mp3", "t": "清便自调者，"}, {"f": "audio/5c/L1-jg-1__11.mp3", "t": "急当救表也。"}], "L1-jg-2": [{"f": "audio/92/L1-jg-2__0.mp3", "t": "太阳病，"}, {"f": "audio/92/L1-jg-2__1.mp3", "t": "发热无汗，"}, {"f": "audio/92/L1-jg-2__2.mp3", "t": "反恶寒者，"}, {"f": "audio/92/L1-jg-2__3.mp3", "t": "名曰刚痉。"}, {"f": "audio/92/L1-jg-2__4.mp3", "t": "太阳病，"}, {"f": "audio/92/L1-jg-2__5.mp3", "t": "发热汗出，"}, {"f": "audio/92/L1-jg-2__6.mp3", "t": "而不恶寒，"}, {"f": "audio/92/L1-jg-2__7.mp3", "t": "名曰柔痉。"}], "L1-jg-3": [{"f": "audio/d1/L1-jg-3__0.mp3", "t": "太阳病，"}, {"f": "audio/d1/L1-jg-3__1.mp3", "t": "其证备，"}, {"f": "audio/d1/L1-jg-3__2.mp3", "t": "身体强，"}, {"f": "audio/d1/L1-jg-3__3.mp3", "t": "几几然，"}, {"f": "audio/d1/L1-jg-3__4.mp3", "t": "脉反沉迟，"}, {"f": "audio/d1/L1-jg-3__5.mp3", "t": "此为痉，"}, {"f": "audio/d1/L1-jg-3__6.mp3", "t": "栝楼桂枝汤主之。"}], "L1-jg-4": [{"f": "audio/c0/L1-jg-4__0.mp3", "t": "风湿相搏，"}, {"f": "audio/c0/L1-jg-4__1.mp3", "t": "一身尽疼痛，"}, {"f": "audio/c0/L1-jg-4__2.mp3", "t": "法当汗出而解，"}, {"f": "audio/c0/L1-jg-4__3.mp3", "t": "值天阴雨不止，"}, {"f": "audio/c0/L1-jg-4__4.mp3", "t": "医云此可发汗，"}, {"f": "audio/c0/L1-jg-4__5.mp3", "t": "汗之病不愈者，"}, {"f": "audio/c0/L1-jg-4__6.mp3", "t": "何也？"}, {"f": "audio/c0/L1-jg-4__7.mp3", "t": "盖发其汗，"}, {"f": "audio/c0/L1-jg-4__8.mp3", "t": "汗大出者，"}, {"f": "audio/c0/L1-jg-4__9.mp3", "t": "但风气去，"}, {"f": "audio/c0/L1-jg-4__10.mp3", "t": "湿气在，"}, {"f": "audio/c0/L1-jg-4__11.mp3", "t": "是故不愈也。"}, {"f": "audio/c0/L1-jg-4__12.mp3", "t": "若治风湿者，"}, {"f": "audio/c0/L1-jg-4__13.mp3", "t": "发其汗，"}, {"f": "audio/c0/L1-jg-4__14.mp3", "t": "但微微似欲出汗者，"}, {"f": "audio/c0/L1-jg-4__15.mp3", "t": "风湿俱去也。"}], "L1-jg-5": [{"f": "audio/f1/L1-jg-5__0.mp3", "t": "风湿脉浮身重，"}, {"f": "audio/f1/L1-jg-5__1.mp3", "t": "汗出恶风者，"}, {"f": "audio/f1/L1-jg-5__2.mp3", "t": "防己黄芪汤主之。"}], "L1-jg-6": [{"f": "audio/fd/L1-jg-6__0.mp3", "t": "风湿相搏，"}, {"f": "audio/fd/L1-jg-6__1.mp3", "t": "骨节疼烦，"}, {"f": "audio/fd/L1-jg-6__2.mp3", "t": "掣痛不得屈伸，"}, {"f": "audio/fd/L1-jg-6__3.mp3", "t": "近之则痛剧，"}, {"f": "audio/fd/L1-jg-6__4.mp3", "t": "汗出短气，"}, {"f": "audio/fd/L1-jg-6__5.mp3", "t": "小便不利，"}, {"f": "audio/fd/L1-jg-6__6.mp3", "t": "恶风不欲去衣，"}, {"f": "audio/fd/L1-jg-6__7.mp3", "t": "或身微肿者，"}, {"f": "audio/fd/L1-jg-6__8.mp3", "t": "甘草附子汤主之。"}], "L1-jg-7": [{"f": "audio/31/L1-jg-7__0.mp3", "t": "百合病者，"}, {"f": "audio/31/L1-jg-7__1.mp3", "t": "百脉一宗，"}, {"f": "audio/31/L1-jg-7__2.mp3", "t": "悉致其病也。"}, {"f": "audio/31/L1-jg-7__3.mp3", "t": "意欲食复不能食，"}, {"f": "audio/31/L1-jg-7__4.mp3", "t": "常默默，"}, {"f": "audio/31/L1-jg-7__5.mp3", "t": "欲卧不能卧，"}, {"f": "audio/31/L1-jg-7__6.mp3", "t": "欲行不能行，"}, {"f": "audio/31/L1-jg-7__7.mp3", "t": "饮食或有美时，"}, {"f": "audio/31/L1-jg-7__8.mp3", "t": "或有不用闻食臭时，"}, {"f": "audio/31/L1-jg-7__9.mp3", "t": "如寒无寒，"}, {"f": "audio/31/L1-jg-7__10.mp3", "t": "如热无热，"}, {"f": "audio/31/L1-jg-7__11.mp3", "t": "口苦，"}, {"f": "audio/31/L1-jg-7__12.mp3", "t": "小便赤，"}, {"f": "audio/31/L1-jg-7__13.mp3", "t": "诸药不能治，"}, {"f": "audio/31/L1-jg-7__14.mp3", "t": "得药则剧吐利，"}, {"f": "audio/31/L1-jg-7__15.mp3", "t": "如有神灵者，"}, {"f": "audio/31/L1-jg-7__16.mp3", "t": "身形如和，"}, {"f": "audio/31/L1-jg-7__17.mp3", "t": "其脉微数。"}], "L1-jg-8": [{"f": "audio/0e/L1-jg-8__0.mp3", "t": "百合病，"}, {"f": "audio/0e/L1-jg-8__1.mp3", "t": "不经吐下发汗，"}, {"f": "audio/0e/L1-jg-8__2.mp3", "t": "病形如初者，"}, {"f": "audio/0e/L1-jg-8__3.mp3", "t": "百合地黄汤主之。"}], "L1-jg-9": [{"f": "audio/8a/L1-jg-9__0.mp3", "t": "狐惑之为病，"}, {"f": "audio/8a/L1-jg-9__1.mp3", "t": "状如伤寒，"}, {"f": "audio/8a/L1-jg-9__2.mp3", "t": "默默欲眠，"}, {"f": "audio/8a/L1-jg-9__3.mp3", "t": "目不得闭，"}, {"f": "audio/8a/L1-jg-9__4.mp3", "t": "卧起不安，"}, {"f": "audio/8a/L1-jg-9__5.mp3", "t": "蚀于喉为惑，"}, {"f": "audio/8a/L1-jg-9__6.mp3", "t": "蚀于阴为狐，"}, {"f": "audio/8a/L1-jg-9__7.mp3", "t": "不欲饮食，"}, {"f": "audio/8a/L1-jg-9__8.mp3", "t": "恶闻食臭，"}, {"f": "audio/8a/L1-jg-9__9.mp3", "t": "其面目乍赤、"}, {"f": "audio/8a/L1-jg-9__10.mp3", "t": "乍黑、"}, {"f": "audio/8a/L1-jg-9__11.mp3", "t": "乍白，"}, {"f": "audio/8a/L1-jg-9__12.mp3", "t": "蚀于上部则声喝，"}, {"f": "audio/8a/L1-jg-9__13.mp3", "t": "甘草泻心汤主之。"}], "L1-jg-10": [{"f": "audio/48/L1-jg-10__0.mp3", "t": "师曰："}, {"f": "audio/48/L1-jg-10__1.mp3", "t": "疟脉自弦，"}, {"f": "audio/48/L1-jg-10__2.mp3", "t": "弦数者多热，"}, {"f": "audio/48/L1-jg-10__3.mp3", "t": "弦迟者多寒。"}], "L1-jg-11": [{"f": "audio/4d/L1-jg-11__0.mp3", "t": "温疟者，"}, {"f": "audio/4d/L1-jg-11__1.mp3", "t": "其脉如平，"}, {"f": "audio/4d/L1-jg-11__2.mp3", "t": "身无寒但热，"}, {"f": "audio/4d/L1-jg-11__3.mp3", "t": "骨节疼烦，"}, {"f": "audio/4d/L1-jg-11__4.mp3", "t": "时呕，"}, {"f": "audio/4d/L1-jg-11__5.mp3", "t": "白虎加桂枝汤主之。"}], "L1-jg-12": [{"f": "audio/fd/L1-jg-12__0.mp3", "t": "邪在于络，"}, {"f": "audio/fd/L1-jg-12__1.mp3", "t": "肌肤不仁；"}, {"f": "audio/fd/L1-jg-12__2.mp3", "t": "邪在于经，"}, {"f": "audio/fd/L1-jg-12__3.mp3", "t": "即重不胜；"}, {"f": "audio/fd/L1-jg-12__4.mp3", "t": "邪入于腑，"}, {"f": "audio/fd/L1-jg-12__5.mp3", "t": "即不识人；"}, {"f": "audio/fd/L1-jg-12__6.mp3", "t": "邪入于脏，"}, {"f": "audio/fd/L1-jg-12__7.mp3", "t": "舌即难言，"}, {"f": "audio/fd/L1-jg-12__8.mp3", "t": "口吐涎。"}], "L1-jg-13": [{"f": "audio/b3/L1-jg-13__0.mp3", "t": "诸肢节疼痛，"}, {"f": "audio/b3/L1-jg-13__1.mp3", "t": "身体魁羸，"}, {"f": "audio/b3/L1-jg-13__2.mp3", "t": "脚肿如脱，"}, {"f": "audio/b3/L1-jg-13__3.mp3", "t": "头眩短气，"}, {"f": "audio/b3/L1-jg-13__4.mp3", "t": "温温欲吐，"}, {"f": "audio/b3/L1-jg-13__5.mp3", "t": "桂枝芍药知母汤主之。"}], "L1-jg-14": [{"f": "audio/6c/L1-jg-14__0.mp3", "t": "血痹阴阳俱微，"}, {"f": "audio/6c/L1-jg-14__1.mp3", "t": "寸口关上微，"}, {"f": "audio/6c/L1-jg-14__2.mp3", "t": "尺中小紧，"}, {"f": "audio/6c/L1-jg-14__3.mp3", "t": "外证身体不仁，"}, {"f": "audio/6c/L1-jg-14__4.mp3", "t": "如风痹状，"}, {"f": "audio/6c/L1-jg-14__5.mp3", "t": "黄芪桂枝五物汤主之。"}], "L1-jg-15": [{"f": "audio/f0/L1-jg-15__0.mp3", "t": "夫男子平人，"}, {"f": "audio/f0/L1-jg-15__1.mp3", "t": "脉大为劳，"}, {"f": "audio/f0/L1-jg-15__2.mp3", "t": "极虚亦为劳。"}], "L1-jg-16": [{"f": "audio/7f/L1-jg-16__0.mp3", "t": "虚劳里急，"}, {"f": "audio/7f/L1-jg-16__1.mp3", "t": "悸，"}, {"f": "audio/7f/L1-jg-16__2.mp3", "t": "衄，"}, {"f": "audio/7f/L1-jg-16__3.mp3", "t": "腹中痛，"}, {"f": "audio/7f/L1-jg-16__4.mp3", "t": "梦失精，"}, {"f": "audio/7f/L1-jg-16__5.mp3", "t": "四肢酸疼，"}, {"f": "audio/7f/L1-jg-16__6.mp3", "t": "手足烦热，"}, {"f": "audio/7f/L1-jg-16__7.mp3", "t": "咽干口燥，"}, {"f": "audio/7f/L1-jg-16__8.mp3", "t": "小建中汤主之。"}], "L1-jg-17": [{"f": "audio/b9/L1-jg-17__0.mp3", "t": "虚劳腰痛，"}, {"f": "audio/b9/L1-jg-17__1.mp3", "t": "少腹拘急，"}, {"f": "audio/b9/L1-jg-17__2.mp3", "t": "小便不利者，"}, {"f": "audio/b9/L1-jg-17__3.mp3", "t": "八味肾气丸主之。"}], "L1-jg-18": [{"f": "audio/bd/L1-jg-18__0.mp3", "t": "虚劳虚烦不得眠，"}, {"f": "audio/bd/L1-jg-18__1.mp3", "t": "酸枣仁汤主之。"}], "L1-jg-19": [{"f": "audio/bb/L1-jg-19__0.mp3", "t": "五劳虚极羸瘦，"}, {"f": "audio/bb/L1-jg-19__1.mp3", "t": "腹满不能饮食，"}, {"f": "audio/bb/L1-jg-19__2.mp3", "t": "食伤、"}, {"f": "audio/bb/L1-jg-19__3.mp3", "t": "忧伤、"}, {"f": "audio/bb/L1-jg-19__4.mp3", "t": "饮伤、"}, {"f": "audio/bb/L1-jg-19__5.mp3", "t": "房室伤、"}, {"f": "audio/bb/L1-jg-19__6.mp3", "t": "饥伤、"}, {"f": "audio/bb/L1-jg-19__7.mp3", "t": "劳伤、"}, {"f": "audio/bb/L1-jg-19__8.mp3", "t": "经络营卫气伤，"}, {"f": "audio/bb/L1-jg-19__9.mp3", "t": "内有干血，"}, {"f": "audio/bb/L1-jg-19__10.mp3", "t": "肌肤甲错，"}, {"f": "audio/bb/L1-jg-19__11.mp3", "t": "两目黯黑。"}, {"f": "audio/bb/L1-jg-19__12.mp3", "t": "缓中补虚，"}, {"f": "audio/bb/L1-jg-19__13.mp3", "t": "大黄䗪虫丸主之。"}], "L1-jg-20": [{"f": "audio/07/L1-jg-20__0.mp3", "t": "肺痿吐涎沫而不咳者，"}, {"f": "audio/07/L1-jg-20__1.mp3", "t": "其人不渴，"}, {"f": "audio/07/L1-jg-20__2.mp3", "t": "必遗尿，"}, {"f": "audio/07/L1-jg-20__3.mp3", "t": "小便数，"}, {"f": "audio/07/L1-jg-20__4.mp3", "t": "所以然者，"}, {"f": "audio/07/L1-jg-20__5.mp3", "t": "以上虚不能制下故也。"}, {"f": "audio/07/L1-jg-20__6.mp3", "t": "此为肺中冷，"}, {"f": "audio/07/L1-jg-20__7.mp3", "t": "必眩，"}, {"f": "audio/07/L1-jg-20__8.mp3", "t": "多涎唾，"}, {"f": "audio/07/L1-jg-20__9.mp3", "t": "甘草干姜汤以温之。"}, {"f": "audio/07/L1-jg-20__10.mp3", "t": "若服汤已渴者，"}, {"f": "audio/07/L1-jg-20__11.mp3", "t": "属消渴。"}], "L1-jg-21": [{"f": "audio/36/L1-jg-21__0.mp3", "t": "大逆上气，"}, {"f": "audio/36/L1-jg-21__1.mp3", "t": "咽喉不利，"}, {"f": "audio/36/L1-jg-21__2.mp3", "t": "止逆下气者，"}, {"f": "audio/36/L1-jg-21__3.mp3", "t": "麦门冬汤主之。"}], "L1-jg-22": [{"f": "audio/11/L1-jg-22__0.mp3", "t": "咳而上气，"}, {"f": "audio/11/L1-jg-22__1.mp3", "t": "喉中水鸡声，"}, {"f": "audio/11/L1-jg-22__2.mp3", "t": "射干麻黄汤主之。"}], "L1-jg-23": [{"f": "audio/19/L1-jg-23__0.mp3", "t": "咳而上气，"}, {"f": "audio/19/L1-jg-23__1.mp3", "t": "此为肺胀，"}, {"f": "audio/19/L1-jg-23__2.mp3", "t": "其人喘，"}, {"f": "audio/19/L1-jg-23__3.mp3", "t": "目如脱状，"}, {"f": "audio/19/L1-jg-23__4.mp3", "t": "脉浮大者，"}, {"f": "audio/19/L1-jg-23__5.mp3", "t": "越婢加半夏汤主之。"}], "L1-jg-24": [{"f": "audio/8f/L1-jg-24__0.mp3", "t": "肺胀，"}, {"f": "audio/8f/L1-jg-24__1.mp3", "t": "咳而上气，"}, {"f": "audio/8f/L1-jg-24__2.mp3", "t": "烦躁而喘，"}, {"f": "audio/8f/L1-jg-24__3.mp3", "t": "脉浮者，"}, {"f": "audio/8f/L1-jg-24__4.mp3", "t": "心下有水，"}, {"f": "audio/8f/L1-jg-24__5.mp3", "t": "小青龙加石膏汤主之。"}], "L1-jg-25": [{"f": "audio/05/L1-jg-25__0.mp3", "t": "咳有微热，"}, {"f": "audio/05/L1-jg-25__1.mp3", "t": "烦满，"}, {"f": "audio/05/L1-jg-25__2.mp3", "t": "胸中甲错，"}, {"f": "audio/05/L1-jg-25__3.mp3", "t": "是为肺痈，"}, {"f": "audio/05/L1-jg-25__4.mp3", "t": "苇茎汤主之。"}], "L1-jg-26": [{"f": "audio/c0/L1-jg-26__0.mp3", "t": "奔豚病，"}, {"f": "audio/c0/L1-jg-26__1.mp3", "t": "从少腹起，"}, {"f": "audio/c0/L1-jg-26__2.mp3", "t": "上冲咽喉，"}, {"f": "audio/c0/L1-jg-26__3.mp3", "t": "发作欲死，"}, {"f": "audio/c0/L1-jg-26__4.mp3", "t": "复还止，"}, {"f": "audio/c0/L1-jg-26__5.mp3", "t": "皆从惊恐得之。"}], "L1-jg-27": [{"f": "audio/1f/L1-jg-27__0.mp3", "t": "奔豚气上冲胸，"}, {"f": "audio/1f/L1-jg-27__1.mp3", "t": "腹痛，"}, {"f": "audio/1f/L1-jg-27__2.mp3", "t": "往来寒热，"}, {"f": "audio/1f/L1-jg-27__3.mp3", "t": "奔豚汤主之。"}], "L1-jg-28": [{"f": "audio/ca/L1-jg-28__0.mp3", "t": "师曰："}, {"f": "audio/ca/L1-jg-28__1.mp3", "t": "夫脉当取太过不及，"}, {"f": "audio/ca/L1-jg-28__2.mp3", "t": "阳微阴弦，"}, {"f": "audio/ca/L1-jg-28__3.mp3", "t": "即胸痹而痛，"}, {"f": "audio/ca/L1-jg-28__4.mp3", "t": "所以然者，"}, {"f": "audio/ca/L1-jg-28__5.mp3", "t": "责其极虚也。"}, {"f": "audio/ca/L1-jg-28__6.mp3", "t": "今阳虚知在上焦，"}, {"f": "audio/ca/L1-jg-28__7.mp3", "t": "所以胸痹心痛者，"}, {"f": "audio/ca/L1-jg-28__8.mp3", "t": "以其阴弦故也。"}], "L1-jg-29": [{"f": "audio/68/L1-jg-29__0.mp3", "t": "胸痹之病，"}, {"f": "audio/68/L1-jg-29__1.mp3", "t": "喘息咳唾，"}, {"f": "audio/68/L1-jg-29__2.mp3", "t": "胸背痛，"}, {"f": "audio/68/L1-jg-29__3.mp3", "t": "短气，"}, {"f": "audio/68/L1-jg-29__4.mp3", "t": "寸口脉沉而迟，"}, {"f": "audio/68/L1-jg-29__5.mp3", "t": "关上小紧数，"}, {"f": "audio/68/L1-jg-29__6.mp3", "t": "栝楼薤白白酒汤主之。"}], "L1-jg-30": [{"f": "audio/e1/L1-jg-30__0.mp3", "t": "胸痹不得卧，"}, {"f": "audio/e1/L1-jg-30__1.mp3", "t": "心痛彻背者，"}, {"f": "audio/e1/L1-jg-30__2.mp3", "t": "栝楼薤白半夏汤主之。"}], "L1-jg-31": [{"f": "audio/80/L1-jg-31__0.mp3", "t": "胸痹，"}, {"f": "audio/80/L1-jg-31__1.mp3", "t": "心中痞气，"}, {"f": "audio/80/L1-jg-31__2.mp3", "t": "气结在胸，"}, {"f": "audio/80/L1-jg-31__3.mp3", "t": "胸满，"}, {"f": "audio/80/L1-jg-31__4.mp3", "t": "胁下逆抢心，"}, {"f": "audio/80/L1-jg-31__5.mp3", "t": "枳实薤白桂枝汤主之，"}, {"f": "audio/80/L1-jg-31__6.mp3", "t": "人参汤亦主之。"}], "L1-jg-32": [{"f": "audio/a6/L1-jg-32__0.mp3", "t": "心痛彻背，"}, {"f": "audio/a6/L1-jg-32__1.mp3", "t": "背痛彻心，"}, {"f": "audio/a6/L1-jg-32__2.mp3", "t": "乌头赤石脂丸主之。"}], "L1-jg-33": [{"f": "audio/75/L1-jg-33__0.mp3", "t": "病腹满，"}, {"f": "audio/75/L1-jg-33__1.mp3", "t": "发热十日，"}, {"f": "audio/75/L1-jg-33__2.mp3", "t": "脉浮而数，"}, {"f": "audio/75/L1-jg-33__3.mp3", "t": "饮食如故，"}, {"f": "audio/75/L1-jg-33__4.mp3", "t": "厚朴七物汤主之。"}], "L1-jg-34": [{"f": "audio/f2/L1-jg-34__0.mp3", "t": "腹满不减，"}, {"f": "audio/f2/L1-jg-34__1.mp3", "t": "减不足言，"}, {"f": "audio/f2/L1-jg-34__2.mp3", "t": "当须下之，"}, {"f": "audio/f2/L1-jg-34__3.mp3", "t": "宜大承气汤。"}], "L1-jg-35": [{"f": "audio/f5/L1-jg-35__0.mp3", "t": "心胸中大寒痛，"}, {"f": "audio/f5/L1-jg-35__1.mp3", "t": "呕不能饮食，"}, {"f": "audio/f5/L1-jg-35__2.mp3", "t": "腹中寒，"}, {"f": "audio/f5/L1-jg-35__3.mp3", "t": "上冲皮起，"}, {"f": "audio/f5/L1-jg-35__4.mp3", "t": "出见有头足，"}, {"f": "audio/f5/L1-jg-35__5.mp3", "t": "上下痛而不可触近，"}, {"f": "audio/f5/L1-jg-35__6.mp3", "t": "大建中汤主之。"}], "L1-jg-36": [{"f": "audio/f6/L1-jg-36__0.mp3", "t": "胁下偏痛，"}, {"f": "audio/f6/L1-jg-36__1.mp3", "t": "发热，"}, {"f": "audio/f6/L1-jg-36__2.mp3", "t": "其脉紧弦，"}, {"f": "audio/f6/L1-jg-36__3.mp3", "t": "此寒也，"}, {"f": "audio/f6/L1-jg-36__4.mp3", "t": "以温药下之，"}, {"f": "audio/f6/L1-jg-36__5.mp3", "t": "宜大黄附子汤。"}], "L1-jg-37": [{"f": "audio/4b/L1-jg-37__0.mp3", "t": "寒疝腹中痛，"}, {"f": "audio/4b/L1-jg-37__1.mp3", "t": "及胁痛里急者，"}, {"f": "audio/4b/L1-jg-37__2.mp3", "t": "当归生姜羊肉汤主之。"}], "L1-jg-38": [{"f": "audio/f9/L1-jg-38__0.mp3", "t": "肝着，"}, {"f": "audio/f9/L1-jg-38__1.mp3", "t": "其人常欲蹈其胸上，"}, {"f": "audio/f9/L1-jg-38__2.mp3", "t": "先未苦时，"}, {"f": "audio/f9/L1-jg-38__3.mp3", "t": "但欲饮热，"}, {"f": "audio/f9/L1-jg-38__4.mp3", "t": "旋覆花汤主之。"}], "L1-jg-39": [{"f": "audio/05/L1-jg-39__0.mp3", "t": "肾着之病，"}, {"f": "audio/05/L1-jg-39__1.mp3", "t": "其人身体重，"}, {"f": "audio/05/L1-jg-39__2.mp3", "t": "腰中冷，"}, {"f": "audio/05/L1-jg-39__3.mp3", "t": "如坐水中，"}, {"f": "audio/05/L1-jg-39__4.mp3", "t": "形如水状，"}, {"f": "audio/05/L1-jg-39__5.mp3", "t": "反不渴，"}, {"f": "audio/05/L1-jg-39__6.mp3", "t": "小便自利，"}, {"f": "audio/05/L1-jg-39__7.mp3", "t": "饮食如故，"}, {"f": "audio/05/L1-jg-39__8.mp3", "t": "病属下焦，"}, {"f": "audio/05/L1-jg-39__9.mp3", "t": "身劳汗出，"}, {"f": "audio/05/L1-jg-39__10.mp3", "t": "衣里冷湿，"}, {"f": "audio/05/L1-jg-39__11.mp3", "t": "久久得之，"}, {"f": "audio/05/L1-jg-39__12.mp3", "t": "腰以下冷痛，"}, {"f": "audio/05/L1-jg-39__13.mp3", "t": "腹重如带五千钱，"}, {"f": "audio/05/L1-jg-39__14.mp3", "t": "甘姜苓术汤主之。"}], "L1-jg-40": [{"f": "audio/7b/L1-jg-40__0.mp3", "t": "夫饮有四，"}, {"f": "audio/7b/L1-jg-40__1.mp3", "t": "何谓也？"}, {"f": "audio/7b/L1-jg-40__2.mp3", "t": "师曰："}, {"f": "audio/7b/L1-jg-40__3.mp3", "t": "有痰饮，"}, {"f": "audio/7b/L1-jg-40__4.mp3", "t": "有悬饮，"}, {"f": "audio/7b/L1-jg-40__5.mp3", "t": "有溢饮，"}, {"f": "audio/7b/L1-jg-40__6.mp3", "t": "有支饮。"}], "L1-jg-41": [{"f": "audio/4d/L1-jg-41__0.mp3", "t": "其人素盛今瘦，"}, {"f": "audio/4d/L1-jg-41__1.mp3", "t": "水走肠间，"}, {"f": "audio/4d/L1-jg-41__2.mp3", "t": "沥沥有声，"}, {"f": "audio/4d/L1-jg-41__3.mp3", "t": "谓之痰饮；"}, {"f": "audio/4d/L1-jg-41__4.mp3", "t": "饮后水流在胁下，"}, {"f": "audio/4d/L1-jg-41__5.mp3", "t": "咳唾引痛，"}, {"f": "audio/4d/L1-jg-41__6.mp3", "t": "谓之悬饮；"}, {"f": "audio/4d/L1-jg-41__7.mp3", "t": "饮水流行，"}, {"f": "audio/4d/L1-jg-41__8.mp3", "t": "归于四肢，"}, {"f": "audio/4d/L1-jg-41__9.mp3", "t": "当汗出而不汗出，"}, {"f": "audio/4d/L1-jg-41__10.mp3", "t": "身体疼重，"}, {"f": "audio/4d/L1-jg-41__11.mp3", "t": "谓之溢饮；"}, {"f": "audio/4d/L1-jg-41__12.mp3", "t": "咳逆倚息，"}, {"f": "audio/4d/L1-jg-41__13.mp3", "t": "短气不得卧，"}, {"f": "audio/4d/L1-jg-41__14.mp3", "t": "其形如肿，"}, {"f": "audio/4d/L1-jg-41__15.mp3", "t": "谓之支饮。"}], "L1-jg-42": [{"f": "audio/a8/L1-jg-42__0.mp3", "t": "病痰饮者，"}, {"f": "audio/a8/L1-jg-42__1.mp3", "t": "当以温药和之。"}], "L1-jg-43": [{"f": "audio/be/L1-jg-43__0.mp3", "t": "心下有痰饮，"}, {"f": "audio/be/L1-jg-43__1.mp3", "t": "胸胁支满，"}, {"f": "audio/be/L1-jg-43__2.mp3", "t": "目眩，"}, {"f": "audio/be/L1-jg-43__3.mp3", "t": "苓桂术甘汤主之。"}], "L1-jg-44": [{"f": "audio/4d/L1-jg-44__0.mp3", "t": "脉沉而弦者，"}, {"f": "audio/4d/L1-jg-44__1.mp3", "t": "悬饮内痛，"}, {"f": "audio/4d/L1-jg-44__2.mp3", "t": "十枣汤主之。"}], "L1-jg-45": [{"f": "audio/ba/L1-jg-45__0.mp3", "t": "病溢饮者，"}, {"f": "audio/ba/L1-jg-45__1.mp3", "t": "当发其汗，"}, {"f": "audio/ba/L1-jg-45__2.mp3", "t": "大青龙汤主之，"}, {"f": "audio/ba/L1-jg-45__3.mp3", "t": "小青龙汤亦主之。"}], "L1-jg-46": [{"f": "audio/20/L1-jg-46__0.mp3", "t": "膈间支饮，"}, {"f": "audio/20/L1-jg-46__1.mp3", "t": "其人喘满，"}, {"f": "audio/20/L1-jg-46__2.mp3", "t": "心下痞坚，"}, {"f": "audio/20/L1-jg-46__3.mp3", "t": "面色黧黑，"}, {"f": "audio/20/L1-jg-46__4.mp3", "t": "其脉沉紧，"}, {"f": "audio/20/L1-jg-46__5.mp3", "t": "得之数十日，"}, {"f": "audio/20/L1-jg-46__6.mp3", "t": "医吐下之不愈，"}, {"f": "audio/20/L1-jg-46__7.mp3", "t": "木防己汤主之。"}], "L1-jg-47": [{"f": "audio/50/L1-jg-47__0.mp3", "t": "心下有支饮，"}, {"f": "audio/50/L1-jg-47__1.mp3", "t": "其人苦冒眩，"}, {"f": "audio/50/L1-jg-47__2.mp3", "t": "泽泻汤主之。"}], "L1-jg-48": [{"f": "audio/28/L1-jg-48__0.mp3", "t": "支饮胸满者，"}, {"f": "audio/28/L1-jg-48__1.mp3", "t": "厚朴大黄汤主之。"}], "L1-jg-49": [{"f": "audio/9e/L1-jg-49__0.mp3", "t": "腹满，"}, {"f": "audio/9e/L1-jg-49__1.mp3", "t": "口舌干燥，"}, {"f": "audio/9e/L1-jg-49__2.mp3", "t": "此肠间有水气，"}, {"f": "audio/9e/L1-jg-49__3.mp3", "t": "己椒苈黄丸主之。"}], "L1-jg-50": [{"f": "audio/ee/L1-jg-50__0.mp3", "t": "男子消渴，"}, {"f": "audio/ee/L1-jg-50__1.mp3", "t": "小便反多，"}, {"f": "audio/ee/L1-jg-50__2.mp3", "t": "以饮一斗，"}, {"f": "audio/ee/L1-jg-50__3.mp3", "t": "小便一斗，"}, {"f": "audio/ee/L1-jg-50__4.mp3", "t": "肾气丸主之。"}], "L1-jg-51": [{"f": "audio/46/L1-jg-51__0.mp3", "t": "小便不利者，"}, {"f": "audio/46/L1-jg-51__1.mp3", "t": "有水气，"}, {"f": "audio/46/L1-jg-51__2.mp3", "t": "其人若渴，"}, {"f": "audio/46/L1-jg-51__3.mp3", "t": "栝楼瞿麦丸主之。"}], "L1-jg-52": [{"f": "audio/24/L1-jg-52__0.mp3", "t": "师曰："}, {"f": "audio/24/L1-jg-52__1.mp3", "t": "病有风水、"}, {"f": "audio/24/L1-jg-52__2.mp3", "t": "有皮水、"}, {"f": "audio/24/L1-jg-52__3.mp3", "t": "有正水、"}, {"f": "audio/24/L1-jg-52__4.mp3", "t": "有石水、"}, {"f": "audio/24/L1-jg-52__5.mp3", "t": "有黄汗。"}], "L1-jg-53": [{"f": "audio/32/L1-jg-53__0.mp3", "t": "脉得诸沉，"}, {"f": "audio/32/L1-jg-53__1.mp3", "t": "当责有水，"}, {"f": "audio/32/L1-jg-53__2.mp3", "t": "身体肿重。"}], "L1-jg-54": [{"f": "audio/78/L1-jg-54__0.mp3", "t": "诸有水者，"}, {"f": "audio/78/L1-jg-54__1.mp3", "t": "腰以下肿，"}, {"f": "audio/78/L1-jg-54__2.mp3", "t": "当利小便；"}, {"f": "audio/78/L1-jg-54__3.mp3", "t": "腰以上肿，"}, {"f": "audio/78/L1-jg-54__4.mp3", "t": "当发汗乃愈。"}], "L1-jg-55": [{"f": "audio/69/L1-jg-55__0.mp3", "t": "风水，"}, {"f": "audio/69/L1-jg-55__1.mp3", "t": "脉浮身重，"}, {"f": "audio/69/L1-jg-55__2.mp3", "t": "汗出恶风者，"}, {"f": "audio/69/L1-jg-55__3.mp3", "t": "防己黄芪汤主之。"}], "L1-jg-56": [{"f": "audio/ec/L1-jg-56__0.mp3", "t": "风水恶风，"}, {"f": "audio/ec/L1-jg-56__1.mp3", "t": "一身悉肿，"}, {"f": "audio/ec/L1-jg-56__2.mp3", "t": "脉浮不渴，"}, {"f": "audio/ec/L1-jg-56__3.mp3", "t": "续自汗出，"}, {"f": "audio/ec/L1-jg-56__4.mp3", "t": "无大热，"}, {"f": "audio/ec/L1-jg-56__5.mp3", "t": "越婢汤主之。"}], "L1-jg-57": [{"f": "audio/7a/L1-jg-57__0.mp3", "t": "皮水为病，"}, {"f": "audio/7a/L1-jg-57__1.mp3", "t": "四肢肿，"}, {"f": "audio/7a/L1-jg-57__2.mp3", "t": "水气在皮肤中，"}, {"f": "audio/7a/L1-jg-57__3.mp3", "t": "四肢聂聂动者，"}, {"f": "audio/7a/L1-jg-57__4.mp3", "t": "防己茯苓汤主之。"}], "L1-jg-58": [{"f": "audio/e5/L1-jg-58__0.mp3", "t": "里水，"}, {"f": "audio/e5/L1-jg-58__1.mp3", "t": "越婢加术汤主之，"}, {"f": "audio/e5/L1-jg-58__2.mp3", "t": "甘草麻黄汤亦主之。"}], "L1-jg-59": [{"f": "audio/dd/L1-jg-59__0.mp3", "t": "水之为病，"}, {"f": "audio/dd/L1-jg-59__1.mp3", "t": "其脉沉小，"}, {"f": "audio/dd/L1-jg-59__2.mp3", "t": "属少阴；"}, {"f": "audio/dd/L1-jg-59__3.mp3", "t": "浮者为风；"}, {"f": "audio/dd/L1-jg-59__4.mp3", "t": "无水虚胀者为气；"}, {"f": "audio/dd/L1-jg-59__5.mp3", "t": "水，"}, {"f": "audio/dd/L1-jg-59__6.mp3", "t": "发其汗即已。"}, {"f": "audio/dd/L1-jg-59__7.mp3", "t": "脉沉者宜麻黄附子汤；"}, {"f": "audio/dd/L1-jg-59__8.mp3", "t": "浮者，"}, {"f": "audio/dd/L1-jg-59__9.mp3", "t": "宜杏子汤。"}], "L1-jg-60": [{"f": "audio/16/L1-jg-60__0.mp3", "t": "寸口脉浮而缓，"}, {"f": "audio/16/L1-jg-60__1.mp3", "t": "浮则为风，"}, {"f": "audio/16/L1-jg-60__2.mp3", "t": "缓则为痹。"}, {"f": "audio/16/L1-jg-60__3.mp3", "t": "痹非中风，"}, {"f": "audio/16/L1-jg-60__4.mp3", "t": "四肢苦烦，"}, {"f": "audio/16/L1-jg-60__5.mp3", "t": "脾色必黄，"}, {"f": "audio/16/L1-jg-60__6.mp3", "t": "瘀热以行。"}], "L1-jg-61": [{"f": "audio/18/L1-jg-61__0.mp3", "t": "趺阳脉紧而数，"}, {"f": "audio/18/L1-jg-61__1.mp3", "t": "数则为热，"}, {"f": "audio/18/L1-jg-61__2.mp3", "t": "热则消谷；"}, {"f": "audio/18/L1-jg-61__3.mp3", "t": "紧则为寒，"}, {"f": "audio/18/L1-jg-61__4.mp3", "t": "食即为满。"}, {"f": "audio/18/L1-jg-61__5.mp3", "t": "尺脉浮为伤肾，"}, {"f": "audio/18/L1-jg-61__6.mp3", "t": "趺阳脉紧为伤脾。"}, {"f": "audio/18/L1-jg-61__7.mp3", "t": "风寒相搏，"}, {"f": "audio/18/L1-jg-61__8.mp3", "t": "食谷即眩，"}, {"f": "audio/18/L1-jg-61__9.mp3", "t": "谷气不消，"}, {"f": "audio/18/L1-jg-61__10.mp3", "t": "胃中苦浊，"}, {"f": "audio/18/L1-jg-61__11.mp3", "t": "浊气下流，"}, {"f": "audio/18/L1-jg-61__12.mp3", "t": "小便不通……身体尽黄，"}, {"f": "audio/18/L1-jg-61__13.mp3", "t": "名曰谷疸。"}, {"f": "audio/18/L1-jg-61__14.mp3", "t": "额上黑，"}, {"f": "audio/18/L1-jg-61__15.mp3", "t": "微汗出，"}, {"f": "audio/18/L1-jg-61__16.mp3", "t": "手足中热，"}, {"f": "audio/18/L1-jg-61__17.mp3", "t": "薄暮即发，"}, {"f": "audio/18/L1-jg-61__18.mp3", "t": "膀胱急，"}, {"f": "audio/18/L1-jg-61__19.mp3", "t": "小便自利，"}, {"f": "audio/18/L1-jg-61__20.mp3", "t": "名曰女劳疸。"}, {"f": "audio/18/L1-jg-61__21.mp3", "t": "腹如水状，"}, {"f": "audio/18/L1-jg-61__22.mp3", "t": "不治。"}, {"f": "audio/18/L1-jg-61__23.mp3", "t": "心中懊憹而热，"}, {"f": "audio/18/L1-jg-61__24.mp3", "t": "不能食，"}, {"f": "audio/18/L1-jg-61__25.mp3", "t": "时欲吐，"}, {"f": "audio/18/L1-jg-61__26.mp3", "t": "名曰酒疸。"}], "L1-jg-62": [{"f": "audio/dc/L1-jg-62__0.mp3", "t": "谷疸之为病，"}, {"f": "audio/dc/L1-jg-62__1.mp3", "t": "寒热不食，"}, {"f": "audio/dc/L1-jg-62__2.mp3", "t": "食即头眩，"}, {"f": "audio/dc/L1-jg-62__3.mp3", "t": "心胸不安，"}, {"f": "audio/dc/L1-jg-62__4.mp3", "t": "久久发黄为谷疸，"}, {"f": "audio/dc/L1-jg-62__5.mp3", "t": "茵陈蒿汤主之。"}], "L1-jg-63": [{"f": "audio/f4/L1-jg-63__0.mp3", "t": "酒黄疸，"}, {"f": "audio/f4/L1-jg-63__1.mp3", "t": "心中懊憹，"}, {"f": "audio/f4/L1-jg-63__2.mp3", "t": "或热痛，"}, {"f": "audio/f4/L1-jg-63__3.mp3", "t": "栀子大黄汤主之。"}], "L1-jg-64": [{"f": "audio/8f/L1-jg-64__0.mp3", "t": "诸病黄家，"}, {"f": "audio/8f/L1-jg-64__1.mp3", "t": "但利其小便。"}, {"f": "audio/8f/L1-jg-64__2.mp3", "t": "假令脉浮，"}, {"f": "audio/8f/L1-jg-64__3.mp3", "t": "当以汗解之，"}, {"f": "audio/8f/L1-jg-64__4.mp3", "t": "宜桂枝加黄芪汤主之。"}], "L1-jg-65": [{"f": "audio/73/L1-jg-65__0.mp3", "t": "病人胸满，"}, {"f": "audio/73/L1-jg-65__1.mp3", "t": "唇痿舌青，"}, {"f": "audio/73/L1-jg-65__2.mp3", "t": "口燥，"}, {"f": "audio/73/L1-jg-65__3.mp3", "t": "但欲漱水不欲咽，"}, {"f": "audio/73/L1-jg-65__4.mp3", "t": "无寒热，"}, {"f": "audio/73/L1-jg-65__5.mp3", "t": "脉微大来迟，"}, {"f": "audio/73/L1-jg-65__6.mp3", "t": "腹不满，"}, {"f": "audio/73/L1-jg-65__7.mp3", "t": "其人言我满，"}, {"f": "audio/73/L1-jg-65__8.mp3", "t": "为有瘀血。"}], "L1-jg-66": [{"f": "audio/ee/L1-jg-66__0.mp3", "t": "火邪者，"}, {"f": "audio/ee/L1-jg-66__1.mp3", "t": "桂枝去芍药加蜀漆牡蛎龙骨救逆汤主之。"}, {"f": "audio/ee/L1-jg-66__2.mp3", "t": "心下悸者，"}, {"f": "audio/ee/L1-jg-66__3.mp3", "t": "半夏麻黄丸主之。"}], "L1-jg-67": [{"f": "audio/73/L1-jg-67__0.mp3", "t": "下血，"}, {"f": "audio/73/L1-jg-67__1.mp3", "t": "先便后血，"}, {"f": "audio/73/L1-jg-67__2.mp3", "t": "此远血也，"}, {"f": "audio/73/L1-jg-67__3.mp3", "t": "黄土汤主之。"}], "L1-jg-68": [{"f": "audio/f2/L1-jg-68__0.mp3", "t": "下血，"}, {"f": "audio/f2/L1-jg-68__1.mp3", "t": "先血后便，"}, {"f": "audio/f2/L1-jg-68__2.mp3", "t": "此近血也，"}, {"f": "audio/f2/L1-jg-68__3.mp3", "t": "赤小豆当归散主之。"}], "L1-jg-69": [{"f": "audio/c2/L1-jg-69__0.mp3", "t": "诸呕吐，"}, {"f": "audio/c2/L1-jg-69__1.mp3", "t": "谷不得下者，"}, {"f": "audio/c2/L1-jg-69__2.mp3", "t": "小半夏汤主之。"}], "L1-jg-70": [{"f": "audio/52/L1-jg-70__0.mp3", "t": "食已即吐者，"}, {"f": "audio/52/L1-jg-70__1.mp3", "t": "大黄甘草汤主之。"}], "L1-jg-71": [{"f": "audio/cd/L1-jg-71__0.mp3", "t": "干呕，"}, {"f": "audio/cd/L1-jg-71__1.mp3", "t": "吐逆，"}, {"f": "audio/cd/L1-jg-71__2.mp3", "t": "吐涎沫，"}, {"f": "audio/cd/L1-jg-71__3.mp3", "t": "半夏干姜散主之。"}], "L1-jg-72": [{"f": "audio/46/L1-jg-72__0.mp3", "t": "病人胸中似喘不喘，"}, {"f": "audio/46/L1-jg-72__1.mp3", "t": "似呕不呕，"}, {"f": "audio/46/L1-jg-72__2.mp3", "t": "似哕不哕，"}, {"f": "audio/46/L1-jg-72__3.mp3", "t": "彻心中愦愦然无奈者，"}, {"f": "audio/46/L1-jg-72__4.mp3", "t": "生姜半夏汤主之。"}], "L1-jg-73": [{"f": "audio/1f/L1-jg-73__0.mp3", "t": "胃反呕吐者，"}, {"f": "audio/1f/L1-jg-73__1.mp3", "t": "大半夏汤主之。"}], "L1-jg-74": [{"f": "audio/8a/L1-jg-74__0.mp3", "t": "哕逆者，"}, {"f": "audio/8a/L1-jg-74__1.mp3", "t": "橘皮竹茹汤主之。"}], "L1-jg-75": [{"f": "audio/1b/L1-jg-75__0.mp3", "t": "肠痈者，"}, {"f": "audio/1b/L1-jg-75__1.mp3", "t": "少腹肿痞，"}, {"f": "audio/1b/L1-jg-75__2.mp3", "t": "按之即痛如淋，"}, {"f": "audio/1b/L1-jg-75__3.mp3", "t": "小便自调，"}, {"f": "audio/1b/L1-jg-75__4.mp3", "t": "时时发热，"}, {"f": "audio/1b/L1-jg-75__5.mp3", "t": "自汗出，"}, {"f": "audio/1b/L1-jg-75__6.mp3", "t": "复恶寒。"}, {"f": "audio/1b/L1-jg-75__7.mp3", "t": "其脉迟紧者，"}, {"f": "audio/1b/L1-jg-75__8.mp3", "t": "脓未成，"}, {"f": "audio/1b/L1-jg-75__9.mp3", "t": "可下之，"}, {"f": "audio/1b/L1-jg-75__10.mp3", "t": "当有血；"}, {"f": "audio/1b/L1-jg-75__11.mp3", "t": "脉洪数者，"}, {"f": "audio/1b/L1-jg-75__12.mp3", "t": "脓已成，"}, {"f": "audio/1b/L1-jg-75__13.mp3", "t": "不可下也，"}, {"f": "audio/1b/L1-jg-75__14.mp3", "t": "大黄牡丹汤主之。"}], "L1-jg-76": [{"f": "audio/a1/L1-jg-76__0.mp3", "t": "妇人宿有癥病，"}, {"f": "audio/a1/L1-jg-76__1.mp3", "t": "经断未及三月，"}, {"f": "audio/a1/L1-jg-76__2.mp3", "t": "而得漏下不止，"}, {"f": "audio/a1/L1-jg-76__3.mp3", "t": "胎动在脐上者，"}, {"f": "audio/a1/L1-jg-76__4.mp3", "t": "为癥痼害。"}, {"f": "audio/a1/L1-jg-76__5.mp3", "t": "妊娠六月动者，"}, {"f": "audio/a1/L1-jg-76__6.mp3", "t": "前三月经水利时，"}, {"f": "audio/a1/L1-jg-76__7.mp3", "t": "胎也。"}, {"f": "audio/a1/L1-jg-76__8.mp3", "t": "下血者，"}, {"f": "audio/a1/L1-jg-76__9.mp3", "t": "后断三月衃也。"}, {"f": "audio/a1/L1-jg-76__10.mp3", "t": "所以血不止者，"}, {"f": "audio/a1/L1-jg-76__11.mp3", "t": "其癥不去故也，"}, {"f": "audio/a1/L1-jg-76__12.mp3", "t": "当下其癥，"}, {"f": "audio/a1/L1-jg-76__13.mp3", "t": "桂枝茯苓丸主之。"}], "L1-jg-77": [{"f": "audio/f9/L1-jg-77__0.mp3", "t": "妇人有漏下者，"}, {"f": "audio/f9/L1-jg-77__1.mp3", "t": "有半产后因续下血都不绝者，"}, {"f": "audio/f9/L1-jg-77__2.mp3", "t": "有妊娠下血者，"}, {"f": "audio/f9/L1-jg-77__3.mp3", "t": "假令妊娠腹中痛，"}, {"f": "audio/f9/L1-jg-77__4.mp3", "t": "为胞阻，"}, {"f": "audio/f9/L1-jg-77__5.mp3", "t": "胶艾汤主之。"}], "L1-jg-78": [{"f": "audio/84/L1-jg-78__0.mp3", "t": "妇人怀妊，"}, {"f": "audio/84/L1-jg-78__1.mp3", "t": "腹中㽲痛，"}, {"f": "audio/84/L1-jg-78__2.mp3", "t": "当归芍药散主之。"}], "L1-jg-79": [{"f": "audio/32/L1-jg-79__0.mp3", "t": "妊娠呕吐不止，"}, {"f": "audio/32/L1-jg-79__1.mp3", "t": "干姜人参半夏丸主之。"}], "L1-jg-80": [{"f": "audio/b7/L1-jg-80__0.mp3", "t": "妊娠小便难，"}, {"f": "audio/b7/L1-jg-80__1.mp3", "t": "饮食如故，"}, {"f": "audio/b7/L1-jg-80__2.mp3", "t": "当归贝母苦参丸主之。"}], "L1-jg-81": [{"f": "audio/52/L1-jg-81__0.mp3", "t": "妇人妊娠，"}, {"f": "audio/52/L1-jg-81__1.mp3", "t": "宜常服当归散主之。"}], "L1-jg-82": [{"f": "audio/04/L1-jg-82__0.mp3", "t": "新产妇人有三病，"}, {"f": "audio/04/L1-jg-82__1.mp3", "t": "一者病痉，"}, {"f": "audio/04/L1-jg-82__2.mp3", "t": "二者病郁冒，"}, {"f": "audio/04/L1-jg-82__3.mp3", "t": "三者大便难，"}, {"f": "audio/04/L1-jg-82__4.mp3", "t": "何谓也？"}, {"f": "audio/04/L1-jg-82__5.mp3", "t": "师曰："}, {"f": "audio/04/L1-jg-82__6.mp3", "t": "新产血虚，"}, {"f": "audio/04/L1-jg-82__7.mp3", "t": "多汗出，"}, {"f": "audio/04/L1-jg-82__8.mp3", "t": "喜中风，"}, {"f": "audio/04/L1-jg-82__9.mp3", "t": "故令病痉；"}, {"f": "audio/04/L1-jg-82__10.mp3", "t": "亡血复汗，"}, {"f": "audio/04/L1-jg-82__11.mp3", "t": "寒多，"}, {"f": "audio/04/L1-jg-82__12.mp3", "t": "故令郁冒；"}, {"f": "audio/04/L1-jg-82__13.mp3", "t": "亡津液，"}, {"f": "audio/04/L1-jg-82__14.mp3", "t": "胃燥，"}, {"f": "audio/04/L1-jg-82__15.mp3", "t": "故大便难。"}], "L1-jg-83": [{"f": "audio/cc/L1-jg-83__0.mp3", "t": "产后腹中㽲痛，"}, {"f": "audio/cc/L1-jg-83__1.mp3", "t": "当归生姜羊肉汤主之。"}], "L1-jg-84": [{"f": "audio/56/L1-jg-84__0.mp3", "t": "产后腹痛，"}, {"f": "audio/56/L1-jg-84__1.mp3", "t": "烦满不得卧，"}, {"f": "audio/56/L1-jg-84__2.mp3", "t": "枳实芍药散主之。"}], "L1-jg-85": [{"f": "audio/24/L1-jg-85__0.mp3", "t": "妇人咽中如有炙脔，"}, {"f": "audio/24/L1-jg-85__1.mp3", "t": "半夏厚朴汤主之。"}], "L1-jg-86": [{"f": "audio/56/L1-jg-86__0.mp3", "t": "妇人脏躁，"}, {"f": "audio/56/L1-jg-86__1.mp3", "t": "喜悲伤欲哭，"}, {"f": "audio/56/L1-jg-86__2.mp3", "t": "象如神灵所作，"}, {"f": "audio/56/L1-jg-86__3.mp3", "t": "数欠伸，"}, {"f": "audio/56/L1-jg-86__4.mp3", "t": "甘麦大枣汤主之。"}], "L1-jg-87": [{"f": "audio/1e/L1-jg-87__0.mp3", "t": "妇人陷经，"}, {"f": "audio/1e/L1-jg-87__1.mp3", "t": "漏下黑不解，"}, {"f": "audio/1e/L1-jg-87__2.mp3", "t": "胶姜汤主之。"}], "L1-jg-88": [{"f": "audio/da/L1-jg-88__0.mp3", "t": "妇人少腹满如敦状，"}, {"f": "audio/da/L1-jg-88__1.mp3", "t": "小便微难而不渴，"}, {"f": "audio/da/L1-jg-88__2.mp3", "t": "生后者，"}, {"f": "audio/da/L1-jg-88__3.mp3", "t": "此为水与血并结在血室也，"}, {"f": "audio/da/L1-jg-88__4.mp3", "t": "大黄甘遂汤主之。"}], "L1-wb-0": [{"f": "audio/68/L1-wb-0__0.mp3", "t": "温邪上受，"}, {"f": "audio/68/L1-wb-0__1.mp3", "t": "首先犯肺，"}, {"f": "audio/68/L1-wb-0__2.mp3", "t": "逆传心包。"}, {"f": "audio/68/L1-wb-0__3.mp3", "t": "肺主气属卫，"}, {"f": "audio/68/L1-wb-0__4.mp3", "t": "心主血属营。"}, {"f": "audio/68/L1-wb-0__5.mp3", "t": "辨营卫气血虽与伤寒同，"}, {"f": "audio/68/L1-wb-0__6.mp3", "t": "若论治法则与伤寒大异也。"}], "L1-wb-1": [{"f": "audio/05/L1-wb-1__0.mp3", "t": "盖伤寒之邪留恋在表，"}, {"f": "audio/05/L1-wb-1__1.mp3", "t": "然后化热入里，"}, {"f": "audio/05/L1-wb-1__2.mp3", "t": "温邪则热变最速。"}, {"f": "audio/05/L1-wb-1__3.mp3", "t": "未传心包，"}, {"f": "audio/05/L1-wb-1__4.mp3", "t": "邪尚在肺，"}, {"f": "audio/05/L1-wb-1__5.mp3", "t": "肺主气，"}, {"f": "audio/05/L1-wb-1__6.mp3", "t": "其合皮毛，"}, {"f": "audio/05/L1-wb-1__7.mp3", "t": "故云在表。"}, {"f": "audio/05/L1-wb-1__8.mp3", "t": "在表初用辛凉轻剂。"}, {"f": "audio/05/L1-wb-1__9.mp3", "t": "挟风则加入薄荷、"}, {"f": "audio/05/L1-wb-1__10.mp3", "t": "牛蒡之属，"}, {"f": "audio/05/L1-wb-1__11.mp3", "t": "挟湿加芦根、"}, {"f": "audio/05/L1-wb-1__12.mp3", "t": "滑石之流。"}], "L1-wb-2": [{"f": "audio/ab/L1-wb-2__0.mp3", "t": "营分受热，"}, {"f": "audio/ab/L1-wb-2__1.mp3", "t": "则血液受劫，"}, {"f": "audio/ab/L1-wb-2__2.mp3", "t": "心神不安，"}, {"f": "audio/ab/L1-wb-2__3.mp3", "t": "夜甚无寐，"}, {"f": "audio/ab/L1-wb-2__4.mp3", "t": "或斑点隐隐。"}], "L1-wb-3": [{"f": "audio/29/L1-wb-3__0.mp3", "t": "若其邪始终在气分流连者，"}, {"f": "audio/29/L1-wb-3__1.mp3", "t": "可冀其战汗透邪，"}, {"f": "audio/29/L1-wb-3__2.mp3", "t": "法宜益胃，"}, {"f": "audio/29/L1-wb-3__3.mp3", "t": "令邪与汗并，"}, {"f": "audio/29/L1-wb-3__4.mp3", "t": "热达腠开，"}, {"f": "audio/29/L1-wb-3__5.mp3", "t": "邪从汗出。"}, {"f": "audio/29/L1-wb-3__6.mp3", "t": "解后胃气空虚，"}, {"f": "audio/29/L1-wb-3__7.mp3", "t": "当肤冷一昼夜，"}, {"f": "audio/29/L1-wb-3__8.mp3", "t": "待气还自温暖如常矣。"}, {"f": "audio/29/L1-wb-3__9.mp3", "t": "盖战汗而解，"}, {"f": "audio/29/L1-wb-3__10.mp3", "t": "邪退正虚，"}, {"f": "audio/29/L1-wb-3__11.mp3", "t": "阳从汗泄，"}, {"f": "audio/29/L1-wb-3__12.mp3", "t": "故渐肤冷，"}, {"f": "audio/29/L1-wb-3__13.mp3", "t": "未必即成脱证。"}, {"f": "audio/29/L1-wb-3__14.mp3", "t": "此时宜令病者，"}, {"f": "audio/29/L1-wb-3__15.mp3", "t": "安舒静卧，"}, {"f": "audio/29/L1-wb-3__16.mp3", "t": "以养阳气来复。"}, {"f": "audio/29/L1-wb-3__17.mp3", "t": "旁人切勿惊惶，"}, {"f": "audio/29/L1-wb-3__18.mp3", "t": "频频呼唤，"}, {"f": "audio/29/L1-wb-3__19.mp3", "t": "扰其元神，"}, {"f": "audio/29/L1-wb-3__20.mp3", "t": "使其烦躁。"}, {"f": "audio/29/L1-wb-3__21.mp3", "t": "但诊其脉，"}, {"f": "audio/29/L1-wb-3__22.mp3", "t": "若虚软和缓，"}, {"f": "audio/29/L1-wb-3__23.mp3", "t": "虽倦卧不语，"}, {"f": "audio/29/L1-wb-3__24.mp3", "t": "汗出肤冷，"}, {"f": "audio/29/L1-wb-3__25.mp3", "t": "却非脱证；"}, {"f": "audio/29/L1-wb-3__26.mp3", "t": "若脉急疾，"}, {"f": "audio/29/L1-wb-3__27.mp3", "t": "躁扰不卧，"}, {"f": "audio/29/L1-wb-3__28.mp3", "t": "肤冷汗出，"}, {"f": "audio/29/L1-wb-3__29.mp3", "t": "便为气脱之证矣。"}], "L1-wb-4": [{"f": "audio/55/L1-wb-4__0.mp3", "t": "大凡看法，"}, {"f": "audio/55/L1-wb-4__1.mp3", "t": "卫之后方言气，"}, {"f": "audio/55/L1-wb-4__2.mp3", "t": "营之后方言血。"}, {"f": "audio/55/L1-wb-4__3.mp3", "t": "在卫汗之可也，"}, {"f": "audio/55/L1-wb-4__4.mp3", "t": "到气才可清气，"}, {"f": "audio/55/L1-wb-4__5.mp3", "t": "入营犹可透热转气，"}, {"f": "audio/55/L1-wb-4__6.mp3", "t": "如犀角、"}, {"f": "audio/55/L1-wb-4__7.mp3", "t": "玄参、"}, {"f": "audio/55/L1-wb-4__8.mp3", "t": "羚羊角等物，"}, {"f": "audio/55/L1-wb-4__9.mp3", "t": "入血就恐耗血动血，"}, {"f": "audio/55/L1-wb-4__10.mp3", "t": "直须凉血散血，"}, {"f": "audio/55/L1-wb-4__11.mp3", "t": "如生地、"}, {"f": "audio/55/L1-wb-4__12.mp3", "t": "丹皮、"}, {"f": "audio/55/L1-wb-4__13.mp3", "t": "阿胶、"}, {"f": "audio/55/L1-wb-4__14.mp3", "t": "赤芍等物。"}, {"f": "audio/55/L1-wb-4__15.mp3", "t": "否则前后不循缓急之法，"}, {"f": "audio/55/L1-wb-4__16.mp3", "t": "虑其动手便错，"}, {"f": "audio/55/L1-wb-4__17.mp3", "t": "反致慌张矣。"}], "L1-wb-5": [{"f": "audio/ee/L1-wb-5__0.mp3", "t": "且吾吴湿邪害人最广，"}, {"f": "audio/ee/L1-wb-5__1.mp3", "t": "如面色白者，"}, {"f": "audio/ee/L1-wb-5__2.mp3", "t": "须要顾其阳气，"}, {"f": "audio/ee/L1-wb-5__3.mp3", "t": "湿胜则阳微也，"}, {"f": "audio/ee/L1-wb-5__4.mp3", "t": "法应清凉，"}, {"f": "audio/ee/L1-wb-5__5.mp3", "t": "然到十分之六七，"}, {"f": "audio/ee/L1-wb-5__6.mp3", "t": "即不可过于寒凉，"}, {"f": "audio/ee/L1-wb-5__7.mp3", "t": "恐成功反弃，"}, {"f": "audio/ee/L1-wb-5__8.mp3", "t": "何以故耶？"}, {"f": "audio/ee/L1-wb-5__9.mp3", "t": "湿热一去，"}, {"f": "audio/ee/L1-wb-5__10.mp3", "t": "阳亦衰微也；"}, {"f": "audio/ee/L1-wb-5__11.mp3", "t": "面色苍者，"}, {"f": "audio/ee/L1-wb-5__12.mp3", "t": "须要顾其津液，"}, {"f": "audio/ee/L1-wb-5__13.mp3", "t": "清凉到十分之六七，"}, {"f": "audio/ee/L1-wb-5__14.mp3", "t": "往往热减身寒者，"}, {"f": "audio/ee/L1-wb-5__15.mp3", "t": "不可就云虚寒而投补剂，"}, {"f": "audio/ee/L1-wb-5__16.mp3", "t": "恐炉烟虽熄，"}, {"f": "audio/ee/L1-wb-5__17.mp3", "t": "灰中有火也，"}, {"f": "audio/ee/L1-wb-5__18.mp3", "t": "须细察精详，"}, {"f": "audio/ee/L1-wb-5__19.mp3", "t": "方少少与之，"}, {"f": "audio/ee/L1-wb-5__20.mp3", "t": "慎不可直率而往也。"}], "L1-wb-6": [{"f": "audio/b2/L1-wb-6__0.mp3", "t": "伤寒大便溏为邪已尽，"}, {"f": "audio/b2/L1-wb-6__1.mp3", "t": "不可再下；"}, {"f": "audio/b2/L1-wb-6__2.mp3", "t": "湿温病大便溏为邪未尽，"}, {"f": "audio/b2/L1-wb-6__3.mp3", "t": "必大便硬，"}, {"f": "audio/b2/L1-wb-6__4.mp3", "t": "慎不可再攻也，"}, {"f": "audio/b2/L1-wb-6__5.mp3", "t": "以粪燥为无湿矣。"}], "L1-wb-7": [{"f": "audio/8e/L1-wb-7__0.mp3", "t": "再人之体，"}, {"f": "audio/8e/L1-wb-7__1.mp3", "t": "脘在腹上，"}, {"f": "audio/8e/L1-wb-7__2.mp3", "t": "其地位处于中，"}, {"f": "audio/8e/L1-wb-7__3.mp3", "t": "按之痛，"}, {"f": "audio/8e/L1-wb-7__4.mp3", "t": "或自痛，"}, {"f": "audio/8e/L1-wb-7__5.mp3", "t": "或痞胀，"}, {"f": "audio/8e/L1-wb-7__6.mp3", "t": "当用苦泄，"}, {"f": "audio/8e/L1-wb-7__7.mp3", "t": "以其入腹近也。"}], "L1-wb-8": [{"f": "audio/f2/L1-wb-8__0.mp3", "t": "斑属血者恒多，"}, {"f": "audio/f2/L1-wb-8__1.mp3", "t": "疹属气者不少。"}, {"f": "audio/f2/L1-wb-8__2.mp3", "t": "斑疹皆是邪气外露之象，"}, {"f": "audio/f2/L1-wb-8__3.mp3", "t": "发出宜神情清爽，"}, {"f": "audio/f2/L1-wb-8__4.mp3", "t": "为外解里和之意；"}, {"f": "audio/f2/L1-wb-8__5.mp3", "t": "如斑疹出而昏者，"}, {"f": "audio/f2/L1-wb-8__6.mp3", "t": "正不胜邪，"}, {"f": "audio/f2/L1-wb-8__7.mp3", "t": "内陷为患。"}], "L1-wb-9": [{"f": "audio/04/L1-wb-9__0.mp3", "t": "湿热证，"}, {"f": "audio/04/L1-wb-9__1.mp3", "t": "始恶寒，"}, {"f": "audio/04/L1-wb-9__2.mp3", "t": "后但热不寒，"}, {"f": "audio/04/L1-wb-9__3.mp3", "t": "汗出胸痞，"}, {"f": "audio/04/L1-wb-9__4.mp3", "t": "舌白，"}, {"f": "audio/04/L1-wb-9__5.mp3", "t": "口渴不引饮。"}], "L1-wb-10": [{"f": "audio/b8/L1-wb-10__0.mp3", "t": "湿热之邪从表伤者，"}, {"f": "audio/b8/L1-wb-10__1.mp3", "t": "十之一二，"}, {"f": "audio/b8/L1-wb-10__2.mp3", "t": "由口鼻入者，"}, {"f": "audio/b8/L1-wb-10__3.mp3", "t": "十之八九。"}, {"f": "audio/b8/L1-wb-10__4.mp3", "t": "阳明为水谷之海，"}, {"f": "audio/b8/L1-wb-10__5.mp3", "t": "太阴为湿土之脏，"}, {"f": "audio/b8/L1-wb-10__6.mp3", "t": "故多阳明太阴受病。"}], "L1-wb-11": [{"f": "audio/f5/L1-wb-11__0.mp3", "t": "湿热证，"}, {"f": "audio/f5/L1-wb-11__1.mp3", "t": "恶寒无汗，"}, {"f": "audio/f5/L1-wb-11__2.mp3", "t": "身重头痛，"}, {"f": "audio/f5/L1-wb-11__3.mp3", "t": "湿在表分，"}, {"f": "audio/f5/L1-wb-11__4.mp3", "t": "宜藿香、"}, {"f": "audio/f5/L1-wb-11__5.mp3", "t": "香薷、"}, {"f": "audio/f5/L1-wb-11__6.mp3", "t": "羌活、"}, {"f": "audio/f5/L1-wb-11__7.mp3", "t": "苍术皮、"}, {"f": "audio/f5/L1-wb-11__8.mp3", "t": "薄荷、"}, {"f": "audio/f5/L1-wb-11__9.mp3", "t": "牛蒡子等味。"}], "L1-wb-12": [{"f": "audio/30/L1-wb-12__0.mp3", "t": "湿热证，"}, {"f": "audio/30/L1-wb-12__1.mp3", "t": "恶寒发热，"}, {"f": "audio/30/L1-wb-12__2.mp3", "t": "身重关节疼痛，"}, {"f": "audio/30/L1-wb-12__3.mp3", "t": "湿在肌肉，"}, {"f": "audio/30/L1-wb-12__4.mp3", "t": "不为汗解，"}, {"f": "audio/30/L1-wb-12__5.mp3", "t": "宜滑石、"}, {"f": "audio/30/L1-wb-12__6.mp3", "t": "大豆黄卷、"}, {"f": "audio/30/L1-wb-12__7.mp3", "t": "茯苓皮、"}, {"f": "audio/30/L1-wb-12__8.mp3", "t": "苍术皮、"}, {"f": "audio/30/L1-wb-12__9.mp3", "t": "藿香、"}, {"f": "audio/30/L1-wb-12__10.mp3", "t": "鲜荷叶、"}, {"f": "audio/30/L1-wb-12__11.mp3", "t": "通草等味。"}], "L1-wb-13": [{"f": "audio/5c/L1-wb-13__0.mp3", "t": "湿热证，"}, {"f": "audio/5c/L1-wb-13__1.mp3", "t": "数日后，"}, {"f": "audio/5c/L1-wb-13__2.mp3", "t": "脘中微闷，"}, {"f": "audio/5c/L1-wb-13__3.mp3", "t": "知饥不食，"}, {"f": "audio/5c/L1-wb-13__4.mp3", "t": "湿邪蒙绕三焦，"}, {"f": "audio/5c/L1-wb-13__5.mp3", "t": "宜藿香叶、"}, {"f": "audio/5c/L1-wb-13__6.mp3", "t": "薄荷叶、"}, {"f": "audio/5c/L1-wb-13__7.mp3", "t": "鲜荷叶、"}, {"f": "audio/5c/L1-wb-13__8.mp3", "t": "枇杷叶、"}, {"f": "audio/5c/L1-wb-13__9.mp3", "t": "佩兰叶、"}, {"f": "audio/5c/L1-wb-13__10.mp3", "t": "芦根等味。"}], "L1-wb-14": [{"f": "audio/d0/L1-wb-14__0.mp3", "t": "湿热证，"}, {"f": "audio/d0/L1-wb-14__1.mp3", "t": "数日后自利，"}, {"f": "audio/d0/L1-wb-14__2.mp3", "t": "溺赤，"}, {"f": "audio/d0/L1-wb-14__3.mp3", "t": "口渴，"}, {"f": "audio/d0/L1-wb-14__4.mp3", "t": "湿流下焦，"}, {"f": "audio/d0/L1-wb-14__5.mp3", "t": "宜滑石、"}, {"f": "audio/d0/L1-wb-14__6.mp3", "t": "猪苓、"}, {"f": "audio/d0/L1-wb-14__7.mp3", "t": "茯苓、"}, {"f": "audio/d0/L1-wb-14__8.mp3", "t": "泽泻、"}, {"f": "audio/d0/L1-wb-14__9.mp3", "t": "萆薢、"}, {"f": "audio/d0/L1-wb-14__10.mp3", "t": "通草等味。"}], "L1-wb-15": [{"f": "audio/24/L1-wb-15__0.mp3", "t": "湿热证，"}, {"f": "audio/24/L1-wb-15__1.mp3", "t": "舌遍体白，"}, {"f": "audio/24/L1-wb-15__2.mp3", "t": "口渴，"}, {"f": "audio/24/L1-wb-15__3.mp3", "t": "湿滞阳明，"}, {"f": "audio/24/L1-wb-15__4.mp3", "t": "宜用辛开，"}, {"f": "audio/24/L1-wb-15__5.mp3", "t": "如厚朴、"}, {"f": "audio/24/L1-wb-15__6.mp3", "t": "草果、"}, {"f": "audio/24/L1-wb-15__7.mp3", "t": "半夏、"}, {"f": "audio/24/L1-wb-15__8.mp3", "t": "干菖蒲等味。"}], "L1-wb-16": [{"f": "audio/f8/L1-wb-16__0.mp3", "t": "湿热证，"}, {"f": "audio/f8/L1-wb-16__1.mp3", "t": "按法治之，"}, {"f": "audio/f8/L1-wb-16__2.mp3", "t": "诸证皆退，"}, {"f": "audio/f8/L1-wb-16__3.mp3", "t": "惟目瞑则惊悸梦惕，"}, {"f": "audio/f8/L1-wb-16__4.mp3", "t": "余邪内留，"}, {"f": "audio/f8/L1-wb-16__5.mp3", "t": "胆气未舒，"}, {"f": "audio/f8/L1-wb-16__6.mp3", "t": "宜用酒浸郁李仁、"}, {"f": "audio/f8/L1-wb-16__7.mp3", "t": "姜汁炒枣仁、"}, {"f": "audio/f8/L1-wb-16__8.mp3", "t": "猪胆皮等味。"}], "L1-wb-17": [{"f": "audio/c6/L1-wb-17__0.mp3", "t": "温病者："}, {"f": "audio/c6/L1-wb-17__1.mp3", "t": "有风温、"}, {"f": "audio/c6/L1-wb-17__2.mp3", "t": "有温热、"}, {"f": "audio/c6/L1-wb-17__3.mp3", "t": "有温疫、"}, {"f": "audio/c6/L1-wb-17__4.mp3", "t": "有温毒、"}, {"f": "audio/c6/L1-wb-17__5.mp3", "t": "有暑温、"}, {"f": "audio/c6/L1-wb-17__6.mp3", "t": "有湿温、"}, {"f": "audio/c6/L1-wb-17__7.mp3", "t": "有秋燥、"}, {"f": "audio/c6/L1-wb-17__8.mp3", "t": "有冬温、"}, {"f": "audio/c6/L1-wb-17__9.mp3", "t": "有温疟。"}], "L1-wb-18": [{"f": "audio/6b/L1-wb-18__0.mp3", "t": "凡病温者，"}, {"f": "audio/6b/L1-wb-18__1.mp3", "t": "始于上焦，"}, {"f": "audio/6b/L1-wb-18__2.mp3", "t": "在手太阴。"}], "L1-wb-19": [{"f": "audio/32/L1-wb-19__0.mp3", "t": "太阴之为病，"}, {"f": "audio/32/L1-wb-19__1.mp3", "t": "脉不缓不紧而动数，"}, {"f": "audio/32/L1-wb-19__2.mp3", "t": "或两寸独大，"}, {"f": "audio/32/L1-wb-19__3.mp3", "t": "尺肤热，"}, {"f": "audio/32/L1-wb-19__4.mp3", "t": "头痛，"}, {"f": "audio/32/L1-wb-19__5.mp3", "t": "微恶风寒，"}, {"f": "audio/32/L1-wb-19__6.mp3", "t": "身热自汗，"}, {"f": "audio/32/L1-wb-19__7.mp3", "t": "口渴，"}, {"f": "audio/32/L1-wb-19__8.mp3", "t": "或不渴，"}, {"f": "audio/32/L1-wb-19__9.mp3", "t": "而咳，"}, {"f": "audio/32/L1-wb-19__10.mp3", "t": "午后热甚者，"}, {"f": "audio/32/L1-wb-19__11.mp3", "t": "名曰温病。"}], "L1-wb-20": [{"f": "audio/cc/L1-wb-20__0.mp3", "t": "太阴风温、"}, {"f": "audio/cc/L1-wb-20__1.mp3", "t": "温热、"}, {"f": "audio/cc/L1-wb-20__2.mp3", "t": "温疫、"}, {"f": "audio/cc/L1-wb-20__3.mp3", "t": "冬温，"}, {"f": "audio/cc/L1-wb-20__4.mp3", "t": "初起恶风寒者，"}, {"f": "audio/cc/L1-wb-20__5.mp3", "t": "桂枝汤主之；"}, {"f": "audio/cc/L1-wb-20__6.mp3", "t": "但热不恶寒而渴者，"}, {"f": "audio/cc/L1-wb-20__7.mp3", "t": "辛凉平剂银翘散主之。"}], "L1-wb-21": [{"f": "audio/75/L1-wb-21__0.mp3", "t": "太阴风温，"}, {"f": "audio/75/L1-wb-21__1.mp3", "t": "但咳，"}, {"f": "audio/75/L1-wb-21__2.mp3", "t": "身不甚热，"}, {"f": "audio/75/L1-wb-21__3.mp3", "t": "微渴者，"}, {"f": "audio/75/L1-wb-21__4.mp3", "t": "辛凉轻剂桑菊饮主之。"}], "L1-wb-22": [{"f": "audio/8a/L1-wb-22__0.mp3", "t": "白虎本为达热出表，"}, {"f": "audio/8a/L1-wb-22__1.mp3", "t": "若其人脉浮弦而细者，"}, {"f": "audio/8a/L1-wb-22__2.mp3", "t": "不可与也；"}, {"f": "audio/8a/L1-wb-22__3.mp3", "t": "脉沉者，"}, {"f": "audio/8a/L1-wb-22__4.mp3", "t": "不可与也；"}, {"f": "audio/8a/L1-wb-22__5.mp3", "t": "不渴者，"}, {"f": "audio/8a/L1-wb-22__6.mp3", "t": "不可与也；"}, {"f": "audio/8a/L1-wb-22__7.mp3", "t": "汗不出者，"}, {"f": "audio/8a/L1-wb-22__8.mp3", "t": "不可与也。"}, {"f": "audio/8a/L1-wb-22__9.mp3", "t": "常须识此，"}, {"f": "audio/8a/L1-wb-22__10.mp3", "t": "勿令误也。"}], "L1-wb-23": [{"f": "audio/1c/L1-wb-23__0.mp3", "t": "太阴温病，"}, {"f": "audio/1c/L1-wb-23__1.mp3", "t": "气血两燔者，"}, {"f": "audio/1c/L1-wb-23__2.mp3", "t": "玉女煎去牛膝加元参主之。"}], "L1-wb-24": [{"f": "audio/83/L1-wb-24__0.mp3", "t": "太阴温病，"}, {"f": "audio/83/L1-wb-24__1.mp3", "t": "血从上溢者，"}, {"f": "audio/83/L1-wb-24__2.mp3", "t": "犀角地黄汤合银翘散主之。"}], "L1-wb-25": [{"f": "audio/73/L1-wb-25__0.mp3", "t": "邪入心包，"}, {"f": "audio/73/L1-wb-25__1.mp3", "t": "舌蹇肢厥，"}, {"f": "audio/73/L1-wb-25__2.mp3", "t": "牛黄丸主之，"}, {"f": "audio/73/L1-wb-25__3.mp3", "t": "紫雪丹亦主之。"}], "L1-wb-26": [{"f": "audio/e8/L1-wb-26__0.mp3", "t": "手太阴暑湿，"}, {"f": "audio/e8/L1-wb-26__1.mp3", "t": "按之或咳或不咳，"}, {"f": "audio/e8/L1-wb-26__2.mp3", "t": "无热，"}, {"f": "audio/e8/L1-wb-26__3.mp3", "t": "但胸微闷，"}, {"f": "audio/e8/L1-wb-26__4.mp3", "t": "或四肢倦怠，"}, {"f": "audio/e8/L1-wb-26__5.mp3", "t": "无汗者，"}, {"f": "audio/e8/L1-wb-26__6.mp3", "t": "新加香薷饮主之。"}], "L1-wb-27": [{"f": "audio/60/L1-wb-27__0.mp3", "t": "手太阴暑温，"}, {"f": "audio/60/L1-wb-27__1.mp3", "t": "或已经发汗，"}, {"f": "audio/60/L1-wb-27__2.mp3", "t": "或未发汗，"}, {"f": "audio/60/L1-wb-27__3.mp3", "t": "而汗不止，"}, {"f": "audio/60/L1-wb-27__4.mp3", "t": "烦渴而喘，"}, {"f": "audio/60/L1-wb-27__5.mp3", "t": "脉洪大有力者，"}, {"f": "audio/60/L1-wb-27__6.mp3", "t": "白虎汤主之。"}], "L1-wb-28": [{"f": "audio/2d/L1-wb-28__0.mp3", "t": "小儿暑温，"}, {"f": "audio/2d/L1-wb-28__1.mp3", "t": "身热，"}, {"f": "audio/2d/L1-wb-28__2.mp3", "t": "卒然痉厥，"}, {"f": "audio/2d/L1-wb-28__3.mp3", "t": "名曰暑痫，"}, {"f": "audio/2d/L1-wb-28__4.mp3", "t": "清营汤主之。"}], "L1-wb-29": [{"f": "audio/4a/L1-wb-29__0.mp3", "t": "长夏受暑，"}, {"f": "audio/4a/L1-wb-29__1.mp3", "t": "过夏而发者，"}, {"f": "audio/4a/L1-wb-29__2.mp3", "t": "名曰伏暑。"}], "L1-wb-30": [{"f": "audio/61/L1-wb-30__0.mp3", "t": "伏暑、"}, {"f": "audio/61/L1-wb-30__1.mp3", "t": "暑温、"}, {"f": "audio/61/L1-wb-30__2.mp3", "t": "湿温，"}, {"f": "audio/61/L1-wb-30__3.mp3", "t": "证本一源，"}, {"f": "audio/61/L1-wb-30__4.mp3", "t": "前后互参，"}, {"f": "audio/61/L1-wb-30__5.mp3", "t": "不可偏执。"}], "L1-wb-31": [{"f": "audio/38/L1-wb-31__0.mp3", "t": "头痛恶寒，"}, {"f": "audio/38/L1-wb-31__1.mp3", "t": "身重疼痛，"}, {"f": "audio/38/L1-wb-31__2.mp3", "t": "舌白不渴，"}, {"f": "audio/38/L1-wb-31__3.mp3", "t": "脉弦细而濡，"}, {"f": "audio/38/L1-wb-31__4.mp3", "t": "面色淡黄，"}, {"f": "audio/38/L1-wb-31__5.mp3", "t": "胸闷不饥，"}, {"f": "audio/38/L1-wb-31__6.mp3", "t": "午后身热，"}, {"f": "audio/38/L1-wb-31__7.mp3", "t": "状若阴虚，"}, {"f": "audio/38/L1-wb-31__8.mp3", "t": "病难速已，"}, {"f": "audio/38/L1-wb-31__9.mp3", "t": "名曰湿温。"}, {"f": "audio/38/L1-wb-31__10.mp3", "t": "汗之则神昏耳聋，"}, {"f": "audio/38/L1-wb-31__11.mp3", "t": "甚则目瞑不欲言，"}, {"f": "audio/38/L1-wb-31__12.mp3", "t": "下之则洞泄，"}, {"f": "audio/38/L1-wb-31__13.mp3", "t": "润之则病深不解，"}, {"f": "audio/38/L1-wb-31__14.mp3", "t": "三仁汤主之。"}], "L1-wb-32": [{"f": "audio/e1/L1-wb-32__0.mp3", "t": "燥伤肺胃阴分，"}, {"f": "audio/e1/L1-wb-32__1.mp3", "t": "或热或咳者，"}, {"f": "audio/e1/L1-wb-32__2.mp3", "t": "沙参麦冬汤主之。"}], "L1-wb-33": [{"f": "audio/45/L1-wb-33__0.mp3", "t": "燥气化火，"}, {"f": "audio/45/L1-wb-33__1.mp3", "t": "清窍不利者，"}, {"f": "audio/45/L1-wb-33__2.mp3", "t": "翘荷汤主之。"}], "L1-wb-34": [{"f": "audio/4e/L1-wb-34__0.mp3", "t": "诸气膹郁，"}, {"f": "audio/4e/L1-wb-34__1.mp3", "t": "诸痿喘呕之因于燥者，"}, {"f": "audio/4e/L1-wb-34__2.mp3", "t": "喻氏清燥救肺汤主之。"}], "L1-wb-35": [{"f": "audio/44/L1-wb-35__0.mp3", "t": "面目俱赤，"}, {"f": "audio/44/L1-wb-35__1.mp3", "t": "语声重浊，"}, {"f": "audio/44/L1-wb-35__2.mp3", "t": "呼吸俱粗，"}, {"f": "audio/44/L1-wb-35__3.mp3", "t": "大便闭，"}, {"f": "audio/44/L1-wb-35__4.mp3", "t": "小便涩，"}, {"f": "audio/44/L1-wb-35__5.mp3", "t": "舌苔老黄，"}, {"f": "audio/44/L1-wb-35__6.mp3", "t": "甚则黑有芒刺，"}, {"f": "audio/44/L1-wb-35__7.mp3", "t": "但恶热不恶寒，"}, {"f": "audio/44/L1-wb-35__8.mp3", "t": "日晡益甚者，"}, {"f": "audio/44/L1-wb-35__9.mp3", "t": "传至中焦，"}, {"f": "audio/44/L1-wb-35__10.mp3", "t": "阳明温病也。"}, {"f": "audio/44/L1-wb-35__11.mp3", "t": "脉浮洪躁甚者，"}, {"f": "audio/44/L1-wb-35__12.mp3", "t": "白虎汤主之；"}, {"f": "audio/44/L1-wb-35__13.mp3", "t": "脉沉数有力，"}, {"f": "audio/44/L1-wb-35__14.mp3", "t": "甚则脉体反小而实者，"}, {"f": "audio/44/L1-wb-35__15.mp3", "t": "大承气汤主之。"}, {"f": "audio/44/L1-wb-35__16.mp3", "t": "暑温、"}, {"f": "audio/44/L1-wb-35__17.mp3", "t": "湿温、"}, {"f": "audio/44/L1-wb-35__18.mp3", "t": "温疟不在此例。"}], "L1-wb-36": [{"f": "audio/81/L1-wb-36__0.mp3", "t": "承气非可轻尝也，"}, {"f": "audio/81/L1-wb-36__1.mp3", "t": "即邪入中焦，"}, {"f": "audio/81/L1-wb-36__2.mp3", "t": "有急下、"}, {"f": "audio/81/L1-wb-36__3.mp3", "t": "可下、"}, {"f": "audio/81/L1-wb-36__4.mp3", "t": "不可下之分，"}, {"f": "audio/81/L1-wb-36__5.mp3", "t": "当细辨之。"}], "L1-wb-37": [{"f": "audio/82/L1-wb-37__0.mp3", "t": "阳明温病，"}, {"f": "audio/82/L1-wb-37__1.mp3", "t": "下后汗出，"}, {"f": "audio/82/L1-wb-37__2.mp3", "t": "当复其阴，"}, {"f": "audio/82/L1-wb-37__3.mp3", "t": "益胃汤主之。"}], "L1-wb-38": [{"f": "audio/09/L1-wb-38__0.mp3", "t": "阳明温病，"}, {"f": "audio/09/L1-wb-38__1.mp3", "t": "下之不通，"}, {"f": "audio/09/L1-wb-38__2.mp3", "t": "其证有五："}, {"f": "audio/09/L1-wb-38__3.mp3", "t": "应下失下，"}, {"f": "audio/09/L1-wb-38__4.mp3", "t": "正虚不能运药，"}, {"f": "audio/09/L1-wb-38__5.mp3", "t": "不运药者死，"}, {"f": "audio/09/L1-wb-38__6.mp3", "t": "新加黄龙汤主之；"}, {"f": "audio/09/L1-wb-38__7.mp3", "t": "喘促不宁，"}, {"f": "audio/09/L1-wb-38__8.mp3", "t": "痰涎壅滞，"}, {"f": "audio/09/L1-wb-38__9.mp3", "t": "右寸实大，"}, {"f": "audio/09/L1-wb-38__10.mp3", "t": "肺气不降者，"}, {"f": "audio/09/L1-wb-38__11.mp3", "t": "宣白承气汤主之；"}, {"f": "audio/09/L1-wb-38__12.mp3", "t": "左尺牢坚，"}, {"f": "audio/09/L1-wb-38__13.mp3", "t": "小便赤痛，"}, {"f": "audio/09/L1-wb-38__14.mp3", "t": "时烦渴甚，"}, {"f": "audio/09/L1-wb-38__15.mp3", "t": "导赤承气汤主之；"}, {"f": "audio/09/L1-wb-38__16.mp3", "t": "邪闭心包，"}, {"f": "audio/09/L1-wb-38__17.mp3", "t": "神昏舌短，"}, {"f": "audio/09/L1-wb-38__18.mp3", "t": "内窍不通，"}, {"f": "audio/09/L1-wb-38__19.mp3", "t": "饮不解渴者，"}, {"f": "audio/09/L1-wb-38__20.mp3", "t": "牛黄承气汤主之；"}, {"f": "audio/09/L1-wb-38__21.mp3", "t": "津液不足，"}, {"f": "audio/09/L1-wb-38__22.mp3", "t": "无水舟停者，"}, {"f": "audio/09/L1-wb-38__23.mp3", "t": "间服增液，"}, {"f": "audio/09/L1-wb-38__24.mp3", "t": "再不下者，"}, {"f": "audio/09/L1-wb-38__25.mp3", "t": "增液承气汤主之。"}], "L1-wb-39": [{"f": "audio/14/L1-wb-39__0.mp3", "t": "斑疹，"}, {"f": "audio/14/L1-wb-39__1.mp3", "t": "用升提则衄，"}, {"f": "audio/14/L1-wb-39__2.mp3", "t": "或厥，"}, {"f": "audio/14/L1-wb-39__3.mp3", "t": "或呛咳，"}, {"f": "audio/14/L1-wb-39__4.mp3", "t": "或昏痉；"}, {"f": "audio/14/L1-wb-39__5.mp3", "t": "用壅补则瞀乱。"}], "L1-wb-40": [{"f": "audio/af/L1-wb-40__0.mp3", "t": "温病小便不利者，"}, {"f": "audio/af/L1-wb-40__1.mp3", "t": "淡渗不可与也，"}, {"f": "audio/af/L1-wb-40__2.mp3", "t": "忌五苓、"}, {"f": "audio/af/L1-wb-40__3.mp3", "t": "八正辈。"}], "L1-wb-41": [{"f": "audio/c8/L1-wb-41__0.mp3", "t": "脉洪滑，"}, {"f": "audio/c8/L1-wb-41__1.mp3", "t": "面赤，"}, {"f": "audio/c8/L1-wb-41__2.mp3", "t": "身热，"}, {"f": "audio/c8/L1-wb-41__3.mp3", "t": "头晕，"}, {"f": "audio/c8/L1-wb-41__4.mp3", "t": "不恶寒，"}, {"f": "audio/c8/L1-wb-41__5.mp3", "t": "但恶热，"}, {"f": "audio/c8/L1-wb-41__6.mp3", "t": "舌上黄滑苔，"}, {"f": "audio/c8/L1-wb-41__7.mp3", "t": "渴欲凉饮，"}, {"f": "audio/c8/L1-wb-41__8.mp3", "t": "饮不解渴，"}, {"f": "audio/c8/L1-wb-41__9.mp3", "t": "得水则呕，"}, {"f": "audio/c8/L1-wb-41__10.mp3", "t": "按之胸下痛，"}, {"f": "audio/c8/L1-wb-41__11.mp3", "t": "小便短，"}, {"f": "audio/c8/L1-wb-41__12.mp3", "t": "大便闭者，"}, {"f": "audio/c8/L1-wb-41__13.mp3", "t": "阳明暑温，"}, {"f": "audio/c8/L1-wb-41__14.mp3", "t": "水结在胸也，"}, {"f": "audio/c8/L1-wb-41__15.mp3", "t": "小陷胸汤加枳实主之。"}], "L1-wb-42": [{"f": "audio/51/L1-wb-42__0.mp3", "t": "暑湿蔓延三焦，"}, {"f": "audio/51/L1-wb-42__1.mp3", "t": "舌滑微黄，"}, {"f": "audio/51/L1-wb-42__2.mp3", "t": "邪在气分者，"}, {"f": "audio/51/L1-wb-42__3.mp3", "t": "三石汤主之。"}], "L1-wb-43": [{"f": "audio/c8/L1-wb-43__0.mp3", "t": "脉缓身痛，"}, {"f": "audio/c8/L1-wb-43__1.mp3", "t": "舌淡黄而滑，"}, {"f": "audio/c8/L1-wb-43__2.mp3", "t": "渴不多饮，"}, {"f": "audio/c8/L1-wb-43__3.mp3", "t": "或竟不渴，"}, {"f": "audio/c8/L1-wb-43__4.mp3", "t": "汗出热解，"}, {"f": "audio/c8/L1-wb-43__5.mp3", "t": "继而复热，"}, {"f": "audio/c8/L1-wb-43__6.mp3", "t": "内不能运水谷之湿，"}, {"f": "audio/c8/L1-wb-43__7.mp3", "t": "外复感时令之湿，"}, {"f": "audio/c8/L1-wb-43__8.mp3", "t": "发表攻里，"}, {"f": "audio/c8/L1-wb-43__9.mp3", "t": "两不可施，"}, {"f": "audio/c8/L1-wb-43__10.mp3", "t": "误认伤寒，"}, {"f": "audio/c8/L1-wb-43__11.mp3", "t": "必转坏证，"}, {"f": "audio/c8/L1-wb-43__12.mp3", "t": "徒清热则湿不退，"}, {"f": "audio/c8/L1-wb-43__13.mp3", "t": "徒祛湿则热愈炽，"}, {"f": "audio/c8/L1-wb-43__14.mp3", "t": "黄芩滑石汤主之。"}], "L1-wb-44": [{"f": "audio/be/L1-wb-44__0.mp3", "t": "痹证大抵不越寒热两条，"}, {"f": "audio/be/L1-wb-44__1.mp3", "t": "虚实异治。"}, {"f": "audio/be/L1-wb-44__2.mp3", "t": "寒痹势重而治反易，"}, {"f": "audio/be/L1-wb-44__3.mp3", "t": "热痹势缓而治反难，"}, {"f": "audio/be/L1-wb-44__4.mp3", "t": "实者单病躯壳，"}, {"f": "audio/be/L1-wb-44__5.mp3", "t": "易治；"}, {"f": "audio/be/L1-wb-44__6.mp3", "t": "虚者兼病脏腑，"}, {"f": "audio/be/L1-wb-44__7.mp3", "t": "难治。"}], "L1-wb-45": [{"f": "audio/eb/L1-wb-45__0.mp3", "t": "风温、"}, {"f": "audio/eb/L1-wb-45__1.mp3", "t": "温热、"}, {"f": "audio/eb/L1-wb-45__2.mp3", "t": "温疫、"}, {"f": "audio/eb/L1-wb-45__3.mp3", "t": "温毒、"}, {"f": "audio/eb/L1-wb-45__4.mp3", "t": "冬温，"}, {"f": "audio/eb/L1-wb-45__5.mp3", "t": "邪在阳明久羁，"}, {"f": "audio/eb/L1-wb-45__6.mp3", "t": "或已下，"}, {"f": "audio/eb/L1-wb-45__7.mp3", "t": "或未下，"}, {"f": "audio/eb/L1-wb-45__8.mp3", "t": "身热面赤，"}, {"f": "audio/eb/L1-wb-45__9.mp3", "t": "口干舌燥，"}, {"f": "audio/eb/L1-wb-45__10.mp3", "t": "甚则齿黑唇裂，"}, {"f": "audio/eb/L1-wb-45__11.mp3", "t": "脉虚大，"}, {"f": "audio/eb/L1-wb-45__12.mp3", "t": "手足心热甚于手足背者，"}, {"f": "audio/eb/L1-wb-45__13.mp3", "t": "加减复脉汤主之。"}], "L1-wb-46": [{"f": "audio/c9/L1-wb-46__0.mp3", "t": "少阴温病，"}, {"f": "audio/c9/L1-wb-46__1.mp3", "t": "真阴欲竭，"}, {"f": "audio/c9/L1-wb-46__2.mp3", "t": "壮火复炽，"}, {"f": "audio/c9/L1-wb-46__3.mp3", "t": "心中烦，"}, {"f": "audio/c9/L1-wb-46__4.mp3", "t": "不得卧者，"}, {"f": "audio/c9/L1-wb-46__5.mp3", "t": "黄连阿胶汤主之。"}], "L1-wb-47": [{"f": "audio/2f/L1-wb-47__0.mp3", "t": "夜热早凉，"}, {"f": "audio/2f/L1-wb-47__1.mp3", "t": "热退无汗，"}, {"f": "audio/2f/L1-wb-47__2.mp3", "t": "热自阴来者，"}, {"f": "audio/2f/L1-wb-47__3.mp3", "t": "青蒿鳖甲汤主之。"}], "L1-wb-48": [{"f": "audio/1b/L1-wb-48__0.mp3", "t": "下焦温病，"}, {"f": "audio/1b/L1-wb-48__1.mp3", "t": "热深厥甚，"}, {"f": "audio/1b/L1-wb-48__2.mp3", "t": "脉细促，"}, {"f": "audio/1b/L1-wb-48__3.mp3", "t": "心中憺憺大动，"}, {"f": "audio/1b/L1-wb-48__4.mp3", "t": "甚则心中痛者，"}, {"f": "audio/1b/L1-wb-48__5.mp3", "t": "三甲复脉汤主之。"}], "L1-wb-49": [{"f": "audio/5b/L1-wb-49__0.mp3", "t": "热邪久羁，"}, {"f": "audio/5b/L1-wb-49__1.mp3", "t": "吸烁真阴，"}, {"f": "audio/5b/L1-wb-49__2.mp3", "t": "或因误表，"}, {"f": "audio/5b/L1-wb-49__3.mp3", "t": "或因妄攻，"}, {"f": "audio/5b/L1-wb-49__4.mp3", "t": "神倦瘛疭，"}, {"f": "audio/5b/L1-wb-49__5.mp3", "t": "脉气虚弱，"}, {"f": "audio/5b/L1-wb-49__6.mp3", "t": "舌绛苔少，"}, {"f": "audio/5b/L1-wb-49__7.mp3", "t": "时时欲脱者，"}, {"f": "audio/5b/L1-wb-49__8.mp3", "t": "大定风珠主之。"}], "L1-wb-50": [{"f": "audio/b3/L1-wb-50__0.mp3", "t": "暑邪深入少阴消渴者，"}, {"f": "audio/b3/L1-wb-50__1.mp3", "t": "连梅汤主之；"}, {"f": "audio/b3/L1-wb-50__2.mp3", "t": "入厥阴麻痹者，"}, {"f": "audio/b3/L1-wb-50__3.mp3", "t": "连梅汤主之；"}, {"f": "audio/b3/L1-wb-50__4.mp3", "t": "心热烦躁神迷甚者，"}, {"f": "audio/b3/L1-wb-50__5.mp3", "t": "先与紫雪丹，"}, {"f": "audio/b3/L1-wb-50__6.mp3", "t": "再与连梅汤。"}], "L1-wb-51": [{"f": "audio/a4/L1-wb-51__0.mp3", "t": "治上焦如羽，"}, {"f": "audio/a4/L1-wb-51__1.mp3", "t": "非轻不举；"}, {"f": "audio/a4/L1-wb-51__2.mp3", "t": "治中焦如衡，"}, {"f": "audio/a4/L1-wb-51__3.mp3", "t": "非平不安；"}, {"f": "audio/a4/L1-wb-51__4.mp3", "t": "治下焦如权，"}, {"f": "audio/a4/L1-wb-51__5.mp3", "t": "非重不沉。"}], "L1-wb-52": [{"f": "audio/1a/L1-wb-52__0.mp3", "t": "风温为病，"}, {"f": "audio/1a/L1-wb-52__1.mp3", "t": "春月与冬季居多，"}, {"f": "audio/1a/L1-wb-52__2.mp3", "t": "或恶风，"}, {"f": "audio/1a/L1-wb-52__3.mp3", "t": "或不恶风，"}, {"f": "audio/1a/L1-wb-52__4.mp3", "t": "必身热，"}, {"f": "audio/1a/L1-wb-52__5.mp3", "t": "咳嗽，"}, {"f": "audio/1a/L1-wb-52__6.mp3", "t": "烦渴，"}, {"f": "audio/1a/L1-wb-52__7.mp3", "t": "此风温证之提纲也。"}], "L1-wb-53": [{"f": "audio/e3/L1-wb-53__0.mp3", "t": "夫温疫之为病，"}, {"f": "audio/e3/L1-wb-53__1.mp3", "t": "非风、"}, {"f": "audio/e3/L1-wb-53__2.mp3", "t": "非寒、"}, {"f": "audio/e3/L1-wb-53__3.mp3", "t": "非暑、"}, {"f": "audio/e3/L1-wb-53__4.mp3", "t": "非湿，"}, {"f": "audio/e3/L1-wb-53__5.mp3", "t": "乃天地间别有一种异气所感。"}], "L1-wb-54": [{"f": "audio/7c/L1-wb-54__0.mp3", "t": "本气充满，"}, {"f": "audio/7c/L1-wb-54__1.mp3", "t": "邪不易入；"}, {"f": "audio/7c/L1-wb-54__2.mp3", "t": "本气适逢亏欠，"}, {"f": "audio/7c/L1-wb-54__3.mp3", "t": "呼吸之间，"}, {"f": "audio/7c/L1-wb-54__4.mp3", "t": "外邪因而乘之。"}], "L1-wb-55": [{"f": "audio/3f/L1-wb-55__0.mp3", "t": "温疫初起，"}, {"f": "audio/3f/L1-wb-55__1.mp3", "t": "先憎寒而后发热，"}, {"f": "audio/3f/L1-wb-55__2.mp3", "t": "日后但热而无憎寒也。"}, {"f": "audio/3f/L1-wb-55__3.mp3", "t": "初得之二三日，"}, {"f": "audio/3f/L1-wb-55__4.mp3", "t": "其脉不浮不沉而数，"}, {"f": "audio/3f/L1-wb-55__5.mp3", "t": "昼夜发热，"}, {"f": "audio/3f/L1-wb-55__6.mp3", "t": "日晡益甚，"}, {"f": "audio/3f/L1-wb-55__7.mp3", "t": "头疼身痛，"}, {"f": "audio/3f/L1-wb-55__8.mp3", "t": "宜达原饮。"}], "L1-wb-56": [{"f": "audio/2e/L1-wb-56__0.mp3", "t": "大凡客邪贵乎早逐，"}, {"f": "audio/2e/L1-wb-56__1.mp3", "t": "乘人气血未乱，"}, {"f": "audio/2e/L1-wb-56__2.mp3", "t": "肌肉未消，"}, {"f": "audio/2e/L1-wb-56__3.mp3", "t": "津液未耗，"}, {"f": "audio/2e/L1-wb-56__4.mp3", "t": "病人不至危殆，"}, {"f": "audio/2e/L1-wb-56__5.mp3", "t": "投剂不至掣肘，"}, {"f": "audio/2e/L1-wb-56__6.mp3", "t": "愈后亦易平复。"}], "L1-wb-57": [{"f": "audio/58/L1-wb-57__0.mp3", "t": "伤寒在下其燥结，"}, {"f": "audio/58/L1-wb-57__1.mp3", "t": "时疫在下其郁热。"}], "L1-wb-58": [{"f": "audio/60/L1-wb-58__0.mp3", "t": "春温一证，"}, {"f": "audio/60/L1-wb-58__1.mp3", "t": "由冬令收藏未固，"}, {"f": "audio/60/L1-wb-58__2.mp3", "t": "昔人以冬寒内伏，"}, {"f": "audio/60/L1-wb-58__3.mp3", "t": "藏于少阴，"}, {"f": "audio/60/L1-wb-58__4.mp3", "t": "入春发于少阳。"}], "L1-wb-59": [{"f": "audio/18/L1-wb-59__0.mp3", "t": "风温者，"}, {"f": "audio/18/L1-wb-59__1.mp3", "t": "春月受风，"}, {"f": "audio/18/L1-wb-59__2.mp3", "t": "其气已温，"}, {"f": "audio/18/L1-wb-59__3.mp3", "t": "经谓春病在头，"}, {"f": "audio/18/L1-wb-59__4.mp3", "t": "治在上焦。"}, {"f": "audio/18/L1-wb-59__5.mp3", "t": "肺位最高，"}, {"f": "audio/18/L1-wb-59__6.mp3", "t": "邪必先伤。"}], "school-sch-nj-0": [{"f": "audio/6b/school-sch-nj-0__0.mp3", "t": "黄帝曰："}, {"f": "audio/6b/school-sch-nj-0__1.mp3", "t": "阴阳者，"}, {"f": "audio/6b/school-sch-nj-0__2.mp3", "t": "天地之道也，"}, {"f": "audio/6b/school-sch-nj-0__3.mp3", "t": "万物之纲纪，"}, {"f": "audio/6b/school-sch-nj-0__4.mp3", "t": "变化之父母，"}, {"f": "audio/6b/school-sch-nj-0__5.mp3", "t": "生杀之本始，"}, {"f": "audio/6b/school-sch-nj-0__6.mp3", "t": "神明之府也。"}, {"f": "audio/6b/school-sch-nj-0__7.mp3", "t": "治病必求于本。"}, {"f": "audio/6b/school-sch-nj-0__8.mp3", "t": "故积阳为天，"}, {"f": "audio/6b/school-sch-nj-0__9.mp3", "t": "积阴为地。"}, {"f": "audio/6b/school-sch-nj-0__10.mp3", "t": "阴静阳躁。"}, {"f": "audio/6b/school-sch-nj-0__11.mp3", "t": "阳生阴长，"}, {"f": "audio/6b/school-sch-nj-0__12.mp3", "t": "阳杀阴藏。"}, {"f": "audio/6b/school-sch-nj-0__13.mp3", "t": "阳化气，"}, {"f": "audio/6b/school-sch-nj-0__14.mp3", "t": "阴成形。"}, {"f": "audio/6b/school-sch-nj-0__15.mp3", "t": "寒极生热，"}, {"f": "audio/6b/school-sch-nj-0__16.mp3", "t": "热极生寒。"}, {"f": "audio/6b/school-sch-nj-0__17.mp3", "t": "寒气生浊，"}, {"f": "audio/6b/school-sch-nj-0__18.mp3", "t": "热气生清。"}, {"f": "audio/6b/school-sch-nj-0__19.mp3", "t": "清气在下，"}, {"f": "audio/6b/school-sch-nj-0__20.mp3", "t": "则生飧泄。"}, {"f": "audio/6b/school-sch-nj-0__21.mp3", "t": "浊气在上，"}, {"f": "audio/6b/school-sch-nj-0__22.mp3", "t": "则生䐜胀。"}, {"f": "audio/6b/school-sch-nj-0__23.mp3", "t": "此阴阳反作，"}, {"f": "audio/6b/school-sch-nj-0__24.mp3", "t": "病之逆从也。"}], "school-sch-nj-1": [{"f": "audio/52/school-sch-nj-1__0.mp3", "t": "故清阳为天，"}, {"f": "audio/52/school-sch-nj-1__1.mp3", "t": "浊阴为地。"}, {"f": "audio/52/school-sch-nj-1__2.mp3", "t": "地气上为云，"}, {"f": "audio/52/school-sch-nj-1__3.mp3", "t": "天气下为雨；"}, {"f": "audio/52/school-sch-nj-1__4.mp3", "t": "雨出地气，"}, {"f": "audio/52/school-sch-nj-1__5.mp3", "t": "云出天气。"}, {"f": "audio/52/school-sch-nj-1__6.mp3", "t": "故清阳出上窍，"}, {"f": "audio/52/school-sch-nj-1__7.mp3", "t": "浊阴出下窍；"}, {"f": "audio/52/school-sch-nj-1__8.mp3", "t": "清阳发腠理，"}, {"f": "audio/52/school-sch-nj-1__9.mp3", "t": "浊阴走五藏；"}, {"f": "audio/52/school-sch-nj-1__10.mp3", "t": "清阳实四支，"}, {"f": "audio/52/school-sch-nj-1__11.mp3", "t": "浊阴归六府。"}], "school-sch-nj-2": [{"f": "audio/07/school-sch-nj-2__0.mp3", "t": "水为阴，"}, {"f": "audio/07/school-sch-nj-2__1.mp3", "t": "火为阳，"}, {"f": "audio/07/school-sch-nj-2__2.mp3", "t": "阳为气，"}, {"f": "audio/07/school-sch-nj-2__3.mp3", "t": "阴为味，"}, {"f": "audio/07/school-sch-nj-2__4.mp3", "t": "味归形，"}, {"f": "audio/07/school-sch-nj-2__5.mp3", "t": "形归气，"}, {"f": "audio/07/school-sch-nj-2__6.mp3", "t": "气归精，"}, {"f": "audio/07/school-sch-nj-2__7.mp3", "t": "精归化，"}, {"f": "audio/07/school-sch-nj-2__8.mp3", "t": "精食气，"}, {"f": "audio/07/school-sch-nj-2__9.mp3", "t": "形食味，"}, {"f": "audio/07/school-sch-nj-2__10.mp3", "t": "化生精，"}, {"f": "audio/07/school-sch-nj-2__11.mp3", "t": "气生形。"}, {"f": "audio/07/school-sch-nj-2__12.mp3", "t": "味伤形，"}, {"f": "audio/07/school-sch-nj-2__13.mp3", "t": "气伤精，"}, {"f": "audio/07/school-sch-nj-2__14.mp3", "t": "精化为气，"}, {"f": "audio/07/school-sch-nj-2__15.mp3", "t": "气伤于味。"}], "school-sch-nj-3": [{"f": "audio/00/school-sch-nj-3__0.mp3", "t": "阴胜则阳病，"}, {"f": "audio/00/school-sch-nj-3__1.mp3", "t": "阳胜则阴病。"}, {"f": "audio/00/school-sch-nj-3__2.mp3", "t": "阳胜则热，"}, {"f": "audio/00/school-sch-nj-3__3.mp3", "t": "阴胜则寒。"}, {"f": "audio/00/school-sch-nj-3__4.mp3", "t": "重寒则热，"}, {"f": "audio/00/school-sch-nj-3__5.mp3", "t": "重热则寒。"}, {"f": "audio/00/school-sch-nj-3__6.mp3", "t": "寒伤形，"}, {"f": "audio/00/school-sch-nj-3__7.mp3", "t": "热伤气，"}, {"f": "audio/00/school-sch-nj-3__8.mp3", "t": "气伤痛，"}, {"f": "audio/00/school-sch-nj-3__9.mp3", "t": "形伤肿。"}, {"f": "audio/00/school-sch-nj-3__10.mp3", "t": "故先痛而后肿者，"}, {"f": "audio/00/school-sch-nj-3__11.mp3", "t": "气伤形也；"}, {"f": "audio/00/school-sch-nj-3__12.mp3", "t": "先肿而后痛者，"}, {"f": "audio/00/school-sch-nj-3__13.mp3", "t": "形伤气也。"}, {"f": "audio/00/school-sch-nj-3__14.mp3", "t": "风胜则动，"}, {"f": "audio/00/school-sch-nj-3__15.mp3", "t": "热胜则肿，"}, {"f": "audio/00/school-sch-nj-3__16.mp3", "t": "燥胜则干，"}, {"f": "audio/00/school-sch-nj-3__17.mp3", "t": "寒胜则浮，"}, {"f": "audio/00/school-sch-nj-3__18.mp3", "t": "湿胜则濡泻。"}], "school-sch-nj-4": [{"f": "audio/62/school-sch-nj-4__0.mp3", "t": "天有四时五行，"}, {"f": "audio/62/school-sch-nj-4__1.mp3", "t": "以生长收藏，"}, {"f": "audio/62/school-sch-nj-4__2.mp3", "t": "以生寒暑燥湿风。"}, {"f": "audio/62/school-sch-nj-4__3.mp3", "t": "人有五藏化五气，"}, {"f": "audio/62/school-sch-nj-4__4.mp3", "t": "以生喜怒忧恐。"}, {"f": "audio/62/school-sch-nj-4__5.mp3", "t": "故喜怒伤气，"}, {"f": "audio/62/school-sch-nj-4__6.mp3", "t": "寒暑伤形；"}, {"f": "audio/62/school-sch-nj-4__7.mp3", "t": "暴怒伤阴，"}, {"f": "audio/62/school-sch-nj-4__8.mp3", "t": "暴喜伤阳。"}, {"f": "audio/62/school-sch-nj-4__9.mp3", "t": "厥气上行，"}, {"f": "audio/62/school-sch-nj-4__10.mp3", "t": "满脉去形。"}, {"f": "audio/62/school-sch-nj-4__11.mp3", "t": "喜怒不节，"}, {"f": "audio/62/school-sch-nj-4__12.mp3", "t": "寒暑过度，"}, {"f": "audio/62/school-sch-nj-4__13.mp3", "t": "生乃不固。"}, {"f": "audio/62/school-sch-nj-4__14.mp3", "t": "故重阴必阳，"}, {"f": "audio/62/school-sch-nj-4__15.mp3", "t": "重阳必阴。"}, {"f": "audio/62/school-sch-nj-4__16.mp3", "t": "故曰："}, {"f": "audio/62/school-sch-nj-4__17.mp3", "t": "冬伤于寒，"}, {"f": "audio/62/school-sch-nj-4__18.mp3", "t": "春必温病；"}, {"f": "audio/62/school-sch-nj-4__19.mp3", "t": "春伤于风，"}, {"f": "audio/62/school-sch-nj-4__20.mp3", "t": "夏生飧泄；"}, {"f": "audio/62/school-sch-nj-4__21.mp3", "t": "夏伤于暑，"}, {"f": "audio/62/school-sch-nj-4__22.mp3", "t": "秋必痎疟；"}, {"f": "audio/62/school-sch-nj-4__23.mp3", "t": "秋伤于湿，"}, {"f": "audio/62/school-sch-nj-4__24.mp3", "t": "冬生咳嗽。"}], "school-sch-nj-5": [{"f": "audio/20/school-sch-nj-5__0.mp3", "t": "帝曰："}, {"f": "audio/20/school-sch-nj-5__1.mp3", "t": "法阴阳奈何？"}, {"f": "audio/20/school-sch-nj-5__2.mp3", "t": "岐伯曰："}, {"f": "audio/20/school-sch-nj-5__3.mp3", "t": "阳胜则身热，"}, {"f": "audio/20/school-sch-nj-5__4.mp3", "t": "腠理闭，"}, {"f": "audio/20/school-sch-nj-5__5.mp3", "t": "喘粗为之俛仰，"}, {"f": "audio/20/school-sch-nj-5__6.mp3", "t": "汗不出而热，"}, {"f": "audio/20/school-sch-nj-5__7.mp3", "t": "齿干以烦冤，"}, {"f": "audio/20/school-sch-nj-5__8.mp3", "t": "腹满，"}, {"f": "audio/20/school-sch-nj-5__9.mp3", "t": "死，"}, {"f": "audio/20/school-sch-nj-5__10.mp3", "t": "能冬不能夏；"}, {"f": "audio/20/school-sch-nj-5__11.mp3", "t": "阴胜则身寒，"}, {"f": "audio/20/school-sch-nj-5__12.mp3", "t": "汗出身常清，"}, {"f": "audio/20/school-sch-nj-5__13.mp3", "t": "数栗而寒，"}, {"f": "audio/20/school-sch-nj-5__14.mp3", "t": "寒则厥，"}, {"f": "audio/20/school-sch-nj-5__15.mp3", "t": "厥则腹满，"}, {"f": "audio/20/school-sch-nj-5__16.mp3", "t": "死，"}, {"f": "audio/20/school-sch-nj-5__17.mp3", "t": "能夏不能冬。"}, {"f": "audio/20/school-sch-nj-5__18.mp3", "t": "此阴阳更胜之变，"}, {"f": "audio/20/school-sch-nj-5__19.mp3", "t": "病之形能也。"}], "school-sch-nj-6": [{"f": "audio/4c/school-sch-nj-6__0.mp3", "t": "帝曰："}, {"f": "audio/4c/school-sch-nj-6__1.mp3", "t": "调此二者奈何？"}, {"f": "audio/4c/school-sch-nj-6__2.mp3", "t": "岐伯曰："}, {"f": "audio/4c/school-sch-nj-6__3.mp3", "t": "能知七损八益，"}, {"f": "audio/4c/school-sch-nj-6__4.mp3", "t": "则二者可调；"}, {"f": "audio/4c/school-sch-nj-6__5.mp3", "t": "不知用此，"}, {"f": "audio/4c/school-sch-nj-6__6.mp3", "t": "则早衰之节也。"}, {"f": "audio/4c/school-sch-nj-6__7.mp3", "t": "年四十，"}, {"f": "audio/4c/school-sch-nj-6__8.mp3", "t": "而阴气自半也，"}, {"f": "audio/4c/school-sch-nj-6__9.mp3", "t": "起居衰矣；"}, {"f": "audio/4c/school-sch-nj-6__10.mp3", "t": "年五十，"}, {"f": "audio/4c/school-sch-nj-6__11.mp3", "t": "体重，"}, {"f": "audio/4c/school-sch-nj-6__12.mp3", "t": "耳目不聪明矣；"}, {"f": "audio/4c/school-sch-nj-6__13.mp3", "t": "年六十，"}, {"f": "audio/4c/school-sch-nj-6__14.mp3", "t": "阴痿，"}, {"f": "audio/4c/school-sch-nj-6__15.mp3", "t": "气大衰，"}, {"f": "audio/4c/school-sch-nj-6__16.mp3", "t": "九窍不利，"}, {"f": "audio/4c/school-sch-nj-6__17.mp3", "t": "下虚上实，"}, {"f": "audio/4c/school-sch-nj-6__18.mp3", "t": "涕泣俱出矣。"}, {"f": "audio/4c/school-sch-nj-6__19.mp3", "t": "故曰："}, {"f": "audio/4c/school-sch-nj-6__20.mp3", "t": "知之则强，"}, {"f": "audio/4c/school-sch-nj-6__21.mp3", "t": "不知则老，"}, {"f": "audio/4c/school-sch-nj-6__22.mp3", "t": "故同出而名异耳。"}, {"f": "audio/4c/school-sch-nj-6__23.mp3", "t": "智者察同，"}, {"f": "audio/4c/school-sch-nj-6__24.mp3", "t": "愚者察异，"}, {"f": "audio/4c/school-sch-nj-6__25.mp3", "t": "愚者不足，"}, {"f": "audio/4c/school-sch-nj-6__26.mp3", "t": "智者有余。"}, {"f": "audio/4c/school-sch-nj-6__27.mp3", "t": "有余则耳目聪明，"}, {"f": "audio/4c/school-sch-nj-6__28.mp3", "t": "身体轻强，"}, {"f": "audio/4c/school-sch-nj-6__29.mp3", "t": "老者复壮，"}, {"f": "audio/4c/school-sch-nj-6__30.mp3", "t": "壮者益治。"}, {"f": "audio/4c/school-sch-nj-6__31.mp3", "t": "是以圣人为无为之事，"}, {"f": "audio/4c/school-sch-nj-6__32.mp3", "t": "乐恬愉之能，"}, {"f": "audio/4c/school-sch-nj-6__33.mp3", "t": "从欲快志于虚无之守，"}, {"f": "audio/4c/school-sch-nj-6__34.mp3", "t": "故寿命无穷，"}, {"f": "audio/4c/school-sch-nj-6__35.mp3", "t": "与天地终，"}, {"f": "audio/4c/school-sch-nj-6__36.mp3", "t": "此圣人之治身也。"}], "school-sch-nj-7": [{"f": "audio/ed/school-sch-nj-7__0.mp3", "t": "故邪风之至，"}, {"f": "audio/ed/school-sch-nj-7__1.mp3", "t": "疾如风雨，"}, {"f": "audio/ed/school-sch-nj-7__2.mp3", "t": "故善治者治皮毛，"}, {"f": "audio/ed/school-sch-nj-7__3.mp3", "t": "其次治肌肤，"}, {"f": "audio/ed/school-sch-nj-7__4.mp3", "t": "其次治六府，"}, {"f": "audio/ed/school-sch-nj-7__5.mp3", "t": "其次治五藏。"}, {"f": "audio/ed/school-sch-nj-7__6.mp3", "t": "治五藏者，"}, {"f": "audio/ed/school-sch-nj-7__7.mp3", "t": "半死半生也。"}, {"f": "audio/ed/school-sch-nj-7__8.mp3", "t": "故天之邪气，"}, {"f": "audio/ed/school-sch-nj-7__9.mp3", "t": "感则害人五藏；"}, {"f": "audio/ed/school-sch-nj-7__10.mp3", "t": "水谷之寒热，"}, {"f": "audio/ed/school-sch-nj-7__11.mp3", "t": "感则害于六府；"}, {"f": "audio/ed/school-sch-nj-7__12.mp3", "t": "地之湿气，"}, {"f": "audio/ed/school-sch-nj-7__13.mp3", "t": "感则害皮肉筋脉。"}], "school-sch-nj-8": [{"f": "audio/20/school-sch-nj-8__0.mp3", "t": "故善用针者，"}, {"f": "audio/20/school-sch-nj-8__1.mp3", "t": "从阴引阳，"}, {"f": "audio/20/school-sch-nj-8__2.mp3", "t": "从阳引阴；"}, {"f": "audio/20/school-sch-nj-8__3.mp3", "t": "以右治左，"}, {"f": "audio/20/school-sch-nj-8__4.mp3", "t": "以左治右；"}, {"f": "audio/20/school-sch-nj-8__5.mp3", "t": "以我知彼，"}, {"f": "audio/20/school-sch-nj-8__6.mp3", "t": "以表知里，"}, {"f": "audio/20/school-sch-nj-8__7.mp3", "t": "以观过与不及之理，"}, {"f": "audio/20/school-sch-nj-8__8.mp3", "t": "见微得过，"}, {"f": "audio/20/school-sch-nj-8__9.mp3", "t": "用之不殆。"}], "school-sch-nj-9": [{"f": "audio/29/school-sch-nj-9__0.mp3", "t": "善诊者，"}, {"f": "audio/29/school-sch-nj-9__1.mp3", "t": "察色按脉，"}, {"f": "audio/29/school-sch-nj-9__2.mp3", "t": "先别阴阳，"}, {"f": "audio/29/school-sch-nj-9__3.mp3", "t": "审清浊而知部分；"}, {"f": "audio/29/school-sch-nj-9__4.mp3", "t": "视喘息，"}, {"f": "audio/29/school-sch-nj-9__5.mp3", "t": "听音声而知所苦；"}, {"f": "audio/29/school-sch-nj-9__6.mp3", "t": "观权衡规矩而知病所主；"}, {"f": "audio/29/school-sch-nj-9__7.mp3", "t": "按尺寸，"}, {"f": "audio/29/school-sch-nj-9__8.mp3", "t": "观浮沉滑涩而知病所生。"}, {"f": "audio/29/school-sch-nj-9__9.mp3", "t": "以治无过，"}, {"f": "audio/29/school-sch-nj-9__10.mp3", "t": "以诊则不失矣。"}], "school-sch-nj-10": [{"f": "audio/9d/school-sch-nj-10__0.mp3", "t": "黄帝曰："}, {"f": "audio/9d/school-sch-nj-10__1.mp3", "t": "夫自古通天者，"}, {"f": "audio/9d/school-sch-nj-10__2.mp3", "t": "生之本，"}, {"f": "audio/9d/school-sch-nj-10__3.mp3", "t": "本于阴阳。"}, {"f": "audio/9d/school-sch-nj-10__4.mp3", "t": "天地之间，"}, {"f": "audio/9d/school-sch-nj-10__5.mp3", "t": "六合之内，"}, {"f": "audio/9d/school-sch-nj-10__6.mp3", "t": "其气九州、"}, {"f": "audio/9d/school-sch-nj-10__7.mp3", "t": "九窍、"}, {"f": "audio/9d/school-sch-nj-10__8.mp3", "t": "五藏、"}, {"f": "audio/9d/school-sch-nj-10__9.mp3", "t": "十二节，"}, {"f": "audio/9d/school-sch-nj-10__10.mp3", "t": "皆通乎天气。"}, {"f": "audio/9d/school-sch-nj-10__11.mp3", "t": "其生五，"}, {"f": "audio/9d/school-sch-nj-10__12.mp3", "t": "其气三，"}, {"f": "audio/9d/school-sch-nj-10__13.mp3", "t": "数犯此者，"}, {"f": "audio/9d/school-sch-nj-10__14.mp3", "t": "则邪气伤人，"}, {"f": "audio/9d/school-sch-nj-10__15.mp3", "t": "此寿命之本也。"}, {"f": "audio/9d/school-sch-nj-10__16.mp3", "t": "苍天之气，"}, {"f": "audio/9d/school-sch-nj-10__17.mp3", "t": "清静则志意治，"}, {"f": "audio/9d/school-sch-nj-10__18.mp3", "t": "顺之则阳气固，"}, {"f": "audio/9d/school-sch-nj-10__19.mp3", "t": "虽有贼邪，"}, {"f": "audio/9d/school-sch-nj-10__20.mp3", "t": "弗能害也。"}, {"f": "audio/9d/school-sch-nj-10__21.mp3", "t": "此因时之序。"}, {"f": "audio/9d/school-sch-nj-10__22.mp3", "t": "故圣人传精神，"}, {"f": "audio/9d/school-sch-nj-10__23.mp3", "t": "服天气，"}, {"f": "audio/9d/school-sch-nj-10__24.mp3", "t": "而通神明。"}, {"f": "audio/9d/school-sch-nj-10__25.mp3", "t": "失之，"}, {"f": "audio/9d/school-sch-nj-10__26.mp3", "t": "则内闭九窍，"}, {"f": "audio/9d/school-sch-nj-10__27.mp3", "t": "外壅肌肉，"}, {"f": "audio/9d/school-sch-nj-10__28.mp3", "t": "卫气散解，"}, {"f": "audio/9d/school-sch-nj-10__29.mp3", "t": "此谓自伤，"}, {"f": "audio/9d/school-sch-nj-10__30.mp3", "t": "气之削也。"}], "school-sch-nj-11": [{"f": "audio/4e/school-sch-nj-11__0.mp3", "t": "阳气者，"}, {"f": "audio/4e/school-sch-nj-11__1.mp3", "t": "若天与日，"}, {"f": "audio/4e/school-sch-nj-11__2.mp3", "t": "失其所则折寿而不彰。"}, {"f": "audio/4e/school-sch-nj-11__3.mp3", "t": "故天运当以日光明。"}, {"f": "audio/4e/school-sch-nj-11__4.mp3", "t": "是故阳因而上，"}, {"f": "audio/4e/school-sch-nj-11__5.mp3", "t": "卫外者也。"}, {"f": "audio/4e/school-sch-nj-11__6.mp3", "t": "因于寒，"}, {"f": "audio/4e/school-sch-nj-11__7.mp3", "t": "欲如运枢，"}, {"f": "audio/4e/school-sch-nj-11__8.mp3", "t": "起居如惊，"}, {"f": "audio/4e/school-sch-nj-11__9.mp3", "t": "神气乃浮；"}, {"f": "audio/4e/school-sch-nj-11__10.mp3", "t": "因于暑，"}, {"f": "audio/4e/school-sch-nj-11__11.mp3", "t": "汗，"}, {"f": "audio/4e/school-sch-nj-11__12.mp3", "t": "烦则喘喝，"}, {"f": "audio/4e/school-sch-nj-11__13.mp3", "t": "静则多言，"}, {"f": "audio/4e/school-sch-nj-11__14.mp3", "t": "体若燔炭，"}, {"f": "audio/4e/school-sch-nj-11__15.mp3", "t": "汗出而散；"}, {"f": "audio/4e/school-sch-nj-11__16.mp3", "t": "因于湿，"}, {"f": "audio/4e/school-sch-nj-11__17.mp3", "t": "首如裹，"}, {"f": "audio/4e/school-sch-nj-11__18.mp3", "t": "湿热不攘，"}, {"f": "audio/4e/school-sch-nj-11__19.mp3", "t": "大筋緛短，"}, {"f": "audio/4e/school-sch-nj-11__20.mp3", "t": "小筋弛长。"}, {"f": "audio/4e/school-sch-nj-11__21.mp3", "t": "緛短为拘，"}, {"f": "audio/4e/school-sch-nj-11__22.mp3", "t": "弛长为痿；"}, {"f": "audio/4e/school-sch-nj-11__23.mp3", "t": "因于气，"}, {"f": "audio/4e/school-sch-nj-11__24.mp3", "t": "为肿，"}, {"f": "audio/4e/school-sch-nj-11__25.mp3", "t": "四维相代，"}, {"f": "audio/4e/school-sch-nj-11__26.mp3", "t": "阳气乃竭。"}], "school-sch-nj-12": [{"f": "audio/b5/school-sch-nj-12__0.mp3", "t": "阳气者，"}, {"f": "audio/b5/school-sch-nj-12__1.mp3", "t": "烦劳则张，"}, {"f": "audio/b5/school-sch-nj-12__2.mp3", "t": "精绝，"}, {"f": "audio/b5/school-sch-nj-12__3.mp3", "t": "辟积于夏，"}, {"f": "audio/b5/school-sch-nj-12__4.mp3", "t": "使人煎厥；"}, {"f": "audio/b5/school-sch-nj-12__5.mp3", "t": "目盲不可以视，"}, {"f": "audio/b5/school-sch-nj-12__6.mp3", "t": "耳闭不可以听，"}, {"f": "audio/b5/school-sch-nj-12__7.mp3", "t": "溃溃乎若坏都，"}, {"f": "audio/b5/school-sch-nj-12__8.mp3", "t": "汩汩乎不可止。"}, {"f": "audio/b5/school-sch-nj-12__9.mp3", "t": "阳气者，"}, {"f": "audio/b5/school-sch-nj-12__10.mp3", "t": "大怒则形气绝，"}, {"f": "audio/b5/school-sch-nj-12__11.mp3", "t": "而血菀于上，"}, {"f": "audio/b5/school-sch-nj-12__12.mp3", "t": "使人薄厥。"}, {"f": "audio/b5/school-sch-nj-12__13.mp3", "t": "有伤于筋，"}, {"f": "audio/b5/school-sch-nj-12__14.mp3", "t": "纵，"}, {"f": "audio/b5/school-sch-nj-12__15.mp3", "t": "其若不容。"}, {"f": "audio/b5/school-sch-nj-12__16.mp3", "t": "汗出偏沮，"}, {"f": "audio/b5/school-sch-nj-12__17.mp3", "t": "使人偏枯。"}, {"f": "audio/b5/school-sch-nj-12__18.mp3", "t": "汗出见湿，"}, {"f": "audio/b5/school-sch-nj-12__19.mp3", "t": "乃生痤痱。"}, {"f": "audio/b5/school-sch-nj-12__20.mp3", "t": "高梁之变，"}, {"f": "audio/b5/school-sch-nj-12__21.mp3", "t": "足生大丁，"}, {"f": "audio/b5/school-sch-nj-12__22.mp3", "t": "受如持虚。"}, {"f": "audio/b5/school-sch-nj-12__23.mp3", "t": "劳汗当风，"}, {"f": "audio/b5/school-sch-nj-12__24.mp3", "t": "寒薄为皶，"}, {"f": "audio/b5/school-sch-nj-12__25.mp3", "t": "郁乃痤。"}], "school-sch-nj-13": [{"f": "audio/27/school-sch-nj-13__0.mp3", "t": "阳气者，"}, {"f": "audio/27/school-sch-nj-13__1.mp3", "t": "精则养神，"}, {"f": "audio/27/school-sch-nj-13__2.mp3", "t": "柔则养筋。"}, {"f": "audio/27/school-sch-nj-13__3.mp3", "t": "开合不得，"}, {"f": "audio/27/school-sch-nj-13__4.mp3", "t": "寒气从之，"}, {"f": "audio/27/school-sch-nj-13__5.mp3", "t": "乃生大偻。"}, {"f": "audio/27/school-sch-nj-13__6.mp3", "t": "陷脉为瘘，"}, {"f": "audio/27/school-sch-nj-13__7.mp3", "t": "留连肉腠，"}, {"f": "audio/27/school-sch-nj-13__8.mp3", "t": "俞气化薄，"}, {"f": "audio/27/school-sch-nj-13__9.mp3", "t": "传为善畏，"}, {"f": "audio/27/school-sch-nj-13__10.mp3", "t": "及为惊骇。"}, {"f": "audio/27/school-sch-nj-13__11.mp3", "t": "营气不从，"}, {"f": "audio/27/school-sch-nj-13__12.mp3", "t": "逆于肉理，"}, {"f": "audio/27/school-sch-nj-13__13.mp3", "t": "乃生痈肿。"}, {"f": "audio/27/school-sch-nj-13__14.mp3", "t": "魄汗未尽，"}, {"f": "audio/27/school-sch-nj-13__15.mp3", "t": "形弱而气烁，"}, {"f": "audio/27/school-sch-nj-13__16.mp3", "t": "穴俞以闭，"}, {"f": "audio/27/school-sch-nj-13__17.mp3", "t": "发为风疟。"}], "school-sch-nj-14": [{"f": "audio/aa/school-sch-nj-14__0.mp3", "t": "故风者，"}, {"f": "audio/aa/school-sch-nj-14__1.mp3", "t": "百病之始也，"}, {"f": "audio/aa/school-sch-nj-14__2.mp3", "t": "清静则肉腠闭拒，"}, {"f": "audio/aa/school-sch-nj-14__3.mp3", "t": "虽有大风苛毒，"}, {"f": "audio/aa/school-sch-nj-14__4.mp3", "t": "弗之能害，"}, {"f": "audio/aa/school-sch-nj-14__5.mp3", "t": "此因时之序也。"}, {"f": "audio/aa/school-sch-nj-14__6.mp3", "t": "故病久则传化，"}, {"f": "audio/aa/school-sch-nj-14__7.mp3", "t": "上下不并，"}, {"f": "audio/aa/school-sch-nj-14__8.mp3", "t": "良医弗为。"}, {"f": "audio/aa/school-sch-nj-14__9.mp3", "t": "故阳畜积病死，"}, {"f": "audio/aa/school-sch-nj-14__10.mp3", "t": "而阳气当隔，"}, {"f": "audio/aa/school-sch-nj-14__11.mp3", "t": "隔者当泻。"}, {"f": "audio/aa/school-sch-nj-14__12.mp3", "t": "不亟正治，"}, {"f": "audio/aa/school-sch-nj-14__13.mp3", "t": "粗乃败之。"}], "school-sch-nj-15": [{"f": "audio/76/school-sch-nj-15__0.mp3", "t": "故阳气者，"}, {"f": "audio/76/school-sch-nj-15__1.mp3", "t": "一日而主外，"}, {"f": "audio/76/school-sch-nj-15__2.mp3", "t": "平旦人气生，"}, {"f": "audio/76/school-sch-nj-15__3.mp3", "t": "日中而阳气隆，"}, {"f": "audio/76/school-sch-nj-15__4.mp3", "t": "日西而阳气已虚，"}, {"f": "audio/76/school-sch-nj-15__5.mp3", "t": "气门乃闭。"}, {"f": "audio/76/school-sch-nj-15__6.mp3", "t": "是故暮而收拒，"}, {"f": "audio/76/school-sch-nj-15__7.mp3", "t": "无扰筋骨，"}, {"f": "audio/76/school-sch-nj-15__8.mp3", "t": "无见雾露，"}, {"f": "audio/76/school-sch-nj-15__9.mp3", "t": "反此三时，"}, {"f": "audio/76/school-sch-nj-15__10.mp3", "t": "形乃困薄。"}], "school-sch-nj-16": [{"f": "audio/7c/school-sch-nj-16__0.mp3", "t": "岐伯曰："}, {"f": "audio/7c/school-sch-nj-16__1.mp3", "t": "阴者藏精而起亟也；"}, {"f": "audio/7c/school-sch-nj-16__2.mp3", "t": "阳者卫外而为固也。"}, {"f": "audio/7c/school-sch-nj-16__3.mp3", "t": "阴不胜其阳，"}, {"f": "audio/7c/school-sch-nj-16__4.mp3", "t": "则脉流薄疾，"}, {"f": "audio/7c/school-sch-nj-16__5.mp3", "t": "并乃狂；"}, {"f": "audio/7c/school-sch-nj-16__6.mp3", "t": "阳不胜其阴，"}, {"f": "audio/7c/school-sch-nj-16__7.mp3", "t": "则五藏气争，"}, {"f": "audio/7c/school-sch-nj-16__8.mp3", "t": "九窍不通。"}, {"f": "audio/7c/school-sch-nj-16__9.mp3", "t": "是以圣人陈阴阳，"}, {"f": "audio/7c/school-sch-nj-16__10.mp3", "t": "筋脉和同，"}, {"f": "audio/7c/school-sch-nj-16__11.mp3", "t": "骨髓坚固，"}, {"f": "audio/7c/school-sch-nj-16__12.mp3", "t": "气血皆从。"}, {"f": "audio/7c/school-sch-nj-16__13.mp3", "t": "如是则内外调和，"}, {"f": "audio/7c/school-sch-nj-16__14.mp3", "t": "邪不能害，"}, {"f": "audio/7c/school-sch-nj-16__15.mp3", "t": "耳目聪明，"}, {"f": "audio/7c/school-sch-nj-16__16.mp3", "t": "气立如故。"}], "school-sch-nj-17": [{"f": "audio/86/school-sch-nj-17__0.mp3", "t": "风客淫气，"}, {"f": "audio/86/school-sch-nj-17__1.mp3", "t": "精乃亡，"}, {"f": "audio/86/school-sch-nj-17__2.mp3", "t": "邪伤肝也。"}, {"f": "audio/86/school-sch-nj-17__3.mp3", "t": "因而饱食，"}, {"f": "audio/86/school-sch-nj-17__4.mp3", "t": "筋脉横解，"}, {"f": "audio/86/school-sch-nj-17__5.mp3", "t": "肠澼为痔。"}, {"f": "audio/86/school-sch-nj-17__6.mp3", "t": "因而大饮，"}, {"f": "audio/86/school-sch-nj-17__7.mp3", "t": "则气逆。"}, {"f": "audio/86/school-sch-nj-17__8.mp3", "t": "因而强力，"}, {"f": "audio/86/school-sch-nj-17__9.mp3", "t": "肾气乃伤，"}, {"f": "audio/86/school-sch-nj-17__10.mp3", "t": "高骨乃坏。"}], "school-sch-nj-18": [{"f": "audio/23/school-sch-nj-18__0.mp3", "t": "凡阴阳之要，"}, {"f": "audio/23/school-sch-nj-18__1.mp3", "t": "阳密乃固，"}, {"f": "audio/23/school-sch-nj-18__2.mp3", "t": "两者不和，"}, {"f": "audio/23/school-sch-nj-18__3.mp3", "t": "若春无秋，"}, {"f": "audio/23/school-sch-nj-18__4.mp3", "t": "若冬无夏。"}, {"f": "audio/23/school-sch-nj-18__5.mp3", "t": "因而和之，"}, {"f": "audio/23/school-sch-nj-18__6.mp3", "t": "是谓圣度。"}, {"f": "audio/23/school-sch-nj-18__7.mp3", "t": "故阳强不能密，"}, {"f": "audio/23/school-sch-nj-18__8.mp3", "t": "阴气乃绝。"}, {"f": "audio/23/school-sch-nj-18__9.mp3", "t": "阴平阳秘，"}, {"f": "audio/23/school-sch-nj-18__10.mp3", "t": "精神乃治；"}, {"f": "audio/23/school-sch-nj-18__11.mp3", "t": "阴阳离决，"}, {"f": "audio/23/school-sch-nj-18__12.mp3", "t": "精气乃绝。"}], "school-sch-nj-19": [{"f": "audio/c0/school-sch-nj-19__0.mp3", "t": "因于露风，"}, {"f": "audio/c0/school-sch-nj-19__1.mp3", "t": "乃生寒热。"}, {"f": "audio/c0/school-sch-nj-19__2.mp3", "t": "是以春伤于风，"}, {"f": "audio/c0/school-sch-nj-19__3.mp3", "t": "邪气留连，"}, {"f": "audio/c0/school-sch-nj-19__4.mp3", "t": "乃为洞泄。"}, {"f": "audio/c0/school-sch-nj-19__5.mp3", "t": "夏伤于暑，"}, {"f": "audio/c0/school-sch-nj-19__6.mp3", "t": "秋为痎疟。"}, {"f": "audio/c0/school-sch-nj-19__7.mp3", "t": "秋伤于湿，"}, {"f": "audio/c0/school-sch-nj-19__8.mp3", "t": "上逆而咳，"}, {"f": "audio/c0/school-sch-nj-19__9.mp3", "t": "发为痿厥。"}, {"f": "audio/c0/school-sch-nj-19__10.mp3", "t": "冬伤于寒，"}, {"f": "audio/c0/school-sch-nj-19__11.mp3", "t": "春必温病。"}, {"f": "audio/c0/school-sch-nj-19__12.mp3", "t": "四时之气，"}, {"f": "audio/c0/school-sch-nj-19__13.mp3", "t": "更伤五藏。"}], "school-sch-nj-20": [{"f": "audio/15/school-sch-nj-20__0.mp3", "t": "阴之所生，"}, {"f": "audio/15/school-sch-nj-20__1.mp3", "t": "本在五味；"}, {"f": "audio/15/school-sch-nj-20__2.mp3", "t": "阴之五宫，"}, {"f": "audio/15/school-sch-nj-20__3.mp3", "t": "伤在五味。"}, {"f": "audio/15/school-sch-nj-20__4.mp3", "t": "是故味过于酸，"}, {"f": "audio/15/school-sch-nj-20__5.mp3", "t": "肝气以津，"}, {"f": "audio/15/school-sch-nj-20__6.mp3", "t": "脾气乃绝。"}, {"f": "audio/15/school-sch-nj-20__7.mp3", "t": "味过于咸，"}, {"f": "audio/15/school-sch-nj-20__8.mp3", "t": "大骨气劳，"}, {"f": "audio/15/school-sch-nj-20__9.mp3", "t": "短肌，"}, {"f": "audio/15/school-sch-nj-20__10.mp3", "t": "心气抑。"}, {"f": "audio/15/school-sch-nj-20__11.mp3", "t": "味过于苦，"}, {"f": "audio/15/school-sch-nj-20__12.mp3", "t": "心气喘满，"}, {"f": "audio/15/school-sch-nj-20__13.mp3", "t": "色黑，"}, {"f": "audio/15/school-sch-nj-20__14.mp3", "t": "肾气不衡。"}, {"f": "audio/15/school-sch-nj-20__15.mp3", "t": "味过于甘，"}, {"f": "audio/15/school-sch-nj-20__16.mp3", "t": "脾气濡，"}, {"f": "audio/15/school-sch-nj-20__17.mp3", "t": "胃气乃厚。"}, {"f": "audio/15/school-sch-nj-20__18.mp3", "t": "味过于辛，"}, {"f": "audio/15/school-sch-nj-20__19.mp3", "t": "筋脉沮弛，"}, {"f": "audio/15/school-sch-nj-20__20.mp3", "t": "精神乃央。"}, {"f": "audio/15/school-sch-nj-20__21.mp3", "t": "是故谨和五味，"}, {"f": "audio/15/school-sch-nj-20__22.mp3", "t": "骨正筋柔，"}, {"f": "audio/15/school-sch-nj-20__23.mp3", "t": "气血以流，"}, {"f": "audio/15/school-sch-nj-20__24.mp3", "t": "腠理以密，"}, {"f": "audio/15/school-sch-nj-20__25.mp3", "t": "如是则骨气以精。"}, {"f": "audio/15/school-sch-nj-20__26.mp3", "t": "谨道如法，"}, {"f": "audio/15/school-sch-nj-20__27.mp3", "t": "长有天命。"}], "school-sch-nj-21": [{"f": "audio/25/school-sch-nj-21__0.mp3", "t": "黄帝问曰："}, {"f": "audio/25/school-sch-nj-21__1.mp3", "t": "愿闻十二藏之相使，"}, {"f": "audio/25/school-sch-nj-21__2.mp3", "t": "贵贱何如？"}, {"f": "audio/25/school-sch-nj-21__3.mp3", "t": "岐伯曰："}, {"f": "audio/25/school-sch-nj-21__4.mp3", "t": "悉乎哉问也，"}, {"f": "audio/25/school-sch-nj-21__5.mp3", "t": "请遂言之："}, {"f": "audio/25/school-sch-nj-21__6.mp3", "t": "心者，"}, {"f": "audio/25/school-sch-nj-21__7.mp3", "t": "君主之官也，"}, {"f": "audio/25/school-sch-nj-21__8.mp3", "t": "神明出焉。"}, {"f": "audio/25/school-sch-nj-21__9.mp3", "t": "肺者，"}, {"f": "audio/25/school-sch-nj-21__10.mp3", "t": "相傅之官，"}, {"f": "audio/25/school-sch-nj-21__11.mp3", "t": "治节出焉。"}, {"f": "audio/25/school-sch-nj-21__12.mp3", "t": "肝者，"}, {"f": "audio/25/school-sch-nj-21__13.mp3", "t": "将军之官，"}, {"f": "audio/25/school-sch-nj-21__14.mp3", "t": "谋虑出焉。"}, {"f": "audio/25/school-sch-nj-21__15.mp3", "t": "胆者，"}, {"f": "audio/25/school-sch-nj-21__16.mp3", "t": "中正之官，"}, {"f": "audio/25/school-sch-nj-21__17.mp3", "t": "决断出焉。"}, {"f": "audio/25/school-sch-nj-21__18.mp3", "t": "膻中者，"}, {"f": "audio/25/school-sch-nj-21__19.mp3", "t": "臣使之官，"}, {"f": "audio/25/school-sch-nj-21__20.mp3", "t": "喜乐出焉。"}, {"f": "audio/25/school-sch-nj-21__21.mp3", "t": "脾胃者，"}, {"f": "audio/25/school-sch-nj-21__22.mp3", "t": "仓廪之官，"}, {"f": "audio/25/school-sch-nj-21__23.mp3", "t": "五味出焉。"}, {"f": "audio/25/school-sch-nj-21__24.mp3", "t": "大肠者，"}, {"f": "audio/25/school-sch-nj-21__25.mp3", "t": "传道之官，"}, {"f": "audio/25/school-sch-nj-21__26.mp3", "t": "变化出焉。"}, {"f": "audio/25/school-sch-nj-21__27.mp3", "t": "小肠者，"}, {"f": "audio/25/school-sch-nj-21__28.mp3", "t": "受盛之官，"}, {"f": "audio/25/school-sch-nj-21__29.mp3", "t": "化物出焉。"}, {"f": "audio/25/school-sch-nj-21__30.mp3", "t": "肾者，"}, {"f": "audio/25/school-sch-nj-21__31.mp3", "t": "作强之官，"}, {"f": "audio/25/school-sch-nj-21__32.mp3", "t": "伎巧出焉。"}, {"f": "audio/25/school-sch-nj-21__33.mp3", "t": "三焦者，"}, {"f": "audio/25/school-sch-nj-21__34.mp3", "t": "决渎之官，"}, {"f": "audio/25/school-sch-nj-21__35.mp3", "t": "水道出焉。"}, {"f": "audio/25/school-sch-nj-21__36.mp3", "t": "膀胱者，"}, {"f": "audio/25/school-sch-nj-21__37.mp3", "t": "州都之官，"}, {"f": "audio/25/school-sch-nj-21__38.mp3", "t": "津液藏焉，"}, {"f": "audio/25/school-sch-nj-21__39.mp3", "t": "气化则能出矣。"}, {"f": "audio/25/school-sch-nj-21__40.mp3", "t": "凡此十二官者，"}, {"f": "audio/25/school-sch-nj-21__41.mp3", "t": "不得相失也。"}, {"f": "audio/25/school-sch-nj-21__42.mp3", "t": "故主明则下安，"}, {"f": "audio/25/school-sch-nj-21__43.mp3", "t": "以此养生则寿，"}, {"f": "audio/25/school-sch-nj-21__44.mp3", "t": "没世不殆，"}, {"f": "audio/25/school-sch-nj-21__45.mp3", "t": "以为天下则大昌。"}, {"f": "audio/25/school-sch-nj-21__46.mp3", "t": "主不明则十二官危，"}, {"f": "audio/25/school-sch-nj-21__47.mp3", "t": "使道闭塞而不通，"}, {"f": "audio/25/school-sch-nj-21__48.mp3", "t": "形乃大伤，"}, {"f": "audio/25/school-sch-nj-21__49.mp3", "t": "以此养生则殃，"}, {"f": "audio/25/school-sch-nj-21__50.mp3", "t": "以为天下者，"}, {"f": "audio/25/school-sch-nj-21__51.mp3", "t": "其宗大危，"}, {"f": "audio/25/school-sch-nj-21__52.mp3", "t": "戒之戒之！"}], "school-sch-nj-22": [{"f": "audio/18/school-sch-nj-22__0.mp3", "t": "帝曰："}, {"f": "audio/18/school-sch-nj-22__1.mp3", "t": "藏象何如？"}, {"f": "audio/18/school-sch-nj-22__2.mp3", "t": "岐伯曰："}, {"f": "audio/18/school-sch-nj-22__3.mp3", "t": "心者，"}, {"f": "audio/18/school-sch-nj-22__4.mp3", "t": "生之本，"}, {"f": "audio/18/school-sch-nj-22__5.mp3", "t": "神之变也；"}, {"f": "audio/18/school-sch-nj-22__6.mp3", "t": "其华在面，"}, {"f": "audio/18/school-sch-nj-22__7.mp3", "t": "其充在血脉，"}, {"f": "audio/18/school-sch-nj-22__8.mp3", "t": "为阳中之太阳，"}, {"f": "audio/18/school-sch-nj-22__9.mp3", "t": "通于夏气。"}, {"f": "audio/18/school-sch-nj-22__10.mp3", "t": "肺者，"}, {"f": "audio/18/school-sch-nj-22__11.mp3", "t": "气之本，"}, {"f": "audio/18/school-sch-nj-22__12.mp3", "t": "魄之处也；"}, {"f": "audio/18/school-sch-nj-22__13.mp3", "t": "其华在毛，"}, {"f": "audio/18/school-sch-nj-22__14.mp3", "t": "其充在皮，"}, {"f": "audio/18/school-sch-nj-22__15.mp3", "t": "为阳中之太阴，"}, {"f": "audio/18/school-sch-nj-22__16.mp3", "t": "通于秋气。"}, {"f": "audio/18/school-sch-nj-22__17.mp3", "t": "肾者，"}, {"f": "audio/18/school-sch-nj-22__18.mp3", "t": "主蛰，"}, {"f": "audio/18/school-sch-nj-22__19.mp3", "t": "封藏之本，"}, {"f": "audio/18/school-sch-nj-22__20.mp3", "t": "精之处也；"}, {"f": "audio/18/school-sch-nj-22__21.mp3", "t": "其华在发，"}, {"f": "audio/18/school-sch-nj-22__22.mp3", "t": "其充在骨，"}, {"f": "audio/18/school-sch-nj-22__23.mp3", "t": "为阴中之少阴，"}, {"f": "audio/18/school-sch-nj-22__24.mp3", "t": "通于冬气。"}, {"f": "audio/18/school-sch-nj-22__25.mp3", "t": "肝者，"}, {"f": "audio/18/school-sch-nj-22__26.mp3", "t": "罢极之本，"}, {"f": "audio/18/school-sch-nj-22__27.mp3", "t": "魂之居也；"}, {"f": "audio/18/school-sch-nj-22__28.mp3", "t": "其华在爪，"}, {"f": "audio/18/school-sch-nj-22__29.mp3", "t": "其充在筋，"}, {"f": "audio/18/school-sch-nj-22__30.mp3", "t": "以生血气，"}, {"f": "audio/18/school-sch-nj-22__31.mp3", "t": "其味酸，"}, {"f": "audio/18/school-sch-nj-22__32.mp3", "t": "其色苍，"}, {"f": "audio/18/school-sch-nj-22__33.mp3", "t": "此为阳中之少阳，"}, {"f": "audio/18/school-sch-nj-22__34.mp3", "t": "通于春气。"}, {"f": "audio/18/school-sch-nj-22__35.mp3", "t": "脾、"}, {"f": "audio/18/school-sch-nj-22__36.mp3", "t": "胃、"}, {"f": "audio/18/school-sch-nj-22__37.mp3", "t": "大肠、"}, {"f": "audio/18/school-sch-nj-22__38.mp3", "t": "小肠、"}, {"f": "audio/18/school-sch-nj-22__39.mp3", "t": "三焦、"}, {"f": "audio/18/school-sch-nj-22__40.mp3", "t": "膀胱者，"}, {"f": "audio/18/school-sch-nj-22__41.mp3", "t": "仓廪之本，"}, {"f": "audio/18/school-sch-nj-22__42.mp3", "t": "营之居也。"}, {"f": "audio/18/school-sch-nj-22__43.mp3", "t": "名曰器，"}, {"f": "audio/18/school-sch-nj-22__44.mp3", "t": "能化糟粕，"}, {"f": "audio/18/school-sch-nj-22__45.mp3", "t": "转味而入出者也，"}, {"f": "audio/18/school-sch-nj-22__46.mp3", "t": "其华在唇四白，"}, {"f": "audio/18/school-sch-nj-22__47.mp3", "t": "其充在肌，"}, {"f": "audio/18/school-sch-nj-22__48.mp3", "t": "其味甘，"}, {"f": "audio/18/school-sch-nj-22__49.mp3", "t": "其色黄，"}, {"f": "audio/18/school-sch-nj-22__50.mp3", "t": "此至阴之类，"}, {"f": "audio/18/school-sch-nj-22__51.mp3", "t": "通于土气。"}, {"f": "audio/18/school-sch-nj-22__52.mp3", "t": "凡十一藏，"}, {"f": "audio/18/school-sch-nj-22__53.mp3", "t": "取决于胆也。"}], "school-sch-nj-23": [{"f": "audio/53/school-sch-nj-23__0.mp3", "t": "黄帝问曰："}, {"f": "audio/53/school-sch-nj-23__1.mp3", "t": "余闻方士，"}, {"f": "audio/53/school-sch-nj-23__2.mp3", "t": "或以脑髓为藏，"}, {"f": "audio/53/school-sch-nj-23__3.mp3", "t": "或以肠胃为藏，"}, {"f": "audio/53/school-sch-nj-23__4.mp3", "t": "或以为府，"}, {"f": "audio/53/school-sch-nj-23__5.mp3", "t": "敢问更相反，"}, {"f": "audio/53/school-sch-nj-23__6.mp3", "t": "皆自谓是，"}, {"f": "audio/53/school-sch-nj-23__7.mp3", "t": "不知其道，"}, {"f": "audio/53/school-sch-nj-23__8.mp3", "t": "愿闻其说。"}, {"f": "audio/53/school-sch-nj-23__9.mp3", "t": "岐伯对曰："}, {"f": "audio/53/school-sch-nj-23__10.mp3", "t": "脑、"}, {"f": "audio/53/school-sch-nj-23__11.mp3", "t": "髓、"}, {"f": "audio/53/school-sch-nj-23__12.mp3", "t": "骨、"}, {"f": "audio/53/school-sch-nj-23__13.mp3", "t": "脉、"}, {"f": "audio/53/school-sch-nj-23__14.mp3", "t": "胆、"}, {"f": "audio/53/school-sch-nj-23__15.mp3", "t": "女子胞，"}, {"f": "audio/53/school-sch-nj-23__16.mp3", "t": "此六者，"}, {"f": "audio/53/school-sch-nj-23__17.mp3", "t": "地气之所生也，"}, {"f": "audio/53/school-sch-nj-23__18.mp3", "t": "皆藏于阴而象于地，"}, {"f": "audio/53/school-sch-nj-23__19.mp3", "t": "故藏而不写，"}, {"f": "audio/53/school-sch-nj-23__20.mp3", "t": "名曰奇恒之府。"}, {"f": "audio/53/school-sch-nj-23__21.mp3", "t": "夫胃、"}, {"f": "audio/53/school-sch-nj-23__22.mp3", "t": "大肠、"}, {"f": "audio/53/school-sch-nj-23__23.mp3", "t": "小肠、"}, {"f": "audio/53/school-sch-nj-23__24.mp3", "t": "三焦、"}, {"f": "audio/53/school-sch-nj-23__25.mp3", "t": "膀胱，"}, {"f": "audio/53/school-sch-nj-23__26.mp3", "t": "此五者，"}, {"f": "audio/53/school-sch-nj-23__27.mp3", "t": "天气之所生也，"}, {"f": "audio/53/school-sch-nj-23__28.mp3", "t": "其气象天，"}, {"f": "audio/53/school-sch-nj-23__29.mp3", "t": "故写而不藏，"}, {"f": "audio/53/school-sch-nj-23__30.mp3", "t": "此受五藏浊气，"}, {"f": "audio/53/school-sch-nj-23__31.mp3", "t": "名曰传化之府，"}, {"f": "audio/53/school-sch-nj-23__32.mp3", "t": "此不能久留，"}, {"f": "audio/53/school-sch-nj-23__33.mp3", "t": "输写者也。"}, {"f": "audio/53/school-sch-nj-23__34.mp3", "t": "魄门亦为五藏使，"}, {"f": "audio/53/school-sch-nj-23__35.mp3", "t": "水谷不得久藏。"}], "school-sch-nj-24": [{"f": "audio/31/school-sch-nj-24__0.mp3", "t": "所谓五藏者，"}, {"f": "audio/31/school-sch-nj-24__1.mp3", "t": "藏精气而不写也，"}, {"f": "audio/31/school-sch-nj-24__2.mp3", "t": "故满而不能实；"}, {"f": "audio/31/school-sch-nj-24__3.mp3", "t": "六府者，"}, {"f": "audio/31/school-sch-nj-24__4.mp3", "t": "传化物而不藏，"}, {"f": "audio/31/school-sch-nj-24__5.mp3", "t": "故实而不能满也。"}, {"f": "audio/31/school-sch-nj-24__6.mp3", "t": "所以然者，"}, {"f": "audio/31/school-sch-nj-24__7.mp3", "t": "水谷入口，"}, {"f": "audio/31/school-sch-nj-24__8.mp3", "t": "则胃实而肠虚；"}, {"f": "audio/31/school-sch-nj-24__9.mp3", "t": "食下则肠实而胃虚。"}, {"f": "audio/31/school-sch-nj-24__10.mp3", "t": "故曰："}, {"f": "audio/31/school-sch-nj-24__11.mp3", "t": "实而不满，"}, {"f": "audio/31/school-sch-nj-24__12.mp3", "t": "满而不实也。"}], "school-sch-nj-25": [{"f": "audio/33/school-sch-nj-25__0.mp3", "t": "帝曰："}, {"f": "audio/33/school-sch-nj-25__1.mp3", "t": "气口何以独为五藏主？"}, {"f": "audio/33/school-sch-nj-25__2.mp3", "t": "岐伯曰："}, {"f": "audio/33/school-sch-nj-25__3.mp3", "t": "胃者，"}, {"f": "audio/33/school-sch-nj-25__4.mp3", "t": "水谷之海，"}, {"f": "audio/33/school-sch-nj-25__5.mp3", "t": "六府之大源也。"}, {"f": "audio/33/school-sch-nj-25__6.mp3", "t": "五味入口，"}, {"f": "audio/33/school-sch-nj-25__7.mp3", "t": "藏于胃，"}, {"f": "audio/33/school-sch-nj-25__8.mp3", "t": "以养五藏气。"}, {"f": "audio/33/school-sch-nj-25__9.mp3", "t": "气口亦太阴也。"}, {"f": "audio/33/school-sch-nj-25__10.mp3", "t": "是以五藏六府之气味，"}, {"f": "audio/33/school-sch-nj-25__11.mp3", "t": "皆出于胃，"}, {"f": "audio/33/school-sch-nj-25__12.mp3", "t": "变见于气口。"}, {"f": "audio/33/school-sch-nj-25__13.mp3", "t": "故五气入鼻，"}, {"f": "audio/33/school-sch-nj-25__14.mp3", "t": "藏于心肺，"}, {"f": "audio/33/school-sch-nj-25__15.mp3", "t": "心肺有病，"}, {"f": "audio/33/school-sch-nj-25__16.mp3", "t": "而鼻为之不利也。"}], "school-sch-nj-26": [{"f": "audio/e1/school-sch-nj-26__0.mp3", "t": "凡治病，"}, {"f": "audio/e1/school-sch-nj-26__1.mp3", "t": "必察其下，"}, {"f": "audio/e1/school-sch-nj-26__2.mp3", "t": "适其脉，"}, {"f": "audio/e1/school-sch-nj-26__3.mp3", "t": "观其志意，"}, {"f": "audio/e1/school-sch-nj-26__4.mp3", "t": "与其病也。"}, {"f": "audio/e1/school-sch-nj-26__5.mp3", "t": "拘于鬼神者，"}, {"f": "audio/e1/school-sch-nj-26__6.mp3", "t": "不可与言至德；"}, {"f": "audio/e1/school-sch-nj-26__7.mp3", "t": "恶于针石者，"}, {"f": "audio/e1/school-sch-nj-26__8.mp3", "t": "不可与言至巧；"}, {"f": "audio/e1/school-sch-nj-26__9.mp3", "t": "病不许治者，"}, {"f": "audio/e1/school-sch-nj-26__10.mp3", "t": "病必不治，"}, {"f": "audio/e1/school-sch-nj-26__11.mp3", "t": "治之无功矣。"}], "school-sch-nj-27": [{"f": "audio/ed/school-sch-nj-27__0.mp3", "t": "黄帝问曰："}, {"f": "audio/ed/school-sch-nj-27__1.mp3", "t": "人之居处动静勇怯，"}, {"f": "audio/ed/school-sch-nj-27__2.mp3", "t": "脉亦为之变乎？"}, {"f": "audio/ed/school-sch-nj-27__3.mp3", "t": "岐伯对曰："}, {"f": "audio/ed/school-sch-nj-27__4.mp3", "t": "凡人之惊恐恚劳动静，"}, {"f": "audio/ed/school-sch-nj-27__5.mp3", "t": "皆为变也。"}, {"f": "audio/ed/school-sch-nj-27__6.mp3", "t": "是以夜行则喘出于肾，"}, {"f": "audio/ed/school-sch-nj-27__7.mp3", "t": "淫气病肺。"}, {"f": "audio/ed/school-sch-nj-27__8.mp3", "t": "有所堕恐，"}, {"f": "audio/ed/school-sch-nj-27__9.mp3", "t": "喘出于肝，"}, {"f": "audio/ed/school-sch-nj-27__10.mp3", "t": "淫气害脾。"}, {"f": "audio/ed/school-sch-nj-27__11.mp3", "t": "有所惊恐，"}, {"f": "audio/ed/school-sch-nj-27__12.mp3", "t": "喘出于肺，"}, {"f": "audio/ed/school-sch-nj-27__13.mp3", "t": "淫气伤心。"}, {"f": "audio/ed/school-sch-nj-27__14.mp3", "t": "度水跌仆，"}, {"f": "audio/ed/school-sch-nj-27__15.mp3", "t": "喘出于肾与骨，"}, {"f": "audio/ed/school-sch-nj-27__16.mp3", "t": "当是之时，"}, {"f": "audio/ed/school-sch-nj-27__17.mp3", "t": "勇者气行则已；"}, {"f": "audio/ed/school-sch-nj-27__18.mp3", "t": "怯者则著而为病也。"}, {"f": "audio/ed/school-sch-nj-27__19.mp3", "t": "故曰："}, {"f": "audio/ed/school-sch-nj-27__20.mp3", "t": "诊病之道，"}, {"f": "audio/ed/school-sch-nj-27__21.mp3", "t": "观人勇怯，"}, {"f": "audio/ed/school-sch-nj-27__22.mp3", "t": "骨肉皮肤，"}, {"f": "audio/ed/school-sch-nj-27__23.mp3", "t": "能知其情，"}, {"f": "audio/ed/school-sch-nj-27__24.mp3", "t": "以为诊法也。"}], "school-sch-nj-28": [{"f": "audio/26/school-sch-nj-28__0.mp3", "t": "故饮食饱甚，"}, {"f": "audio/26/school-sch-nj-28__1.mp3", "t": "汗出于胃；"}, {"f": "audio/26/school-sch-nj-28__2.mp3", "t": "惊而夺精，"}, {"f": "audio/26/school-sch-nj-28__3.mp3", "t": "汗出于心；"}, {"f": "audio/26/school-sch-nj-28__4.mp3", "t": "持重远行，"}, {"f": "audio/26/school-sch-nj-28__5.mp3", "t": "汗出于肾；"}, {"f": "audio/26/school-sch-nj-28__6.mp3", "t": "疾走恐惧，"}, {"f": "audio/26/school-sch-nj-28__7.mp3", "t": "汗出于肝；"}, {"f": "audio/26/school-sch-nj-28__8.mp3", "t": "摇体劳苦，"}, {"f": "audio/26/school-sch-nj-28__9.mp3", "t": "汗出于脾。"}, {"f": "audio/26/school-sch-nj-28__10.mp3", "t": "故春秋冬夏，"}, {"f": "audio/26/school-sch-nj-28__11.mp3", "t": "四时阴阳，"}, {"f": "audio/26/school-sch-nj-28__12.mp3", "t": "生病起于过用，"}, {"f": "audio/26/school-sch-nj-28__13.mp3", "t": "此为常也。"}], "school-sch-nj-29": [{"f": "audio/72/school-sch-nj-29__0.mp3", "t": "食气入胃，"}, {"f": "audio/72/school-sch-nj-29__1.mp3", "t": "散精于肝，"}, {"f": "audio/72/school-sch-nj-29__2.mp3", "t": "淫气于筋。"}, {"f": "audio/72/school-sch-nj-29__3.mp3", "t": "食气入胃，"}, {"f": "audio/72/school-sch-nj-29__4.mp3", "t": "浊气归心，"}, {"f": "audio/72/school-sch-nj-29__5.mp3", "t": "淫精于脉。"}, {"f": "audio/72/school-sch-nj-29__6.mp3", "t": "脉气流经，"}, {"f": "audio/72/school-sch-nj-29__7.mp3", "t": "经气归于肺，"}, {"f": "audio/72/school-sch-nj-29__8.mp3", "t": "肺朝百脉，"}, {"f": "audio/72/school-sch-nj-29__9.mp3", "t": "输精于皮毛。"}, {"f": "audio/72/school-sch-nj-29__10.mp3", "t": "毛脉合精，"}, {"f": "audio/72/school-sch-nj-29__11.mp3", "t": "行气于府，"}, {"f": "audio/72/school-sch-nj-29__12.mp3", "t": "府精神明，"}, {"f": "audio/72/school-sch-nj-29__13.mp3", "t": "留于四藏，"}, {"f": "audio/72/school-sch-nj-29__14.mp3", "t": "气归于权衡。"}, {"f": "audio/72/school-sch-nj-29__15.mp3", "t": "权衡以平，"}, {"f": "audio/72/school-sch-nj-29__16.mp3", "t": "气口成寸，"}, {"f": "audio/72/school-sch-nj-29__17.mp3", "t": "以决死生。"}], "school-sch-nj-30": [{"f": "audio/0f/school-sch-nj-30__0.mp3", "t": "饮入于胃，"}, {"f": "audio/0f/school-sch-nj-30__1.mp3", "t": "游溢精气，"}, {"f": "audio/0f/school-sch-nj-30__2.mp3", "t": "上输于脾，"}, {"f": "audio/0f/school-sch-nj-30__3.mp3", "t": "脾气散精，"}, {"f": "audio/0f/school-sch-nj-30__4.mp3", "t": "上归于肺，"}, {"f": "audio/0f/school-sch-nj-30__5.mp3", "t": "通调水道，"}, {"f": "audio/0f/school-sch-nj-30__6.mp3", "t": "下输膀胱，"}, {"f": "audio/0f/school-sch-nj-30__7.mp3", "t": "水精四布，"}, {"f": "audio/0f/school-sch-nj-30__8.mp3", "t": "五经并行，"}, {"f": "audio/0f/school-sch-nj-30__9.mp3", "t": "合于四时五藏阴阳，"}, {"f": "audio/0f/school-sch-nj-30__10.mp3", "t": "揆度以为常也。"}], "school-sch-nj-31": [{"f": "audio/b5/school-sch-nj-31__0.mp3", "t": "黄帝问曰："}, {"f": "audio/b5/school-sch-nj-31__1.mp3", "t": "太阴阳明为表里，"}, {"f": "audio/b5/school-sch-nj-31__2.mp3", "t": "脾胃脉也，"}, {"f": "audio/b5/school-sch-nj-31__3.mp3", "t": "生病而异者，"}, {"f": "audio/b5/school-sch-nj-31__4.mp3", "t": "何也？"}, {"f": "audio/b5/school-sch-nj-31__5.mp3", "t": "岐伯对曰："}, {"f": "audio/b5/school-sch-nj-31__6.mp3", "t": "阴阳异位，"}, {"f": "audio/b5/school-sch-nj-31__7.mp3", "t": "更虚更实，"}, {"f": "audio/b5/school-sch-nj-31__8.mp3", "t": "更逆更从，"}, {"f": "audio/b5/school-sch-nj-31__9.mp3", "t": "或从内，"}, {"f": "audio/b5/school-sch-nj-31__10.mp3", "t": "或从外，"}, {"f": "audio/b5/school-sch-nj-31__11.mp3", "t": "所从不同，"}, {"f": "audio/b5/school-sch-nj-31__12.mp3", "t": "故病异名也。"}], "school-sch-nj-32": [{"f": "audio/f0/school-sch-nj-32__0.mp3", "t": "帝曰："}, {"f": "audio/f0/school-sch-nj-32__1.mp3", "t": "愿闻其异状也？"}, {"f": "audio/f0/school-sch-nj-32__2.mp3", "t": "岐伯曰："}, {"f": "audio/f0/school-sch-nj-32__3.mp3", "t": "阳者，"}, {"f": "audio/f0/school-sch-nj-32__4.mp3", "t": "天气也，"}, {"f": "audio/f0/school-sch-nj-32__5.mp3", "t": "主外；"}, {"f": "audio/f0/school-sch-nj-32__6.mp3", "t": "阴者，"}, {"f": "audio/f0/school-sch-nj-32__7.mp3", "t": "地气也，"}, {"f": "audio/f0/school-sch-nj-32__8.mp3", "t": "主内。"}, {"f": "audio/f0/school-sch-nj-32__9.mp3", "t": "故阳道实，"}, {"f": "audio/f0/school-sch-nj-32__10.mp3", "t": "阴道虚。"}, {"f": "audio/f0/school-sch-nj-32__11.mp3", "t": "故犯贼风虚邪者，"}, {"f": "audio/f0/school-sch-nj-32__12.mp3", "t": "阳受之；"}, {"f": "audio/f0/school-sch-nj-32__13.mp3", "t": "食饮不节，"}, {"f": "audio/f0/school-sch-nj-32__14.mp3", "t": "起居不时者，"}, {"f": "audio/f0/school-sch-nj-32__15.mp3", "t": "阴受之。"}, {"f": "audio/f0/school-sch-nj-32__16.mp3", "t": "阳受之则入六府，"}, {"f": "audio/f0/school-sch-nj-32__17.mp3", "t": "阴受之则入五藏。"}, {"f": "audio/f0/school-sch-nj-32__18.mp3", "t": "入六府则身热，"}, {"f": "audio/f0/school-sch-nj-32__19.mp3", "t": "不时卧，"}, {"f": "audio/f0/school-sch-nj-32__20.mp3", "t": "上为喘呼。"}, {"f": "audio/f0/school-sch-nj-32__21.mp3", "t": "入五藏则䐜满闭塞，"}, {"f": "audio/f0/school-sch-nj-32__22.mp3", "t": "下为飧泄，"}, {"f": "audio/f0/school-sch-nj-32__23.mp3", "t": "久为肠澼。"}, {"f": "audio/f0/school-sch-nj-32__24.mp3", "t": "故喉主天气，"}, {"f": "audio/f0/school-sch-nj-32__25.mp3", "t": "咽主地气。"}, {"f": "audio/f0/school-sch-nj-32__26.mp3", "t": "故阳受风气，"}, {"f": "audio/f0/school-sch-nj-32__27.mp3", "t": "阴受湿气。"}, {"f": "audio/f0/school-sch-nj-32__28.mp3", "t": "故阴气从足上行至头，"}, {"f": "audio/f0/school-sch-nj-32__29.mp3", "t": "而下行循臂至指端。"}, {"f": "audio/f0/school-sch-nj-32__30.mp3", "t": "阳气从手上行至头，"}, {"f": "audio/f0/school-sch-nj-32__31.mp3", "t": "而下行至足。"}, {"f": "audio/f0/school-sch-nj-32__32.mp3", "t": "故曰："}, {"f": "audio/f0/school-sch-nj-32__33.mp3", "t": "\"阳病者，"}, {"f": "audio/f0/school-sch-nj-32__34.mp3", "t": "上行极而下；"}, {"f": "audio/f0/school-sch-nj-32__35.mp3", "t": "阴病者，"}, {"f": "audio/f0/school-sch-nj-32__36.mp3", "t": "下行极而上。"}, {"f": "audio/f0/school-sch-nj-32__37.mp3", "t": "\"故伤于风者，"}, {"f": "audio/f0/school-sch-nj-32__38.mp3", "t": "上先受之；"}, {"f": "audio/f0/school-sch-nj-32__39.mp3", "t": "伤于湿者，"}, {"f": "audio/f0/school-sch-nj-32__40.mp3", "t": "下先受之。"}], "school-sch-nj-33": [{"f": "audio/08/school-sch-nj-33__0.mp3", "t": "帝曰："}, {"f": "audio/08/school-sch-nj-33__1.mp3", "t": "脾病而四支不用，"}, {"f": "audio/08/school-sch-nj-33__2.mp3", "t": "何也？"}, {"f": "audio/08/school-sch-nj-33__3.mp3", "t": "岐伯曰："}, {"f": "audio/08/school-sch-nj-33__4.mp3", "t": "四支皆禀气于胃，"}, {"f": "audio/08/school-sch-nj-33__5.mp3", "t": "而不得至经，"}, {"f": "audio/08/school-sch-nj-33__6.mp3", "t": "必因于脾，"}, {"f": "audio/08/school-sch-nj-33__7.mp3", "t": "乃得禀也。"}, {"f": "audio/08/school-sch-nj-33__8.mp3", "t": "今脾病不能为胃行其津液，"}, {"f": "audio/08/school-sch-nj-33__9.mp3", "t": "四支不得禀水谷气，"}, {"f": "audio/08/school-sch-nj-33__10.mp3", "t": "气日以衰，"}, {"f": "audio/08/school-sch-nj-33__11.mp3", "t": "脉道不利，"}, {"f": "audio/08/school-sch-nj-33__12.mp3", "t": "筋骨肌肉，"}, {"f": "audio/08/school-sch-nj-33__13.mp3", "t": "皆无气以生，"}, {"f": "audio/08/school-sch-nj-33__14.mp3", "t": "故不用焉。"}], "school-sch-nj-34": [{"f": "audio/ae/school-sch-nj-34__0.mp3", "t": "帝曰："}, {"f": "audio/ae/school-sch-nj-34__1.mp3", "t": "脾不主时，"}, {"f": "audio/ae/school-sch-nj-34__2.mp3", "t": "何也？"}, {"f": "audio/ae/school-sch-nj-34__3.mp3", "t": "岐伯曰："}, {"f": "audio/ae/school-sch-nj-34__4.mp3", "t": "脾者土也，"}, {"f": "audio/ae/school-sch-nj-34__5.mp3", "t": "治中央，"}, {"f": "audio/ae/school-sch-nj-34__6.mp3", "t": "常以四时长四藏，"}, {"f": "audio/ae/school-sch-nj-34__7.mp3", "t": "各十八日寄治，"}, {"f": "audio/ae/school-sch-nj-34__8.mp3", "t": "不得独主于时也。"}, {"f": "audio/ae/school-sch-nj-34__9.mp3", "t": "脾藏者，"}, {"f": "audio/ae/school-sch-nj-34__10.mp3", "t": "常著胃土之精也。"}, {"f": "audio/ae/school-sch-nj-34__11.mp3", "t": "土者生万物而法天地，"}, {"f": "audio/ae/school-sch-nj-34__12.mp3", "t": "故上下至头足，"}, {"f": "audio/ae/school-sch-nj-34__13.mp3", "t": "不得主时也。"}], "school-sch-nj-35": [{"f": "audio/27/school-sch-nj-35__0.mp3", "t": "帝曰："}, {"f": "audio/27/school-sch-nj-35__1.mp3", "t": "脾与胃以膜相连耳，"}, {"f": "audio/27/school-sch-nj-35__2.mp3", "t": "而能为之行其津液，"}, {"f": "audio/27/school-sch-nj-35__3.mp3", "t": "何也？"}, {"f": "audio/27/school-sch-nj-35__4.mp3", "t": "岐伯曰："}, {"f": "audio/27/school-sch-nj-35__5.mp3", "t": "足太阴者，"}, {"f": "audio/27/school-sch-nj-35__6.mp3", "t": "三阴也，"}, {"f": "audio/27/school-sch-nj-35__7.mp3", "t": "其脉贯胃属脾络嗌，"}, {"f": "audio/27/school-sch-nj-35__8.mp3", "t": "故太阴为之行气于三阴。"}, {"f": "audio/27/school-sch-nj-35__9.mp3", "t": "阳明者，"}, {"f": "audio/27/school-sch-nj-35__10.mp3", "t": "表也，"}, {"f": "audio/27/school-sch-nj-35__11.mp3", "t": "五藏六府之海也，"}, {"f": "audio/27/school-sch-nj-35__12.mp3", "t": "亦为之行气于三阳。"}, {"f": "audio/27/school-sch-nj-35__13.mp3", "t": "藏府各因其经而受气于阳明，"}, {"f": "audio/27/school-sch-nj-35__14.mp3", "t": "故为胃行其津液。"}, {"f": "audio/27/school-sch-nj-35__15.mp3", "t": "四支不得禀水谷气，"}, {"f": "audio/27/school-sch-nj-35__16.mp3", "t": "日以益衰，"}, {"f": "audio/27/school-sch-nj-35__17.mp3", "t": "阴道不利，"}, {"f": "audio/27/school-sch-nj-35__18.mp3", "t": "筋骨肌肉，"}, {"f": "audio/27/school-sch-nj-35__19.mp3", "t": "无气以生，"}, {"f": "audio/27/school-sch-nj-35__20.mp3", "t": "故不用焉。"}], "school-sch-nj-36": [{"f": "audio/34/school-sch-nj-36__0.mp3", "t": "黄帝问于岐伯曰："}, {"f": "audio/34/school-sch-nj-36__1.mp3", "t": "凡刺之法，"}, {"f": "audio/34/school-sch-nj-36__2.mp3", "t": "先必本于神。"}, {"f": "audio/34/school-sch-nj-36__3.mp3", "t": "血脉营气精神，"}, {"f": "audio/34/school-sch-nj-36__4.mp3", "t": "此五藏之所藏也。"}, {"f": "audio/34/school-sch-nj-36__5.mp3", "t": "至其淫泆离藏则精失，"}, {"f": "audio/34/school-sch-nj-36__6.mp3", "t": "魂魄飞扬，"}, {"f": "audio/34/school-sch-nj-36__7.mp3", "t": "志意恍乱，"}, {"f": "audio/34/school-sch-nj-36__8.mp3", "t": "智虑去身者，"}, {"f": "audio/34/school-sch-nj-36__9.mp3", "t": "何因而然乎？"}, {"f": "audio/34/school-sch-nj-36__10.mp3", "t": "天之罪与？"}, {"f": "audio/34/school-sch-nj-36__11.mp3", "t": "人之过乎？"}, {"f": "audio/34/school-sch-nj-36__12.mp3", "t": "何谓德、"}, {"f": "audio/34/school-sch-nj-36__13.mp3", "t": "气、"}, {"f": "audio/34/school-sch-nj-36__14.mp3", "t": "生、"}, {"f": "audio/34/school-sch-nj-36__15.mp3", "t": "精、"}, {"f": "audio/34/school-sch-nj-36__16.mp3", "t": "神、"}, {"f": "audio/34/school-sch-nj-36__17.mp3", "t": "魂、"}, {"f": "audio/34/school-sch-nj-36__18.mp3", "t": "魄、"}, {"f": "audio/34/school-sch-nj-36__19.mp3", "t": "心、"}, {"f": "audio/34/school-sch-nj-36__20.mp3", "t": "意、"}, {"f": "audio/34/school-sch-nj-36__21.mp3", "t": "志、"}, {"f": "audio/34/school-sch-nj-36__22.mp3", "t": "思、"}, {"f": "audio/34/school-sch-nj-36__23.mp3", "t": "智、"}, {"f": "audio/34/school-sch-nj-36__24.mp3", "t": "虑？"}, {"f": "audio/34/school-sch-nj-36__25.mp3", "t": "请问其故。"}], "school-sch-nj-37": [{"f": "audio/f1/school-sch-nj-37__0.mp3", "t": "岐伯答曰："}, {"f": "audio/f1/school-sch-nj-37__1.mp3", "t": "天之在我者德也，"}, {"f": "audio/f1/school-sch-nj-37__2.mp3", "t": "地之在我者气也。"}, {"f": "audio/f1/school-sch-nj-37__3.mp3", "t": "德流气薄而生者也。"}, {"f": "audio/f1/school-sch-nj-37__4.mp3", "t": "故生之来谓之精，"}, {"f": "audio/f1/school-sch-nj-37__5.mp3", "t": "两精相搏谓之神，"}, {"f": "audio/f1/school-sch-nj-37__6.mp3", "t": "随神往来者谓之魂，"}, {"f": "audio/f1/school-sch-nj-37__7.mp3", "t": "并精而出入者谓之魄。"}, {"f": "audio/f1/school-sch-nj-37__8.mp3", "t": "所以任物者谓之心，"}, {"f": "audio/f1/school-sch-nj-37__9.mp3", "t": "心有所忆谓之意，"}, {"f": "audio/f1/school-sch-nj-37__10.mp3", "t": "意之所存谓之志，"}, {"f": "audio/f1/school-sch-nj-37__11.mp3", "t": "因志而存变谓之思，"}, {"f": "audio/f1/school-sch-nj-37__12.mp3", "t": "因思而远慕谓之虑，"}, {"f": "audio/f1/school-sch-nj-37__13.mp3", "t": "因虑而处物谓之智。"}, {"f": "audio/f1/school-sch-nj-37__14.mp3", "t": "故智者之养生也，"}, {"f": "audio/f1/school-sch-nj-37__15.mp3", "t": "必顺四时而适寒暑，"}, {"f": "audio/f1/school-sch-nj-37__16.mp3", "t": "和喜怒而安居处，"}, {"f": "audio/f1/school-sch-nj-37__17.mp3", "t": "节阴阳而调刚柔。"}, {"f": "audio/f1/school-sch-nj-37__18.mp3", "t": "如是，"}, {"f": "audio/f1/school-sch-nj-37__19.mp3", "t": "则僻邪不至，"}, {"f": "audio/f1/school-sch-nj-37__20.mp3", "t": "长生久视。"}], "school-sch-nj-38": [{"f": "audio/53/school-sch-nj-38__0.mp3", "t": "是故怵惕思虑者则伤神，"}, {"f": "audio/53/school-sch-nj-38__1.mp3", "t": "神伤则恐惧，"}, {"f": "audio/53/school-sch-nj-38__2.mp3", "t": "流淫而不止。"}, {"f": "audio/53/school-sch-nj-38__3.mp3", "t": "因悲哀动中者，"}, {"f": "audio/53/school-sch-nj-38__4.mp3", "t": "竭绝而失生。"}, {"f": "audio/53/school-sch-nj-38__5.mp3", "t": "喜乐者，"}, {"f": "audio/53/school-sch-nj-38__6.mp3", "t": "神惮散而不藏。"}, {"f": "audio/53/school-sch-nj-38__7.mp3", "t": "愁忧者，"}, {"f": "audio/53/school-sch-nj-38__8.mp3", "t": "气闭塞而不行。"}, {"f": "audio/53/school-sch-nj-38__9.mp3", "t": "盛怒者，"}, {"f": "audio/53/school-sch-nj-38__10.mp3", "t": "迷惑而不治。"}, {"f": "audio/53/school-sch-nj-38__11.mp3", "t": "恐惧者，"}, {"f": "audio/53/school-sch-nj-38__12.mp3", "t": "神荡惮而不收。"}], "school-sch-nj-39": [{"f": "audio/c4/school-sch-nj-39__0.mp3", "t": "心，"}, {"f": "audio/c4/school-sch-nj-39__1.mp3", "t": "怵惕思虑则伤神，"}, {"f": "audio/c4/school-sch-nj-39__2.mp3", "t": "神伤则恐惧自失，"}, {"f": "audio/c4/school-sch-nj-39__3.mp3", "t": "破䐃脱肉；"}, {"f": "audio/c4/school-sch-nj-39__4.mp3", "t": "毛悴色夭，"}, {"f": "audio/c4/school-sch-nj-39__5.mp3", "t": "死于冬。"}, {"f": "audio/c4/school-sch-nj-39__6.mp3", "t": "脾愁忧而不解则伤意，"}, {"f": "audio/c4/school-sch-nj-39__7.mp3", "t": "意伤则悗乱，"}, {"f": "audio/c4/school-sch-nj-39__8.mp3", "t": "四肢不举，"}, {"f": "audio/c4/school-sch-nj-39__9.mp3", "t": "毛悴色夭，"}, {"f": "audio/c4/school-sch-nj-39__10.mp3", "t": "死于春。"}, {"f": "audio/c4/school-sch-nj-39__11.mp3", "t": "肝悲哀动中则伤魂，"}, {"f": "audio/c4/school-sch-nj-39__12.mp3", "t": "魂伤则狂忘不精，"}, {"f": "audio/c4/school-sch-nj-39__13.mp3", "t": "不精则不正，"}, {"f": "audio/c4/school-sch-nj-39__14.mp3", "t": "当人阴缩而挛筋，"}, {"f": "audio/c4/school-sch-nj-39__15.mp3", "t": "两胁骨不举；"}, {"f": "audio/c4/school-sch-nj-39__16.mp3", "t": "毛悴色夭，"}, {"f": "audio/c4/school-sch-nj-39__17.mp3", "t": "死于秋。"}, {"f": "audio/c4/school-sch-nj-39__18.mp3", "t": "肺喜乐无极则伤魄，"}, {"f": "audio/c4/school-sch-nj-39__19.mp3", "t": "魄伤则狂，"}, {"f": "audio/c4/school-sch-nj-39__20.mp3", "t": "狂者意不存人，"}, {"f": "audio/c4/school-sch-nj-39__21.mp3", "t": "皮革焦，"}, {"f": "audio/c4/school-sch-nj-39__22.mp3", "t": "毛悴色夭，"}, {"f": "audio/c4/school-sch-nj-39__23.mp3", "t": "死于夏。"}, {"f": "audio/c4/school-sch-nj-39__24.mp3", "t": "肾盛怒而不止则伤志，"}, {"f": "audio/c4/school-sch-nj-39__25.mp3", "t": "志伤则喜忘其前言，"}, {"f": "audio/c4/school-sch-nj-39__26.mp3", "t": "腰脊不可以俛仰屈伸，"}, {"f": "audio/c4/school-sch-nj-39__27.mp3", "t": "毛悴色夭，"}, {"f": "audio/c4/school-sch-nj-39__28.mp3", "t": "死于季夏。"}, {"f": "audio/c4/school-sch-nj-39__29.mp3", "t": "恐惧而不解则伤精，"}, {"f": "audio/c4/school-sch-nj-39__30.mp3", "t": "精伤则骨酸痿厥，"}, {"f": "audio/c4/school-sch-nj-39__31.mp3", "t": "精时自下。"}, {"f": "audio/c4/school-sch-nj-39__32.mp3", "t": "是故五藏主藏精者也，"}, {"f": "audio/c4/school-sch-nj-39__33.mp3", "t": "不可伤，"}, {"f": "audio/c4/school-sch-nj-39__34.mp3", "t": "伤则失守而阴虚，"}, {"f": "audio/c4/school-sch-nj-39__35.mp3", "t": "阴虚则无气，"}, {"f": "audio/c4/school-sch-nj-39__36.mp3", "t": "无气则死矣。"}, {"f": "audio/c4/school-sch-nj-39__37.mp3", "t": "是故用针者，"}, {"f": "audio/c4/school-sch-nj-39__38.mp3", "t": "察观病人之态，"}, {"f": "audio/c4/school-sch-nj-39__39.mp3", "t": "以知精神魂魄之存亡得失之意，"}, {"f": "audio/c4/school-sch-nj-39__40.mp3", "t": "五者以伤，"}, {"f": "audio/c4/school-sch-nj-39__41.mp3", "t": "针不可以治之也。"}], "school-sch-nj-40": [{"f": "audio/d0/school-sch-nj-40__0.mp3", "t": "肝藏血，"}, {"f": "audio/d0/school-sch-nj-40__1.mp3", "t": "血舍魂，"}, {"f": "audio/d0/school-sch-nj-40__2.mp3", "t": "肝气虚则恐，"}, {"f": "audio/d0/school-sch-nj-40__3.mp3", "t": "实则怒。"}, {"f": "audio/d0/school-sch-nj-40__4.mp3", "t": "脾藏营，"}, {"f": "audio/d0/school-sch-nj-40__5.mp3", "t": "营舍意，"}, {"f": "audio/d0/school-sch-nj-40__6.mp3", "t": "脾气虚则四肢不用，"}, {"f": "audio/d0/school-sch-nj-40__7.mp3", "t": "五藏不安，"}, {"f": "audio/d0/school-sch-nj-40__8.mp3", "t": "实则腹胀经溲不利。"}, {"f": "audio/d0/school-sch-nj-40__9.mp3", "t": "心藏脉，"}, {"f": "audio/d0/school-sch-nj-40__10.mp3", "t": "脉舍神，"}, {"f": "audio/d0/school-sch-nj-40__11.mp3", "t": "心气虚则悲，"}, {"f": "audio/d0/school-sch-nj-40__12.mp3", "t": "实则笑不休。"}, {"f": "audio/d0/school-sch-nj-40__13.mp3", "t": "肺藏气，"}, {"f": "audio/d0/school-sch-nj-40__14.mp3", "t": "气舍魄，"}, {"f": "audio/d0/school-sch-nj-40__15.mp3", "t": "肺气虚则鼻塞不利，"}, {"f": "audio/d0/school-sch-nj-40__16.mp3", "t": "少气，"}, {"f": "audio/d0/school-sch-nj-40__17.mp3", "t": "实则喘喝胸盈仰息。"}, {"f": "audio/d0/school-sch-nj-40__18.mp3", "t": "肾藏精，"}, {"f": "audio/d0/school-sch-nj-40__19.mp3", "t": "精舍志，"}, {"f": "audio/d0/school-sch-nj-40__20.mp3", "t": "肾气虚则厥，"}, {"f": "audio/d0/school-sch-nj-40__21.mp3", "t": "实则胀，"}, {"f": "audio/d0/school-sch-nj-40__22.mp3", "t": "五藏不安。"}, {"f": "audio/d0/school-sch-nj-40__23.mp3", "t": "必审五藏之病形，"}, {"f": "audio/d0/school-sch-nj-40__24.mp3", "t": "以知其气之虚实，"}, {"f": "audio/d0/school-sch-nj-40__25.mp3", "t": "谨而调之也。"}], "school-sch-nj-41": [{"f": "audio/34/school-sch-nj-41__0.mp3", "t": "黄帝问于岐伯曰："}, {"f": "audio/34/school-sch-nj-41__1.mp3", "t": "人焉受气？"}, {"f": "audio/34/school-sch-nj-41__2.mp3", "t": "阴阳焉会？"}, {"f": "audio/34/school-sch-nj-41__3.mp3", "t": "何气为营？"}, {"f": "audio/34/school-sch-nj-41__4.mp3", "t": "何气为卫？"}, {"f": "audio/34/school-sch-nj-41__5.mp3", "t": "营安从生？"}, {"f": "audio/34/school-sch-nj-41__6.mp3", "t": "卫于焉会？"}, {"f": "audio/34/school-sch-nj-41__7.mp3", "t": "老壮不同气，"}, {"f": "audio/34/school-sch-nj-41__8.mp3", "t": "阴阳异位，"}, {"f": "audio/34/school-sch-nj-41__9.mp3", "t": "愿闻其会。"}, {"f": "audio/34/school-sch-nj-41__10.mp3", "t": "岐伯答曰："}, {"f": "audio/34/school-sch-nj-41__11.mp3", "t": "人受气于谷，"}, {"f": "audio/34/school-sch-nj-41__12.mp3", "t": "谷入于胃，"}, {"f": "audio/34/school-sch-nj-41__13.mp3", "t": "以传与肺，"}, {"f": "audio/34/school-sch-nj-41__14.mp3", "t": "五藏六府，"}, {"f": "audio/34/school-sch-nj-41__15.mp3", "t": "皆以受气，"}, {"f": "audio/34/school-sch-nj-41__16.mp3", "t": "其清者为营，"}, {"f": "audio/34/school-sch-nj-41__17.mp3", "t": "浊者为卫，"}, {"f": "audio/34/school-sch-nj-41__18.mp3", "t": "营在脉中，"}, {"f": "audio/34/school-sch-nj-41__19.mp3", "t": "卫在脉外，"}, {"f": "audio/34/school-sch-nj-41__20.mp3", "t": "营周不休，"}, {"f": "audio/34/school-sch-nj-41__21.mp3", "t": "五十度而复大会。"}, {"f": "audio/34/school-sch-nj-41__22.mp3", "t": "阴阳相贯，"}, {"f": "audio/34/school-sch-nj-41__23.mp3", "t": "如环无端。"}, {"f": "audio/34/school-sch-nj-41__24.mp3", "t": "卫气行于阴二十五度，"}, {"f": "audio/34/school-sch-nj-41__25.mp3", "t": "行于阳二十五度，"}, {"f": "audio/34/school-sch-nj-41__26.mp3", "t": "分为昼夜，"}, {"f": "audio/34/school-sch-nj-41__27.mp3", "t": "故气至阳而起，"}, {"f": "audio/34/school-sch-nj-41__28.mp3", "t": "至阴而止。"}, {"f": "audio/34/school-sch-nj-41__29.mp3", "t": "故曰："}, {"f": "audio/34/school-sch-nj-41__30.mp3", "t": "日中而阳陇为重阳，"}, {"f": "audio/34/school-sch-nj-41__31.mp3", "t": "夜半而阴陇为重阴。"}, {"f": "audio/34/school-sch-nj-41__32.mp3", "t": "故太阴主内，"}, {"f": "audio/34/school-sch-nj-41__33.mp3", "t": "太阳主外，"}, {"f": "audio/34/school-sch-nj-41__34.mp3", "t": "各行二十五度，"}, {"f": "audio/34/school-sch-nj-41__35.mp3", "t": "分为昼夜。"}, {"f": "audio/34/school-sch-nj-41__36.mp3", "t": "夜半为阴陇，"}, {"f": "audio/34/school-sch-nj-41__37.mp3", "t": "夜半后而阴衰，"}, {"f": "audio/34/school-sch-nj-41__38.mp3", "t": "平旦阴尽而阳受气矣。"}, {"f": "audio/34/school-sch-nj-41__39.mp3", "t": "日中为阳陇，"}, {"f": "audio/34/school-sch-nj-41__40.mp3", "t": "日西为阳衰，"}, {"f": "audio/34/school-sch-nj-41__41.mp3", "t": "日入阳尽而阴受气矣。"}, {"f": "audio/34/school-sch-nj-41__42.mp3", "t": "夜半而大会，"}, {"f": "audio/34/school-sch-nj-41__43.mp3", "t": "万民皆卧，"}, {"f": "audio/34/school-sch-nj-41__44.mp3", "t": "命曰合阴。"}, {"f": "audio/34/school-sch-nj-41__45.mp3", "t": "平旦阴尽而阳受气，"}, {"f": "audio/34/school-sch-nj-41__46.mp3", "t": "如是无已，"}, {"f": "audio/34/school-sch-nj-41__47.mp3", "t": "与天地同纪。"}], "school-sch-nj-42": [{"f": "audio/9e/school-sch-nj-42__0.mp3", "t": "黄帝曰："}, {"f": "audio/9e/school-sch-nj-42__1.mp3", "t": "老人之不夜瞑者，"}, {"f": "audio/9e/school-sch-nj-42__2.mp3", "t": "何气使然？"}, {"f": "audio/9e/school-sch-nj-42__3.mp3", "t": "少壮之人不昼瞑者，"}, {"f": "audio/9e/school-sch-nj-42__4.mp3", "t": "何气使然？"}, {"f": "audio/9e/school-sch-nj-42__5.mp3", "t": "岐伯答曰："}, {"f": "audio/9e/school-sch-nj-42__6.mp3", "t": "壮者之气血盛，"}, {"f": "audio/9e/school-sch-nj-42__7.mp3", "t": "其肌肉滑，"}, {"f": "audio/9e/school-sch-nj-42__8.mp3", "t": "气道通，"}, {"f": "audio/9e/school-sch-nj-42__9.mp3", "t": "营卫之行，"}, {"f": "audio/9e/school-sch-nj-42__10.mp3", "t": "不失其常，"}, {"f": "audio/9e/school-sch-nj-42__11.mp3", "t": "故昼精而夜瞑。"}, {"f": "audio/9e/school-sch-nj-42__12.mp3", "t": "老者之气血衰，"}, {"f": "audio/9e/school-sch-nj-42__13.mp3", "t": "其肌肉枯，"}, {"f": "audio/9e/school-sch-nj-42__14.mp3", "t": "气道涩，"}, {"f": "audio/9e/school-sch-nj-42__15.mp3", "t": "五藏之气相搏，"}, {"f": "audio/9e/school-sch-nj-42__16.mp3", "t": "其营气衰少而卫气内伐，"}, {"f": "audio/9e/school-sch-nj-42__17.mp3", "t": "故昼不精，"}, {"f": "audio/9e/school-sch-nj-42__18.mp3", "t": "夜不瞑。"}], "school-sch-nj-43": [{"f": "audio/bc/school-sch-nj-43__0.mp3", "t": "黄帝曰："}, {"f": "audio/bc/school-sch-nj-43__1.mp3", "t": "愿闻营卫之所行，"}, {"f": "audio/bc/school-sch-nj-43__2.mp3", "t": "皆何道从来？"}, {"f": "audio/bc/school-sch-nj-43__3.mp3", "t": "岐伯答曰："}, {"f": "audio/bc/school-sch-nj-43__4.mp3", "t": "营出于中焦，"}, {"f": "audio/bc/school-sch-nj-43__5.mp3", "t": "卫出于下焦。"}, {"f": "audio/bc/school-sch-nj-43__6.mp3", "t": "黄帝曰："}, {"f": "audio/bc/school-sch-nj-43__7.mp3", "t": "愿闻三焦之所出。"}, {"f": "audio/bc/school-sch-nj-43__8.mp3", "t": "岐伯答曰："}, {"f": "audio/bc/school-sch-nj-43__9.mp3", "t": "上焦出于胃上口，"}, {"f": "audio/bc/school-sch-nj-43__10.mp3", "t": "并咽以上，"}, {"f": "audio/bc/school-sch-nj-43__11.mp3", "t": "贯膈而布胸中，"}, {"f": "audio/bc/school-sch-nj-43__12.mp3", "t": "走腋，"}, {"f": "audio/bc/school-sch-nj-43__13.mp3", "t": "循太阴之分而行，"}, {"f": "audio/bc/school-sch-nj-43__14.mp3", "t": "还至阳明，"}, {"f": "audio/bc/school-sch-nj-43__15.mp3", "t": "上至舌，"}, {"f": "audio/bc/school-sch-nj-43__16.mp3", "t": "下足阳明，"}, {"f": "audio/bc/school-sch-nj-43__17.mp3", "t": "常与营俱行于阳二十五度，"}, {"f": "audio/bc/school-sch-nj-43__18.mp3", "t": "行于阴亦二十五度，"}, {"f": "audio/bc/school-sch-nj-43__19.mp3", "t": "一周也。"}, {"f": "audio/bc/school-sch-nj-43__20.mp3", "t": "故五十度而复大会于手太阴矣。"}], "school-sch-nj-44": [{"f": "audio/1c/school-sch-nj-44__0.mp3", "t": "黄帝曰："}, {"f": "audio/1c/school-sch-nj-44__1.mp3", "t": "人有热饮食下胃，"}, {"f": "audio/1c/school-sch-nj-44__2.mp3", "t": "其气未定，"}, {"f": "audio/1c/school-sch-nj-44__3.mp3", "t": "汗则出，"}, {"f": "audio/1c/school-sch-nj-44__4.mp3", "t": "或出于面，"}, {"f": "audio/1c/school-sch-nj-44__5.mp3", "t": "或出于背，"}, {"f": "audio/1c/school-sch-nj-44__6.mp3", "t": "或出于身半，"}, {"f": "audio/1c/school-sch-nj-44__7.mp3", "t": "其不循卫气之道而出，"}, {"f": "audio/1c/school-sch-nj-44__8.mp3", "t": "何也？"}, {"f": "audio/1c/school-sch-nj-44__9.mp3", "t": "岐伯曰："}, {"f": "audio/1c/school-sch-nj-44__10.mp3", "t": "此外伤于风，"}, {"f": "audio/1c/school-sch-nj-44__11.mp3", "t": "内开腠理，"}, {"f": "audio/1c/school-sch-nj-44__12.mp3", "t": "毛蒸理泄，"}, {"f": "audio/1c/school-sch-nj-44__13.mp3", "t": "卫气走之，"}, {"f": "audio/1c/school-sch-nj-44__14.mp3", "t": "固不得循其道，"}, {"f": "audio/1c/school-sch-nj-44__15.mp3", "t": "此气慓悍滑疾，"}, {"f": "audio/1c/school-sch-nj-44__16.mp3", "t": "见开而出，"}, {"f": "audio/1c/school-sch-nj-44__17.mp3", "t": "故不得从其道，"}, {"f": "audio/1c/school-sch-nj-44__18.mp3", "t": "故命曰漏泄。"}], "school-sch-nj-45": [{"f": "audio/20/school-sch-nj-45__0.mp3", "t": "黄帝曰："}, {"f": "audio/20/school-sch-nj-45__1.mp3", "t": "愿闻中焦之所出。"}, {"f": "audio/20/school-sch-nj-45__2.mp3", "t": "岐伯答曰："}, {"f": "audio/20/school-sch-nj-45__3.mp3", "t": "中焦亦并胃中，"}, {"f": "audio/20/school-sch-nj-45__4.mp3", "t": "出上焦之后，"}, {"f": "audio/20/school-sch-nj-45__5.mp3", "t": "此所受气者，"}, {"f": "audio/20/school-sch-nj-45__6.mp3", "t": "泌糟粕，"}, {"f": "audio/20/school-sch-nj-45__7.mp3", "t": "蒸津液，"}, {"f": "audio/20/school-sch-nj-45__8.mp3", "t": "化其精微，"}, {"f": "audio/20/school-sch-nj-45__9.mp3", "t": "上注于肺脉，"}, {"f": "audio/20/school-sch-nj-45__10.mp3", "t": "乃化而为血，"}, {"f": "audio/20/school-sch-nj-45__11.mp3", "t": "以奉生身，"}, {"f": "audio/20/school-sch-nj-45__12.mp3", "t": "莫贵于此，"}, {"f": "audio/20/school-sch-nj-45__13.mp3", "t": "故独得行于经隧，"}, {"f": "audio/20/school-sch-nj-45__14.mp3", "t": "命曰营气。"}], "school-sch-nj-46": [{"f": "audio/04/school-sch-nj-46__0.mp3", "t": "黄帝曰："}, {"f": "audio/04/school-sch-nj-46__1.mp3", "t": "夫血之与气，"}, {"f": "audio/04/school-sch-nj-46__2.mp3", "t": "异名同类，"}, {"f": "audio/04/school-sch-nj-46__3.mp3", "t": "何谓也？"}, {"f": "audio/04/school-sch-nj-46__4.mp3", "t": "岐伯答曰："}, {"f": "audio/04/school-sch-nj-46__5.mp3", "t": "营卫者，"}, {"f": "audio/04/school-sch-nj-46__6.mp3", "t": "精气也，"}, {"f": "audio/04/school-sch-nj-46__7.mp3", "t": "血者，"}, {"f": "audio/04/school-sch-nj-46__8.mp3", "t": "神气也。"}, {"f": "audio/04/school-sch-nj-46__9.mp3", "t": "故血之与气，"}, {"f": "audio/04/school-sch-nj-46__10.mp3", "t": "异名同类焉。"}, {"f": "audio/04/school-sch-nj-46__11.mp3", "t": "故夺血者无汗，"}, {"f": "audio/04/school-sch-nj-46__12.mp3", "t": "夺汗者无血，"}, {"f": "audio/04/school-sch-nj-46__13.mp3", "t": "故人生有两死，"}, {"f": "audio/04/school-sch-nj-46__14.mp3", "t": "而无两生。"}], "school-sch-nj-47": [{"f": "audio/08/school-sch-nj-47__0.mp3", "t": "黄帝曰："}, {"f": "audio/08/school-sch-nj-47__1.mp3", "t": "愿闻下焦之所出。"}, {"f": "audio/08/school-sch-nj-47__2.mp3", "t": "岐伯答曰："}, {"f": "audio/08/school-sch-nj-47__3.mp3", "t": "下焦者，"}, {"f": "audio/08/school-sch-nj-47__4.mp3", "t": "别回肠，"}, {"f": "audio/08/school-sch-nj-47__5.mp3", "t": "注于膀胱，"}, {"f": "audio/08/school-sch-nj-47__6.mp3", "t": "而渗入焉。"}, {"f": "audio/08/school-sch-nj-47__7.mp3", "t": "故水谷者，"}, {"f": "audio/08/school-sch-nj-47__8.mp3", "t": "常并居于胃中，"}, {"f": "audio/08/school-sch-nj-47__9.mp3", "t": "成糟粕而俱下于大肠，"}, {"f": "audio/08/school-sch-nj-47__10.mp3", "t": "而成下焦，"}, {"f": "audio/08/school-sch-nj-47__11.mp3", "t": "渗而俱下，"}, {"f": "audio/08/school-sch-nj-47__12.mp3", "t": "济泌别汁，"}, {"f": "audio/08/school-sch-nj-47__13.mp3", "t": "循下焦而渗入膀胱焉。"}], "school-sch-nj-48": [{"f": "audio/93/school-sch-nj-48__0.mp3", "t": "黄帝曰："}, {"f": "audio/93/school-sch-nj-48__1.mp3", "t": "人饮酒，"}, {"f": "audio/93/school-sch-nj-48__2.mp3", "t": "酒亦入胃，"}, {"f": "audio/93/school-sch-nj-48__3.mp3", "t": "谷未熟而小便独先下，"}, {"f": "audio/93/school-sch-nj-48__4.mp3", "t": "何也？"}, {"f": "audio/93/school-sch-nj-48__5.mp3", "t": "岐伯答曰："}, {"f": "audio/93/school-sch-nj-48__6.mp3", "t": "酒者熟谷之液也。"}, {"f": "audio/93/school-sch-nj-48__7.mp3", "t": "其气悍以清，"}, {"f": "audio/93/school-sch-nj-48__8.mp3", "t": "故后谷而入，"}, {"f": "audio/93/school-sch-nj-48__9.mp3", "t": "先谷而液出焉。"}], "school-sch-nj-49": [{"f": "audio/ff/school-sch-nj-49__0.mp3", "t": "黄帝曰："}, {"f": "audio/ff/school-sch-nj-49__1.mp3", "t": "善。"}, {"f": "audio/ff/school-sch-nj-49__2.mp3", "t": "余闻上焦如雾，"}, {"f": "audio/ff/school-sch-nj-49__3.mp3", "t": "中焦如沤，"}, {"f": "audio/ff/school-sch-nj-49__4.mp3", "t": "下焦如渎，"}, {"f": "audio/ff/school-sch-nj-49__5.mp3", "t": "此之谓也。"}], "school-sch-nj-50": [{"f": "audio/f9/school-sch-nj-50__0.mp3", "t": "黄帝曰："}, {"f": "audio/f9/school-sch-nj-50__1.mp3", "t": "余闻人有精、"}, {"f": "audio/f9/school-sch-nj-50__2.mp3", "t": "气、"}, {"f": "audio/f9/school-sch-nj-50__3.mp3", "t": "津、"}, {"f": "audio/f9/school-sch-nj-50__4.mp3", "t": "液、"}, {"f": "audio/f9/school-sch-nj-50__5.mp3", "t": "血、"}, {"f": "audio/f9/school-sch-nj-50__6.mp3", "t": "脉，"}, {"f": "audio/f9/school-sch-nj-50__7.mp3", "t": "余意以为一气耳，"}, {"f": "audio/f9/school-sch-nj-50__8.mp3", "t": "今乃辨为六名，"}, {"f": "audio/f9/school-sch-nj-50__9.mp3", "t": "余不知其所以然。"}, {"f": "audio/f9/school-sch-nj-50__10.mp3", "t": "岐伯曰："}, {"f": "audio/f9/school-sch-nj-50__11.mp3", "t": "两神相搏，"}, {"f": "audio/f9/school-sch-nj-50__12.mp3", "t": "合而成形，"}, {"f": "audio/f9/school-sch-nj-50__13.mp3", "t": "常先身生，"}, {"f": "audio/f9/school-sch-nj-50__14.mp3", "t": "是谓精。"}, {"f": "audio/f9/school-sch-nj-50__15.mp3", "t": "何谓气？"}, {"f": "audio/f9/school-sch-nj-50__16.mp3", "t": "岐伯曰："}, {"f": "audio/f9/school-sch-nj-50__17.mp3", "t": "上焦开发，"}, {"f": "audio/f9/school-sch-nj-50__18.mp3", "t": "宣五谷味，"}, {"f": "audio/f9/school-sch-nj-50__19.mp3", "t": "熏肤充身泽毛，"}, {"f": "audio/f9/school-sch-nj-50__20.mp3", "t": "若雾露之溉，"}, {"f": "audio/f9/school-sch-nj-50__21.mp3", "t": "是谓气。"}, {"f": "audio/f9/school-sch-nj-50__22.mp3", "t": "何谓津？"}, {"f": "audio/f9/school-sch-nj-50__23.mp3", "t": "岐伯曰："}, {"f": "audio/f9/school-sch-nj-50__24.mp3", "t": "腠理发泄，"}, {"f": "audio/f9/school-sch-nj-50__25.mp3", "t": "汗出溱溱，"}, {"f": "audio/f9/school-sch-nj-50__26.mp3", "t": "是谓津。"}, {"f": "audio/f9/school-sch-nj-50__27.mp3", "t": "何谓液？"}, {"f": "audio/f9/school-sch-nj-50__28.mp3", "t": "岐伯曰："}, {"f": "audio/f9/school-sch-nj-50__29.mp3", "t": "谷入气满，"}, {"f": "audio/f9/school-sch-nj-50__30.mp3", "t": "淖泽注于骨，"}, {"f": "audio/f9/school-sch-nj-50__31.mp3", "t": "骨属屈伸，"}, {"f": "audio/f9/school-sch-nj-50__32.mp3", "t": "泄泽补益脑髓，"}, {"f": "audio/f9/school-sch-nj-50__33.mp3", "t": "皮肤润泽，"}, {"f": "audio/f9/school-sch-nj-50__34.mp3", "t": "是谓液。"}, {"f": "audio/f9/school-sch-nj-50__35.mp3", "t": "何谓血？"}, {"f": "audio/f9/school-sch-nj-50__36.mp3", "t": "岐伯曰："}, {"f": "audio/f9/school-sch-nj-50__37.mp3", "t": "中焦受气取汁，"}, {"f": "audio/f9/school-sch-nj-50__38.mp3", "t": "变化而赤，"}, {"f": "audio/f9/school-sch-nj-50__39.mp3", "t": "是谓血。"}, {"f": "audio/f9/school-sch-nj-50__40.mp3", "t": "何谓脉？"}, {"f": "audio/f9/school-sch-nj-50__41.mp3", "t": "岐伯曰："}, {"f": "audio/f9/school-sch-nj-50__42.mp3", "t": "壅遏营气，"}, {"f": "audio/f9/school-sch-nj-50__43.mp3", "t": "令无所避，"}, {"f": "audio/f9/school-sch-nj-50__44.mp3", "t": "是谓脉。"}], "school-sch-nj-51": [{"f": "audio/0a/school-sch-nj-51__0.mp3", "t": "黄帝曰："}, {"f": "audio/0a/school-sch-nj-51__1.mp3", "t": "六气者，"}, {"f": "audio/0a/school-sch-nj-51__2.mp3", "t": "有余不足，"}, {"f": "audio/0a/school-sch-nj-51__3.mp3", "t": "气之多少，"}, {"f": "audio/0a/school-sch-nj-51__4.mp3", "t": "脑髓之虚实，"}, {"f": "audio/0a/school-sch-nj-51__5.mp3", "t": "血脉之清浊，"}, {"f": "audio/0a/school-sch-nj-51__6.mp3", "t": "何以知之？"}, {"f": "audio/0a/school-sch-nj-51__7.mp3", "t": "岐伯曰："}, {"f": "audio/0a/school-sch-nj-51__8.mp3", "t": "精脱者，"}, {"f": "audio/0a/school-sch-nj-51__9.mp3", "t": "耳聋。"}, {"f": "audio/0a/school-sch-nj-51__10.mp3", "t": "气脱者，"}, {"f": "audio/0a/school-sch-nj-51__11.mp3", "t": "目不明；"}, {"f": "audio/0a/school-sch-nj-51__12.mp3", "t": "津脱者，"}, {"f": "audio/0a/school-sch-nj-51__13.mp3", "t": "腠理开，"}, {"f": "audio/0a/school-sch-nj-51__14.mp3", "t": "汗大泄；"}, {"f": "audio/0a/school-sch-nj-51__15.mp3", "t": "液脱者，"}, {"f": "audio/0a/school-sch-nj-51__16.mp3", "t": "骨属屈伸不利，"}, {"f": "audio/0a/school-sch-nj-51__17.mp3", "t": "色夭，"}, {"f": "audio/0a/school-sch-nj-51__18.mp3", "t": "脑髓消，"}, {"f": "audio/0a/school-sch-nj-51__19.mp3", "t": "胫酸，"}, {"f": "audio/0a/school-sch-nj-51__20.mp3", "t": "耳数鸣；"}, {"f": "audio/0a/school-sch-nj-51__21.mp3", "t": "血脱者，"}, {"f": "audio/0a/school-sch-nj-51__22.mp3", "t": "色白，"}, {"f": "audio/0a/school-sch-nj-51__23.mp3", "t": "夭然不泽，"}, {"f": "audio/0a/school-sch-nj-51__24.mp3", "t": "其脉空虚，"}, {"f": "audio/0a/school-sch-nj-51__25.mp3", "t": "此其候也。"}], "school-sch-nj-52": [{"f": "audio/13/school-sch-nj-52__0.mp3", "t": "黄帝问于岐伯曰："}, {"f": "audio/13/school-sch-nj-52__1.mp3", "t": "夫百病之始生也，"}, {"f": "audio/13/school-sch-nj-52__2.mp3", "t": "皆生于风雨寒暑，"}, {"f": "audio/13/school-sch-nj-52__3.mp3", "t": "清湿喜怒。"}, {"f": "audio/13/school-sch-nj-52__4.mp3", "t": "喜怒不节则伤藏，"}, {"f": "audio/13/school-sch-nj-52__5.mp3", "t": "风雨则伤上，"}, {"f": "audio/13/school-sch-nj-52__6.mp3", "t": "清湿则伤下。"}, {"f": "audio/13/school-sch-nj-52__7.mp3", "t": "三部之气，"}, {"f": "audio/13/school-sch-nj-52__8.mp3", "t": "所伤异类，"}, {"f": "audio/13/school-sch-nj-52__9.mp3", "t": "愿闻其会。"}, {"f": "audio/13/school-sch-nj-52__10.mp3", "t": "岐伯曰："}, {"f": "audio/13/school-sch-nj-52__11.mp3", "t": "三部之气各不同，"}, {"f": "audio/13/school-sch-nj-52__12.mp3", "t": "或起于阴，"}, {"f": "audio/13/school-sch-nj-52__13.mp3", "t": "或起于阳，"}, {"f": "audio/13/school-sch-nj-52__14.mp3", "t": "请言其方。"}, {"f": "audio/13/school-sch-nj-52__15.mp3", "t": "喜怒不节则伤藏，"}, {"f": "audio/13/school-sch-nj-52__16.mp3", "t": "藏伤则病起于阴也；"}, {"f": "audio/13/school-sch-nj-52__17.mp3", "t": "清湿袭虚，"}, {"f": "audio/13/school-sch-nj-52__18.mp3", "t": "则病起于下；"}, {"f": "audio/13/school-sch-nj-52__19.mp3", "t": "风雨袭虚，"}, {"f": "audio/13/school-sch-nj-52__20.mp3", "t": "则病起于上，"}, {"f": "audio/13/school-sch-nj-52__21.mp3", "t": "是谓三部。"}, {"f": "audio/13/school-sch-nj-52__22.mp3", "t": "至于其淫泆，"}, {"f": "audio/13/school-sch-nj-52__23.mp3", "t": "不可胜数。"}], "school-sch-nj-53": [{"f": "audio/e5/school-sch-nj-53__0.mp3", "t": "黄帝曰："}, {"f": "audio/e5/school-sch-nj-53__1.mp3", "t": "余固不能数，"}, {"f": "audio/e5/school-sch-nj-53__2.mp3", "t": "故问先师，"}, {"f": "audio/e5/school-sch-nj-53__3.mp3", "t": "愿卒闻其道。"}, {"f": "audio/e5/school-sch-nj-53__4.mp3", "t": "岐伯曰："}, {"f": "audio/e5/school-sch-nj-53__5.mp3", "t": "风雨寒热，"}, {"f": "audio/e5/school-sch-nj-53__6.mp3", "t": "不得虚，"}, {"f": "audio/e5/school-sch-nj-53__7.mp3", "t": "邪不能独伤人，"}, {"f": "audio/e5/school-sch-nj-53__8.mp3", "t": "卒然逢疾风暴雨而不病者，"}, {"f": "audio/e5/school-sch-nj-53__9.mp3", "t": "盖无虚，"}, {"f": "audio/e5/school-sch-nj-53__10.mp3", "t": "故邪不能独伤人。"}, {"f": "audio/e5/school-sch-nj-53__11.mp3", "t": "此必因虚邪之风，"}, {"f": "audio/e5/school-sch-nj-53__12.mp3", "t": "与其身形，"}, {"f": "audio/e5/school-sch-nj-53__13.mp3", "t": "两虚相得，"}, {"f": "audio/e5/school-sch-nj-53__14.mp3", "t": "乃客其形。"}, {"f": "audio/e5/school-sch-nj-53__15.mp3", "t": "两实相逢，"}, {"f": "audio/e5/school-sch-nj-53__16.mp3", "t": "众人肉坚。"}, {"f": "audio/e5/school-sch-nj-53__17.mp3", "t": "其中于虚邪也，"}, {"f": "audio/e5/school-sch-nj-53__18.mp3", "t": "因于天时，"}, {"f": "audio/e5/school-sch-nj-53__19.mp3", "t": "与其身形，"}, {"f": "audio/e5/school-sch-nj-53__20.mp3", "t": "参以虚实，"}, {"f": "audio/e5/school-sch-nj-53__21.mp3", "t": "大病乃成。"}, {"f": "audio/e5/school-sch-nj-53__22.mp3", "t": "气有定舍，"}, {"f": "audio/e5/school-sch-nj-53__23.mp3", "t": "因处为名。"}, {"f": "audio/e5/school-sch-nj-53__24.mp3", "t": "上下中外，"}, {"f": "audio/e5/school-sch-nj-53__25.mp3", "t": "分为三员。"}], "school-sch-nj-54": [{"f": "audio/b4/school-sch-nj-54__0.mp3", "t": "是故虚邪之中人也，"}, {"f": "audio/b4/school-sch-nj-54__1.mp3", "t": "始于皮肤，"}, {"f": "audio/b4/school-sch-nj-54__2.mp3", "t": "皮肤缓则腠理开，"}, {"f": "audio/b4/school-sch-nj-54__3.mp3", "t": "开则邪从毛发入，"}, {"f": "audio/b4/school-sch-nj-54__4.mp3", "t": "入则抵深，"}, {"f": "audio/b4/school-sch-nj-54__5.mp3", "t": "深则毛发立，"}, {"f": "audio/b4/school-sch-nj-54__6.mp3", "t": "毛发立则淅然，"}, {"f": "audio/b4/school-sch-nj-54__7.mp3", "t": "故皮肤痛。"}, {"f": "audio/b4/school-sch-nj-54__8.mp3", "t": "留而不去，"}, {"f": "audio/b4/school-sch-nj-54__9.mp3", "t": "则传舍于络脉，"}, {"f": "audio/b4/school-sch-nj-54__10.mp3", "t": "在络之时，"}, {"f": "audio/b4/school-sch-nj-54__11.mp3", "t": "痛于肌肉，"}, {"f": "audio/b4/school-sch-nj-54__12.mp3", "t": "故痛之时息，"}, {"f": "audio/b4/school-sch-nj-54__13.mp3", "t": "大经乃代。"}, {"f": "audio/b4/school-sch-nj-54__14.mp3", "t": "留而不去，"}, {"f": "audio/b4/school-sch-nj-54__15.mp3", "t": "传舍于经，"}, {"f": "audio/b4/school-sch-nj-54__16.mp3", "t": "在经之时，"}, {"f": "audio/b4/school-sch-nj-54__17.mp3", "t": "洒淅喜惊。"}, {"f": "audio/b4/school-sch-nj-54__18.mp3", "t": "留而不去，"}, {"f": "audio/b4/school-sch-nj-54__19.mp3", "t": "传舍于输，"}, {"f": "audio/b4/school-sch-nj-54__20.mp3", "t": "在输之时，"}, {"f": "audio/b4/school-sch-nj-54__21.mp3", "t": "六经不通四肢，"}, {"f": "audio/b4/school-sch-nj-54__22.mp3", "t": "则肢节痛，"}, {"f": "audio/b4/school-sch-nj-54__23.mp3", "t": "腰脊乃强。"}, {"f": "audio/b4/school-sch-nj-54__24.mp3", "t": "留而不去，"}, {"f": "audio/b4/school-sch-nj-54__25.mp3", "t": "传舍于伏冲之脉，"}, {"f": "audio/b4/school-sch-nj-54__26.mp3", "t": "在伏冲之时，"}, {"f": "audio/b4/school-sch-nj-54__27.mp3", "t": "体重身痛。"}, {"f": "audio/b4/school-sch-nj-54__28.mp3", "t": "留而不去，"}, {"f": "audio/b4/school-sch-nj-54__29.mp3", "t": "传舍于肠胃，"}, {"f": "audio/b4/school-sch-nj-54__30.mp3", "t": "在肠胃之时，"}, {"f": "audio/b4/school-sch-nj-54__31.mp3", "t": "贲响腹胀，"}, {"f": "audio/b4/school-sch-nj-54__32.mp3", "t": "多寒则肠鸣飧泄，"}, {"f": "audio/b4/school-sch-nj-54__33.mp3", "t": "食不化；"}, {"f": "audio/b4/school-sch-nj-54__34.mp3", "t": "多热则溏出糜。"}, {"f": "audio/b4/school-sch-nj-54__35.mp3", "t": "留而不去，"}, {"f": "audio/b4/school-sch-nj-54__36.mp3", "t": "传舍于肠胃之外，"}, {"f": "audio/b4/school-sch-nj-54__37.mp3", "t": "募原之间，"}, {"f": "audio/b4/school-sch-nj-54__38.mp3", "t": "留著于脉，"}, {"f": "audio/b4/school-sch-nj-54__39.mp3", "t": "稽留而不去，"}, {"f": "audio/b4/school-sch-nj-54__40.mp3", "t": "息而成积。"}, {"f": "audio/b4/school-sch-nj-54__41.mp3", "t": "或著孙脉，"}, {"f": "audio/b4/school-sch-nj-54__42.mp3", "t": "或著络脉，"}, {"f": "audio/b4/school-sch-nj-54__43.mp3", "t": "或著经脉，"}, {"f": "audio/b4/school-sch-nj-54__44.mp3", "t": "或著输脉，"}, {"f": "audio/b4/school-sch-nj-54__45.mp3", "t": "或著于伏冲之脉，"}, {"f": "audio/b4/school-sch-nj-54__46.mp3", "t": "或著于膂筋，"}, {"f": "audio/b4/school-sch-nj-54__47.mp3", "t": "或著于肠胃之募原，"}, {"f": "audio/b4/school-sch-nj-54__48.mp3", "t": "上连于缓筋，"}, {"f": "audio/b4/school-sch-nj-54__49.mp3", "t": "邪气淫泆，"}, {"f": "audio/b4/school-sch-nj-54__50.mp3", "t": "不可胜论。"}], "school-sch-nj-55": [{"f": "audio/03/school-sch-nj-55__0.mp3", "t": "黄帝曰："}, {"f": "audio/03/school-sch-nj-55__1.mp3", "t": "愿尽闻其所由然。"}, {"f": "audio/03/school-sch-nj-55__2.mp3", "t": "岐伯曰："}, {"f": "audio/03/school-sch-nj-55__3.mp3", "t": "其著孙络之脉而成积者，"}, {"f": "audio/03/school-sch-nj-55__4.mp3", "t": "其积往来上下，"}, {"f": "audio/03/school-sch-nj-55__5.mp3", "t": "臂手孙络之居也，"}, {"f": "audio/03/school-sch-nj-55__6.mp3", "t": "浮而缓，"}, {"f": "audio/03/school-sch-nj-55__7.mp3", "t": "不能句积而止之，"}, {"f": "audio/03/school-sch-nj-55__8.mp3", "t": "故往来移行肠胃之间，"}, {"f": "audio/03/school-sch-nj-55__9.mp3", "t": "水凑渗注灌，"}, {"f": "audio/03/school-sch-nj-55__10.mp3", "t": "濯濯有音；"}, {"f": "audio/03/school-sch-nj-55__11.mp3", "t": "有寒则䐜满雷引，"}, {"f": "audio/03/school-sch-nj-55__12.mp3", "t": "故时切痛。"}, {"f": "audio/03/school-sch-nj-55__13.mp3", "t": "其著于阳明之经，"}, {"f": "audio/03/school-sch-nj-55__14.mp3", "t": "则挟脐而居，"}, {"f": "audio/03/school-sch-nj-55__15.mp3", "t": "饱食则益大，"}, {"f": "audio/03/school-sch-nj-55__16.mp3", "t": "饥则益小。"}, {"f": "audio/03/school-sch-nj-55__17.mp3", "t": "其著于缓筋也，"}, {"f": "audio/03/school-sch-nj-55__18.mp3", "t": "似阳明之积，"}, {"f": "audio/03/school-sch-nj-55__19.mp3", "t": "饱食则痛，"}, {"f": "audio/03/school-sch-nj-55__20.mp3", "t": "饥则安。"}, {"f": "audio/03/school-sch-nj-55__21.mp3", "t": "其著于肠胃之募原也，"}, {"f": "audio/03/school-sch-nj-55__22.mp3", "t": "痛而外连于缓筋，"}, {"f": "audio/03/school-sch-nj-55__23.mp3", "t": "饱食则安，"}, {"f": "audio/03/school-sch-nj-55__24.mp3", "t": "饥则痛。"}, {"f": "audio/03/school-sch-nj-55__25.mp3", "t": "其著于伏冲之脉者，"}, {"f": "audio/03/school-sch-nj-55__26.mp3", "t": "揣之应手而动，"}, {"f": "audio/03/school-sch-nj-55__27.mp3", "t": "发手，"}, {"f": "audio/03/school-sch-nj-55__28.mp3", "t": "则热气下于两股，"}, {"f": "audio/03/school-sch-nj-55__29.mp3", "t": "如汤沃之状。"}, {"f": "audio/03/school-sch-nj-55__30.mp3", "t": "其著于膂筋，"}, {"f": "audio/03/school-sch-nj-55__31.mp3", "t": "在肠后者，"}, {"f": "audio/03/school-sch-nj-55__32.mp3", "t": "饥则积见，"}, {"f": "audio/03/school-sch-nj-55__33.mp3", "t": "饱则积不见，"}, {"f": "audio/03/school-sch-nj-55__34.mp3", "t": "按之不得。"}, {"f": "audio/03/school-sch-nj-55__35.mp3", "t": "其著于输之脉者，"}, {"f": "audio/03/school-sch-nj-55__36.mp3", "t": "闭塞不通，"}, {"f": "audio/03/school-sch-nj-55__37.mp3", "t": "津液不下，"}, {"f": "audio/03/school-sch-nj-55__38.mp3", "t": "孔窍干壅。"}, {"f": "audio/03/school-sch-nj-55__39.mp3", "t": "此邪气之从外入内，"}, {"f": "audio/03/school-sch-nj-55__40.mp3", "t": "从上下也。"}], "school-sch-nj-56": [{"f": "audio/74/school-sch-nj-56__0.mp3", "t": "黄帝曰："}, {"f": "audio/74/school-sch-nj-56__1.mp3", "t": "积之始生，"}, {"f": "audio/74/school-sch-nj-56__2.mp3", "t": "至其已成，"}, {"f": "audio/74/school-sch-nj-56__3.mp3", "t": "奈何？"}, {"f": "audio/74/school-sch-nj-56__4.mp3", "t": "岐伯曰："}, {"f": "audio/74/school-sch-nj-56__5.mp3", "t": "积之始生，"}, {"f": "audio/74/school-sch-nj-56__6.mp3", "t": "得寒乃生，"}, {"f": "audio/74/school-sch-nj-56__7.mp3", "t": "厥乃成积也。"}, {"f": "audio/74/school-sch-nj-56__8.mp3", "t": "黄帝曰："}, {"f": "audio/74/school-sch-nj-56__9.mp3", "t": "其成积奈何？"}, {"f": "audio/74/school-sch-nj-56__10.mp3", "t": "岐伯曰："}, {"f": "audio/74/school-sch-nj-56__11.mp3", "t": "厥气生足悗，"}, {"f": "audio/74/school-sch-nj-56__12.mp3", "t": "悗生胫寒，"}, {"f": "audio/74/school-sch-nj-56__13.mp3", "t": "胫寒则血脉凝涩，"}, {"f": "audio/74/school-sch-nj-56__14.mp3", "t": "血脉凝涩则寒气上入于肠胃，"}, {"f": "audio/74/school-sch-nj-56__15.mp3", "t": "入于肠胃则䐜胀，"}, {"f": "audio/74/school-sch-nj-56__16.mp3", "t": "䐜胀则肠外之汁沫迫聚不得散，"}, {"f": "audio/74/school-sch-nj-56__17.mp3", "t": "日以成积。"}, {"f": "audio/74/school-sch-nj-56__18.mp3", "t": "卒然多食饮，"}, {"f": "audio/74/school-sch-nj-56__19.mp3", "t": "则肠满。"}, {"f": "audio/74/school-sch-nj-56__20.mp3", "t": "起居不节，"}, {"f": "audio/74/school-sch-nj-56__21.mp3", "t": "用力过度，"}, {"f": "audio/74/school-sch-nj-56__22.mp3", "t": "则络脉伤。"}, {"f": "audio/74/school-sch-nj-56__23.mp3", "t": "阳络伤则血外溢，"}, {"f": "audio/74/school-sch-nj-56__24.mp3", "t": "血外溢则衄血；"}, {"f": "audio/74/school-sch-nj-56__25.mp3", "t": "阴络伤则血内溢，"}, {"f": "audio/74/school-sch-nj-56__26.mp3", "t": "血内溢则后血。"}, {"f": "audio/74/school-sch-nj-56__27.mp3", "t": "肠胃之络伤，"}, {"f": "audio/74/school-sch-nj-56__28.mp3", "t": "则血溢于肠外，"}, {"f": "audio/74/school-sch-nj-56__29.mp3", "t": "肠外有寒，"}, {"f": "audio/74/school-sch-nj-56__30.mp3", "t": "汁沫与血相搏，"}, {"f": "audio/74/school-sch-nj-56__31.mp3", "t": "则并合凝聚不得散，"}, {"f": "audio/74/school-sch-nj-56__32.mp3", "t": "而积成矣。"}, {"f": "audio/74/school-sch-nj-56__33.mp3", "t": "卒然中外于寒，"}, {"f": "audio/74/school-sch-nj-56__34.mp3", "t": "若内伤于忧愁，"}, {"f": "audio/74/school-sch-nj-56__35.mp3", "t": "则气上逆，"}, {"f": "audio/74/school-sch-nj-56__36.mp3", "t": "气上逆则六输不通，"}, {"f": "audio/74/school-sch-nj-56__37.mp3", "t": "温气不行，"}, {"f": "audio/74/school-sch-nj-56__38.mp3", "t": "凝血蕴裹而不散，"}, {"f": "audio/74/school-sch-nj-56__39.mp3", "t": "津液涩渗，"}, {"f": "audio/74/school-sch-nj-56__40.mp3", "t": "著而不去，"}, {"f": "audio/74/school-sch-nj-56__41.mp3", "t": "而积皆成矣。"}], "school-sch-nj-57": [{"f": "audio/fa/school-sch-nj-57__0.mp3", "t": "黄帝曰："}, {"f": "audio/fa/school-sch-nj-57__1.mp3", "t": "其生于阴者，"}, {"f": "audio/fa/school-sch-nj-57__2.mp3", "t": "奈何？"}, {"f": "audio/fa/school-sch-nj-57__3.mp3", "t": "岐伯曰："}, {"f": "audio/fa/school-sch-nj-57__4.mp3", "t": "忧思伤心；"}, {"f": "audio/fa/school-sch-nj-57__5.mp3", "t": "重寒伤肺；"}, {"f": "audio/fa/school-sch-nj-57__6.mp3", "t": "忿怒伤肝；"}, {"f": "audio/fa/school-sch-nj-57__7.mp3", "t": "醉以入房，"}, {"f": "audio/fa/school-sch-nj-57__8.mp3", "t": "汗出当风伤脾；"}, {"f": "audio/fa/school-sch-nj-57__9.mp3", "t": "用力过度，"}, {"f": "audio/fa/school-sch-nj-57__10.mp3", "t": "若入房汗出浴，"}, {"f": "audio/fa/school-sch-nj-57__11.mp3", "t": "则伤肾，"}, {"f": "audio/fa/school-sch-nj-57__12.mp3", "t": "此内外三部之所生病者也。"}], "school-sch-nj-58": [{"f": "audio/b0/school-sch-nj-58__0.mp3", "t": "黄帝曰："}, {"f": "audio/b0/school-sch-nj-58__1.mp3", "t": "善。"}, {"f": "audio/b0/school-sch-nj-58__2.mp3", "t": "治之奈何？"}, {"f": "audio/b0/school-sch-nj-58__3.mp3", "t": "岐伯答曰："}, {"f": "audio/b0/school-sch-nj-58__4.mp3", "t": "察其所痛，"}, {"f": "audio/b0/school-sch-nj-58__5.mp3", "t": "以知其应，"}, {"f": "audio/b0/school-sch-nj-58__6.mp3", "t": "有余不足，"}, {"f": "audio/b0/school-sch-nj-58__7.mp3", "t": "当补则补，"}, {"f": "audio/b0/school-sch-nj-58__8.mp3", "t": "当写则写，"}, {"f": "audio/b0/school-sch-nj-58__9.mp3", "t": "毋逆天时，"}, {"f": "audio/b0/school-sch-nj-58__10.mp3", "t": "是谓至治。"}], "school-sch-nj-59": [{"f": "audio/bb/school-sch-nj-59__0.mp3", "t": "黄帝问曰："}, {"f": "audio/bb/school-sch-nj-59__1.mp3", "t": "余闻善言天者，"}, {"f": "audio/bb/school-sch-nj-59__2.mp3", "t": "必有验于人；"}, {"f": "audio/bb/school-sch-nj-59__3.mp3", "t": "善言古者，"}, {"f": "audio/bb/school-sch-nj-59__4.mp3", "t": "必有合于今；"}, {"f": "audio/bb/school-sch-nj-59__5.mp3", "t": "善言人者，"}, {"f": "audio/bb/school-sch-nj-59__6.mp3", "t": "必有厌于己。"}, {"f": "audio/bb/school-sch-nj-59__7.mp3", "t": "如此，"}, {"f": "audio/bb/school-sch-nj-59__8.mp3", "t": "则道不惑而要数极，"}, {"f": "audio/bb/school-sch-nj-59__9.mp3", "t": "所谓明也。"}, {"f": "audio/bb/school-sch-nj-59__10.mp3", "t": "今余问于夫子，"}, {"f": "audio/bb/school-sch-nj-59__11.mp3", "t": "令言而可知，"}, {"f": "audio/bb/school-sch-nj-59__12.mp3", "t": "视而可见，"}, {"f": "audio/bb/school-sch-nj-59__13.mp3", "t": "扪而可得，"}, {"f": "audio/bb/school-sch-nj-59__14.mp3", "t": "令验于己，"}, {"f": "audio/bb/school-sch-nj-59__15.mp3", "t": "而发蒙解惑，"}, {"f": "audio/bb/school-sch-nj-59__16.mp3", "t": "可得而闻乎？"}], "school-sch-nj-60": [{"f": "audio/2b/school-sch-nj-60__0.mp3", "t": "岐伯再拜稽首对曰："}, {"f": "audio/2b/school-sch-nj-60__1.mp3", "t": "何道之问也？"}, {"f": "audio/2b/school-sch-nj-60__2.mp3", "t": "帝曰："}, {"f": "audio/2b/school-sch-nj-60__3.mp3", "t": "愿闻人之五藏卒痛，"}, {"f": "audio/2b/school-sch-nj-60__4.mp3", "t": "何气使然？"}, {"f": "audio/2b/school-sch-nj-60__5.mp3", "t": "岐伯对曰："}, {"f": "audio/2b/school-sch-nj-60__6.mp3", "t": "经脉流行不止，"}, {"f": "audio/2b/school-sch-nj-60__7.mp3", "t": "环周不休。"}, {"f": "audio/2b/school-sch-nj-60__8.mp3", "t": "寒气入经而稽迟，"}, {"f": "audio/2b/school-sch-nj-60__9.mp3", "t": "泣而不行，"}, {"f": "audio/2b/school-sch-nj-60__10.mp3", "t": "客于脉外则血少，"}, {"f": "audio/2b/school-sch-nj-60__11.mp3", "t": "客于脉中则气不通，"}, {"f": "audio/2b/school-sch-nj-60__12.mp3", "t": "故卒然而痛。"}], "school-sch-nj-61": [{"f": "audio/22/school-sch-nj-61__0.mp3", "t": "帝曰："}, {"f": "audio/22/school-sch-nj-61__1.mp3", "t": "其痛或卒然而止者，"}, {"f": "audio/22/school-sch-nj-61__2.mp3", "t": "或痛甚不休者，"}, {"f": "audio/22/school-sch-nj-61__3.mp3", "t": "或痛甚不可按者，"}, {"f": "audio/22/school-sch-nj-61__4.mp3", "t": "或按之而痛止者，"}, {"f": "audio/22/school-sch-nj-61__5.mp3", "t": "或按之无益者，"}, {"f": "audio/22/school-sch-nj-61__6.mp3", "t": "或喘动应手者，"}, {"f": "audio/22/school-sch-nj-61__7.mp3", "t": "或心与背相引而痛者，"}, {"f": "audio/22/school-sch-nj-61__8.mp3", "t": "或胁肋与少腹相引而痛者，"}, {"f": "audio/22/school-sch-nj-61__9.mp3", "t": "或腹痛引阴股者，"}, {"f": "audio/22/school-sch-nj-61__10.mp3", "t": "或痛宿昔而成积者，"}, {"f": "audio/22/school-sch-nj-61__11.mp3", "t": "或卒然痛死不知人，"}, {"f": "audio/22/school-sch-nj-61__12.mp3", "t": "有少间复生者，"}, {"f": "audio/22/school-sch-nj-61__13.mp3", "t": "或痛而呕者，"}, {"f": "audio/22/school-sch-nj-61__14.mp3", "t": "或腹痛而后泄者，"}, {"f": "audio/22/school-sch-nj-61__15.mp3", "t": "或痛而闭不通者。"}, {"f": "audio/22/school-sch-nj-61__16.mp3", "t": "凡此诸痛，"}, {"f": "audio/22/school-sch-nj-61__17.mp3", "t": "各不同形，"}, {"f": "audio/22/school-sch-nj-61__18.mp3", "t": "别之奈何？"}], "school-sch-nj-62": [{"f": "audio/f1/school-sch-nj-62__0.mp3", "t": "岐伯曰："}, {"f": "audio/f1/school-sch-nj-62__1.mp3", "t": "寒气客于脉外则脉寒，"}, {"f": "audio/f1/school-sch-nj-62__2.mp3", "t": "脉寒则缩蜷，"}, {"f": "audio/f1/school-sch-nj-62__3.mp3", "t": "缩蜷则脉绌急，"}, {"f": "audio/f1/school-sch-nj-62__4.mp3", "t": "则外引小络，"}, {"f": "audio/f1/school-sch-nj-62__5.mp3", "t": "故卒然而痛。"}, {"f": "audio/f1/school-sch-nj-62__6.mp3", "t": "得炅则痛立止，"}, {"f": "audio/f1/school-sch-nj-62__7.mp3", "t": "因重中于寒，"}, {"f": "audio/f1/school-sch-nj-62__8.mp3", "t": "则痛久矣。"}, {"f": "audio/f1/school-sch-nj-62__9.mp3", "t": "寒气客于经脉之中，"}, {"f": "audio/f1/school-sch-nj-62__10.mp3", "t": "与炅气相薄则脉满，"}, {"f": "audio/f1/school-sch-nj-62__11.mp3", "t": "满则痛而不可按也。"}, {"f": "audio/f1/school-sch-nj-62__12.mp3", "t": "寒气稽留，"}, {"f": "audio/f1/school-sch-nj-62__13.mp3", "t": "炅气从上，"}, {"f": "audio/f1/school-sch-nj-62__14.mp3", "t": "则脉充大而血气乱，"}, {"f": "audio/f1/school-sch-nj-62__15.mp3", "t": "故痛甚不可按也。"}, {"f": "audio/f1/school-sch-nj-62__16.mp3", "t": "寒气客于肠胃之间，"}, {"f": "audio/f1/school-sch-nj-62__17.mp3", "t": "膜原之下，"}, {"f": "audio/f1/school-sch-nj-62__18.mp3", "t": "血不得散，"}, {"f": "audio/f1/school-sch-nj-62__19.mp3", "t": "小络急引故痛，"}, {"f": "audio/f1/school-sch-nj-62__20.mp3", "t": "按之则血气散，"}, {"f": "audio/f1/school-sch-nj-62__21.mp3", "t": "故按之痛止。"}, {"f": "audio/f1/school-sch-nj-62__22.mp3", "t": "寒气客于侠脊之脉，"}, {"f": "audio/f1/school-sch-nj-62__23.mp3", "t": "则深按之不能及，"}, {"f": "audio/f1/school-sch-nj-62__24.mp3", "t": "故按之无益也。"}, {"f": "audio/f1/school-sch-nj-62__25.mp3", "t": "寒气客于冲脉，"}, {"f": "audio/f1/school-sch-nj-62__26.mp3", "t": "冲脉起于关元，"}, {"f": "audio/f1/school-sch-nj-62__27.mp3", "t": "随腹直上，"}, {"f": "audio/f1/school-sch-nj-62__28.mp3", "t": "寒气客则脉不通，"}, {"f": "audio/f1/school-sch-nj-62__29.mp3", "t": "脉不通则气因之，"}, {"f": "audio/f1/school-sch-nj-62__30.mp3", "t": "故喘动应手矣。"}, {"f": "audio/f1/school-sch-nj-62__31.mp3", "t": "寒气客于背俞之脉则脉泣，"}, {"f": "audio/f1/school-sch-nj-62__32.mp3", "t": "脉泣则血虚，"}, {"f": "audio/f1/school-sch-nj-62__33.mp3", "t": "血虚则痛。"}, {"f": "audio/f1/school-sch-nj-62__34.mp3", "t": "其俞注于心，"}, {"f": "audio/f1/school-sch-nj-62__35.mp3", "t": "故相引而痛。"}, {"f": "audio/f1/school-sch-nj-62__36.mp3", "t": "按之则热气至，"}, {"f": "audio/f1/school-sch-nj-62__37.mp3", "t": "热气至则痛止矣。"}, {"f": "audio/f1/school-sch-nj-62__38.mp3", "t": "寒气客于厥阴之脉，"}, {"f": "audio/f1/school-sch-nj-62__39.mp3", "t": "厥阴之脉者，"}, {"f": "audio/f1/school-sch-nj-62__40.mp3", "t": "络阴器，"}, {"f": "audio/f1/school-sch-nj-62__41.mp3", "t": "系于肝，"}, {"f": "audio/f1/school-sch-nj-62__42.mp3", "t": "寒气客于脉中，"}, {"f": "audio/f1/school-sch-nj-62__43.mp3", "t": "则血泣脉急，"}, {"f": "audio/f1/school-sch-nj-62__44.mp3", "t": "故胁肋与少腹相引痛矣。"}, {"f": "audio/f1/school-sch-nj-62__45.mp3", "t": "厥气客于阴股，"}, {"f": "audio/f1/school-sch-nj-62__46.mp3", "t": "寒气上及少腹，"}, {"f": "audio/f1/school-sch-nj-62__47.mp3", "t": "血泣在下相引，"}, {"f": "audio/f1/school-sch-nj-62__48.mp3", "t": "故腹痛引阴股。"}, {"f": "audio/f1/school-sch-nj-62__49.mp3", "t": "寒气客于小肠膜原之间，"}, {"f": "audio/f1/school-sch-nj-62__50.mp3", "t": "络血之中，"}, {"f": "audio/f1/school-sch-nj-62__51.mp3", "t": "血泣不得注于大经，"}, {"f": "audio/f1/school-sch-nj-62__52.mp3", "t": "血气稽留不得行，"}, {"f": "audio/f1/school-sch-nj-62__53.mp3", "t": "故宿昔而成积矣。"}, {"f": "audio/f1/school-sch-nj-62__54.mp3", "t": "寒气客于五藏，"}, {"f": "audio/f1/school-sch-nj-62__55.mp3", "t": "厥逆上泄，"}, {"f": "audio/f1/school-sch-nj-62__56.mp3", "t": "阴气竭，"}, {"f": "audio/f1/school-sch-nj-62__57.mp3", "t": "阳气未入，"}, {"f": "audio/f1/school-sch-nj-62__58.mp3", "t": "故卒然痛死不知人，"}, {"f": "audio/f1/school-sch-nj-62__59.mp3", "t": "气复反则生矣。"}, {"f": "audio/f1/school-sch-nj-62__60.mp3", "t": "寒气客于肠胃，"}, {"f": "audio/f1/school-sch-nj-62__61.mp3", "t": "厥逆上出，"}, {"f": "audio/f1/school-sch-nj-62__62.mp3", "t": "故痛而呕也。"}, {"f": "audio/f1/school-sch-nj-62__63.mp3", "t": "寒气客于小肠，"}, {"f": "audio/f1/school-sch-nj-62__64.mp3", "t": "小肠不得成聚，"}, {"f": "audio/f1/school-sch-nj-62__65.mp3", "t": "故后泄腹痛矣。"}, {"f": "audio/f1/school-sch-nj-62__66.mp3", "t": "热气留于小肠，"}, {"f": "audio/f1/school-sch-nj-62__67.mp3", "t": "肠中痛、"}, {"f": "audio/f1/school-sch-nj-62__68.mp3", "t": "瘅热焦渴，"}, {"f": "audio/f1/school-sch-nj-62__69.mp3", "t": "则坚干不得出，"}, {"f": "audio/f1/school-sch-nj-62__70.mp3", "t": "故痛而闭不通矣。"}], "school-sch-nj-63": [{"f": "audio/c7/school-sch-nj-63__0.mp3", "t": "帝曰："}, {"f": "audio/c7/school-sch-nj-63__1.mp3", "t": "所谓言而可知者也，"}, {"f": "audio/c7/school-sch-nj-63__2.mp3", "t": "视而可见，"}, {"f": "audio/c7/school-sch-nj-63__3.mp3", "t": "奈何？"}, {"f": "audio/c7/school-sch-nj-63__4.mp3", "t": "岐伯曰："}, {"f": "audio/c7/school-sch-nj-63__5.mp3", "t": "五藏六府，"}, {"f": "audio/c7/school-sch-nj-63__6.mp3", "t": "固尽有部，"}, {"f": "audio/c7/school-sch-nj-63__7.mp3", "t": "视其五色，"}, {"f": "audio/c7/school-sch-nj-63__8.mp3", "t": "黄赤为热，"}, {"f": "audio/c7/school-sch-nj-63__9.mp3", "t": "白为寒，"}, {"f": "audio/c7/school-sch-nj-63__10.mp3", "t": "青黑为痛，"}, {"f": "audio/c7/school-sch-nj-63__11.mp3", "t": "此所谓视而可见者也。"}, {"f": "audio/c7/school-sch-nj-63__12.mp3", "t": "帝曰："}, {"f": "audio/c7/school-sch-nj-63__13.mp3", "t": "扪而可得奈何？"}, {"f": "audio/c7/school-sch-nj-63__14.mp3", "t": "岐伯曰："}, {"f": "audio/c7/school-sch-nj-63__15.mp3", "t": "视其主病之脉，"}, {"f": "audio/c7/school-sch-nj-63__16.mp3", "t": "坚而血及陷下者，"}, {"f": "audio/c7/school-sch-nj-63__17.mp3", "t": "皆可扪而得也。"}], "school-sch-nj-64": [{"f": "audio/f6/school-sch-nj-64__0.mp3", "t": "帝曰："}, {"f": "audio/f6/school-sch-nj-64__1.mp3", "t": "善。"}, {"f": "audio/f6/school-sch-nj-64__2.mp3", "t": "余知百病生于气也，"}, {"f": "audio/f6/school-sch-nj-64__3.mp3", "t": "怒则气上，"}, {"f": "audio/f6/school-sch-nj-64__4.mp3", "t": "喜则气缓，"}, {"f": "audio/f6/school-sch-nj-64__5.mp3", "t": "悲则气消，"}, {"f": "audio/f6/school-sch-nj-64__6.mp3", "t": "恐则气下，"}, {"f": "audio/f6/school-sch-nj-64__7.mp3", "t": "寒则气收，"}, {"f": "audio/f6/school-sch-nj-64__8.mp3", "t": "炅则气泄，"}, {"f": "audio/f6/school-sch-nj-64__9.mp3", "t": "惊则气乱，"}, {"f": "audio/f6/school-sch-nj-64__10.mp3", "t": "劳则气耗，"}, {"f": "audio/f6/school-sch-nj-64__11.mp3", "t": "思则气结，"}, {"f": "audio/f6/school-sch-nj-64__12.mp3", "t": "九气不同，"}, {"f": "audio/f6/school-sch-nj-64__13.mp3", "t": "何病之生？"}, {"f": "audio/f6/school-sch-nj-64__14.mp3", "t": "岐伯曰："}, {"f": "audio/f6/school-sch-nj-64__15.mp3", "t": "怒则气逆，"}, {"f": "audio/f6/school-sch-nj-64__16.mp3", "t": "甚则呕血及飧泄，"}, {"f": "audio/f6/school-sch-nj-64__17.mp3", "t": "故气上矣。"}, {"f": "audio/f6/school-sch-nj-64__18.mp3", "t": "喜则气和志达，"}, {"f": "audio/f6/school-sch-nj-64__19.mp3", "t": "荣卫通利，"}, {"f": "audio/f6/school-sch-nj-64__20.mp3", "t": "故气缓矣。"}, {"f": "audio/f6/school-sch-nj-64__21.mp3", "t": "悲则心系急，"}, {"f": "audio/f6/school-sch-nj-64__22.mp3", "t": "肺布叶举，"}, {"f": "audio/f6/school-sch-nj-64__23.mp3", "t": "而上焦不通，"}, {"f": "audio/f6/school-sch-nj-64__24.mp3", "t": "荣卫不散，"}, {"f": "audio/f6/school-sch-nj-64__25.mp3", "t": "热气在中，"}, {"f": "audio/f6/school-sch-nj-64__26.mp3", "t": "故气消矣。"}, {"f": "audio/f6/school-sch-nj-64__27.mp3", "t": "恐则精却，"}, {"f": "audio/f6/school-sch-nj-64__28.mp3", "t": "却则上焦闭，"}, {"f": "audio/f6/school-sch-nj-64__29.mp3", "t": "闭则气还，"}, {"f": "audio/f6/school-sch-nj-64__30.mp3", "t": "还则下焦胀，"}, {"f": "audio/f6/school-sch-nj-64__31.mp3", "t": "故气不行矣。"}, {"f": "audio/f6/school-sch-nj-64__32.mp3", "t": "寒则腠理闭，"}, {"f": "audio/f6/school-sch-nj-64__33.mp3", "t": "气不行，"}, {"f": "audio/f6/school-sch-nj-64__34.mp3", "t": "故气收矣。"}, {"f": "audio/f6/school-sch-nj-64__35.mp3", "t": "炅则腠理开，"}, {"f": "audio/f6/school-sch-nj-64__36.mp3", "t": "荣卫通，"}, {"f": "audio/f6/school-sch-nj-64__37.mp3", "t": "汗大泄，"}, {"f": "audio/f6/school-sch-nj-64__38.mp3", "t": "故气泄。"}, {"f": "audio/f6/school-sch-nj-64__39.mp3", "t": "惊则心无所倚，"}, {"f": "audio/f6/school-sch-nj-64__40.mp3", "t": "神无所归，"}, {"f": "audio/f6/school-sch-nj-64__41.mp3", "t": "虑无所定，"}, {"f": "audio/f6/school-sch-nj-64__42.mp3", "t": "故气乱矣。"}, {"f": "audio/f6/school-sch-nj-64__43.mp3", "t": "劳则喘息汗出，"}, {"f": "audio/f6/school-sch-nj-64__44.mp3", "t": "外内皆越，"}, {"f": "audio/f6/school-sch-nj-64__45.mp3", "t": "故气耗矣。"}, {"f": "audio/f6/school-sch-nj-64__46.mp3", "t": "思则心有所存，"}, {"f": "audio/f6/school-sch-nj-64__47.mp3", "t": "神有所归，"}, {"f": "audio/f6/school-sch-nj-64__48.mp3", "t": "正气留而不行，"}, {"f": "audio/f6/school-sch-nj-64__49.mp3", "t": "故气结矣。"}], "school-sch-nj-65": [{"f": "audio/2f/school-sch-nj-65__0.mp3", "t": "岐伯曰："}, {"f": "audio/2f/school-sch-nj-65__1.mp3", "t": "审察病机，"}, {"f": "audio/2f/school-sch-nj-65__2.mp3", "t": "无失气宜，"}, {"f": "audio/2f/school-sch-nj-65__3.mp3", "t": "此之谓也。"}], "school-sch-nj-66": [{"f": "audio/d8/school-sch-nj-66__0.mp3", "t": "帝曰："}, {"f": "audio/d8/school-sch-nj-66__1.mp3", "t": "愿闻病机何如？"}, {"f": "audio/d8/school-sch-nj-66__2.mp3", "t": "岐伯曰："}, {"f": "audio/d8/school-sch-nj-66__3.mp3", "t": "诸风掉眩，"}, {"f": "audio/d8/school-sch-nj-66__4.mp3", "t": "皆属于肝；"}, {"f": "audio/d8/school-sch-nj-66__5.mp3", "t": "诸寒收引，"}, {"f": "audio/d8/school-sch-nj-66__6.mp3", "t": "皆属于肾；"}, {"f": "audio/d8/school-sch-nj-66__7.mp3", "t": "诸气膹郁，"}, {"f": "audio/d8/school-sch-nj-66__8.mp3", "t": "皆属于肺；"}, {"f": "audio/d8/school-sch-nj-66__9.mp3", "t": "诸湿肿满，"}, {"f": "audio/d8/school-sch-nj-66__10.mp3", "t": "皆属于脾；"}, {"f": "audio/d8/school-sch-nj-66__11.mp3", "t": "诸热瞀瘛，"}, {"f": "audio/d8/school-sch-nj-66__12.mp3", "t": "皆属于火；"}, {"f": "audio/d8/school-sch-nj-66__13.mp3", "t": "诸痛痒疮，"}, {"f": "audio/d8/school-sch-nj-66__14.mp3", "t": "皆属于心；"}, {"f": "audio/d8/school-sch-nj-66__15.mp3", "t": "诸厥固泄，"}, {"f": "audio/d8/school-sch-nj-66__16.mp3", "t": "皆属于下；"}, {"f": "audio/d8/school-sch-nj-66__17.mp3", "t": "诸痿喘呕，"}, {"f": "audio/d8/school-sch-nj-66__18.mp3", "t": "皆属于上；"}, {"f": "audio/d8/school-sch-nj-66__19.mp3", "t": "诸禁鼓栗，"}, {"f": "audio/d8/school-sch-nj-66__20.mp3", "t": "如丧神守，"}, {"f": "audio/d8/school-sch-nj-66__21.mp3", "t": "皆属于火；"}, {"f": "audio/d8/school-sch-nj-66__22.mp3", "t": "诸痉项强，"}, {"f": "audio/d8/school-sch-nj-66__23.mp3", "t": "皆属于湿；"}, {"f": "audio/d8/school-sch-nj-66__24.mp3", "t": "诸逆冲上，"}, {"f": "audio/d8/school-sch-nj-66__25.mp3", "t": "皆属于火；"}, {"f": "audio/d8/school-sch-nj-66__26.mp3", "t": "诸胀腹大，"}, {"f": "audio/d8/school-sch-nj-66__27.mp3", "t": "皆属于热；"}, {"f": "audio/d8/school-sch-nj-66__28.mp3", "t": "诸躁狂越，"}, {"f": "audio/d8/school-sch-nj-66__29.mp3", "t": "皆属于火；"}, {"f": "audio/d8/school-sch-nj-66__30.mp3", "t": "诸暴强直，"}, {"f": "audio/d8/school-sch-nj-66__31.mp3", "t": "皆属于风；"}, {"f": "audio/d8/school-sch-nj-66__32.mp3", "t": "诸病有声，"}, {"f": "audio/d8/school-sch-nj-66__33.mp3", "t": "鼓之如鼓，"}, {"f": "audio/d8/school-sch-nj-66__34.mp3", "t": "皆属于热；"}, {"f": "audio/d8/school-sch-nj-66__35.mp3", "t": "诸病胕肿，"}, {"f": "audio/d8/school-sch-nj-66__36.mp3", "t": "疼酸惊骇，"}, {"f": "audio/d8/school-sch-nj-66__37.mp3", "t": "皆属于火；"}, {"f": "audio/d8/school-sch-nj-66__38.mp3", "t": "诸转反戾，"}, {"f": "audio/d8/school-sch-nj-66__39.mp3", "t": "水液浑浊，"}, {"f": "audio/d8/school-sch-nj-66__40.mp3", "t": "皆属于热；"}, {"f": "audio/d8/school-sch-nj-66__41.mp3", "t": "诸病水液，"}, {"f": "audio/d8/school-sch-nj-66__42.mp3", "t": "澄澈清冷，"}, {"f": "audio/d8/school-sch-nj-66__43.mp3", "t": "皆属于寒；"}, {"f": "audio/d8/school-sch-nj-66__44.mp3", "t": "诸呕吐酸，"}, {"f": "audio/d8/school-sch-nj-66__45.mp3", "t": "暴注下迫，"}, {"f": "audio/d8/school-sch-nj-66__46.mp3", "t": "皆属于热。"}, {"f": "audio/d8/school-sch-nj-66__47.mp3", "t": "故《大要》曰："}, {"f": "audio/d8/school-sch-nj-66__48.mp3", "t": "谨守病机，"}, {"f": "audio/d8/school-sch-nj-66__49.mp3", "t": "各司其属，"}, {"f": "audio/d8/school-sch-nj-66__50.mp3", "t": "有者求之，"}, {"f": "audio/d8/school-sch-nj-66__51.mp3", "t": "无者求之，"}, {"f": "audio/d8/school-sch-nj-66__52.mp3", "t": "盛者责之，"}, {"f": "audio/d8/school-sch-nj-66__53.mp3", "t": "虚者责之，"}, {"f": "audio/d8/school-sch-nj-66__54.mp3", "t": "必先五藏，"}, {"f": "audio/d8/school-sch-nj-66__55.mp3", "t": "疏其血气，"}, {"f": "audio/d8/school-sch-nj-66__56.mp3", "t": "令其调达，"}, {"f": "audio/d8/school-sch-nj-66__57.mp3", "t": "而致和平，"}, {"f": "audio/d8/school-sch-nj-66__58.mp3", "t": "此之谓也。"}], "school-sch-nj-67": [{"f": "audio/4c/school-sch-nj-67__0.mp3", "t": "帝曰："}, {"f": "audio/4c/school-sch-nj-67__1.mp3", "t": "何谓逆从？"}, {"f": "audio/4c/school-sch-nj-67__2.mp3", "t": "岐伯曰："}, {"f": "audio/4c/school-sch-nj-67__3.mp3", "t": "逆者正治，"}, {"f": "audio/4c/school-sch-nj-67__4.mp3", "t": "从者反治，"}, {"f": "audio/4c/school-sch-nj-67__5.mp3", "t": "从少从多，"}, {"f": "audio/4c/school-sch-nj-67__6.mp3", "t": "观其事也。"}, {"f": "audio/4c/school-sch-nj-67__7.mp3", "t": "帝曰："}, {"f": "audio/4c/school-sch-nj-67__8.mp3", "t": "反治何谓？"}, {"f": "audio/4c/school-sch-nj-67__9.mp3", "t": "岐伯曰："}, {"f": "audio/4c/school-sch-nj-67__10.mp3", "t": "热因寒用，"}, {"f": "audio/4c/school-sch-nj-67__11.mp3", "t": "寒因热用，"}, {"f": "audio/4c/school-sch-nj-67__12.mp3", "t": "塞因塞用，"}, {"f": "audio/4c/school-sch-nj-67__13.mp3", "t": "通因通用，"}, {"f": "audio/4c/school-sch-nj-67__14.mp3", "t": "必伏其所主，"}, {"f": "audio/4c/school-sch-nj-67__15.mp3", "t": "而先其所因，"}, {"f": "audio/4c/school-sch-nj-67__16.mp3", "t": "其始则同，"}, {"f": "audio/4c/school-sch-nj-67__17.mp3", "t": "其终则异，"}, {"f": "audio/4c/school-sch-nj-67__18.mp3", "t": "可使破积，"}, {"f": "audio/4c/school-sch-nj-67__19.mp3", "t": "可使气和，"}, {"f": "audio/4c/school-sch-nj-67__20.mp3", "t": "可使必已。"}, {"f": "audio/4c/school-sch-nj-67__21.mp3", "t": "帝曰："}, {"f": "audio/4c/school-sch-nj-67__22.mp3", "t": "善。"}, {"f": "audio/4c/school-sch-nj-67__23.mp3", "t": "气调而得者，"}, {"f": "audio/4c/school-sch-nj-67__24.mp3", "t": "何如？"}, {"f": "audio/4c/school-sch-nj-67__25.mp3", "t": "岐伯曰："}, {"f": "audio/4c/school-sch-nj-67__26.mp3", "t": "逆之，"}, {"f": "audio/4c/school-sch-nj-67__27.mp3", "t": "从之，"}, {"f": "audio/4c/school-sch-nj-67__28.mp3", "t": "逆而从之，"}, {"f": "audio/4c/school-sch-nj-67__29.mp3", "t": "从而逆之，"}, {"f": "audio/4c/school-sch-nj-67__30.mp3", "t": "疏气令调，"}, {"f": "audio/4c/school-sch-nj-67__31.mp3", "t": "则其道也。"}], "school-sch-nj-68": [{"f": "audio/3e/school-sch-nj-68__0.mp3", "t": "帝曰："}, {"f": "audio/3e/school-sch-nj-68__1.mp3", "t": "论言治寒以热，"}, {"f": "audio/3e/school-sch-nj-68__2.mp3", "t": "治热以寒，"}, {"f": "audio/3e/school-sch-nj-68__3.mp3", "t": "而方士不能废绳墨而更其道也。"}, {"f": "audio/3e/school-sch-nj-68__4.mp3", "t": "有病热者，"}, {"f": "audio/3e/school-sch-nj-68__5.mp3", "t": "寒之而热；"}, {"f": "audio/3e/school-sch-nj-68__6.mp3", "t": "有病寒者，"}, {"f": "audio/3e/school-sch-nj-68__7.mp3", "t": "热之而寒。"}, {"f": "audio/3e/school-sch-nj-68__8.mp3", "t": "二者皆在，"}, {"f": "audio/3e/school-sch-nj-68__9.mp3", "t": "新病复起，"}, {"f": "audio/3e/school-sch-nj-68__10.mp3", "t": "奈何治？"}, {"f": "audio/3e/school-sch-nj-68__11.mp3", "t": "岐伯曰："}, {"f": "audio/3e/school-sch-nj-68__12.mp3", "t": "诸寒之而热者取之阴，"}, {"f": "audio/3e/school-sch-nj-68__13.mp3", "t": "热之而寒者取之阳，"}, {"f": "audio/3e/school-sch-nj-68__14.mp3", "t": "所谓求其属也。"}], "school-sch-nj-69": [{"f": "audio/e8/school-sch-nj-69__0.mp3", "t": "黄帝问曰："}, {"f": "audio/e8/school-sch-nj-69__1.mp3", "t": "余闻《刺法》言，"}, {"f": "audio/e8/school-sch-nj-69__2.mp3", "t": "有余泻之，"}, {"f": "audio/e8/school-sch-nj-69__3.mp3", "t": "不足补之。"}, {"f": "audio/e8/school-sch-nj-69__4.mp3", "t": "何谓有余，"}, {"f": "audio/e8/school-sch-nj-69__5.mp3", "t": "何谓不足？"}, {"f": "audio/e8/school-sch-nj-69__6.mp3", "t": "岐伯对曰："}, {"f": "audio/e8/school-sch-nj-69__7.mp3", "t": "有余有五，"}, {"f": "audio/e8/school-sch-nj-69__8.mp3", "t": "不足亦有五。"}, {"f": "audio/e8/school-sch-nj-69__9.mp3", "t": "帝欲何问？"}, {"f": "audio/e8/school-sch-nj-69__10.mp3", "t": "帝曰："}, {"f": "audio/e8/school-sch-nj-69__11.mp3", "t": "愿尽闻之。"}, {"f": "audio/e8/school-sch-nj-69__12.mp3", "t": "岐伯曰："}, {"f": "audio/e8/school-sch-nj-69__13.mp3", "t": "神有余有不足；"}, {"f": "audio/e8/school-sch-nj-69__14.mp3", "t": "气有余有不足，"}, {"f": "audio/e8/school-sch-nj-69__15.mp3", "t": "血有余有不足，"}, {"f": "audio/e8/school-sch-nj-69__16.mp3", "t": "形有余有不足，"}, {"f": "audio/e8/school-sch-nj-69__17.mp3", "t": "志有余有不足。"}, {"f": "audio/e8/school-sch-nj-69__18.mp3", "t": "凡此十者，"}, {"f": "audio/e8/school-sch-nj-69__19.mp3", "t": "其气不等也。"}, {"f": "audio/e8/school-sch-nj-69__20.mp3", "t": "帝曰："}, {"f": "audio/e8/school-sch-nj-69__21.mp3", "t": "人有精气、"}, {"f": "audio/e8/school-sch-nj-69__22.mp3", "t": "津液，"}, {"f": "audio/e8/school-sch-nj-69__23.mp3", "t": "四支、"}, {"f": "audio/e8/school-sch-nj-69__24.mp3", "t": "九窍、"}, {"f": "audio/e8/school-sch-nj-69__25.mp3", "t": "五藏、"}, {"f": "audio/e8/school-sch-nj-69__26.mp3", "t": "十六部、"}, {"f": "audio/e8/school-sch-nj-69__27.mp3", "t": "三百六十五节，"}, {"f": "audio/e8/school-sch-nj-69__28.mp3", "t": "乃生百病。"}, {"f": "audio/e8/school-sch-nj-69__29.mp3", "t": "百病之生，"}, {"f": "audio/e8/school-sch-nj-69__30.mp3", "t": "皆有虚实。"}, {"f": "audio/e8/school-sch-nj-69__31.mp3", "t": "今夫子乃言有余有五，"}, {"f": "audio/e8/school-sch-nj-69__32.mp3", "t": "不足亦有五，"}, {"f": "audio/e8/school-sch-nj-69__33.mp3", "t": "何以生之乎？"}, {"f": "audio/e8/school-sch-nj-69__34.mp3", "t": "岐伯曰："}, {"f": "audio/e8/school-sch-nj-69__35.mp3", "t": "皆生于五藏也。"}, {"f": "audio/e8/school-sch-nj-69__36.mp3", "t": "夫心藏神，"}, {"f": "audio/e8/school-sch-nj-69__37.mp3", "t": "肺藏气，"}, {"f": "audio/e8/school-sch-nj-69__38.mp3", "t": "肝藏血，"}, {"f": "audio/e8/school-sch-nj-69__39.mp3", "t": "脾藏肉，"}, {"f": "audio/e8/school-sch-nj-69__40.mp3", "t": "肾藏志，"}, {"f": "audio/e8/school-sch-nj-69__41.mp3", "t": "而此成形。"}, {"f": "audio/e8/school-sch-nj-69__42.mp3", "t": "志意通，"}, {"f": "audio/e8/school-sch-nj-69__43.mp3", "t": "内连骨髓，"}, {"f": "audio/e8/school-sch-nj-69__44.mp3", "t": "而成身形五藏。"}, {"f": "audio/e8/school-sch-nj-69__45.mp3", "t": "五藏之道，"}, {"f": "audio/e8/school-sch-nj-69__46.mp3", "t": "皆出于经隧，"}, {"f": "audio/e8/school-sch-nj-69__47.mp3", "t": "以行血气，"}, {"f": "audio/e8/school-sch-nj-69__48.mp3", "t": "血气不和，"}, {"f": "audio/e8/school-sch-nj-69__49.mp3", "t": "百病乃变化而生，"}, {"f": "audio/e8/school-sch-nj-69__50.mp3", "t": "是故守经隧焉。"}], "school-sch-nj-70": [{"f": "audio/2f/school-sch-nj-70__0.mp3", "t": "帝曰："}, {"f": "audio/2f/school-sch-nj-70__1.mp3", "t": "经言阳虚则外寒，"}, {"f": "audio/2f/school-sch-nj-70__2.mp3", "t": "阴虚则内热，"}, {"f": "audio/2f/school-sch-nj-70__3.mp3", "t": "阳盛则外热，"}, {"f": "audio/2f/school-sch-nj-70__4.mp3", "t": "阴盛则内寒，"}, {"f": "audio/2f/school-sch-nj-70__5.mp3", "t": "余已闻之矣，"}, {"f": "audio/2f/school-sch-nj-70__6.mp3", "t": "不知其所由然也。"}, {"f": "audio/2f/school-sch-nj-70__7.mp3", "t": "岐伯曰："}, {"f": "audio/2f/school-sch-nj-70__8.mp3", "t": "阳受气于上焦，"}, {"f": "audio/2f/school-sch-nj-70__9.mp3", "t": "以温皮肤分肉之间。"}, {"f": "audio/2f/school-sch-nj-70__10.mp3", "t": "令寒气在外，"}, {"f": "audio/2f/school-sch-nj-70__11.mp3", "t": "则上焦不通，"}, {"f": "audio/2f/school-sch-nj-70__12.mp3", "t": "上焦不通，"}, {"f": "audio/2f/school-sch-nj-70__13.mp3", "t": "则寒气独留于外，"}, {"f": "audio/2f/school-sch-nj-70__14.mp3", "t": "故寒栗。"}, {"f": "audio/2f/school-sch-nj-70__15.mp3", "t": "帝曰："}, {"f": "audio/2f/school-sch-nj-70__16.mp3", "t": "阴虚生内热奈何？"}, {"f": "audio/2f/school-sch-nj-70__17.mp3", "t": "岐伯曰："}, {"f": "audio/2f/school-sch-nj-70__18.mp3", "t": "有所劳倦，"}, {"f": "audio/2f/school-sch-nj-70__19.mp3", "t": "形气衰少，"}, {"f": "audio/2f/school-sch-nj-70__20.mp3", "t": "谷气不盛，"}, {"f": "audio/2f/school-sch-nj-70__21.mp3", "t": "上焦不行，"}, {"f": "audio/2f/school-sch-nj-70__22.mp3", "t": "下脘不通，"}, {"f": "audio/2f/school-sch-nj-70__23.mp3", "t": "胃气热，"}, {"f": "audio/2f/school-sch-nj-70__24.mp3", "t": "热气熏胸中，"}, {"f": "audio/2f/school-sch-nj-70__25.mp3", "t": "故内热。"}, {"f": "audio/2f/school-sch-nj-70__26.mp3", "t": "帝曰："}, {"f": "audio/2f/school-sch-nj-70__27.mp3", "t": "阳盛生外热奈何？"}, {"f": "audio/2f/school-sch-nj-70__28.mp3", "t": "岐伯曰："}, {"f": "audio/2f/school-sch-nj-70__29.mp3", "t": "上焦不通利，"}, {"f": "audio/2f/school-sch-nj-70__30.mp3", "t": "则皮肤致密，"}, {"f": "audio/2f/school-sch-nj-70__31.mp3", "t": "腠理闭塞，"}, {"f": "audio/2f/school-sch-nj-70__32.mp3", "t": "玄府不通，"}, {"f": "audio/2f/school-sch-nj-70__33.mp3", "t": "卫气不得泄越，"}, {"f": "audio/2f/school-sch-nj-70__34.mp3", "t": "故外热。"}, {"f": "audio/2f/school-sch-nj-70__35.mp3", "t": "帝曰："}, {"f": "audio/2f/school-sch-nj-70__36.mp3", "t": "阴盛生内寒奈何？"}, {"f": "audio/2f/school-sch-nj-70__37.mp3", "t": "岐伯曰："}, {"f": "audio/2f/school-sch-nj-70__38.mp3", "t": "厥气上逆，"}, {"f": "audio/2f/school-sch-nj-70__39.mp3", "t": "寒气积于胃中而不写，"}, {"f": "audio/2f/school-sch-nj-70__40.mp3", "t": "不写则温气去，"}, {"f": "audio/2f/school-sch-nj-70__41.mp3", "t": "寒独留，"}, {"f": "audio/2f/school-sch-nj-70__42.mp3", "t": "则血凝泣，"}, {"f": "audio/2f/school-sch-nj-70__43.mp3", "t": "凝则脉不通，"}, {"f": "audio/2f/school-sch-nj-70__44.mp3", "t": "其脉盛大以涩，"}, {"f": "audio/2f/school-sch-nj-70__45.mp3", "t": "故中寒。"}], "school-sch-nj-71": [{"f": "audio/a8/school-sch-nj-71__0.mp3", "t": "黄帝问曰："}, {"f": "audio/a8/school-sch-nj-71__1.mp3", "t": "今夫热病者，"}, {"f": "audio/a8/school-sch-nj-71__2.mp3", "t": "皆伤寒之类也，"}, {"f": "audio/a8/school-sch-nj-71__3.mp3", "t": "或愈或死，"}, {"f": "audio/a8/school-sch-nj-71__4.mp3", "t": "其死皆以六七日之间，"}, {"f": "audio/a8/school-sch-nj-71__5.mp3", "t": "其愈皆以十日以上者，"}, {"f": "audio/a8/school-sch-nj-71__6.mp3", "t": "何也？"}, {"f": "audio/a8/school-sch-nj-71__7.mp3", "t": "不知其解，"}, {"f": "audio/a8/school-sch-nj-71__8.mp3", "t": "愿闻其故。"}], "school-sch-nj-72": [{"f": "audio/0d/school-sch-nj-72__0.mp3", "t": "岐伯对曰："}, {"f": "audio/0d/school-sch-nj-72__1.mp3", "t": "巨阳者，"}, {"f": "audio/0d/school-sch-nj-72__2.mp3", "t": "诸阳之属也。"}, {"f": "audio/0d/school-sch-nj-72__3.mp3", "t": "其脉连于风府，"}, {"f": "audio/0d/school-sch-nj-72__4.mp3", "t": "故为诸阳主气也。"}, {"f": "audio/0d/school-sch-nj-72__5.mp3", "t": "人之伤于寒也，"}, {"f": "audio/0d/school-sch-nj-72__6.mp3", "t": "则为病热，"}, {"f": "audio/0d/school-sch-nj-72__7.mp3", "t": "热虽甚不死，"}, {"f": "audio/0d/school-sch-nj-72__8.mp3", "t": "其两感于寒而病者，"}, {"f": "audio/0d/school-sch-nj-72__9.mp3", "t": "必不免于死。"}], "school-sch-nj-73": [{"f": "audio/56/school-sch-nj-73__0.mp3", "t": "帝曰："}, {"f": "audio/56/school-sch-nj-73__1.mp3", "t": "愿闻其状。"}, {"f": "audio/56/school-sch-nj-73__2.mp3", "t": "岐伯曰："}, {"f": "audio/56/school-sch-nj-73__3.mp3", "t": "伤寒一日，"}, {"f": "audio/56/school-sch-nj-73__4.mp3", "t": "巨阳受之，"}, {"f": "audio/56/school-sch-nj-73__5.mp3", "t": "故头项痛，"}, {"f": "audio/56/school-sch-nj-73__6.mp3", "t": "腰脊强。"}, {"f": "audio/56/school-sch-nj-73__7.mp3", "t": "二日，"}, {"f": "audio/56/school-sch-nj-73__8.mp3", "t": "阳明受之，"}, {"f": "audio/56/school-sch-nj-73__9.mp3", "t": "阳明主肉，"}, {"f": "audio/56/school-sch-nj-73__10.mp3", "t": "其脉挟鼻络于目，"}, {"f": "audio/56/school-sch-nj-73__11.mp3", "t": "故身热目疼而鼻干，"}, {"f": "audio/56/school-sch-nj-73__12.mp3", "t": "不得卧也。"}, {"f": "audio/56/school-sch-nj-73__13.mp3", "t": "三日，"}, {"f": "audio/56/school-sch-nj-73__14.mp3", "t": "少阳受之，"}, {"f": "audio/56/school-sch-nj-73__15.mp3", "t": "少阳主胆，"}, {"f": "audio/56/school-sch-nj-73__16.mp3", "t": "其脉循胁络于耳，"}, {"f": "audio/56/school-sch-nj-73__17.mp3", "t": "故胸胁痛而耳聋。"}, {"f": "audio/56/school-sch-nj-73__18.mp3", "t": "三阳经络皆受其病，"}, {"f": "audio/56/school-sch-nj-73__19.mp3", "t": "而未入于藏者，"}, {"f": "audio/56/school-sch-nj-73__20.mp3", "t": "故可汗而已。"}, {"f": "audio/56/school-sch-nj-73__21.mp3", "t": "四日，"}, {"f": "audio/56/school-sch-nj-73__22.mp3", "t": "太阴受之，"}, {"f": "audio/56/school-sch-nj-73__23.mp3", "t": "太阴脉布胃中络于嗌，"}, {"f": "audio/56/school-sch-nj-73__24.mp3", "t": "故腹满而嗌干。"}, {"f": "audio/56/school-sch-nj-73__25.mp3", "t": "五日，"}, {"f": "audio/56/school-sch-nj-73__26.mp3", "t": "少阴受之，"}, {"f": "audio/56/school-sch-nj-73__27.mp3", "t": "少阴脉贯脊络于肺，"}, {"f": "audio/56/school-sch-nj-73__28.mp3", "t": "系舌本，"}, {"f": "audio/56/school-sch-nj-73__29.mp3", "t": "故口燥舌干而渴。"}, {"f": "audio/56/school-sch-nj-73__30.mp3", "t": "六日，"}, {"f": "audio/56/school-sch-nj-73__31.mp3", "t": "厥阴受之，"}, {"f": "audio/56/school-sch-nj-73__32.mp3", "t": "厥阴脉循阴器而络于肝，"}, {"f": "audio/56/school-sch-nj-73__33.mp3", "t": "故烦满而囊缩。"}, {"f": "audio/56/school-sch-nj-73__34.mp3", "t": "三阴三阳，"}, {"f": "audio/56/school-sch-nj-73__35.mp3", "t": "五藏六府皆受病，"}, {"f": "audio/56/school-sch-nj-73__36.mp3", "t": "营卫不行，"}, {"f": "audio/56/school-sch-nj-73__37.mp3", "t": "五藏不通，"}, {"f": "audio/56/school-sch-nj-73__38.mp3", "t": "则死矣。"}], "school-sch-nj-74": [{"f": "audio/72/school-sch-nj-74__0.mp3", "t": "其不两感于寒者，"}, {"f": "audio/72/school-sch-nj-74__1.mp3", "t": "七日，"}, {"f": "audio/72/school-sch-nj-74__2.mp3", "t": "巨阳病衰，"}, {"f": "audio/72/school-sch-nj-74__3.mp3", "t": "头痛少愈。"}, {"f": "audio/72/school-sch-nj-74__4.mp3", "t": "八日，"}, {"f": "audio/72/school-sch-nj-74__5.mp3", "t": "阳明病衰，"}, {"f": "audio/72/school-sch-nj-74__6.mp3", "t": "身热少愈。"}, {"f": "audio/72/school-sch-nj-74__7.mp3", "t": "九日，"}, {"f": "audio/72/school-sch-nj-74__8.mp3", "t": "少阳病衰，"}, {"f": "audio/72/school-sch-nj-74__9.mp3", "t": "耳聋微闻。"}, {"f": "audio/72/school-sch-nj-74__10.mp3", "t": "十日，"}, {"f": "audio/72/school-sch-nj-74__11.mp3", "t": "太阴病衰，"}, {"f": "audio/72/school-sch-nj-74__12.mp3", "t": "腹减如故，"}, {"f": "audio/72/school-sch-nj-74__13.mp3", "t": "则思饮食。"}, {"f": "audio/72/school-sch-nj-74__14.mp3", "t": "十一日，"}, {"f": "audio/72/school-sch-nj-74__15.mp3", "t": "少阴病衰，"}, {"f": "audio/72/school-sch-nj-74__16.mp3", "t": "渴止，"}, {"f": "audio/72/school-sch-nj-74__17.mp3", "t": "满，"}, {"f": "audio/72/school-sch-nj-74__18.mp3", "t": "舌干已而嚏。"}, {"f": "audio/72/school-sch-nj-74__19.mp3", "t": "十二日，"}, {"f": "audio/72/school-sch-nj-74__20.mp3", "t": "厥阴病衰，"}, {"f": "audio/72/school-sch-nj-74__21.mp3", "t": "囊纵，"}, {"f": "audio/72/school-sch-nj-74__22.mp3", "t": "少腹微下，"}, {"f": "audio/72/school-sch-nj-74__23.mp3", "t": "大气皆去，"}, {"f": "audio/72/school-sch-nj-74__24.mp3", "t": "病日已矣。"}], "school-sch-nj-75": [{"f": "audio/e5/school-sch-nj-75__0.mp3", "t": "帝曰："}, {"f": "audio/e5/school-sch-nj-75__1.mp3", "t": "治之奈何？"}, {"f": "audio/e5/school-sch-nj-75__2.mp3", "t": "岐伯曰："}, {"f": "audio/e5/school-sch-nj-75__3.mp3", "t": "治之各通其藏脉，"}, {"f": "audio/e5/school-sch-nj-75__4.mp3", "t": "病日衰已矣。"}, {"f": "audio/e5/school-sch-nj-75__5.mp3", "t": "其未满三日者，"}, {"f": "audio/e5/school-sch-nj-75__6.mp3", "t": "可汗而已；"}, {"f": "audio/e5/school-sch-nj-75__7.mp3", "t": "其满三日者，"}, {"f": "audio/e5/school-sch-nj-75__8.mp3", "t": "可泄而已。"}], "school-sch-nj-76": [{"f": "audio/cf/school-sch-nj-76__0.mp3", "t": "帝曰："}, {"f": "audio/cf/school-sch-nj-76__1.mp3", "t": "热病已愈，"}, {"f": "audio/cf/school-sch-nj-76__2.mp3", "t": "时有所遗者，"}, {"f": "audio/cf/school-sch-nj-76__3.mp3", "t": "何也？"}, {"f": "audio/cf/school-sch-nj-76__4.mp3", "t": "岐伯曰："}, {"f": "audio/cf/school-sch-nj-76__5.mp3", "t": "诸遗者，"}, {"f": "audio/cf/school-sch-nj-76__6.mp3", "t": "热甚而强食之，"}, {"f": "audio/cf/school-sch-nj-76__7.mp3", "t": "故有所遗也。"}, {"f": "audio/cf/school-sch-nj-76__8.mp3", "t": "若此者，"}, {"f": "audio/cf/school-sch-nj-76__9.mp3", "t": "皆病已衰而热有所藏，"}, {"f": "audio/cf/school-sch-nj-76__10.mp3", "t": "因其谷气相薄，"}, {"f": "audio/cf/school-sch-nj-76__11.mp3", "t": "两热相合，"}, {"f": "audio/cf/school-sch-nj-76__12.mp3", "t": "故有所遗也。"}, {"f": "audio/cf/school-sch-nj-76__13.mp3", "t": "帝曰："}, {"f": "audio/cf/school-sch-nj-76__14.mp3", "t": "善。"}, {"f": "audio/cf/school-sch-nj-76__15.mp3", "t": "治遗奈何？"}, {"f": "audio/cf/school-sch-nj-76__16.mp3", "t": "岐伯曰："}, {"f": "audio/cf/school-sch-nj-76__17.mp3", "t": "视其虚实，"}, {"f": "audio/cf/school-sch-nj-76__18.mp3", "t": "调其逆从，"}, {"f": "audio/cf/school-sch-nj-76__19.mp3", "t": "可使必已矣。"}, {"f": "audio/cf/school-sch-nj-76__20.mp3", "t": "帝曰："}, {"f": "audio/cf/school-sch-nj-76__21.mp3", "t": "病热当何禁之？"}, {"f": "audio/cf/school-sch-nj-76__22.mp3", "t": "岐伯曰："}, {"f": "audio/cf/school-sch-nj-76__23.mp3", "t": "病热少愈，"}, {"f": "audio/cf/school-sch-nj-76__24.mp3", "t": "食肉则复，"}, {"f": "audio/cf/school-sch-nj-76__25.mp3", "t": "多食则遗，"}, {"f": "audio/cf/school-sch-nj-76__26.mp3", "t": "此其禁也。"}], "school-sch-nj-77": [{"f": "audio/23/school-sch-nj-77__0.mp3", "t": "帝曰："}, {"f": "audio/23/school-sch-nj-77__1.mp3", "t": "其病两感于寒者，"}, {"f": "audio/23/school-sch-nj-77__2.mp3", "t": "其脉应与其病形何如？"}, {"f": "audio/23/school-sch-nj-77__3.mp3", "t": "岐伯曰："}, {"f": "audio/23/school-sch-nj-77__4.mp3", "t": "两感于寒者，"}, {"f": "audio/23/school-sch-nj-77__5.mp3", "t": "病一日，"}, {"f": "audio/23/school-sch-nj-77__6.mp3", "t": "则巨阳与少阴俱病，"}, {"f": "audio/23/school-sch-nj-77__7.mp3", "t": "则头痛口干而烦满。"}, {"f": "audio/23/school-sch-nj-77__8.mp3", "t": "二日，"}, {"f": "audio/23/school-sch-nj-77__9.mp3", "t": "则阳明与太阴俱病，"}, {"f": "audio/23/school-sch-nj-77__10.mp3", "t": "则腹满身热，"}, {"f": "audio/23/school-sch-nj-77__11.mp3", "t": "不欲食，"}, {"f": "audio/23/school-sch-nj-77__12.mp3", "t": "谵言；"}, {"f": "audio/23/school-sch-nj-77__13.mp3", "t": "三日，"}, {"f": "audio/23/school-sch-nj-77__14.mp3", "t": "则少阳与厥阴俱病，"}, {"f": "audio/23/school-sch-nj-77__15.mp3", "t": "则耳聋囊缩而厥、"}, {"f": "audio/23/school-sch-nj-77__16.mp3", "t": "水浆不入、"}, {"f": "audio/23/school-sch-nj-77__17.mp3", "t": "不知人，"}, {"f": "audio/23/school-sch-nj-77__18.mp3", "t": "六日死。"}, {"f": "audio/23/school-sch-nj-77__19.mp3", "t": "帝曰："}, {"f": "audio/23/school-sch-nj-77__20.mp3", "t": "五藏已伤，"}, {"f": "audio/23/school-sch-nj-77__21.mp3", "t": "六府不通，"}, {"f": "audio/23/school-sch-nj-77__22.mp3", "t": "荣卫不行，"}, {"f": "audio/23/school-sch-nj-77__23.mp3", "t": "如是之后，"}, {"f": "audio/23/school-sch-nj-77__24.mp3", "t": "三日乃死，"}, {"f": "audio/23/school-sch-nj-77__25.mp3", "t": "何也？"}, {"f": "audio/23/school-sch-nj-77__26.mp3", "t": "岐伯曰："}, {"f": "audio/23/school-sch-nj-77__27.mp3", "t": "阳明者，"}, {"f": "audio/23/school-sch-nj-77__28.mp3", "t": "十二经脉之长也，"}, {"f": "audio/23/school-sch-nj-77__29.mp3", "t": "其血气盛，"}, {"f": "audio/23/school-sch-nj-77__30.mp3", "t": "故不知人。"}, {"f": "audio/23/school-sch-nj-77__31.mp3", "t": "三日，"}, {"f": "audio/23/school-sch-nj-77__32.mp3", "t": "其气乃尽，"}, {"f": "audio/23/school-sch-nj-77__33.mp3", "t": "故死矣。"}], "school-sch-nj-78": [{"f": "audio/3e/school-sch-nj-78__0.mp3", "t": "凡病伤寒而成温者，"}, {"f": "audio/3e/school-sch-nj-78__1.mp3", "t": "先夏至日者为病温，"}, {"f": "audio/3e/school-sch-nj-78__2.mp3", "t": "后夏至日者为病暑，"}, {"f": "audio/3e/school-sch-nj-78__3.mp3", "t": "暑当与汗皆出，"}, {"f": "audio/3e/school-sch-nj-78__4.mp3", "t": "勿止。"}], "school-sch-nj-79": [{"f": "audio/26/school-sch-nj-79__0.mp3", "t": "黄帝问曰："}, {"f": "audio/26/school-sch-nj-79__1.mp3", "t": "有病温者，"}, {"f": "audio/26/school-sch-nj-79__2.mp3", "t": "汗出辄复热，"}, {"f": "audio/26/school-sch-nj-79__3.mp3", "t": "而脉躁疾不为汗衰，"}, {"f": "audio/26/school-sch-nj-79__4.mp3", "t": "狂言不能食，"}, {"f": "audio/26/school-sch-nj-79__5.mp3", "t": "病名为何？"}, {"f": "audio/26/school-sch-nj-79__6.mp3", "t": "岐伯对曰："}, {"f": "audio/26/school-sch-nj-79__7.mp3", "t": "病名阴阳交，"}, {"f": "audio/26/school-sch-nj-79__8.mp3", "t": "交者，"}, {"f": "audio/26/school-sch-nj-79__9.mp3", "t": "死也。"}, {"f": "audio/26/school-sch-nj-79__10.mp3", "t": "帝曰："}, {"f": "audio/26/school-sch-nj-79__11.mp3", "t": "愿闻其说。"}, {"f": "audio/26/school-sch-nj-79__12.mp3", "t": "岐伯曰："}, {"f": "audio/26/school-sch-nj-79__13.mp3", "t": "人所以汗出者，"}, {"f": "audio/26/school-sch-nj-79__14.mp3", "t": "皆生于谷，"}, {"f": "audio/26/school-sch-nj-79__15.mp3", "t": "谷生于精，"}, {"f": "audio/26/school-sch-nj-79__16.mp3", "t": "今邪气交争于骨肉而得汗者，"}, {"f": "audio/26/school-sch-nj-79__17.mp3", "t": "是邪却而精胜也。"}, {"f": "audio/26/school-sch-nj-79__18.mp3", "t": "精胜，"}, {"f": "audio/26/school-sch-nj-79__19.mp3", "t": "则当能食而不复热。"}, {"f": "audio/26/school-sch-nj-79__20.mp3", "t": "复热者，"}, {"f": "audio/26/school-sch-nj-79__21.mp3", "t": "邪气也，"}, {"f": "audio/26/school-sch-nj-79__22.mp3", "t": "汗者，"}, {"f": "audio/26/school-sch-nj-79__23.mp3", "t": "精气也，"}, {"f": "audio/26/school-sch-nj-79__24.mp3", "t": "今汗出而辄复热者，"}, {"f": "audio/26/school-sch-nj-79__25.mp3", "t": "是邪胜也；"}, {"f": "audio/26/school-sch-nj-79__26.mp3", "t": "不能食者，"}, {"f": "audio/26/school-sch-nj-79__27.mp3", "t": "精无俾也；"}, {"f": "audio/26/school-sch-nj-79__28.mp3", "t": "病而留者，"}, {"f": "audio/26/school-sch-nj-79__29.mp3", "t": "其寿可立而倾也。"}, {"f": "audio/26/school-sch-nj-79__30.mp3", "t": "且夫《热论》曰："}, {"f": "audio/26/school-sch-nj-79__31.mp3", "t": "汗出而脉尚躁盛者死。"}, {"f": "audio/26/school-sch-nj-79__32.mp3", "t": "今脉不与汗相应，"}, {"f": "audio/26/school-sch-nj-79__33.mp3", "t": "此不胜其病也，"}, {"f": "audio/26/school-sch-nj-79__34.mp3", "t": "其死明矣。"}, {"f": "audio/26/school-sch-nj-79__35.mp3", "t": "狂言者，"}, {"f": "audio/26/school-sch-nj-79__36.mp3", "t": "是失志，"}, {"f": "audio/26/school-sch-nj-79__37.mp3", "t": "失志者死。"}, {"f": "audio/26/school-sch-nj-79__38.mp3", "t": "今见三死，"}, {"f": "audio/26/school-sch-nj-79__39.mp3", "t": "不见一生，"}, {"f": "audio/26/school-sch-nj-79__40.mp3", "t": "虽愈必死也。"}], "school-sch-nj-80": [{"f": "audio/3a/school-sch-nj-80__0.mp3", "t": "帝曰："}, {"f": "audio/3a/school-sch-nj-80__1.mp3", "t": "有病身热，"}, {"f": "audio/3a/school-sch-nj-80__2.mp3", "t": "汗出烦满，"}, {"f": "audio/3a/school-sch-nj-80__3.mp3", "t": "烦满不为汗解，"}, {"f": "audio/3a/school-sch-nj-80__4.mp3", "t": "此为何病？"}, {"f": "audio/3a/school-sch-nj-80__5.mp3", "t": "岐伯曰："}, {"f": "audio/3a/school-sch-nj-80__6.mp3", "t": "汗出而身热者，"}, {"f": "audio/3a/school-sch-nj-80__7.mp3", "t": "风也；"}, {"f": "audio/3a/school-sch-nj-80__8.mp3", "t": "汗出而烦满不解者，"}, {"f": "audio/3a/school-sch-nj-80__9.mp3", "t": "厥也。"}, {"f": "audio/3a/school-sch-nj-80__10.mp3", "t": "病名曰风厥。"}, {"f": "audio/3a/school-sch-nj-80__11.mp3", "t": "帝曰："}, {"f": "audio/3a/school-sch-nj-80__12.mp3", "t": "愿卒闻之。"}, {"f": "audio/3a/school-sch-nj-80__13.mp3", "t": "岐伯曰："}, {"f": "audio/3a/school-sch-nj-80__14.mp3", "t": "巨阳主气，"}, {"f": "audio/3a/school-sch-nj-80__15.mp3", "t": "故先受邪，"}, {"f": "audio/3a/school-sch-nj-80__16.mp3", "t": "少阴与其为表里也，"}, {"f": "audio/3a/school-sch-nj-80__17.mp3", "t": "得热则上从之，"}, {"f": "audio/3a/school-sch-nj-80__18.mp3", "t": "从之则厥也。"}, {"f": "audio/3a/school-sch-nj-80__19.mp3", "t": "帝曰："}, {"f": "audio/3a/school-sch-nj-80__20.mp3", "t": "治之奈何？"}, {"f": "audio/3a/school-sch-nj-80__21.mp3", "t": "岐伯曰："}, {"f": "audio/3a/school-sch-nj-80__22.mp3", "t": "表里刺之，"}, {"f": "audio/3a/school-sch-nj-80__23.mp3", "t": "饮之服汤。"}], "school-sch-nj-81": [{"f": "audio/d7/school-sch-nj-81__0.mp3", "t": "帝曰："}, {"f": "audio/d7/school-sch-nj-81__1.mp3", "t": "劳风为病何如？"}, {"f": "audio/d7/school-sch-nj-81__2.mp3", "t": "岐伯曰："}, {"f": "audio/d7/school-sch-nj-81__3.mp3", "t": "劳风法在肺下，"}, {"f": "audio/d7/school-sch-nj-81__4.mp3", "t": "其为病也，"}, {"f": "audio/d7/school-sch-nj-81__5.mp3", "t": "使人强上冥视，"}, {"f": "audio/d7/school-sch-nj-81__6.mp3", "t": "唾出若涕，"}, {"f": "audio/d7/school-sch-nj-81__7.mp3", "t": "恶风而振寒，"}, {"f": "audio/d7/school-sch-nj-81__8.mp3", "t": "此为劳风之病。"}, {"f": "audio/d7/school-sch-nj-81__9.mp3", "t": "帝曰："}, {"f": "audio/d7/school-sch-nj-81__10.mp3", "t": "治之奈何？"}, {"f": "audio/d7/school-sch-nj-81__11.mp3", "t": "岐伯曰："}, {"f": "audio/d7/school-sch-nj-81__12.mp3", "t": "以救俯仰。"}, {"f": "audio/d7/school-sch-nj-81__13.mp3", "t": "巨阳引，"}, {"f": "audio/d7/school-sch-nj-81__14.mp3", "t": "精者三日，"}, {"f": "audio/d7/school-sch-nj-81__15.mp3", "t": "中年者五日，"}, {"f": "audio/d7/school-sch-nj-81__16.mp3", "t": "不精者七日。"}, {"f": "audio/d7/school-sch-nj-81__17.mp3", "t": "咳出青黄涕，"}, {"f": "audio/d7/school-sch-nj-81__18.mp3", "t": "其状如脓，"}, {"f": "audio/d7/school-sch-nj-81__19.mp3", "t": "大如弹丸，"}, {"f": "audio/d7/school-sch-nj-81__20.mp3", "t": "从口中若鼻中出，"}, {"f": "audio/d7/school-sch-nj-81__21.mp3", "t": "不出则伤肺，"}, {"f": "audio/d7/school-sch-nj-81__22.mp3", "t": "伤肺则死也。"}], "school-sch-nj-82": [{"f": "audio/01/school-sch-nj-82__0.mp3", "t": "帝曰："}, {"f": "audio/01/school-sch-nj-82__1.mp3", "t": "有病肾风者，"}, {"f": "audio/01/school-sch-nj-82__2.mp3", "t": "面胕痝然，"}, {"f": "audio/01/school-sch-nj-82__3.mp3", "t": "害于言，"}, {"f": "audio/01/school-sch-nj-82__4.mp3", "t": "可刺不？"}, {"f": "audio/01/school-sch-nj-82__5.mp3", "t": "岐伯曰："}, {"f": "audio/01/school-sch-nj-82__6.mp3", "t": "虚不当刺，"}, {"f": "audio/01/school-sch-nj-82__7.mp3", "t": "不当刺而刺，"}, {"f": "audio/01/school-sch-nj-82__8.mp3", "t": "后五日，"}, {"f": "audio/01/school-sch-nj-82__9.mp3", "t": "其气必至。"}, {"f": "audio/01/school-sch-nj-82__10.mp3", "t": "帝曰："}, {"f": "audio/01/school-sch-nj-82__11.mp3", "t": "其至何如？"}, {"f": "audio/01/school-sch-nj-82__12.mp3", "t": "岐伯曰："}, {"f": "audio/01/school-sch-nj-82__13.mp3", "t": "至必少气时热，"}, {"f": "audio/01/school-sch-nj-82__14.mp3", "t": "时热从胸背上至头，"}, {"f": "audio/01/school-sch-nj-82__15.mp3", "t": "汗出手热，"}, {"f": "audio/01/school-sch-nj-82__16.mp3", "t": "口干苦渴，"}, {"f": "audio/01/school-sch-nj-82__17.mp3", "t": "小便黄，"}, {"f": "audio/01/school-sch-nj-82__18.mp3", "t": "目下肿，"}, {"f": "audio/01/school-sch-nj-82__19.mp3", "t": "腹中鸣，"}, {"f": "audio/01/school-sch-nj-82__20.mp3", "t": "身重难以行，"}, {"f": "audio/01/school-sch-nj-82__21.mp3", "t": "月事不来，"}, {"f": "audio/01/school-sch-nj-82__22.mp3", "t": "烦而不能食，"}, {"f": "audio/01/school-sch-nj-82__23.mp3", "t": "不能正偃，"}, {"f": "audio/01/school-sch-nj-82__24.mp3", "t": "正偃则咳，"}, {"f": "audio/01/school-sch-nj-82__25.mp3", "t": "病名曰风水，"}, {"f": "audio/01/school-sch-nj-82__26.mp3", "t": "论在《刺法》中。"}], "school-sch-nj-83": [{"f": "audio/f3/school-sch-nj-83__0.mp3", "t": "帝曰："}, {"f": "audio/f3/school-sch-nj-83__1.mp3", "t": "愿闻其说。"}, {"f": "audio/f3/school-sch-nj-83__2.mp3", "t": "岐伯曰："}, {"f": "audio/f3/school-sch-nj-83__3.mp3", "t": "邪之所凑，"}, {"f": "audio/f3/school-sch-nj-83__4.mp3", "t": "其气必虚。"}, {"f": "audio/f3/school-sch-nj-83__5.mp3", "t": "阴虚者，"}, {"f": "audio/f3/school-sch-nj-83__6.mp3", "t": "阳必凑之，"}, {"f": "audio/f3/school-sch-nj-83__7.mp3", "t": "故少气时热而汗出也。"}, {"f": "audio/f3/school-sch-nj-83__8.mp3", "t": "小便黄者，"}, {"f": "audio/f3/school-sch-nj-83__9.mp3", "t": "少腹中有热也。"}, {"f": "audio/f3/school-sch-nj-83__10.mp3", "t": "不能正偃者，"}, {"f": "audio/f3/school-sch-nj-83__11.mp3", "t": "胃中不和也。"}, {"f": "audio/f3/school-sch-nj-83__12.mp3", "t": "正偃则咳甚，"}, {"f": "audio/f3/school-sch-nj-83__13.mp3", "t": "上迫肺也。"}, {"f": "audio/f3/school-sch-nj-83__14.mp3", "t": "诸有水气者，"}, {"f": "audio/f3/school-sch-nj-83__15.mp3", "t": "微肿先见于目下也。"}, {"f": "audio/f3/school-sch-nj-83__16.mp3", "t": "帝曰："}, {"f": "audio/f3/school-sch-nj-83__17.mp3", "t": "何以言？"}, {"f": "audio/f3/school-sch-nj-83__18.mp3", "t": "岐伯曰："}, {"f": "audio/f3/school-sch-nj-83__19.mp3", "t": "水者，"}, {"f": "audio/f3/school-sch-nj-83__20.mp3", "t": "阴也，"}, {"f": "audio/f3/school-sch-nj-83__21.mp3", "t": "目下亦阴也，"}, {"f": "audio/f3/school-sch-nj-83__22.mp3", "t": "腹者至阴之所居，"}, {"f": "audio/f3/school-sch-nj-83__23.mp3", "t": "故水在腹者，"}, {"f": "audio/f3/school-sch-nj-83__24.mp3", "t": "必使目下肿也。"}, {"f": "audio/f3/school-sch-nj-83__25.mp3", "t": "真气上逆，"}, {"f": "audio/f3/school-sch-nj-83__26.mp3", "t": "故口苦舌干，"}, {"f": "audio/f3/school-sch-nj-83__27.mp3", "t": "卧不得正偃，"}, {"f": "audio/f3/school-sch-nj-83__28.mp3", "t": "正偃则咳出清水也。"}, {"f": "audio/f3/school-sch-nj-83__29.mp3", "t": "诸水病者，"}, {"f": "audio/f3/school-sch-nj-83__30.mp3", "t": "故不得卧，"}, {"f": "audio/f3/school-sch-nj-83__31.mp3", "t": "卧则惊，"}, {"f": "audio/f3/school-sch-nj-83__32.mp3", "t": "惊则咳甚也。"}, {"f": "audio/f3/school-sch-nj-83__33.mp3", "t": "腹中鸣者，"}, {"f": "audio/f3/school-sch-nj-83__34.mp3", "t": "病本于胃也。"}, {"f": "audio/f3/school-sch-nj-83__35.mp3", "t": "薄脾则烦，"}, {"f": "audio/f3/school-sch-nj-83__36.mp3", "t": "不能食。"}, {"f": "audio/f3/school-sch-nj-83__37.mp3", "t": "食不下者，"}, {"f": "audio/f3/school-sch-nj-83__38.mp3", "t": "胃脘膈也。"}, {"f": "audio/f3/school-sch-nj-83__39.mp3", "t": "身重难以行者，"}, {"f": "audio/f3/school-sch-nj-83__40.mp3", "t": "胃脉在足也。"}, {"f": "audio/f3/school-sch-nj-83__41.mp3", "t": "月事不来者，"}, {"f": "audio/f3/school-sch-nj-83__42.mp3", "t": "胞脉闭也。"}, {"f": "audio/f3/school-sch-nj-83__43.mp3", "t": "胞脉者，"}, {"f": "audio/f3/school-sch-nj-83__44.mp3", "t": "属心而络于胞中。"}, {"f": "audio/f3/school-sch-nj-83__45.mp3", "t": "今气上迫肺，"}, {"f": "audio/f3/school-sch-nj-83__46.mp3", "t": "心气不得下通，"}, {"f": "audio/f3/school-sch-nj-83__47.mp3", "t": "故月事不来也。"}, {"f": "audio/f3/school-sch-nj-83__48.mp3", "t": "帝曰："}, {"f": "audio/f3/school-sch-nj-83__49.mp3", "t": "善。"}], "school-sch-nj-84": [{"f": "audio/aa/school-sch-nj-84__0.mp3", "t": "黄帝问曰："}, {"f": "audio/aa/school-sch-nj-84__1.mp3", "t": "肺之令人咳，"}, {"f": "audio/aa/school-sch-nj-84__2.mp3", "t": "何也？"}, {"f": "audio/aa/school-sch-nj-84__3.mp3", "t": "岐伯对曰："}, {"f": "audio/aa/school-sch-nj-84__4.mp3", "t": "五藏六府皆令人咳，"}, {"f": "audio/aa/school-sch-nj-84__5.mp3", "t": "非独肺也。"}, {"f": "audio/aa/school-sch-nj-84__6.mp3", "t": "帝曰："}, {"f": "audio/aa/school-sch-nj-84__7.mp3", "t": "愿闻其状。"}, {"f": "audio/aa/school-sch-nj-84__8.mp3", "t": "岐伯曰："}, {"f": "audio/aa/school-sch-nj-84__9.mp3", "t": "皮毛者，"}, {"f": "audio/aa/school-sch-nj-84__10.mp3", "t": "肺之合也，"}, {"f": "audio/aa/school-sch-nj-84__11.mp3", "t": "皮毛先受邪气，"}, {"f": "audio/aa/school-sch-nj-84__12.mp3", "t": "邪气以从其合也。"}, {"f": "audio/aa/school-sch-nj-84__13.mp3", "t": "其寒饮食入胃，"}, {"f": "audio/aa/school-sch-nj-84__14.mp3", "t": "从肺脉上至于肺，"}, {"f": "audio/aa/school-sch-nj-84__15.mp3", "t": "则肺寒，"}, {"f": "audio/aa/school-sch-nj-84__16.mp3", "t": "肺寒则外内合邪，"}, {"f": "audio/aa/school-sch-nj-84__17.mp3", "t": "因而客之，"}, {"f": "audio/aa/school-sch-nj-84__18.mp3", "t": "则为肺咳。"}, {"f": "audio/aa/school-sch-nj-84__19.mp3", "t": "五藏各以其时受病，"}, {"f": "audio/aa/school-sch-nj-84__20.mp3", "t": "非其时各传以与之。"}, {"f": "audio/aa/school-sch-nj-84__21.mp3", "t": "人与天地相参，"}, {"f": "audio/aa/school-sch-nj-84__22.mp3", "t": "故五藏各以治时，"}, {"f": "audio/aa/school-sch-nj-84__23.mp3", "t": "感于寒则受病，"}, {"f": "audio/aa/school-sch-nj-84__24.mp3", "t": "微则为咳，"}, {"f": "audio/aa/school-sch-nj-84__25.mp3", "t": "甚则为泄、"}, {"f": "audio/aa/school-sch-nj-84__26.mp3", "t": "为痛。"}, {"f": "audio/aa/school-sch-nj-84__27.mp3", "t": "乘秋则肺先受邪，"}, {"f": "audio/aa/school-sch-nj-84__28.mp3", "t": "乘春则肝先受之，"}, {"f": "audio/aa/school-sch-nj-84__29.mp3", "t": "乘夏则心先受之，"}, {"f": "audio/aa/school-sch-nj-84__30.mp3", "t": "乘至阴则脾先受之，"}, {"f": "audio/aa/school-sch-nj-84__31.mp3", "t": "乘冬则肾先受之。"}], "school-sch-nj-85": [{"f": "audio/d4/school-sch-nj-85__0.mp3", "t": "帝曰："}, {"f": "audio/d4/school-sch-nj-85__1.mp3", "t": "何以异之？"}, {"f": "audio/d4/school-sch-nj-85__2.mp3", "t": "岐伯曰："}, {"f": "audio/d4/school-sch-nj-85__3.mp3", "t": "肺咳之状，"}, {"f": "audio/d4/school-sch-nj-85__4.mp3", "t": "咳而喘息有音，"}, {"f": "audio/d4/school-sch-nj-85__5.mp3", "t": "甚则唾血。"}, {"f": "audio/d4/school-sch-nj-85__6.mp3", "t": "心咳之状，"}, {"f": "audio/d4/school-sch-nj-85__7.mp3", "t": "咳则心痛，"}, {"f": "audio/d4/school-sch-nj-85__8.mp3", "t": "喉中介介如梗状，"}, {"f": "audio/d4/school-sch-nj-85__9.mp3", "t": "甚则咽肿喉痹。"}, {"f": "audio/d4/school-sch-nj-85__10.mp3", "t": "肝咳之状，"}, {"f": "audio/d4/school-sch-nj-85__11.mp3", "t": "咳则两胁下痛，"}, {"f": "audio/d4/school-sch-nj-85__12.mp3", "t": "甚则不可以转，"}, {"f": "audio/d4/school-sch-nj-85__13.mp3", "t": "转则两胠下满。"}, {"f": "audio/d4/school-sch-nj-85__14.mp3", "t": "脾咳之状，"}, {"f": "audio/d4/school-sch-nj-85__15.mp3", "t": "咳则右胁下痛，"}, {"f": "audio/d4/school-sch-nj-85__16.mp3", "t": "阴阴引肩背，"}, {"f": "audio/d4/school-sch-nj-85__17.mp3", "t": "甚则不可以动，"}, {"f": "audio/d4/school-sch-nj-85__18.mp3", "t": "动则咳剧。"}, {"f": "audio/d4/school-sch-nj-85__19.mp3", "t": "肾咳之状，"}, {"f": "audio/d4/school-sch-nj-85__20.mp3", "t": "咳则腰背相引而痛，"}, {"f": "audio/d4/school-sch-nj-85__21.mp3", "t": "甚则咳涎。"}], "school-sch-nj-86": [{"f": "audio/2e/school-sch-nj-86__0.mp3", "t": "帝曰："}, {"f": "audio/2e/school-sch-nj-86__1.mp3", "t": "六府之咳奈何？"}, {"f": "audio/2e/school-sch-nj-86__2.mp3", "t": "安所受病？"}, {"f": "audio/2e/school-sch-nj-86__3.mp3", "t": "岐伯曰："}, {"f": "audio/2e/school-sch-nj-86__4.mp3", "t": "五藏之久咳，"}, {"f": "audio/2e/school-sch-nj-86__5.mp3", "t": "乃移于六府。"}, {"f": "audio/2e/school-sch-nj-86__6.mp3", "t": "脾咳不已，"}, {"f": "audio/2e/school-sch-nj-86__7.mp3", "t": "则胃受之。"}, {"f": "audio/2e/school-sch-nj-86__8.mp3", "t": "胃咳之状，"}, {"f": "audio/2e/school-sch-nj-86__9.mp3", "t": "咳而呕，"}, {"f": "audio/2e/school-sch-nj-86__10.mp3", "t": "呕甚则长虫出。"}, {"f": "audio/2e/school-sch-nj-86__11.mp3", "t": "肝咳不已，"}, {"f": "audio/2e/school-sch-nj-86__12.mp3", "t": "则胆受之。"}, {"f": "audio/2e/school-sch-nj-86__13.mp3", "t": "胆咳之状，"}, {"f": "audio/2e/school-sch-nj-86__14.mp3", "t": "咳呕胆汁。"}, {"f": "audio/2e/school-sch-nj-86__15.mp3", "t": "肺咳不已，"}, {"f": "audio/2e/school-sch-nj-86__16.mp3", "t": "则大肠受之。"}, {"f": "audio/2e/school-sch-nj-86__17.mp3", "t": "大肠咳状，"}, {"f": "audio/2e/school-sch-nj-86__18.mp3", "t": "咳而遗矢。"}, {"f": "audio/2e/school-sch-nj-86__19.mp3", "t": "心咳不已，"}, {"f": "audio/2e/school-sch-nj-86__20.mp3", "t": "则小肠受之。"}, {"f": "audio/2e/school-sch-nj-86__21.mp3", "t": "小肠咳状，"}, {"f": "audio/2e/school-sch-nj-86__22.mp3", "t": "咳而失气，"}, {"f": "audio/2e/school-sch-nj-86__23.mp3", "t": "气与咳俱失。"}, {"f": "audio/2e/school-sch-nj-86__24.mp3", "t": "肾咳不已，"}, {"f": "audio/2e/school-sch-nj-86__25.mp3", "t": "则膀胱受之。"}, {"f": "audio/2e/school-sch-nj-86__26.mp3", "t": "膀胱咳状，"}, {"f": "audio/2e/school-sch-nj-86__27.mp3", "t": "咳而遗溺，"}, {"f": "audio/2e/school-sch-nj-86__28.mp3", "t": "久咳不已，"}, {"f": "audio/2e/school-sch-nj-86__29.mp3", "t": "则三焦受之，"}, {"f": "audio/2e/school-sch-nj-86__30.mp3", "t": "三焦咳状，"}, {"f": "audio/2e/school-sch-nj-86__31.mp3", "t": "咳而腹满，"}, {"f": "audio/2e/school-sch-nj-86__32.mp3", "t": "不欲食饮。"}, {"f": "audio/2e/school-sch-nj-86__33.mp3", "t": "此皆聚于胃，"}, {"f": "audio/2e/school-sch-nj-86__34.mp3", "t": "关于肺，"}, {"f": "audio/2e/school-sch-nj-86__35.mp3", "t": "使人多涕唾，"}, {"f": "audio/2e/school-sch-nj-86__36.mp3", "t": "而面浮肿气逆也。"}], "school-sch-nj-87": [{"f": "audio/15/school-sch-nj-87__0.mp3", "t": "帝曰："}, {"f": "audio/15/school-sch-nj-87__1.mp3", "t": "治之奈何？"}, {"f": "audio/15/school-sch-nj-87__2.mp3", "t": "岐伯曰："}, {"f": "audio/15/school-sch-nj-87__3.mp3", "t": "治藏者，"}, {"f": "audio/15/school-sch-nj-87__4.mp3", "t": "治其俞；"}, {"f": "audio/15/school-sch-nj-87__5.mp3", "t": "治府者，"}, {"f": "audio/15/school-sch-nj-87__6.mp3", "t": "治其合；"}, {"f": "audio/15/school-sch-nj-87__7.mp3", "t": "浮肿者，"}, {"f": "audio/15/school-sch-nj-87__8.mp3", "t": "治其经。"}, {"f": "audio/15/school-sch-nj-87__9.mp3", "t": "帝曰："}, {"f": "audio/15/school-sch-nj-87__10.mp3", "t": "善。"}], "school-sch-nj-88": [{"f": "audio/69/school-sch-nj-88__0.mp3", "t": "黄帝问曰："}, {"f": "audio/69/school-sch-nj-88__1.mp3", "t": "痹之安生？"}, {"f": "audio/69/school-sch-nj-88__2.mp3", "t": "岐伯对曰："}, {"f": "audio/69/school-sch-nj-88__3.mp3", "t": "风、"}, {"f": "audio/69/school-sch-nj-88__4.mp3", "t": "寒、"}, {"f": "audio/69/school-sch-nj-88__5.mp3", "t": "湿三气杂至，"}, {"f": "audio/69/school-sch-nj-88__6.mp3", "t": "合而为痹也。"}, {"f": "audio/69/school-sch-nj-88__7.mp3", "t": "其风气胜者，"}, {"f": "audio/69/school-sch-nj-88__8.mp3", "t": "为行痹；"}, {"f": "audio/69/school-sch-nj-88__9.mp3", "t": "寒气胜者，"}, {"f": "audio/69/school-sch-nj-88__10.mp3", "t": "为痛痹；"}, {"f": "audio/69/school-sch-nj-88__11.mp3", "t": "湿气胜者，"}, {"f": "audio/69/school-sch-nj-88__12.mp3", "t": "为着痹也。"}, {"f": "audio/69/school-sch-nj-88__13.mp3", "t": "帝曰："}, {"f": "audio/69/school-sch-nj-88__14.mp3", "t": "其有五者，"}, {"f": "audio/69/school-sch-nj-88__15.mp3", "t": "何也？"}, {"f": "audio/69/school-sch-nj-88__16.mp3", "t": "岐伯曰："}, {"f": "audio/69/school-sch-nj-88__17.mp3", "t": "以冬遇此者为骨痹，"}, {"f": "audio/69/school-sch-nj-88__18.mp3", "t": "以春遇此者为筋痹，"}, {"f": "audio/69/school-sch-nj-88__19.mp3", "t": "以夏遇此者为脉痹，"}, {"f": "audio/69/school-sch-nj-88__20.mp3", "t": "以至阴遇此者为肌痹，"}, {"f": "audio/69/school-sch-nj-88__21.mp3", "t": "以秋遇此者为皮痹。"}], "school-sch-nj-89": [{"f": "audio/6c/school-sch-nj-89__0.mp3", "t": "帝曰："}, {"f": "audio/6c/school-sch-nj-89__1.mp3", "t": "内舍五藏六府，"}, {"f": "audio/6c/school-sch-nj-89__2.mp3", "t": "何气使然？"}, {"f": "audio/6c/school-sch-nj-89__3.mp3", "t": "岐伯曰："}, {"f": "audio/6c/school-sch-nj-89__4.mp3", "t": "五藏皆有合，"}, {"f": "audio/6c/school-sch-nj-89__5.mp3", "t": "病久而不去者，"}, {"f": "audio/6c/school-sch-nj-89__6.mp3", "t": "内舍于其合也。"}, {"f": "audio/6c/school-sch-nj-89__7.mp3", "t": "故骨痹不已复感于邪，"}, {"f": "audio/6c/school-sch-nj-89__8.mp3", "t": "内舍于肾；"}, {"f": "audio/6c/school-sch-nj-89__9.mp3", "t": "筋痹不已，"}, {"f": "audio/6c/school-sch-nj-89__10.mp3", "t": "复感于邪，"}, {"f": "audio/6c/school-sch-nj-89__11.mp3", "t": "内舍于肝；"}, {"f": "audio/6c/school-sch-nj-89__12.mp3", "t": "脉痹不已，"}, {"f": "audio/6c/school-sch-nj-89__13.mp3", "t": "复感于邪，"}, {"f": "audio/6c/school-sch-nj-89__14.mp3", "t": "内舍于心；"}, {"f": "audio/6c/school-sch-nj-89__15.mp3", "t": "肌痹不已，"}, {"f": "audio/6c/school-sch-nj-89__16.mp3", "t": "复感于邪，"}, {"f": "audio/6c/school-sch-nj-89__17.mp3", "t": "内舍于脾；"}, {"f": "audio/6c/school-sch-nj-89__18.mp3", "t": "皮痹不已，"}, {"f": "audio/6c/school-sch-nj-89__19.mp3", "t": "复感于邪，"}, {"f": "audio/6c/school-sch-nj-89__20.mp3", "t": "内舍于肺。"}, {"f": "audio/6c/school-sch-nj-89__21.mp3", "t": "所谓痹者，"}, {"f": "audio/6c/school-sch-nj-89__22.mp3", "t": "各以其时重感于风寒湿之气也。"}], "school-sch-nj-90": [{"f": "audio/b0/school-sch-nj-90__0.mp3", "t": "凡痹之客五藏者，"}, {"f": "audio/b0/school-sch-nj-90__1.mp3", "t": "肺痹者，"}, {"f": "audio/b0/school-sch-nj-90__2.mp3", "t": "烦满，"}, {"f": "audio/b0/school-sch-nj-90__3.mp3", "t": "喘而呕；"}, {"f": "audio/b0/school-sch-nj-90__4.mp3", "t": "心痹者，"}, {"f": "audio/b0/school-sch-nj-90__5.mp3", "t": "脉不通，"}, {"f": "audio/b0/school-sch-nj-90__6.mp3", "t": "烦则心下鼓，"}, {"f": "audio/b0/school-sch-nj-90__7.mp3", "t": "暴上气而喘，"}, {"f": "audio/b0/school-sch-nj-90__8.mp3", "t": "嗌干，"}, {"f": "audio/b0/school-sch-nj-90__9.mp3", "t": "善噫，"}, {"f": "audio/b0/school-sch-nj-90__10.mp3", "t": "厥气上则恐；"}, {"f": "audio/b0/school-sch-nj-90__11.mp3", "t": "肝痹者，"}, {"f": "audio/b0/school-sch-nj-90__12.mp3", "t": "夜卧则惊，"}, {"f": "audio/b0/school-sch-nj-90__13.mp3", "t": "多饮，"}, {"f": "audio/b0/school-sch-nj-90__14.mp3", "t": "数小便，"}, {"f": "audio/b0/school-sch-nj-90__15.mp3", "t": "上为引如怀；"}, {"f": "audio/b0/school-sch-nj-90__16.mp3", "t": "肾痹者，"}, {"f": "audio/b0/school-sch-nj-90__17.mp3", "t": "善胀，"}, {"f": "audio/b0/school-sch-nj-90__18.mp3", "t": "尻以代踵，"}, {"f": "audio/b0/school-sch-nj-90__19.mp3", "t": "脊以代头；"}, {"f": "audio/b0/school-sch-nj-90__20.mp3", "t": "脾痹者，"}, {"f": "audio/b0/school-sch-nj-90__21.mp3", "t": "四支解堕，"}, {"f": "audio/b0/school-sch-nj-90__22.mp3", "t": "发咳，"}, {"f": "audio/b0/school-sch-nj-90__23.mp3", "t": "呕汁，"}, {"f": "audio/b0/school-sch-nj-90__24.mp3", "t": "上为大塞。"}, {"f": "audio/b0/school-sch-nj-90__25.mp3", "t": "肠痹者，"}, {"f": "audio/b0/school-sch-nj-90__26.mp3", "t": "数饮而出不得，"}, {"f": "audio/b0/school-sch-nj-90__27.mp3", "t": "中气喘争，"}, {"f": "audio/b0/school-sch-nj-90__28.mp3", "t": "时发飧泄。"}, {"f": "audio/b0/school-sch-nj-90__29.mp3", "t": "胞痹者，"}, {"f": "audio/b0/school-sch-nj-90__30.mp3", "t": "少腹膀胱按之内痛，"}, {"f": "audio/b0/school-sch-nj-90__31.mp3", "t": "若沃以汤，"}, {"f": "audio/b0/school-sch-nj-90__32.mp3", "t": "涩于小便，"}, {"f": "audio/b0/school-sch-nj-90__33.mp3", "t": "上为清涕。"}], "school-sch-nj-91": [{"f": "audio/1f/school-sch-nj-91__0.mp3", "t": "阴气者，"}, {"f": "audio/1f/school-sch-nj-91__1.mp3", "t": "静则神藏，"}, {"f": "audio/1f/school-sch-nj-91__2.mp3", "t": "躁则消亡。"}, {"f": "audio/1f/school-sch-nj-91__3.mp3", "t": "饮食自倍，"}, {"f": "audio/1f/school-sch-nj-91__4.mp3", "t": "肠胃乃伤。"}, {"f": "audio/1f/school-sch-nj-91__5.mp3", "t": "淫气喘息，"}, {"f": "audio/1f/school-sch-nj-91__6.mp3", "t": "痹聚在肺。"}, {"f": "audio/1f/school-sch-nj-91__7.mp3", "t": "淫气忧思，"}, {"f": "audio/1f/school-sch-nj-91__8.mp3", "t": "痹聚在心。"}, {"f": "audio/1f/school-sch-nj-91__9.mp3", "t": "淫气遗溺，"}, {"f": "audio/1f/school-sch-nj-91__10.mp3", "t": "痹聚在肾。"}, {"f": "audio/1f/school-sch-nj-91__11.mp3", "t": "淫气乏竭，"}, {"f": "audio/1f/school-sch-nj-91__12.mp3", "t": "痹聚在肝。"}, {"f": "audio/1f/school-sch-nj-91__13.mp3", "t": "淫气肌绝，"}, {"f": "audio/1f/school-sch-nj-91__14.mp3", "t": "痹聚在脾。"}], "school-sch-nj-92": [{"f": "audio/b4/school-sch-nj-92__0.mp3", "t": "诸痹不已，"}, {"f": "audio/b4/school-sch-nj-92__1.mp3", "t": "亦益内也。"}, {"f": "audio/b4/school-sch-nj-92__2.mp3", "t": "其风气胜者，"}, {"f": "audio/b4/school-sch-nj-92__3.mp3", "t": "其人易已也。"}], "school-sch-nj-93": [{"f": "audio/f7/school-sch-nj-93__0.mp3", "t": "帝曰："}, {"f": "audio/f7/school-sch-nj-93__1.mp3", "t": "痹，"}, {"f": "audio/f7/school-sch-nj-93__2.mp3", "t": "其时有死者，"}, {"f": "audio/f7/school-sch-nj-93__3.mp3", "t": "或疼久者，"}, {"f": "audio/f7/school-sch-nj-93__4.mp3", "t": "或易已者，"}, {"f": "audio/f7/school-sch-nj-93__5.mp3", "t": "其故何也？"}, {"f": "audio/f7/school-sch-nj-93__6.mp3", "t": "岐伯曰："}, {"f": "audio/f7/school-sch-nj-93__7.mp3", "t": "其入藏者死，"}, {"f": "audio/f7/school-sch-nj-93__8.mp3", "t": "其留连筋骨间者疼久，"}, {"f": "audio/f7/school-sch-nj-93__9.mp3", "t": "其留皮肤间者易已。"}], "school-sch-nj-94": [{"f": "audio/73/school-sch-nj-94__0.mp3", "t": "帝曰："}, {"f": "audio/73/school-sch-nj-94__1.mp3", "t": "其客于六府者，"}, {"f": "audio/73/school-sch-nj-94__2.mp3", "t": "何也？"}, {"f": "audio/73/school-sch-nj-94__3.mp3", "t": "岐伯曰："}, {"f": "audio/73/school-sch-nj-94__4.mp3", "t": "此亦其食饮居处，"}, {"f": "audio/73/school-sch-nj-94__5.mp3", "t": "为其病本也。"}, {"f": "audio/73/school-sch-nj-94__6.mp3", "t": "六府亦各有俞，"}, {"f": "audio/73/school-sch-nj-94__7.mp3", "t": "风寒湿气中其俞，"}, {"f": "audio/73/school-sch-nj-94__8.mp3", "t": "而食饮应之，"}, {"f": "audio/73/school-sch-nj-94__9.mp3", "t": "循俞而入，"}, {"f": "audio/73/school-sch-nj-94__10.mp3", "t": "各舍其府也。"}], "school-sch-nj-95": [{"f": "audio/36/school-sch-nj-95__0.mp3", "t": "帝曰："}, {"f": "audio/36/school-sch-nj-95__1.mp3", "t": "以针治之奈何？"}, {"f": "audio/36/school-sch-nj-95__2.mp3", "t": "岐伯曰："}, {"f": "audio/36/school-sch-nj-95__3.mp3", "t": "五藏有俞，"}, {"f": "audio/36/school-sch-nj-95__4.mp3", "t": "六府有合，"}, {"f": "audio/36/school-sch-nj-95__5.mp3", "t": "循脉之分，"}, {"f": "audio/36/school-sch-nj-95__6.mp3", "t": "各有所发，"}, {"f": "audio/36/school-sch-nj-95__7.mp3", "t": "各随其过，"}, {"f": "audio/36/school-sch-nj-95__8.mp3", "t": "则病瘳也。"}], "school-sch-nj-96": [{"f": "audio/99/school-sch-nj-96__0.mp3", "t": "帝曰："}, {"f": "audio/99/school-sch-nj-96__1.mp3", "t": "荣卫之气，"}, {"f": "audio/99/school-sch-nj-96__2.mp3", "t": "亦令人痹乎？"}, {"f": "audio/99/school-sch-nj-96__3.mp3", "t": "岐伯曰："}, {"f": "audio/99/school-sch-nj-96__4.mp3", "t": "荣者，"}, {"f": "audio/99/school-sch-nj-96__5.mp3", "t": "水谷之精气也，"}, {"f": "audio/99/school-sch-nj-96__6.mp3", "t": "和调于五藏，"}, {"f": "audio/99/school-sch-nj-96__7.mp3", "t": "洒陈于六府，"}, {"f": "audio/99/school-sch-nj-96__8.mp3", "t": "乃能入于脉也。"}, {"f": "audio/99/school-sch-nj-96__9.mp3", "t": "故循脉上下，"}, {"f": "audio/99/school-sch-nj-96__10.mp3", "t": "贯五藏，"}, {"f": "audio/99/school-sch-nj-96__11.mp3", "t": "络六府也。"}, {"f": "audio/99/school-sch-nj-96__12.mp3", "t": "卫者，"}, {"f": "audio/99/school-sch-nj-96__13.mp3", "t": "水谷之悍气也，"}, {"f": "audio/99/school-sch-nj-96__14.mp3", "t": "其气慓疾滑利，"}, {"f": "audio/99/school-sch-nj-96__15.mp3", "t": "不能入于脉也。"}, {"f": "audio/99/school-sch-nj-96__16.mp3", "t": "故循皮肤之中，"}, {"f": "audio/99/school-sch-nj-96__17.mp3", "t": "分肉之间，"}, {"f": "audio/99/school-sch-nj-96__18.mp3", "t": "熏于肓膜，"}, {"f": "audio/99/school-sch-nj-96__19.mp3", "t": "散于胸腹。"}, {"f": "audio/99/school-sch-nj-96__20.mp3", "t": "逆其气则病，"}, {"f": "audio/99/school-sch-nj-96__21.mp3", "t": "从其气则愈，"}, {"f": "audio/99/school-sch-nj-96__22.mp3", "t": "不与风寒湿气合，"}, {"f": "audio/99/school-sch-nj-96__23.mp3", "t": "故不为痹。"}], "school-sch-nj-97": [{"f": "audio/6e/school-sch-nj-97__0.mp3", "t": "帝曰："}, {"f": "audio/6e/school-sch-nj-97__1.mp3", "t": "善。"}, {"f": "audio/6e/school-sch-nj-97__2.mp3", "t": "痹或痛，"}, {"f": "audio/6e/school-sch-nj-97__3.mp3", "t": "或不痛，"}, {"f": "audio/6e/school-sch-nj-97__4.mp3", "t": "或不仁，"}, {"f": "audio/6e/school-sch-nj-97__5.mp3", "t": "或寒，"}, {"f": "audio/6e/school-sch-nj-97__6.mp3", "t": "或热，"}, {"f": "audio/6e/school-sch-nj-97__7.mp3", "t": "或燥，"}, {"f": "audio/6e/school-sch-nj-97__8.mp3", "t": "或湿，"}, {"f": "audio/6e/school-sch-nj-97__9.mp3", "t": "其故何也？"}, {"f": "audio/6e/school-sch-nj-97__10.mp3", "t": "岐伯曰："}, {"f": "audio/6e/school-sch-nj-97__11.mp3", "t": "痛者，"}, {"f": "audio/6e/school-sch-nj-97__12.mp3", "t": "寒气多也，"}, {"f": "audio/6e/school-sch-nj-97__13.mp3", "t": "有寒故痛也。"}, {"f": "audio/6e/school-sch-nj-97__14.mp3", "t": "其不痛不仁者，"}, {"f": "audio/6e/school-sch-nj-97__15.mp3", "t": "病久入深，"}, {"f": "audio/6e/school-sch-nj-97__16.mp3", "t": "荣卫之行涩，"}, {"f": "audio/6e/school-sch-nj-97__17.mp3", "t": "经络时疏，"}, {"f": "audio/6e/school-sch-nj-97__18.mp3", "t": "故不通；"}, {"f": "audio/6e/school-sch-nj-97__19.mp3", "t": "皮肤不荣，"}, {"f": "audio/6e/school-sch-nj-97__20.mp3", "t": "故为不仁。"}, {"f": "audio/6e/school-sch-nj-97__21.mp3", "t": "其寒者，"}, {"f": "audio/6e/school-sch-nj-97__22.mp3", "t": "阳气少，"}, {"f": "audio/6e/school-sch-nj-97__23.mp3", "t": "阴气多，"}, {"f": "audio/6e/school-sch-nj-97__24.mp3", "t": "与病相益，"}, {"f": "audio/6e/school-sch-nj-97__25.mp3", "t": "故寒也。"}, {"f": "audio/6e/school-sch-nj-97__26.mp3", "t": "其热者，"}, {"f": "audio/6e/school-sch-nj-97__27.mp3", "t": "阳气多，"}, {"f": "audio/6e/school-sch-nj-97__28.mp3", "t": "阴气少，"}, {"f": "audio/6e/school-sch-nj-97__29.mp3", "t": "病气胜，"}, {"f": "audio/6e/school-sch-nj-97__30.mp3", "t": "阳遭阴，"}, {"f": "audio/6e/school-sch-nj-97__31.mp3", "t": "故为痹热。"}, {"f": "audio/6e/school-sch-nj-97__32.mp3", "t": "其多汗而濡者，"}, {"f": "audio/6e/school-sch-nj-97__33.mp3", "t": "此其逢湿甚也，"}, {"f": "audio/6e/school-sch-nj-97__34.mp3", "t": "阳气少，"}, {"f": "audio/6e/school-sch-nj-97__35.mp3", "t": "阴气盛，"}, {"f": "audio/6e/school-sch-nj-97__36.mp3", "t": "两气相感，"}, {"f": "audio/6e/school-sch-nj-97__37.mp3", "t": "故汗出而濡也。"}], "school-sch-nj-98": [{"f": "audio/3f/school-sch-nj-98__0.mp3", "t": "帝曰："}, {"f": "audio/3f/school-sch-nj-98__1.mp3", "t": "夫痹之为病，"}, {"f": "audio/3f/school-sch-nj-98__2.mp3", "t": "不痛何也？"}, {"f": "audio/3f/school-sch-nj-98__3.mp3", "t": "岐伯曰："}, {"f": "audio/3f/school-sch-nj-98__4.mp3", "t": "痹在于骨则重，"}, {"f": "audio/3f/school-sch-nj-98__5.mp3", "t": "在于脉则血凝而不流，"}, {"f": "audio/3f/school-sch-nj-98__6.mp3", "t": "在于筋则屈不伸，"}, {"f": "audio/3f/school-sch-nj-98__7.mp3", "t": "在于肉则不仁，"}, {"f": "audio/3f/school-sch-nj-98__8.mp3", "t": "在于皮则寒，"}, {"f": "audio/3f/school-sch-nj-98__9.mp3", "t": "故具此五者，"}, {"f": "audio/3f/school-sch-nj-98__10.mp3", "t": "则不痛也。"}, {"f": "audio/3f/school-sch-nj-98__11.mp3", "t": "凡痹之类，"}, {"f": "audio/3f/school-sch-nj-98__12.mp3", "t": "逢寒则虫，"}, {"f": "audio/3f/school-sch-nj-98__13.mp3", "t": "逢热则纵。"}, {"f": "audio/3f/school-sch-nj-98__14.mp3", "t": "帝曰："}, {"f": "audio/3f/school-sch-nj-98__15.mp3", "t": "善。"}], "school-sch-nj-99": [{"f": "audio/9e/school-sch-nj-99__0.mp3", "t": "黄帝问曰："}, {"f": "audio/9e/school-sch-nj-99__1.mp3", "t": "五藏使人痿，"}, {"f": "audio/9e/school-sch-nj-99__2.mp3", "t": "何也？"}, {"f": "audio/9e/school-sch-nj-99__3.mp3", "t": "岐伯对曰："}, {"f": "audio/9e/school-sch-nj-99__4.mp3", "t": "肺主身之皮毛，"}, {"f": "audio/9e/school-sch-nj-99__5.mp3", "t": "心主身之血脉，"}, {"f": "audio/9e/school-sch-nj-99__6.mp3", "t": "肝主身之筋膜，"}, {"f": "audio/9e/school-sch-nj-99__7.mp3", "t": "脾主身之肌肉，"}, {"f": "audio/9e/school-sch-nj-99__8.mp3", "t": "肾主身之骨髓。"}, {"f": "audio/9e/school-sch-nj-99__9.mp3", "t": "故肺热叶焦，"}, {"f": "audio/9e/school-sch-nj-99__10.mp3", "t": "则皮毛虚弱急薄，"}, {"f": "audio/9e/school-sch-nj-99__11.mp3", "t": "着则生痿躄也。"}, {"f": "audio/9e/school-sch-nj-99__12.mp3", "t": "心气热，"}, {"f": "audio/9e/school-sch-nj-99__13.mp3", "t": "则下脉厥而上，"}, {"f": "audio/9e/school-sch-nj-99__14.mp3", "t": "上则下脉虚，"}, {"f": "audio/9e/school-sch-nj-99__15.mp3", "t": "虚则生脉痿，"}, {"f": "audio/9e/school-sch-nj-99__16.mp3", "t": "枢折挈，"}, {"f": "audio/9e/school-sch-nj-99__17.mp3", "t": "胫纵而不任地也。"}, {"f": "audio/9e/school-sch-nj-99__18.mp3", "t": "肝气热，"}, {"f": "audio/9e/school-sch-nj-99__19.mp3", "t": "则胆泄口苦，"}, {"f": "audio/9e/school-sch-nj-99__20.mp3", "t": "筋膜干，"}, {"f": "audio/9e/school-sch-nj-99__21.mp3", "t": "筋膜干则筋急而挛，"}, {"f": "audio/9e/school-sch-nj-99__22.mp3", "t": "发为筋痿，"}, {"f": "audio/9e/school-sch-nj-99__23.mp3", "t": "脾气热，"}, {"f": "audio/9e/school-sch-nj-99__24.mp3", "t": "则胃干而渴，"}, {"f": "audio/9e/school-sch-nj-99__25.mp3", "t": "肌肉不仁，"}, {"f": "audio/9e/school-sch-nj-99__26.mp3", "t": "发为肉痿。"}, {"f": "audio/9e/school-sch-nj-99__27.mp3", "t": "肾气热，"}, {"f": "audio/9e/school-sch-nj-99__28.mp3", "t": "则腰脊不举，"}, {"f": "audio/9e/school-sch-nj-99__29.mp3", "t": "骨枯而髓减，"}, {"f": "audio/9e/school-sch-nj-99__30.mp3", "t": "发为骨痿。"}], "school-sch-nj-100": [{"f": "audio/a6/school-sch-nj-100__0.mp3", "t": "帝曰："}, {"f": "audio/a6/school-sch-nj-100__1.mp3", "t": "何以得之？"}, {"f": "audio/a6/school-sch-nj-100__2.mp3", "t": "岐伯曰："}, {"f": "audio/a6/school-sch-nj-100__3.mp3", "t": "肺者，"}, {"f": "audio/a6/school-sch-nj-100__4.mp3", "t": "藏之长也，"}, {"f": "audio/a6/school-sch-nj-100__5.mp3", "t": "为心之盖也，"}, {"f": "audio/a6/school-sch-nj-100__6.mp3", "t": "有所失亡，"}, {"f": "audio/a6/school-sch-nj-100__7.mp3", "t": "所求不得，"}, {"f": "audio/a6/school-sch-nj-100__8.mp3", "t": "则发肺鸣，"}, {"f": "audio/a6/school-sch-nj-100__9.mp3", "t": "鸣则肺热叶焦。"}, {"f": "audio/a6/school-sch-nj-100__10.mp3", "t": "故曰："}, {"f": "audio/a6/school-sch-nj-100__11.mp3", "t": "五藏因肺热叶焦，"}, {"f": "audio/a6/school-sch-nj-100__12.mp3", "t": "发为痿躄。"}, {"f": "audio/a6/school-sch-nj-100__13.mp3", "t": "此之谓也。"}, {"f": "audio/a6/school-sch-nj-100__14.mp3", "t": "悲哀太甚，"}, {"f": "audio/a6/school-sch-nj-100__15.mp3", "t": "则胞络绝，"}, {"f": "audio/a6/school-sch-nj-100__16.mp3", "t": "胞络绝则阳气内动，"}, {"f": "audio/a6/school-sch-nj-100__17.mp3", "t": "发则心下崩，"}, {"f": "audio/a6/school-sch-nj-100__18.mp3", "t": "数溲血也。"}, {"f": "audio/a6/school-sch-nj-100__19.mp3", "t": "故《本病》曰："}, {"f": "audio/a6/school-sch-nj-100__20.mp3", "t": "大经空虚，"}, {"f": "audio/a6/school-sch-nj-100__21.mp3", "t": "发为肌痹，"}, {"f": "audio/a6/school-sch-nj-100__22.mp3", "t": "传为脉痿。"}, {"f": "audio/a6/school-sch-nj-100__23.mp3", "t": "思想无穷，"}, {"f": "audio/a6/school-sch-nj-100__24.mp3", "t": "所愿不得，"}, {"f": "audio/a6/school-sch-nj-100__25.mp3", "t": "意淫于外，"}, {"f": "audio/a6/school-sch-nj-100__26.mp3", "t": "入房太甚，"}, {"f": "audio/a6/school-sch-nj-100__27.mp3", "t": "宗筋弛纵，"}, {"f": "audio/a6/school-sch-nj-100__28.mp3", "t": "发为筋痿，"}, {"f": "audio/a6/school-sch-nj-100__29.mp3", "t": "及为白淫。"}, {"f": "audio/a6/school-sch-nj-100__30.mp3", "t": "故《下经》曰："}, {"f": "audio/a6/school-sch-nj-100__31.mp3", "t": "筋痿者，"}, {"f": "audio/a6/school-sch-nj-100__32.mp3", "t": "生于肝，"}, {"f": "audio/a6/school-sch-nj-100__33.mp3", "t": "使内也。"}, {"f": "audio/a6/school-sch-nj-100__34.mp3", "t": "有渐于湿，"}, {"f": "audio/a6/school-sch-nj-100__35.mp3", "t": "以水为事，"}, {"f": "audio/a6/school-sch-nj-100__36.mp3", "t": "若有所留，"}, {"f": "audio/a6/school-sch-nj-100__37.mp3", "t": "居处相湿，"}, {"f": "audio/a6/school-sch-nj-100__38.mp3", "t": "肌肉濡渍，"}, {"f": "audio/a6/school-sch-nj-100__39.mp3", "t": "痹而不仁，"}, {"f": "audio/a6/school-sch-nj-100__40.mp3", "t": "发为肉痿。"}, {"f": "audio/a6/school-sch-nj-100__41.mp3", "t": "故《下经》曰："}, {"f": "audio/a6/school-sch-nj-100__42.mp3", "t": "肉痿者，"}, {"f": "audio/a6/school-sch-nj-100__43.mp3", "t": "得之湿地也。"}, {"f": "audio/a6/school-sch-nj-100__44.mp3", "t": "有所远行劳倦，"}, {"f": "audio/a6/school-sch-nj-100__45.mp3", "t": "逢大热而渴，"}, {"f": "audio/a6/school-sch-nj-100__46.mp3", "t": "渴则阳气内伐，"}, {"f": "audio/a6/school-sch-nj-100__47.mp3", "t": "内伐则热舍于肾。"}, {"f": "audio/a6/school-sch-nj-100__48.mp3", "t": "肾者水藏也，"}, {"f": "audio/a6/school-sch-nj-100__49.mp3", "t": "今水不胜火，"}, {"f": "audio/a6/school-sch-nj-100__50.mp3", "t": "则骨枯而髓虚，"}, {"f": "audio/a6/school-sch-nj-100__51.mp3", "t": "故足不任身，"}, {"f": "audio/a6/school-sch-nj-100__52.mp3", "t": "发为骨痿。"}, {"f": "audio/a6/school-sch-nj-100__53.mp3", "t": "故《下经》曰："}, {"f": "audio/a6/school-sch-nj-100__54.mp3", "t": "骨痿者，"}, {"f": "audio/a6/school-sch-nj-100__55.mp3", "t": "生于大热也。"}], "school-sch-nj-101": [{"f": "audio/b0/school-sch-nj-101__0.mp3", "t": "帝曰："}, {"f": "audio/b0/school-sch-nj-101__1.mp3", "t": "何以别之？"}, {"f": "audio/b0/school-sch-nj-101__2.mp3", "t": "岐伯曰："}, {"f": "audio/b0/school-sch-nj-101__3.mp3", "t": "肺热者，"}, {"f": "audio/b0/school-sch-nj-101__4.mp3", "t": "色白而毛败；"}, {"f": "audio/b0/school-sch-nj-101__5.mp3", "t": "心热者，"}, {"f": "audio/b0/school-sch-nj-101__6.mp3", "t": "色赤而络脉溢；"}, {"f": "audio/b0/school-sch-nj-101__7.mp3", "t": "肝热者，"}, {"f": "audio/b0/school-sch-nj-101__8.mp3", "t": "色苍而爪枯；"}, {"f": "audio/b0/school-sch-nj-101__9.mp3", "t": "脾热者，"}, {"f": "audio/b0/school-sch-nj-101__10.mp3", "t": "色黄而肉蠕动；"}, {"f": "audio/b0/school-sch-nj-101__11.mp3", "t": "肾热者，"}, {"f": "audio/b0/school-sch-nj-101__12.mp3", "t": "色黑而齿槁。"}], "school-sch-nj-102": [{"f": "audio/75/school-sch-nj-102__0.mp3", "t": "帝曰："}, {"f": "audio/75/school-sch-nj-102__1.mp3", "t": "如夫子言可矣。"}, {"f": "audio/75/school-sch-nj-102__2.mp3", "t": "论言治痿者，"}, {"f": "audio/75/school-sch-nj-102__3.mp3", "t": "独取阳明何也？"}, {"f": "audio/75/school-sch-nj-102__4.mp3", "t": "岐伯曰："}, {"f": "audio/75/school-sch-nj-102__5.mp3", "t": "阳明者，"}, {"f": "audio/75/school-sch-nj-102__6.mp3", "t": "五藏六府之海，"}, {"f": "audio/75/school-sch-nj-102__7.mp3", "t": "主润宗筋，"}, {"f": "audio/75/school-sch-nj-102__8.mp3", "t": "宗筋主束骨而利机关也。"}, {"f": "audio/75/school-sch-nj-102__9.mp3", "t": "冲脉者，"}, {"f": "audio/75/school-sch-nj-102__10.mp3", "t": "经脉之海也，"}, {"f": "audio/75/school-sch-nj-102__11.mp3", "t": "主渗灌溪谷，"}, {"f": "audio/75/school-sch-nj-102__12.mp3", "t": "与阳明合于宗筋。"}, {"f": "audio/75/school-sch-nj-102__13.mp3", "t": "阴阳总宗筋之会，"}, {"f": "audio/75/school-sch-nj-102__14.mp3", "t": "会于气街，"}, {"f": "audio/75/school-sch-nj-102__15.mp3", "t": "而阳明为之长，"}, {"f": "audio/75/school-sch-nj-102__16.mp3", "t": "皆属于带脉，"}, {"f": "audio/75/school-sch-nj-102__17.mp3", "t": "而络于督脉。"}, {"f": "audio/75/school-sch-nj-102__18.mp3", "t": "故阳明虚，"}, {"f": "audio/75/school-sch-nj-102__19.mp3", "t": "则宗筋纵，"}, {"f": "audio/75/school-sch-nj-102__20.mp3", "t": "带脉不引，"}, {"f": "audio/75/school-sch-nj-102__21.mp3", "t": "故足痿不用也。"}, {"f": "audio/75/school-sch-nj-102__22.mp3", "t": "帝曰："}, {"f": "audio/75/school-sch-nj-102__23.mp3", "t": "治之余何？"}, {"f": "audio/75/school-sch-nj-102__24.mp3", "t": "岐伯曰："}, {"f": "audio/75/school-sch-nj-102__25.mp3", "t": "各补其荥而通其俞，"}, {"f": "audio/75/school-sch-nj-102__26.mp3", "t": "调其虚实，"}, {"f": "audio/75/school-sch-nj-102__27.mp3", "t": "和其逆顺，"}, {"f": "audio/75/school-sch-nj-102__28.mp3", "t": "筋脉骨肉，"}, {"f": "audio/75/school-sch-nj-102__29.mp3", "t": "各以其时受月，"}, {"f": "audio/75/school-sch-nj-102__30.mp3", "t": "则病已矣。"}, {"f": "audio/75/school-sch-nj-102__31.mp3", "t": "帝曰："}, {"f": "audio/75/school-sch-nj-102__32.mp3", "t": "善。"}], "school-sch-nj-103": [{"f": "audio/1c/school-sch-nj-103__0.mp3", "t": "黄帝问于岐伯曰："}, {"f": "audio/1c/school-sch-nj-103__1.mp3", "t": "水与肤胀、"}, {"f": "audio/1c/school-sch-nj-103__2.mp3", "t": "鼓胀、"}, {"f": "audio/1c/school-sch-nj-103__3.mp3", "t": "肠覃、"}, {"f": "audio/1c/school-sch-nj-103__4.mp3", "t": "石瘕、"}, {"f": "audio/1c/school-sch-nj-103__5.mp3", "t": "石水，"}, {"f": "audio/1c/school-sch-nj-103__6.mp3", "t": "何以别之？"}, {"f": "audio/1c/school-sch-nj-103__7.mp3", "t": "岐伯答曰："}, {"f": "audio/1c/school-sch-nj-103__8.mp3", "t": "水始起也，"}, {"f": "audio/1c/school-sch-nj-103__9.mp3", "t": "目窠上微肿，"}, {"f": "audio/1c/school-sch-nj-103__10.mp3", "t": "如新卧起之状，"}, {"f": "audio/1c/school-sch-nj-103__11.mp3", "t": "其颈脉动，"}, {"f": "audio/1c/school-sch-nj-103__12.mp3", "t": "时咳，"}, {"f": "audio/1c/school-sch-nj-103__13.mp3", "t": "阴股间寒，"}, {"f": "audio/1c/school-sch-nj-103__14.mp3", "t": "足胫肿，"}, {"f": "audio/1c/school-sch-nj-103__15.mp3", "t": "腹乃大，"}, {"f": "audio/1c/school-sch-nj-103__16.mp3", "t": "其水已成矣。"}, {"f": "audio/1c/school-sch-nj-103__17.mp3", "t": "以手按其腹，"}, {"f": "audio/1c/school-sch-nj-103__18.mp3", "t": "随手而起，"}, {"f": "audio/1c/school-sch-nj-103__19.mp3", "t": "如裹水之状，"}, {"f": "audio/1c/school-sch-nj-103__20.mp3", "t": "此其候也。"}], "school-sch-nj-104": [{"f": "audio/5d/school-sch-nj-104__0.mp3", "t": "黄帝曰："}, {"f": "audio/5d/school-sch-nj-104__1.mp3", "t": "肤胀何以候之？"}, {"f": "audio/5d/school-sch-nj-104__2.mp3", "t": "岐伯曰："}, {"f": "audio/5d/school-sch-nj-104__3.mp3", "t": "肤胀者，"}, {"f": "audio/5d/school-sch-nj-104__4.mp3", "t": "寒气客于皮肤之间，"}, {"f": "audio/5d/school-sch-nj-104__5.mp3", "t": "𪔣𪔣然不坚，"}, {"f": "audio/5d/school-sch-nj-104__6.mp3", "t": "腹大，"}, {"f": "audio/5d/school-sch-nj-104__7.mp3", "t": "身尽肿，"}, {"f": "audio/5d/school-sch-nj-104__8.mp3", "t": "皮厚，"}, {"f": "audio/5d/school-sch-nj-104__9.mp3", "t": "按其腹，"}, {"f": "audio/5d/school-sch-nj-104__10.mp3", "t": "窅而不起，"}, {"f": "audio/5d/school-sch-nj-104__11.mp3", "t": "腹色不变，"}, {"f": "audio/5d/school-sch-nj-104__12.mp3", "t": "此其候也。"}], "school-sch-nj-105": [{"f": "audio/e9/school-sch-nj-105__0.mp3", "t": "鼓胀何如？"}, {"f": "audio/e9/school-sch-nj-105__1.mp3", "t": "岐伯曰："}, {"f": "audio/e9/school-sch-nj-105__2.mp3", "t": "腹胀身皆大，"}, {"f": "audio/e9/school-sch-nj-105__3.mp3", "t": "大与肤胀等也，"}, {"f": "audio/e9/school-sch-nj-105__4.mp3", "t": "色苍黄，"}, {"f": "audio/e9/school-sch-nj-105__5.mp3", "t": "腹筋起，"}, {"f": "audio/e9/school-sch-nj-105__6.mp3", "t": "此其候也。"}], "school-sch-nj-106": [{"f": "audio/15/school-sch-nj-106__0.mp3", "t": "肠覃何如？"}, {"f": "audio/15/school-sch-nj-106__1.mp3", "t": "岐伯曰："}, {"f": "audio/15/school-sch-nj-106__2.mp3", "t": "寒气客于肠外，"}, {"f": "audio/15/school-sch-nj-106__3.mp3", "t": "与卫气相搏，"}, {"f": "audio/15/school-sch-nj-106__4.mp3", "t": "气不得荣，"}, {"f": "audio/15/school-sch-nj-106__5.mp3", "t": "因有所系，"}, {"f": "audio/15/school-sch-nj-106__6.mp3", "t": "癖而内著，"}, {"f": "audio/15/school-sch-nj-106__7.mp3", "t": "恶气乃起，"}, {"f": "audio/15/school-sch-nj-106__8.mp3", "t": "瘜肉乃生。"}, {"f": "audio/15/school-sch-nj-106__9.mp3", "t": "其始生也，"}, {"f": "audio/15/school-sch-nj-106__10.mp3", "t": "大如鸡卵，"}, {"f": "audio/15/school-sch-nj-106__11.mp3", "t": "稍以益大，"}, {"f": "audio/15/school-sch-nj-106__12.mp3", "t": "至其成，"}, {"f": "audio/15/school-sch-nj-106__13.mp3", "t": "如怀子之状，"}, {"f": "audio/15/school-sch-nj-106__14.mp3", "t": "久者离岁，"}, {"f": "audio/15/school-sch-nj-106__15.mp3", "t": "按之则坚，"}, {"f": "audio/15/school-sch-nj-106__16.mp3", "t": "推之则移，"}, {"f": "audio/15/school-sch-nj-106__17.mp3", "t": "月事以时下，"}, {"f": "audio/15/school-sch-nj-106__18.mp3", "t": "此其候也。"}], "school-sch-nj-107": [{"f": "audio/b1/school-sch-nj-107__0.mp3", "t": "石瘕何如？"}, {"f": "audio/b1/school-sch-nj-107__1.mp3", "t": "岐伯曰："}, {"f": "audio/b1/school-sch-nj-107__2.mp3", "t": "石瘕生于胞中，"}, {"f": "audio/b1/school-sch-nj-107__3.mp3", "t": "寒气客于子门，"}, {"f": "audio/b1/school-sch-nj-107__4.mp3", "t": "子门闭塞，"}, {"f": "audio/b1/school-sch-nj-107__5.mp3", "t": "气不得通，"}, {"f": "audio/b1/school-sch-nj-107__6.mp3", "t": "恶血当写不写，"}, {"f": "audio/b1/school-sch-nj-107__7.mp3", "t": "衃以留止。"}, {"f": "audio/b1/school-sch-nj-107__8.mp3", "t": "日以益大，"}, {"f": "audio/b1/school-sch-nj-107__9.mp3", "t": "状如怀子，"}, {"f": "audio/b1/school-sch-nj-107__10.mp3", "t": "月事不以时下。"}, {"f": "audio/b1/school-sch-nj-107__11.mp3", "t": "皆生于女子，"}, {"f": "audio/b1/school-sch-nj-107__12.mp3", "t": "可导而下。"}], "school-sch-nj-108": [{"f": "audio/61/school-sch-nj-108__0.mp3", "t": "黄帝曰："}, {"f": "audio/61/school-sch-nj-108__1.mp3", "t": "肤胀、"}, {"f": "audio/61/school-sch-nj-108__2.mp3", "t": "鼓胀，"}, {"f": "audio/61/school-sch-nj-108__3.mp3", "t": "可刺邪？"}, {"f": "audio/61/school-sch-nj-108__4.mp3", "t": "岐伯曰："}, {"f": "audio/61/school-sch-nj-108__5.mp3", "t": "先写其胀之血络，"}, {"f": "audio/61/school-sch-nj-108__6.mp3", "t": "后调其经，"}, {"f": "audio/61/school-sch-nj-108__7.mp3", "t": "刺去其血络也。"}], "school-sch-nj-109": [{"f": "audio/db/school-sch-nj-109__0.mp3", "t": "黄帝问曰："}, {"f": "audio/db/school-sch-nj-109__1.mp3", "t": "诊法何如？"}, {"f": "audio/db/school-sch-nj-109__2.mp3", "t": "岐伯对曰："}, {"f": "audio/db/school-sch-nj-109__3.mp3", "t": "诊法常以平旦，"}, {"f": "audio/db/school-sch-nj-109__4.mp3", "t": "阴气未动，"}, {"f": "audio/db/school-sch-nj-109__5.mp3", "t": "阳气未散，"}, {"f": "audio/db/school-sch-nj-109__6.mp3", "t": "饮食未进，"}, {"f": "audio/db/school-sch-nj-109__7.mp3", "t": "经脉未盛，"}, {"f": "audio/db/school-sch-nj-109__8.mp3", "t": "络脉调匀，"}, {"f": "audio/db/school-sch-nj-109__9.mp3", "t": "气血未乱，"}, {"f": "audio/db/school-sch-nj-109__10.mp3", "t": "故乃可诊有过之脉。"}, {"f": "audio/db/school-sch-nj-109__11.mp3", "t": "切脉动静，"}, {"f": "audio/db/school-sch-nj-109__12.mp3", "t": "而视精明，"}, {"f": "audio/db/school-sch-nj-109__13.mp3", "t": "察五色，"}, {"f": "audio/db/school-sch-nj-109__14.mp3", "t": "观五藏有余不足，"}, {"f": "audio/db/school-sch-nj-109__15.mp3", "t": "六府强弱，"}, {"f": "audio/db/school-sch-nj-109__16.mp3", "t": "形之盛衰，"}, {"f": "audio/db/school-sch-nj-109__17.mp3", "t": "以此参伍，"}, {"f": "audio/db/school-sch-nj-109__18.mp3", "t": "决死生之分。"}], "school-sch-nj-110": [{"f": "audio/85/school-sch-nj-110__0.mp3", "t": "夫脉者，"}, {"f": "audio/85/school-sch-nj-110__1.mp3", "t": "血之府也。"}, {"f": "audio/85/school-sch-nj-110__2.mp3", "t": "长则气治；"}, {"f": "audio/85/school-sch-nj-110__3.mp3", "t": "短则气病；"}, {"f": "audio/85/school-sch-nj-110__4.mp3", "t": "数则烦心；"}, {"f": "audio/85/school-sch-nj-110__5.mp3", "t": "大则病进；"}, {"f": "audio/85/school-sch-nj-110__6.mp3", "t": "上盛则气高；"}, {"f": "audio/85/school-sch-nj-110__7.mp3", "t": "下盛则气胀；"}, {"f": "audio/85/school-sch-nj-110__8.mp3", "t": "代则气衰；"}, {"f": "audio/85/school-sch-nj-110__9.mp3", "t": "细则气少；"}, {"f": "audio/85/school-sch-nj-110__10.mp3", "t": "涩则心痛；"}, {"f": "audio/85/school-sch-nj-110__11.mp3", "t": "浑浑革至如涌泉，"}, {"f": "audio/85/school-sch-nj-110__12.mp3", "t": "病进而色弊；"}, {"f": "audio/85/school-sch-nj-110__13.mp3", "t": "绵绵其去如弦绝，"}, {"f": "audio/85/school-sch-nj-110__14.mp3", "t": "死。"}], "school-sch-nj-111": [{"f": "audio/3a/school-sch-nj-111__0.mp3", "t": "夫精明五色者，"}, {"f": "audio/3a/school-sch-nj-111__1.mp3", "t": "气之华也。"}, {"f": "audio/3a/school-sch-nj-111__2.mp3", "t": "赤欲如白裹朱，"}, {"f": "audio/3a/school-sch-nj-111__3.mp3", "t": "不欲如赭；"}, {"f": "audio/3a/school-sch-nj-111__4.mp3", "t": "白欲如鹅羽，"}, {"f": "audio/3a/school-sch-nj-111__5.mp3", "t": "不欲如盐，"}, {"f": "audio/3a/school-sch-nj-111__6.mp3", "t": "青欲如苍璧之泽，"}, {"f": "audio/3a/school-sch-nj-111__7.mp3", "t": "不欲如蓝；"}, {"f": "audio/3a/school-sch-nj-111__8.mp3", "t": "黄欲如罗裹雄黄，"}, {"f": "audio/3a/school-sch-nj-111__9.mp3", "t": "不欲如黄土；"}, {"f": "audio/3a/school-sch-nj-111__10.mp3", "t": "黑欲如重漆色，"}, {"f": "audio/3a/school-sch-nj-111__11.mp3", "t": "不欲如地苍。"}, {"f": "audio/3a/school-sch-nj-111__12.mp3", "t": "五色精微象见矣，"}, {"f": "audio/3a/school-sch-nj-111__13.mp3", "t": "其寿不久也。"}, {"f": "audio/3a/school-sch-nj-111__14.mp3", "t": "夫精明者，"}, {"f": "audio/3a/school-sch-nj-111__15.mp3", "t": "所以视万物，"}, {"f": "audio/3a/school-sch-nj-111__16.mp3", "t": "别白黑，"}, {"f": "audio/3a/school-sch-nj-111__17.mp3", "t": "审短长，"}, {"f": "audio/3a/school-sch-nj-111__18.mp3", "t": "以长为短，"}, {"f": "audio/3a/school-sch-nj-111__19.mp3", "t": "以白为黑，"}, {"f": "audio/3a/school-sch-nj-111__20.mp3", "t": "如是则精衰矣。"}], "school-sch-nj-112": [{"f": "audio/d0/school-sch-nj-112__0.mp3", "t": "五藏者，"}, {"f": "audio/d0/school-sch-nj-112__1.mp3", "t": "中之守也。"}, {"f": "audio/d0/school-sch-nj-112__2.mp3", "t": "中盛藏满，"}, {"f": "audio/d0/school-sch-nj-112__3.mp3", "t": "气胜伤恐者，"}, {"f": "audio/d0/school-sch-nj-112__4.mp3", "t": "声如从室中言，"}, {"f": "audio/d0/school-sch-nj-112__5.mp3", "t": "是中气之湿也；"}, {"f": "audio/d0/school-sch-nj-112__6.mp3", "t": "言而微，"}, {"f": "audio/d0/school-sch-nj-112__7.mp3", "t": "终日乃复言者，"}, {"f": "audio/d0/school-sch-nj-112__8.mp3", "t": "此夺气也；"}, {"f": "audio/d0/school-sch-nj-112__9.mp3", "t": "衣被不敛，"}, {"f": "audio/d0/school-sch-nj-112__10.mp3", "t": "言语善恶不避亲疏者，"}, {"f": "audio/d0/school-sch-nj-112__11.mp3", "t": "此神明之乱也；"}, {"f": "audio/d0/school-sch-nj-112__12.mp3", "t": "仓廪不藏者，"}, {"f": "audio/d0/school-sch-nj-112__13.mp3", "t": "是门户不要也；"}, {"f": "audio/d0/school-sch-nj-112__14.mp3", "t": "水泉不止者，"}, {"f": "audio/d0/school-sch-nj-112__15.mp3", "t": "是膀胱不藏也。"}, {"f": "audio/d0/school-sch-nj-112__16.mp3", "t": "得守者生，"}, {"f": "audio/d0/school-sch-nj-112__17.mp3", "t": "失守者死。"}], "school-sch-nj-113": [{"f": "audio/ef/school-sch-nj-113__0.mp3", "t": "夫五藏者，"}, {"f": "audio/ef/school-sch-nj-113__1.mp3", "t": "身之强也。"}, {"f": "audio/ef/school-sch-nj-113__2.mp3", "t": "头者，"}, {"f": "audio/ef/school-sch-nj-113__3.mp3", "t": "精明之府，"}, {"f": "audio/ef/school-sch-nj-113__4.mp3", "t": "头倾视深，"}, {"f": "audio/ef/school-sch-nj-113__5.mp3", "t": "精神将夺矣；"}, {"f": "audio/ef/school-sch-nj-113__6.mp3", "t": "背者，"}, {"f": "audio/ef/school-sch-nj-113__7.mp3", "t": "胸中之府，"}, {"f": "audio/ef/school-sch-nj-113__8.mp3", "t": "背曲肩随，"}, {"f": "audio/ef/school-sch-nj-113__9.mp3", "t": "府将坏矣；"}, {"f": "audio/ef/school-sch-nj-113__10.mp3", "t": "腰者，"}, {"f": "audio/ef/school-sch-nj-113__11.mp3", "t": "肾之府，"}, {"f": "audio/ef/school-sch-nj-113__12.mp3", "t": "转摇不能，"}, {"f": "audio/ef/school-sch-nj-113__13.mp3", "t": "肾将惫矣；"}, {"f": "audio/ef/school-sch-nj-113__14.mp3", "t": "膝者，"}, {"f": "audio/ef/school-sch-nj-113__15.mp3", "t": "筋之府，"}, {"f": "audio/ef/school-sch-nj-113__16.mp3", "t": "屈伸不能，"}, {"f": "audio/ef/school-sch-nj-113__17.mp3", "t": "行则偻附，"}, {"f": "audio/ef/school-sch-nj-113__18.mp3", "t": "筋将惫矣；"}, {"f": "audio/ef/school-sch-nj-113__19.mp3", "t": "骨者，"}, {"f": "audio/ef/school-sch-nj-113__20.mp3", "t": "髓之府，"}, {"f": "audio/ef/school-sch-nj-113__21.mp3", "t": "不能久立，"}, {"f": "audio/ef/school-sch-nj-113__22.mp3", "t": "行则振掉，"}, {"f": "audio/ef/school-sch-nj-113__23.mp3", "t": "骨将惫矣。"}, {"f": "audio/ef/school-sch-nj-113__24.mp3", "t": "得强则生，"}, {"f": "audio/ef/school-sch-nj-113__25.mp3", "t": "失强则死。"}], "school-sch-nj-114": [{"f": "audio/2f/school-sch-nj-114__0.mp3", "t": "帝曰："}, {"f": "audio/2f/school-sch-nj-114__1.mp3", "t": "脉其四时动奈何？"}, {"f": "audio/2f/school-sch-nj-114__2.mp3", "t": "知病之所在奈何？"}, {"f": "audio/2f/school-sch-nj-114__3.mp3", "t": "知病之所变奈何？"}, {"f": "audio/2f/school-sch-nj-114__4.mp3", "t": "知病乍在内奈何？"}, {"f": "audio/2f/school-sch-nj-114__5.mp3", "t": "知病乍在外奈何？"}, {"f": "audio/2f/school-sch-nj-114__6.mp3", "t": "请问此五者，"}, {"f": "audio/2f/school-sch-nj-114__7.mp3", "t": "可得闻乎？"}, {"f": "audio/2f/school-sch-nj-114__8.mp3", "t": "岐伯曰："}, {"f": "audio/2f/school-sch-nj-114__9.mp3", "t": "请言其与天运转大也。"}, {"f": "audio/2f/school-sch-nj-114__10.mp3", "t": "万物之外，"}, {"f": "audio/2f/school-sch-nj-114__11.mp3", "t": "六合之内，"}, {"f": "audio/2f/school-sch-nj-114__12.mp3", "t": "天地之变，"}, {"f": "audio/2f/school-sch-nj-114__13.mp3", "t": "阴阳之应，"}, {"f": "audio/2f/school-sch-nj-114__14.mp3", "t": "彼春之暖，"}, {"f": "audio/2f/school-sch-nj-114__15.mp3", "t": "为夏之暑，"}, {"f": "audio/2f/school-sch-nj-114__16.mp3", "t": "彼秋之忿，"}, {"f": "audio/2f/school-sch-nj-114__17.mp3", "t": "为冬之怒。"}, {"f": "audio/2f/school-sch-nj-114__18.mp3", "t": "四变之动，"}, {"f": "audio/2f/school-sch-nj-114__19.mp3", "t": "脉与之上下，"}, {"f": "audio/2f/school-sch-nj-114__20.mp3", "t": "以春应中规，"}, {"f": "audio/2f/school-sch-nj-114__21.mp3", "t": "夏应中矩，"}, {"f": "audio/2f/school-sch-nj-114__22.mp3", "t": "秋应中衡，"}, {"f": "audio/2f/school-sch-nj-114__23.mp3", "t": "冬应中权。"}, {"f": "audio/2f/school-sch-nj-114__24.mp3", "t": "是故冬至四十五日，"}, {"f": "audio/2f/school-sch-nj-114__25.mp3", "t": "阳气微上，"}, {"f": "audio/2f/school-sch-nj-114__26.mp3", "t": "阴气微下；"}, {"f": "audio/2f/school-sch-nj-114__27.mp3", "t": "夏至四十五日，"}, {"f": "audio/2f/school-sch-nj-114__28.mp3", "t": "阴气微上，"}, {"f": "audio/2f/school-sch-nj-114__29.mp3", "t": "阳气微下。"}, {"f": "audio/2f/school-sch-nj-114__30.mp3", "t": "阴阳有时，"}, {"f": "audio/2f/school-sch-nj-114__31.mp3", "t": "与脉为期，"}, {"f": "audio/2f/school-sch-nj-114__32.mp3", "t": "期而相失，"}, {"f": "audio/2f/school-sch-nj-114__33.mp3", "t": "知脉所分，"}, {"f": "audio/2f/school-sch-nj-114__34.mp3", "t": "分之有期，"}, {"f": "audio/2f/school-sch-nj-114__35.mp3", "t": "故知死时。"}, {"f": "audio/2f/school-sch-nj-114__36.mp3", "t": "微妙在脉，"}, {"f": "audio/2f/school-sch-nj-114__37.mp3", "t": "不可不察，"}, {"f": "audio/2f/school-sch-nj-114__38.mp3", "t": "察之有纪，"}, {"f": "audio/2f/school-sch-nj-114__39.mp3", "t": "从阴阳始，"}, {"f": "audio/2f/school-sch-nj-114__40.mp3", "t": "始之有经，"}, {"f": "audio/2f/school-sch-nj-114__41.mp3", "t": "从五行生，"}, {"f": "audio/2f/school-sch-nj-114__42.mp3", "t": "生之有度，"}, {"f": "audio/2f/school-sch-nj-114__43.mp3", "t": "四时为宜。"}, {"f": "audio/2f/school-sch-nj-114__44.mp3", "t": "补泻勿失，"}, {"f": "audio/2f/school-sch-nj-114__45.mp3", "t": "与天地如一，"}, {"f": "audio/2f/school-sch-nj-114__46.mp3", "t": "得一之情，"}, {"f": "audio/2f/school-sch-nj-114__47.mp3", "t": "以知死生。"}, {"f": "audio/2f/school-sch-nj-114__48.mp3", "t": "是故声合五音，"}, {"f": "audio/2f/school-sch-nj-114__49.mp3", "t": "色合五行，"}, {"f": "audio/2f/school-sch-nj-114__50.mp3", "t": "脉合阴阳。"}], "school-sch-nj-115": [{"f": "audio/f2/school-sch-nj-115__0.mp3", "t": "是故持脉有道，"}, {"f": "audio/f2/school-sch-nj-115__1.mp3", "t": "虚静为保。"}, {"f": "audio/f2/school-sch-nj-115__2.mp3", "t": "春日浮，"}, {"f": "audio/f2/school-sch-nj-115__3.mp3", "t": "如鱼之游在波；"}, {"f": "audio/f2/school-sch-nj-115__4.mp3", "t": "夏日在肤，"}, {"f": "audio/f2/school-sch-nj-115__5.mp3", "t": "泛泛乎万物有余；"}, {"f": "audio/f2/school-sch-nj-115__6.mp3", "t": "秋日下肤，"}, {"f": "audio/f2/school-sch-nj-115__7.mp3", "t": "蛰虫将去；"}, {"f": "audio/f2/school-sch-nj-115__8.mp3", "t": "冬日在骨，"}, {"f": "audio/f2/school-sch-nj-115__9.mp3", "t": "蛰虫周密，"}, {"f": "audio/f2/school-sch-nj-115__10.mp3", "t": "君子居室。"}, {"f": "audio/f2/school-sch-nj-115__11.mp3", "t": "故曰："}, {"f": "audio/f2/school-sch-nj-115__12.mp3", "t": "知内者按而纪之，"}, {"f": "audio/f2/school-sch-nj-115__13.mp3", "t": "知外者终而始之。"}, {"f": "audio/f2/school-sch-nj-115__14.mp3", "t": "此六者，"}, {"f": "audio/f2/school-sch-nj-115__15.mp3", "t": "持脉之大法。"}], "school-sch-nj-116": [{"f": "audio/4a/school-sch-nj-116__0.mp3", "t": "黄帝问曰："}, {"f": "audio/4a/school-sch-nj-116__1.mp3", "t": "平人何如？"}, {"f": "audio/4a/school-sch-nj-116__2.mp3", "t": "岐伯对曰："}, {"f": "audio/4a/school-sch-nj-116__3.mp3", "t": "人一呼脉再动，"}, {"f": "audio/4a/school-sch-nj-116__4.mp3", "t": "一吸脉亦再动，"}, {"f": "audio/4a/school-sch-nj-116__5.mp3", "t": "呼吸定息脉五动，"}, {"f": "audio/4a/school-sch-nj-116__6.mp3", "t": "闰以太息，"}, {"f": "audio/4a/school-sch-nj-116__7.mp3", "t": "命曰平人。"}, {"f": "audio/4a/school-sch-nj-116__8.mp3", "t": "平人者，"}, {"f": "audio/4a/school-sch-nj-116__9.mp3", "t": "不病也。"}, {"f": "audio/4a/school-sch-nj-116__10.mp3", "t": "常以不病调病人，"}, {"f": "audio/4a/school-sch-nj-116__11.mp3", "t": "医不病，"}, {"f": "audio/4a/school-sch-nj-116__12.mp3", "t": "故为病人平息以调之为法。"}, {"f": "audio/4a/school-sch-nj-116__13.mp3", "t": "人一呼脉一动，"}, {"f": "audio/4a/school-sch-nj-116__14.mp3", "t": "一吸脉一动，"}, {"f": "audio/4a/school-sch-nj-116__15.mp3", "t": "曰少气。"}, {"f": "audio/4a/school-sch-nj-116__16.mp3", "t": "人一呼脉三动，"}, {"f": "audio/4a/school-sch-nj-116__17.mp3", "t": "一吸脉三动而躁，"}, {"f": "audio/4a/school-sch-nj-116__18.mp3", "t": "尺热曰病温，"}, {"f": "audio/4a/school-sch-nj-116__19.mp3", "t": "尺不热脉滑曰病风，"}, {"f": "audio/4a/school-sch-nj-116__20.mp3", "t": "脉涩曰痹。"}, {"f": "audio/4a/school-sch-nj-116__21.mp3", "t": "人一呼吸脉四动以上曰死，"}, {"f": "audio/4a/school-sch-nj-116__22.mp3", "t": "脉绝不至曰死，"}, {"f": "audio/4a/school-sch-nj-116__23.mp3", "t": "乍疏乍数曰死。"}], "school-sch-nj-117": [{"f": "audio/1a/school-sch-nj-117__0.mp3", "t": "平人之常气禀于胃，"}, {"f": "audio/1a/school-sch-nj-117__1.mp3", "t": "胃者平人之常气也，"}, {"f": "audio/1a/school-sch-nj-117__2.mp3", "t": "人无胃气曰逆，"}, {"f": "audio/1a/school-sch-nj-117__3.mp3", "t": "逆者死。"}, {"f": "audio/1a/school-sch-nj-117__4.mp3", "t": "春胃微弦曰平，"}, {"f": "audio/1a/school-sch-nj-117__5.mp3", "t": "弦多胃少曰肝病，"}, {"f": "audio/1a/school-sch-nj-117__6.mp3", "t": "但弦无胃曰死，"}, {"f": "audio/1a/school-sch-nj-117__7.mp3", "t": "胃而有毛曰秋病，"}, {"f": "audio/1a/school-sch-nj-117__8.mp3", "t": "毛甚曰今病。"}, {"f": "audio/1a/school-sch-nj-117__9.mp3", "t": "藏真散于肝，"}, {"f": "audio/1a/school-sch-nj-117__10.mp3", "t": "肝藏筋膜之气也。"}, {"f": "audio/1a/school-sch-nj-117__11.mp3", "t": "夏胃微钩曰平，"}, {"f": "audio/1a/school-sch-nj-117__12.mp3", "t": "钩多胃少曰心病，"}, {"f": "audio/1a/school-sch-nj-117__13.mp3", "t": "但钩无胃曰死，"}, {"f": "audio/1a/school-sch-nj-117__14.mp3", "t": "胃而有石曰冬病，"}, {"f": "audio/1a/school-sch-nj-117__15.mp3", "t": "石甚曰今病。"}, {"f": "audio/1a/school-sch-nj-117__16.mp3", "t": "藏真通于心，"}, {"f": "audio/1a/school-sch-nj-117__17.mp3", "t": "心藏血脉之气也。"}, {"f": "audio/1a/school-sch-nj-117__18.mp3", "t": "长夏胃微软弱曰平，"}, {"f": "audio/1a/school-sch-nj-117__19.mp3", "t": "弱多胃少曰脾病，"}, {"f": "audio/1a/school-sch-nj-117__20.mp3", "t": "但代无胃曰死，"}, {"f": "audio/1a/school-sch-nj-117__21.mp3", "t": "软弱有石曰冬病，"}, {"f": "audio/1a/school-sch-nj-117__22.mp3", "t": "弱甚曰今病。"}, {"f": "audio/1a/school-sch-nj-117__23.mp3", "t": "藏真濡于脾，"}, {"f": "audio/1a/school-sch-nj-117__24.mp3", "t": "脾藏肌肉之气也。"}, {"f": "audio/1a/school-sch-nj-117__25.mp3", "t": "秋胃微毛曰平，"}, {"f": "audio/1a/school-sch-nj-117__26.mp3", "t": "毛多胃少曰肺病，"}, {"f": "audio/1a/school-sch-nj-117__27.mp3", "t": "但毛无胃曰死。"}, {"f": "audio/1a/school-sch-nj-117__28.mp3", "t": "毛而有弦曰春病，"}, {"f": "audio/1a/school-sch-nj-117__29.mp3", "t": "弦甚曰今病。"}, {"f": "audio/1a/school-sch-nj-117__30.mp3", "t": "藏真高于肺，"}, {"f": "audio/1a/school-sch-nj-117__31.mp3", "t": "以行营卫阴阳也。"}, {"f": "audio/1a/school-sch-nj-117__32.mp3", "t": "冬胃微石曰平，"}, {"f": "audio/1a/school-sch-nj-117__33.mp3", "t": "石多胃少曰肾病，"}, {"f": "audio/1a/school-sch-nj-117__34.mp3", "t": "但石无胃曰死，"}, {"f": "audio/1a/school-sch-nj-117__35.mp3", "t": "石而有钩曰夏病，"}, {"f": "audio/1a/school-sch-nj-117__36.mp3", "t": "钩甚曰今病。"}, {"f": "audio/1a/school-sch-nj-117__37.mp3", "t": "藏真下于肾，"}, {"f": "audio/1a/school-sch-nj-117__38.mp3", "t": "肾藏骨髓之气也。"}], "school-sch-nj-118": [{"f": "audio/f8/school-sch-nj-118__0.mp3", "t": "胃之大络，"}, {"f": "audio/f8/school-sch-nj-118__1.mp3", "t": "名曰虚里，"}, {"f": "audio/f8/school-sch-nj-118__2.mp3", "t": "贯鬲络肺，"}, {"f": "audio/f8/school-sch-nj-118__3.mp3", "t": "出于左乳下，"}, {"f": "audio/f8/school-sch-nj-118__4.mp3", "t": "其动应衣，"}, {"f": "audio/f8/school-sch-nj-118__5.mp3", "t": "脉宗气也。"}, {"f": "audio/f8/school-sch-nj-118__6.mp3", "t": "盛喘数绝者，"}, {"f": "audio/f8/school-sch-nj-118__7.mp3", "t": "则病在中；"}, {"f": "audio/f8/school-sch-nj-118__8.mp3", "t": "结而横，"}, {"f": "audio/f8/school-sch-nj-118__9.mp3", "t": "有积矣；"}, {"f": "audio/f8/school-sch-nj-118__10.mp3", "t": "绝不至曰死。"}, {"f": "audio/f8/school-sch-nj-118__11.mp3", "t": "乳之下，"}, {"f": "audio/f8/school-sch-nj-118__12.mp3", "t": "其动应衣，"}, {"f": "audio/f8/school-sch-nj-118__13.mp3", "t": "宗气泄也。"}], "school-sch-nj-119": [{"f": "audio/a6/school-sch-nj-119__0.mp3", "t": "五藏受气于其所生，"}, {"f": "audio/a6/school-sch-nj-119__1.mp3", "t": "传之于其所胜，"}, {"f": "audio/a6/school-sch-nj-119__2.mp3", "t": "气舍于其所生，"}, {"f": "audio/a6/school-sch-nj-119__3.mp3", "t": "死于其所不胜。"}, {"f": "audio/a6/school-sch-nj-119__4.mp3", "t": "病之且死，"}, {"f": "audio/a6/school-sch-nj-119__5.mp3", "t": "必先传行，"}, {"f": "audio/a6/school-sch-nj-119__6.mp3", "t": "至其所不胜，"}, {"f": "audio/a6/school-sch-nj-119__7.mp3", "t": "病乃死。"}, {"f": "audio/a6/school-sch-nj-119__8.mp3", "t": "此言气之逆行也，"}, {"f": "audio/a6/school-sch-nj-119__9.mp3", "t": "故死。"}, {"f": "audio/a6/school-sch-nj-119__10.mp3", "t": "肝受气于心，"}, {"f": "audio/a6/school-sch-nj-119__11.mp3", "t": "传之于脾，"}, {"f": "audio/a6/school-sch-nj-119__12.mp3", "t": "气舍于肾，"}, {"f": "audio/a6/school-sch-nj-119__13.mp3", "t": "至肺而死。"}, {"f": "audio/a6/school-sch-nj-119__14.mp3", "t": "心受气于脾，"}, {"f": "audio/a6/school-sch-nj-119__15.mp3", "t": "传之于肺，"}, {"f": "audio/a6/school-sch-nj-119__16.mp3", "t": "气舍于肝，"}, {"f": "audio/a6/school-sch-nj-119__17.mp3", "t": "至肾而死。"}, {"f": "audio/a6/school-sch-nj-119__18.mp3", "t": "脾受气于肺，"}, {"f": "audio/a6/school-sch-nj-119__19.mp3", "t": "传之于肾，"}, {"f": "audio/a6/school-sch-nj-119__20.mp3", "t": "气舍于心，"}, {"f": "audio/a6/school-sch-nj-119__21.mp3", "t": "至肝而死。"}, {"f": "audio/a6/school-sch-nj-119__22.mp3", "t": "肺受气于肾，"}, {"f": "audio/a6/school-sch-nj-119__23.mp3", "t": "传之于肝，"}, {"f": "audio/a6/school-sch-nj-119__24.mp3", "t": "气舍于脾，"}, {"f": "audio/a6/school-sch-nj-119__25.mp3", "t": "至心而死。"}, {"f": "audio/a6/school-sch-nj-119__26.mp3", "t": "肾受气于肝，"}, {"f": "audio/a6/school-sch-nj-119__27.mp3", "t": "传之于心，"}, {"f": "audio/a6/school-sch-nj-119__28.mp3", "t": "气舍于肺，"}, {"f": "audio/a6/school-sch-nj-119__29.mp3", "t": "至脾而死。"}, {"f": "audio/a6/school-sch-nj-119__30.mp3", "t": "此皆逆死也，"}, {"f": "audio/a6/school-sch-nj-119__31.mp3", "t": "一日一夜五分之，"}, {"f": "audio/a6/school-sch-nj-119__32.mp3", "t": "此所以占死生之早暮也。"}, {"f": "audio/a6/school-sch-nj-119__33.mp3", "t": "黄帝曰："}, {"f": "audio/a6/school-sch-nj-119__34.mp3", "t": "五藏相通，"}, {"f": "audio/a6/school-sch-nj-119__35.mp3", "t": "移皆有次。"}, {"f": "audio/a6/school-sch-nj-119__36.mp3", "t": "五藏有病，"}, {"f": "audio/a6/school-sch-nj-119__37.mp3", "t": "则各传其所胜。"}, {"f": "audio/a6/school-sch-nj-119__38.mp3", "t": "不治，"}, {"f": "audio/a6/school-sch-nj-119__39.mp3", "t": "法三月若六月，"}, {"f": "audio/a6/school-sch-nj-119__40.mp3", "t": "若三日若六日，"}, {"f": "audio/a6/school-sch-nj-119__41.mp3", "t": "传五藏而当死，"}, {"f": "audio/a6/school-sch-nj-119__42.mp3", "t": "是顺传所胜之次。"}, {"f": "audio/a6/school-sch-nj-119__43.mp3", "t": "故曰："}, {"f": "audio/a6/school-sch-nj-119__44.mp3", "t": "\"别于阳者，"}, {"f": "audio/a6/school-sch-nj-119__45.mp3", "t": "知病从来；"}, {"f": "audio/a6/school-sch-nj-119__46.mp3", "t": "别于阴者，"}, {"f": "audio/a6/school-sch-nj-119__47.mp3", "t": "知死生之期。"}, {"f": "audio/a6/school-sch-nj-119__48.mp3", "t": "\"言知至其所困而死。"}], "school-sch-nj-120": [{"f": "audio/bc/school-sch-nj-120__0.mp3", "t": "黄帝曰："}, {"f": "audio/bc/school-sch-nj-120__1.mp3", "t": "余闻虚实以决死生，"}, {"f": "audio/bc/school-sch-nj-120__2.mp3", "t": "愿闻其情。"}, {"f": "audio/bc/school-sch-nj-120__3.mp3", "t": "岐伯曰："}, {"f": "audio/bc/school-sch-nj-120__4.mp3", "t": "五实死，"}, {"f": "audio/bc/school-sch-nj-120__5.mp3", "t": "五虚死。"}, {"f": "audio/bc/school-sch-nj-120__6.mp3", "t": "帝曰："}, {"f": "audio/bc/school-sch-nj-120__7.mp3", "t": "愿闻五实五虚。"}, {"f": "audio/bc/school-sch-nj-120__8.mp3", "t": "岐伯曰："}, {"f": "audio/bc/school-sch-nj-120__9.mp3", "t": "脉盛，"}, {"f": "audio/bc/school-sch-nj-120__10.mp3", "t": "皮热，"}, {"f": "audio/bc/school-sch-nj-120__11.mp3", "t": "腹胀，"}, {"f": "audio/bc/school-sch-nj-120__12.mp3", "t": "前后不通，"}, {"f": "audio/bc/school-sch-nj-120__13.mp3", "t": "闷瞀，"}, {"f": "audio/bc/school-sch-nj-120__14.mp3", "t": "此谓五实；"}, {"f": "audio/bc/school-sch-nj-120__15.mp3", "t": "脉细、"}, {"f": "audio/bc/school-sch-nj-120__16.mp3", "t": "皮寒、"}, {"f": "audio/bc/school-sch-nj-120__17.mp3", "t": "气少、"}, {"f": "audio/bc/school-sch-nj-120__18.mp3", "t": "泄利前后、"}, {"f": "audio/bc/school-sch-nj-120__19.mp3", "t": "饮食不入，"}, {"f": "audio/bc/school-sch-nj-120__20.mp3", "t": "此谓五虚。"}, {"f": "audio/bc/school-sch-nj-120__21.mp3", "t": "帝曰："}, {"f": "audio/bc/school-sch-nj-120__22.mp3", "t": "其时有生者何也？"}, {"f": "audio/bc/school-sch-nj-120__23.mp3", "t": "岐伯曰："}, {"f": "audio/bc/school-sch-nj-120__24.mp3", "t": "浆粥入胃，"}, {"f": "audio/bc/school-sch-nj-120__25.mp3", "t": "泄注止，"}, {"f": "audio/bc/school-sch-nj-120__26.mp3", "t": "则虚者活；"}, {"f": "audio/bc/school-sch-nj-120__27.mp3", "t": "身汗得后利，"}, {"f": "audio/bc/school-sch-nj-120__28.mp3", "t": "则实者活。"}, {"f": "audio/bc/school-sch-nj-120__29.mp3", "t": "此其候也。"}], "school-sch-nj-121": [{"f": "audio/20/school-sch-nj-121__0.mp3", "t": "黄帝曰："}, {"f": "audio/20/school-sch-nj-121__1.mp3", "t": "医之治病也，"}, {"f": "audio/20/school-sch-nj-121__2.mp3", "t": "一病而治各不同，"}, {"f": "audio/20/school-sch-nj-121__3.mp3", "t": "皆愈何也？"}, {"f": "audio/20/school-sch-nj-121__4.mp3", "t": "岐伯对曰："}, {"f": "audio/20/school-sch-nj-121__5.mp3", "t": "地势使然也。"}, {"f": "audio/20/school-sch-nj-121__6.mp3", "t": "故东方之域，"}, {"f": "audio/20/school-sch-nj-121__7.mp3", "t": "天地之所始生也。"}, {"f": "audio/20/school-sch-nj-121__8.mp3", "t": "鱼盐之地，"}, {"f": "audio/20/school-sch-nj-121__9.mp3", "t": "海滨傍水，"}, {"f": "audio/20/school-sch-nj-121__10.mp3", "t": "其民食鱼而嗜咸，"}, {"f": "audio/20/school-sch-nj-121__11.mp3", "t": "皆安其处，"}, {"f": "audio/20/school-sch-nj-121__12.mp3", "t": "美其食。"}, {"f": "audio/20/school-sch-nj-121__13.mp3", "t": "鱼者，"}, {"f": "audio/20/school-sch-nj-121__14.mp3", "t": "使人热中，"}, {"f": "audio/20/school-sch-nj-121__15.mp3", "t": "盐者胜血，"}, {"f": "audio/20/school-sch-nj-121__16.mp3", "t": "故其民皆黑色疏理，"}, {"f": "audio/20/school-sch-nj-121__17.mp3", "t": "其病皆为痈疡，"}, {"f": "audio/20/school-sch-nj-121__18.mp3", "t": "其治宜砭石。"}, {"f": "audio/20/school-sch-nj-121__19.mp3", "t": "故砭石者，"}, {"f": "audio/20/school-sch-nj-121__20.mp3", "t": "亦从东方来。"}, {"f": "audio/20/school-sch-nj-121__21.mp3", "t": "西方者，"}, {"f": "audio/20/school-sch-nj-121__22.mp3", "t": "金玉之域，"}, {"f": "audio/20/school-sch-nj-121__23.mp3", "t": "沙石之处，"}, {"f": "audio/20/school-sch-nj-121__24.mp3", "t": "天地之所收引也。"}, {"f": "audio/20/school-sch-nj-121__25.mp3", "t": "其民陵居而多风，"}, {"f": "audio/20/school-sch-nj-121__26.mp3", "t": "水土刚强，"}, {"f": "audio/20/school-sch-nj-121__27.mp3", "t": "其民不衣而褐荐，"}, {"f": "audio/20/school-sch-nj-121__28.mp3", "t": "其民华食而脂肥，"}, {"f": "audio/20/school-sch-nj-121__29.mp3", "t": "故邪不能伤其形体，"}, {"f": "audio/20/school-sch-nj-121__30.mp3", "t": "其病生于内，"}, {"f": "audio/20/school-sch-nj-121__31.mp3", "t": "其治宜毒药。"}, {"f": "audio/20/school-sch-nj-121__32.mp3", "t": "故毒药者，"}, {"f": "audio/20/school-sch-nj-121__33.mp3", "t": "亦从西方来。"}, {"f": "audio/20/school-sch-nj-121__34.mp3", "t": "北方者，"}, {"f": "audio/20/school-sch-nj-121__35.mp3", "t": "天地所闭藏之域也。"}, {"f": "audio/20/school-sch-nj-121__36.mp3", "t": "其地高陵居，"}, {"f": "audio/20/school-sch-nj-121__37.mp3", "t": "风寒冰冽。"}, {"f": "audio/20/school-sch-nj-121__38.mp3", "t": "其民乐野处而乳食，"}, {"f": "audio/20/school-sch-nj-121__39.mp3", "t": "藏寒生满病，"}, {"f": "audio/20/school-sch-nj-121__40.mp3", "t": "其治宜灸焫。"}, {"f": "audio/20/school-sch-nj-121__41.mp3", "t": "故灸焫者，"}, {"f": "audio/20/school-sch-nj-121__42.mp3", "t": "亦从北方来。"}, {"f": "audio/20/school-sch-nj-121__43.mp3", "t": "南方者，"}, {"f": "audio/20/school-sch-nj-121__44.mp3", "t": "天地所长养，"}, {"f": "audio/20/school-sch-nj-121__45.mp3", "t": "阳之所盛处也。"}, {"f": "audio/20/school-sch-nj-121__46.mp3", "t": "其地下，"}, {"f": "audio/20/school-sch-nj-121__47.mp3", "t": "水土弱，"}, {"f": "audio/20/school-sch-nj-121__48.mp3", "t": "雾露之所聚也。"}, {"f": "audio/20/school-sch-nj-121__49.mp3", "t": "其民嗜酸而食胕，"}, {"f": "audio/20/school-sch-nj-121__50.mp3", "t": "故其民皆致理而赤色，"}, {"f": "audio/20/school-sch-nj-121__51.mp3", "t": "其病挛痹，"}, {"f": "audio/20/school-sch-nj-121__52.mp3", "t": "其治宜微针。"}, {"f": "audio/20/school-sch-nj-121__53.mp3", "t": "故九针者，"}, {"f": "audio/20/school-sch-nj-121__54.mp3", "t": "亦从南方来。"}, {"f": "audio/20/school-sch-nj-121__55.mp3", "t": "中央者，"}, {"f": "audio/20/school-sch-nj-121__56.mp3", "t": "其地平以湿，"}, {"f": "audio/20/school-sch-nj-121__57.mp3", "t": "天地所以生万物也众。"}, {"f": "audio/20/school-sch-nj-121__58.mp3", "t": "其民食杂而不劳，"}, {"f": "audio/20/school-sch-nj-121__59.mp3", "t": "故其病多痿厥寒热，"}, {"f": "audio/20/school-sch-nj-121__60.mp3", "t": "其治宜导引按跷。"}, {"f": "audio/20/school-sch-nj-121__61.mp3", "t": "故导引按跷者，"}, {"f": "audio/20/school-sch-nj-121__62.mp3", "t": "亦从中央出也。"}, {"f": "audio/20/school-sch-nj-121__63.mp3", "t": "故圣人杂合以治，"}, {"f": "audio/20/school-sch-nj-121__64.mp3", "t": "各得其所宜。"}, {"f": "audio/20/school-sch-nj-121__65.mp3", "t": "故治所以异而病皆愈者，"}, {"f": "audio/20/school-sch-nj-121__66.mp3", "t": "得病之情，"}, {"f": "audio/20/school-sch-nj-121__67.mp3", "t": "知治之大体也。"}], "school-sch-nj-122": [{"f": "audio/f5/school-sch-nj-122__0.mp3", "t": "黄帝曰："}, {"f": "audio/f5/school-sch-nj-122__1.mp3", "t": "为五谷汤液及醪醴奈何？"}, {"f": "audio/f5/school-sch-nj-122__2.mp3", "t": "岐伯对曰："}, {"f": "audio/f5/school-sch-nj-122__3.mp3", "t": "必以稻米，"}, {"f": "audio/f5/school-sch-nj-122__4.mp3", "t": "炊之稻薪，"}, {"f": "audio/f5/school-sch-nj-122__5.mp3", "t": "稻米者完，"}, {"f": "audio/f5/school-sch-nj-122__6.mp3", "t": "稻薪者坚。"}, {"f": "audio/f5/school-sch-nj-122__7.mp3", "t": "帝曰："}, {"f": "audio/f5/school-sch-nj-122__8.mp3", "t": "何以然？"}, {"f": "audio/f5/school-sch-nj-122__9.mp3", "t": "岐伯曰："}, {"f": "audio/f5/school-sch-nj-122__10.mp3", "t": "此得天地之和，"}, {"f": "audio/f5/school-sch-nj-122__11.mp3", "t": "高下之宜，"}, {"f": "audio/f5/school-sch-nj-122__12.mp3", "t": "故能至完："}, {"f": "audio/f5/school-sch-nj-122__13.mp3", "t": "伐取得时，"}, {"f": "audio/f5/school-sch-nj-122__14.mp3", "t": "故能至坚也。"}], "school-sch-nj-123": [{"f": "audio/89/school-sch-nj-123__0.mp3", "t": "帝曰："}, {"f": "audio/89/school-sch-nj-123__1.mp3", "t": "上古圣人作汤液醪醴，"}, {"f": "audio/89/school-sch-nj-123__2.mp3", "t": "为而不用，"}, {"f": "audio/89/school-sch-nj-123__3.mp3", "t": "何也？"}, {"f": "audio/89/school-sch-nj-123__4.mp3", "t": "岐伯曰："}, {"f": "audio/89/school-sch-nj-123__5.mp3", "t": "自古圣人之作汤液醪醴者，"}, {"f": "audio/89/school-sch-nj-123__6.mp3", "t": "以为备耳。"}, {"f": "audio/89/school-sch-nj-123__7.mp3", "t": "夫上古作汤液，"}, {"f": "audio/89/school-sch-nj-123__8.mp3", "t": "故为而弗服也。"}, {"f": "audio/89/school-sch-nj-123__9.mp3", "t": "中古之世，"}, {"f": "audio/89/school-sch-nj-123__10.mp3", "t": "道德稍衰，"}, {"f": "audio/89/school-sch-nj-123__11.mp3", "t": "邪气时至，"}, {"f": "audio/89/school-sch-nj-123__12.mp3", "t": "服之万全。"}, {"f": "audio/89/school-sch-nj-123__13.mp3", "t": "帝曰："}, {"f": "audio/89/school-sch-nj-123__14.mp3", "t": "今之世，"}, {"f": "audio/89/school-sch-nj-123__15.mp3", "t": "不必已，"}, {"f": "audio/89/school-sch-nj-123__16.mp3", "t": "何也。"}, {"f": "audio/89/school-sch-nj-123__17.mp3", "t": "岐伯曰："}, {"f": "audio/89/school-sch-nj-123__18.mp3", "t": "当今之世，"}, {"f": "audio/89/school-sch-nj-123__19.mp3", "t": "必齐毒药攻其中，"}, {"f": "audio/89/school-sch-nj-123__20.mp3", "t": "镵石、"}, {"f": "audio/89/school-sch-nj-123__21.mp3", "t": "针艾治其外也。"}, {"f": "audio/89/school-sch-nj-123__22.mp3", "t": "帝曰："}, {"f": "audio/89/school-sch-nj-123__23.mp3", "t": "形弊血尽而功不立者何？"}, {"f": "audio/89/school-sch-nj-123__24.mp3", "t": "岐伯曰："}, {"f": "audio/89/school-sch-nj-123__25.mp3", "t": "神不使也。"}, {"f": "audio/89/school-sch-nj-123__26.mp3", "t": "帝曰："}, {"f": "audio/89/school-sch-nj-123__27.mp3", "t": "何谓神不使？"}, {"f": "audio/89/school-sch-nj-123__28.mp3", "t": "岐伯曰："}, {"f": "audio/89/school-sch-nj-123__29.mp3", "t": "针石，"}, {"f": "audio/89/school-sch-nj-123__30.mp3", "t": "道也。"}, {"f": "audio/89/school-sch-nj-123__31.mp3", "t": "精神不进，"}, {"f": "audio/89/school-sch-nj-123__32.mp3", "t": "志意不治，"}, {"f": "audio/89/school-sch-nj-123__33.mp3", "t": "故病不可愈。"}, {"f": "audio/89/school-sch-nj-123__34.mp3", "t": "今精坏神去，"}, {"f": "audio/89/school-sch-nj-123__35.mp3", "t": "荣卫不可复收，"}, {"f": "audio/89/school-sch-nj-123__36.mp3", "t": "何者？"}, {"f": "audio/89/school-sch-nj-123__37.mp3", "t": "嗜欲无穷，"}, {"f": "audio/89/school-sch-nj-123__38.mp3", "t": "而忧患不止，"}, {"f": "audio/89/school-sch-nj-123__39.mp3", "t": "精气弛坏，"}, {"f": "audio/89/school-sch-nj-123__40.mp3", "t": "荣泣卫除，"}, {"f": "audio/89/school-sch-nj-123__41.mp3", "t": "故神去之而病不愈也。"}, {"f": "audio/89/school-sch-nj-123__42.mp3", "t": "帝曰："}, {"f": "audio/89/school-sch-nj-123__43.mp3", "t": "夫病之始生也，"}, {"f": "audio/89/school-sch-nj-123__44.mp3", "t": "极微极精，"}, {"f": "audio/89/school-sch-nj-123__45.mp3", "t": "必先入结于皮肤，"}, {"f": "audio/89/school-sch-nj-123__46.mp3", "t": "今良工皆称曰病成，"}, {"f": "audio/89/school-sch-nj-123__47.mp3", "t": "名曰逆，"}, {"f": "audio/89/school-sch-nj-123__48.mp3", "t": "则针石不能治，"}, {"f": "audio/89/school-sch-nj-123__49.mp3", "t": "良药不能及也。"}, {"f": "audio/89/school-sch-nj-123__50.mp3", "t": "今良工皆得其法，"}, {"f": "audio/89/school-sch-nj-123__51.mp3", "t": "守其数，"}, {"f": "audio/89/school-sch-nj-123__52.mp3", "t": "亲戚兄弟远近，"}, {"f": "audio/89/school-sch-nj-123__53.mp3", "t": "音声日闻于耳，"}, {"f": "audio/89/school-sch-nj-123__54.mp3", "t": "五色日见于目，"}, {"f": "audio/89/school-sch-nj-123__55.mp3", "t": "而病不愈者，"}, {"f": "audio/89/school-sch-nj-123__56.mp3", "t": "亦何暇不早乎？"}, {"f": "audio/89/school-sch-nj-123__57.mp3", "t": "岐伯曰："}, {"f": "audio/89/school-sch-nj-123__58.mp3", "t": "病为本，"}, {"f": "audio/89/school-sch-nj-123__59.mp3", "t": "工为标，"}, {"f": "audio/89/school-sch-nj-123__60.mp3", "t": "标本不得，"}, {"f": "audio/89/school-sch-nj-123__61.mp3", "t": "邪气不服，"}, {"f": "audio/89/school-sch-nj-123__62.mp3", "t": "此之谓也。"}], "school-sch-nj-124": [{"f": "audio/fc/school-sch-nj-124__0.mp3", "t": "帝曰："}, {"f": "audio/fc/school-sch-nj-124__1.mp3", "t": "其有不从毫毛而生，"}, {"f": "audio/fc/school-sch-nj-124__2.mp3", "t": "五藏阳以竭也，"}, {"f": "audio/fc/school-sch-nj-124__3.mp3", "t": "津液充郭，"}, {"f": "audio/fc/school-sch-nj-124__4.mp3", "t": "其魄独居，"}, {"f": "audio/fc/school-sch-nj-124__5.mp3", "t": "孤精于内，"}, {"f": "audio/fc/school-sch-nj-124__6.mp3", "t": "气耗于外，"}, {"f": "audio/fc/school-sch-nj-124__7.mp3", "t": "形不可与衣相保，"}, {"f": "audio/fc/school-sch-nj-124__8.mp3", "t": "此四极急而动中，"}, {"f": "audio/fc/school-sch-nj-124__9.mp3", "t": "是气拒于内，"}, {"f": "audio/fc/school-sch-nj-124__10.mp3", "t": "而形施于外，"}, {"f": "audio/fc/school-sch-nj-124__11.mp3", "t": "治之奈何？"}, {"f": "audio/fc/school-sch-nj-124__12.mp3", "t": "岐伯曰："}, {"f": "audio/fc/school-sch-nj-124__13.mp3", "t": "平治于权衡，"}, {"f": "audio/fc/school-sch-nj-124__14.mp3", "t": "去宛陈莝，"}, {"f": "audio/fc/school-sch-nj-124__15.mp3", "t": "微动四极，"}, {"f": "audio/fc/school-sch-nj-124__16.mp3", "t": "温衣，"}, {"f": "audio/fc/school-sch-nj-124__17.mp3", "t": "缪刺其处，"}, {"f": "audio/fc/school-sch-nj-124__18.mp3", "t": "以复其形；"}, {"f": "audio/fc/school-sch-nj-124__19.mp3", "t": "开鬼门，"}, {"f": "audio/fc/school-sch-nj-124__20.mp3", "t": "洁净府，"}, {"f": "audio/fc/school-sch-nj-124__21.mp3", "t": "精以时服，"}, {"f": "audio/fc/school-sch-nj-124__22.mp3", "t": "五阳已布，"}, {"f": "audio/fc/school-sch-nj-124__23.mp3", "t": "疏涤五藏，"}, {"f": "audio/fc/school-sch-nj-124__24.mp3", "t": "故精自生，"}, {"f": "audio/fc/school-sch-nj-124__25.mp3", "t": "形自盛，"}, {"f": "audio/fc/school-sch-nj-124__26.mp3", "t": "骨肉相保，"}, {"f": "audio/fc/school-sch-nj-124__27.mp3", "t": "巨气乃平。"}, {"f": "audio/fc/school-sch-nj-124__28.mp3", "t": "帝曰："}, {"f": "audio/fc/school-sch-nj-124__29.mp3", "t": "善。"}], "school-sch-nj-125": [{"f": "audio/2a/school-sch-nj-125__0.mp3", "t": "黄帝问曰："}, {"f": "audio/2a/school-sch-nj-125__1.mp3", "t": "病有标本，"}, {"f": "audio/2a/school-sch-nj-125__2.mp3", "t": "刺有逆从，"}, {"f": "audio/2a/school-sch-nj-125__3.mp3", "t": "奈何？"}, {"f": "audio/2a/school-sch-nj-125__4.mp3", "t": "岐伯对曰："}, {"f": "audio/2a/school-sch-nj-125__5.mp3", "t": "凡刺之方，"}, {"f": "audio/2a/school-sch-nj-125__6.mp3", "t": "必别阴阳，"}, {"f": "audio/2a/school-sch-nj-125__7.mp3", "t": "前后相应，"}, {"f": "audio/2a/school-sch-nj-125__8.mp3", "t": "逆从得施，"}, {"f": "audio/2a/school-sch-nj-125__9.mp3", "t": "标本相移。"}, {"f": "audio/2a/school-sch-nj-125__10.mp3", "t": "故曰有其在标而求之于标，"}, {"f": "audio/2a/school-sch-nj-125__11.mp3", "t": "有其在本而求之于本，"}, {"f": "audio/2a/school-sch-nj-125__12.mp3", "t": "有其在本而求之于标，"}, {"f": "audio/2a/school-sch-nj-125__13.mp3", "t": "有其在标而求之于本。"}, {"f": "audio/2a/school-sch-nj-125__14.mp3", "t": "故治有取标而得者，"}, {"f": "audio/2a/school-sch-nj-125__15.mp3", "t": "有取本而得者，"}, {"f": "audio/2a/school-sch-nj-125__16.mp3", "t": "有逆取而得者，"}, {"f": "audio/2a/school-sch-nj-125__17.mp3", "t": "有从取而得者。"}, {"f": "audio/2a/school-sch-nj-125__18.mp3", "t": "故知逆与从，"}, {"f": "audio/2a/school-sch-nj-125__19.mp3", "t": "正行无问，"}, {"f": "audio/2a/school-sch-nj-125__20.mp3", "t": "知标本者，"}, {"f": "audio/2a/school-sch-nj-125__21.mp3", "t": "万举万当，"}, {"f": "audio/2a/school-sch-nj-125__22.mp3", "t": "不知标本，"}, {"f": "audio/2a/school-sch-nj-125__23.mp3", "t": "是谓妄行。"}], "school-sch-nj-126": [{"f": "audio/1b/school-sch-nj-126__0.mp3", "t": "夫阴阳、"}, {"f": "audio/1b/school-sch-nj-126__1.mp3", "t": "逆从、"}, {"f": "audio/1b/school-sch-nj-126__2.mp3", "t": "标本之为道也，"}, {"f": "audio/1b/school-sch-nj-126__3.mp3", "t": "小而大，"}, {"f": "audio/1b/school-sch-nj-126__4.mp3", "t": "言一而知百病之害。"}, {"f": "audio/1b/school-sch-nj-126__5.mp3", "t": "少而多，"}, {"f": "audio/1b/school-sch-nj-126__6.mp3", "t": "浅而博，"}, {"f": "audio/1b/school-sch-nj-126__7.mp3", "t": "可以言一而知百也。"}, {"f": "audio/1b/school-sch-nj-126__8.mp3", "t": "以浅而知深，"}, {"f": "audio/1b/school-sch-nj-126__9.mp3", "t": "察近而知远。"}, {"f": "audio/1b/school-sch-nj-126__10.mp3", "t": "言标与本，"}, {"f": "audio/1b/school-sch-nj-126__11.mp3", "t": "易而勿及。"}], "school-sch-nj-127": [{"f": "audio/10/school-sch-nj-127__0.mp3", "t": "治反为逆，"}, {"f": "audio/10/school-sch-nj-127__1.mp3", "t": "治得为从。"}, {"f": "audio/10/school-sch-nj-127__2.mp3", "t": "先病而后逆者治其本，"}, {"f": "audio/10/school-sch-nj-127__3.mp3", "t": "先逆而后病者治其本；"}, {"f": "audio/10/school-sch-nj-127__4.mp3", "t": "先寒而后生病者治其本，"}, {"f": "audio/10/school-sch-nj-127__5.mp3", "t": "先病而后生寒者治其本；"}, {"f": "audio/10/school-sch-nj-127__6.mp3", "t": "先热而后生病者治其本，"}, {"f": "audio/10/school-sch-nj-127__7.mp3", "t": "先热而后生中满者治其标；"}, {"f": "audio/10/school-sch-nj-127__8.mp3", "t": "先病而后泄者治其本，"}, {"f": "audio/10/school-sch-nj-127__9.mp3", "t": "先泄而后生他病者治其本，"}, {"f": "audio/10/school-sch-nj-127__10.mp3", "t": "必且调之，"}, {"f": "audio/10/school-sch-nj-127__11.mp3", "t": "乃治其他病。"}, {"f": "audio/10/school-sch-nj-127__12.mp3", "t": "先病而后生中满者治其标，"}, {"f": "audio/10/school-sch-nj-127__13.mp3", "t": "先中满而后烦心者治其本。"}, {"f": "audio/10/school-sch-nj-127__14.mp3", "t": "人有客气有同气。"}, {"f": "audio/10/school-sch-nj-127__15.mp3", "t": "小大不利治其标，"}, {"f": "audio/10/school-sch-nj-127__16.mp3", "t": "小大利治其本。"}, {"f": "audio/10/school-sch-nj-127__17.mp3", "t": "病发而有余，"}, {"f": "audio/10/school-sch-nj-127__18.mp3", "t": "本而标之，"}, {"f": "audio/10/school-sch-nj-127__19.mp3", "t": "先治其本，"}, {"f": "audio/10/school-sch-nj-127__20.mp3", "t": "后治其标；"}, {"f": "audio/10/school-sch-nj-127__21.mp3", "t": "病发而不足，"}, {"f": "audio/10/school-sch-nj-127__22.mp3", "t": "标而本之，"}, {"f": "audio/10/school-sch-nj-127__23.mp3", "t": "先治其标，"}, {"f": "audio/10/school-sch-nj-127__24.mp3", "t": "后治其本。"}, {"f": "audio/10/school-sch-nj-127__25.mp3", "t": "谨察间甚，"}, {"f": "audio/10/school-sch-nj-127__26.mp3", "t": "以意调之，"}, {"f": "audio/10/school-sch-nj-127__27.mp3", "t": "间者并行，"}, {"f": "audio/10/school-sch-nj-127__28.mp3", "t": "甚者独行，"}, {"f": "audio/10/school-sch-nj-127__29.mp3", "t": "先小大不利而后生病者治其本。"}], "school-sch-nj-128": [{"f": "audio/a2/school-sch-nj-128__0.mp3", "t": "岐伯对曰："}, {"f": "audio/a2/school-sch-nj-128__1.mp3", "t": "上古之人，"}, {"f": "audio/a2/school-sch-nj-128__2.mp3", "t": "其知道者，"}, {"f": "audio/a2/school-sch-nj-128__3.mp3", "t": "法于阴阳，"}, {"f": "audio/a2/school-sch-nj-128__4.mp3", "t": "和于术数，"}, {"f": "audio/a2/school-sch-nj-128__5.mp3", "t": "食饮有节，"}, {"f": "audio/a2/school-sch-nj-128__6.mp3", "t": "起居有常，"}, {"f": "audio/a2/school-sch-nj-128__7.mp3", "t": "不妄作劳，"}, {"f": "audio/a2/school-sch-nj-128__8.mp3", "t": "故能形与神俱，"}, {"f": "audio/a2/school-sch-nj-128__9.mp3", "t": "而尽终其天年，"}, {"f": "audio/a2/school-sch-nj-128__10.mp3", "t": "度百岁乃去。"}, {"f": "audio/a2/school-sch-nj-128__11.mp3", "t": "今时之人不然也，"}, {"f": "audio/a2/school-sch-nj-128__12.mp3", "t": "以酒为浆，"}, {"f": "audio/a2/school-sch-nj-128__13.mp3", "t": "以妄为常，"}, {"f": "audio/a2/school-sch-nj-128__14.mp3", "t": "醉以入房，"}, {"f": "audio/a2/school-sch-nj-128__15.mp3", "t": "以欲竭其精，"}, {"f": "audio/a2/school-sch-nj-128__16.mp3", "t": "以耗散其真，"}, {"f": "audio/a2/school-sch-nj-128__17.mp3", "t": "不知持满，"}, {"f": "audio/a2/school-sch-nj-128__18.mp3", "t": "不时御神，"}, {"f": "audio/a2/school-sch-nj-128__19.mp3", "t": "务快其心，"}, {"f": "audio/a2/school-sch-nj-128__20.mp3", "t": "逆于生乐，"}, {"f": "audio/a2/school-sch-nj-128__21.mp3", "t": "起居无节，"}, {"f": "audio/a2/school-sch-nj-128__22.mp3", "t": "故半百而衰也。"}], "school-sch-nj-129": [{"f": "audio/ca/school-sch-nj-129__0.mp3", "t": "夫上古圣人之教下也，"}, {"f": "audio/ca/school-sch-nj-129__1.mp3", "t": "皆谓之虚邪贼风，"}, {"f": "audio/ca/school-sch-nj-129__2.mp3", "t": "避之有时，"}, {"f": "audio/ca/school-sch-nj-129__3.mp3", "t": "恬惔虚无，"}, {"f": "audio/ca/school-sch-nj-129__4.mp3", "t": "真气从之，"}, {"f": "audio/ca/school-sch-nj-129__5.mp3", "t": "精神内守，"}, {"f": "audio/ca/school-sch-nj-129__6.mp3", "t": "病安从来。"}, {"f": "audio/ca/school-sch-nj-129__7.mp3", "t": "是以志闲而少欲，"}, {"f": "audio/ca/school-sch-nj-129__8.mp3", "t": "心安而不惧，"}, {"f": "audio/ca/school-sch-nj-129__9.mp3", "t": "形劳而不倦，"}, {"f": "audio/ca/school-sch-nj-129__10.mp3", "t": "气从以顺，"}, {"f": "audio/ca/school-sch-nj-129__11.mp3", "t": "各从其欲，"}, {"f": "audio/ca/school-sch-nj-129__12.mp3", "t": "皆得所愿。"}, {"f": "audio/ca/school-sch-nj-129__13.mp3", "t": "故美其食，"}, {"f": "audio/ca/school-sch-nj-129__14.mp3", "t": "任其服，"}, {"f": "audio/ca/school-sch-nj-129__15.mp3", "t": "乐其俗，"}, {"f": "audio/ca/school-sch-nj-129__16.mp3", "t": "高下不相慕，"}, {"f": "audio/ca/school-sch-nj-129__17.mp3", "t": "其民故曰朴。"}, {"f": "audio/ca/school-sch-nj-129__18.mp3", "t": "是以嗜欲不能劳其目，"}, {"f": "audio/ca/school-sch-nj-129__19.mp3", "t": "淫邪不能惑其心，"}, {"f": "audio/ca/school-sch-nj-129__20.mp3", "t": "愚智贤不肖，"}, {"f": "audio/ca/school-sch-nj-129__21.mp3", "t": "不惧于物，"}, {"f": "audio/ca/school-sch-nj-129__22.mp3", "t": "故合于道。"}, {"f": "audio/ca/school-sch-nj-129__23.mp3", "t": "所以能年皆度百岁，"}, {"f": "audio/ca/school-sch-nj-129__24.mp3", "t": "而动作不衰者，"}, {"f": "audio/ca/school-sch-nj-129__25.mp3", "t": "以其德全不危也。"}], "school-sch-nj-130": [{"f": "audio/2c/school-sch-nj-130__0.mp3", "t": "岐伯曰："}, {"f": "audio/2c/school-sch-nj-130__1.mp3", "t": "女子七岁，"}, {"f": "audio/2c/school-sch-nj-130__2.mp3", "t": "肾气盛，"}, {"f": "audio/2c/school-sch-nj-130__3.mp3", "t": "齿更发长；"}, {"f": "audio/2c/school-sch-nj-130__4.mp3", "t": "二七而天癸至，"}, {"f": "audio/2c/school-sch-nj-130__5.mp3", "t": "任脉通，"}, {"f": "audio/2c/school-sch-nj-130__6.mp3", "t": "太冲脉盛，"}, {"f": "audio/2c/school-sch-nj-130__7.mp3", "t": "月事以时下，"}, {"f": "audio/2c/school-sch-nj-130__8.mp3", "t": "故有子；"}, {"f": "audio/2c/school-sch-nj-130__9.mp3", "t": "三七，"}, {"f": "audio/2c/school-sch-nj-130__10.mp3", "t": "肾气平均，"}, {"f": "audio/2c/school-sch-nj-130__11.mp3", "t": "故真牙生而长极；"}, {"f": "audio/2c/school-sch-nj-130__12.mp3", "t": "四七，"}, {"f": "audio/2c/school-sch-nj-130__13.mp3", "t": "筋骨坚，"}, {"f": "audio/2c/school-sch-nj-130__14.mp3", "t": "发长极，"}, {"f": "audio/2c/school-sch-nj-130__15.mp3", "t": "身体盛壮；"}, {"f": "audio/2c/school-sch-nj-130__16.mp3", "t": "五七，"}, {"f": "audio/2c/school-sch-nj-130__17.mp3", "t": "阳明脉衰，"}, {"f": "audio/2c/school-sch-nj-130__18.mp3", "t": "面始焦，"}, {"f": "audio/2c/school-sch-nj-130__19.mp3", "t": "发始堕；"}, {"f": "audio/2c/school-sch-nj-130__20.mp3", "t": "六七，"}, {"f": "audio/2c/school-sch-nj-130__21.mp3", "t": "三阳脉衰于上，"}, {"f": "audio/2c/school-sch-nj-130__22.mp3", "t": "面皆焦，"}, {"f": "audio/2c/school-sch-nj-130__23.mp3", "t": "发始白；"}, {"f": "audio/2c/school-sch-nj-130__24.mp3", "t": "七七，"}, {"f": "audio/2c/school-sch-nj-130__25.mp3", "t": "任脉虚，"}, {"f": "audio/2c/school-sch-nj-130__26.mp3", "t": "太冲脉衰少，"}, {"f": "audio/2c/school-sch-nj-130__27.mp3", "t": "天癸竭，"}, {"f": "audio/2c/school-sch-nj-130__28.mp3", "t": "地道不通，"}, {"f": "audio/2c/school-sch-nj-130__29.mp3", "t": "故形坏而无子也。"}, {"f": "audio/2c/school-sch-nj-130__30.mp3", "t": "丈夫八岁，"}, {"f": "audio/2c/school-sch-nj-130__31.mp3", "t": "肾气实，"}, {"f": "audio/2c/school-sch-nj-130__32.mp3", "t": "发长齿更；"}, {"f": "audio/2c/school-sch-nj-130__33.mp3", "t": "二八，"}, {"f": "audio/2c/school-sch-nj-130__34.mp3", "t": "肾气盛，"}, {"f": "audio/2c/school-sch-nj-130__35.mp3", "t": "天癸至，"}, {"f": "audio/2c/school-sch-nj-130__36.mp3", "t": "精气溢泻，"}, {"f": "audio/2c/school-sch-nj-130__37.mp3", "t": "阴阳和，"}, {"f": "audio/2c/school-sch-nj-130__38.mp3", "t": "故能有子；"}, {"f": "audio/2c/school-sch-nj-130__39.mp3", "t": "三八，"}, {"f": "audio/2c/school-sch-nj-130__40.mp3", "t": "肾气平均，"}, {"f": "audio/2c/school-sch-nj-130__41.mp3", "t": "筋骨劲强，"}, {"f": "audio/2c/school-sch-nj-130__42.mp3", "t": "故真牙生而长极；"}, {"f": "audio/2c/school-sch-nj-130__43.mp3", "t": "四八，"}, {"f": "audio/2c/school-sch-nj-130__44.mp3", "t": "筋骨隆盛，"}, {"f": "audio/2c/school-sch-nj-130__45.mp3", "t": "肌肉满壮；"}, {"f": "audio/2c/school-sch-nj-130__46.mp3", "t": "五八，"}, {"f": "audio/2c/school-sch-nj-130__47.mp3", "t": "肾气衰，"}, {"f": "audio/2c/school-sch-nj-130__48.mp3", "t": "发堕齿槁；"}, {"f": "audio/2c/school-sch-nj-130__49.mp3", "t": "六八，"}, {"f": "audio/2c/school-sch-nj-130__50.mp3", "t": "阳气衰竭于上，"}, {"f": "audio/2c/school-sch-nj-130__51.mp3", "t": "面焦，"}, {"f": "audio/2c/school-sch-nj-130__52.mp3", "t": "发鬓颁白；"}, {"f": "audio/2c/school-sch-nj-130__53.mp3", "t": "七八，"}, {"f": "audio/2c/school-sch-nj-130__54.mp3", "t": "肝气衰，"}, {"f": "audio/2c/school-sch-nj-130__55.mp3", "t": "筋不能动。"}, {"f": "audio/2c/school-sch-nj-130__56.mp3", "t": "八八，"}, {"f": "audio/2c/school-sch-nj-130__57.mp3", "t": "天癸竭，"}, {"f": "audio/2c/school-sch-nj-130__58.mp3", "t": "精少，"}, {"f": "audio/2c/school-sch-nj-130__59.mp3", "t": "肾藏衰，"}, {"f": "audio/2c/school-sch-nj-130__60.mp3", "t": "形体皆极，"}, {"f": "audio/2c/school-sch-nj-130__61.mp3", "t": "则齿发去。"}, {"f": "audio/2c/school-sch-nj-130__62.mp3", "t": "肾者主水，"}, {"f": "audio/2c/school-sch-nj-130__63.mp3", "t": "受五藏六府之精而藏之，"}, {"f": "audio/2c/school-sch-nj-130__64.mp3", "t": "故五藏盛乃能泻。"}, {"f": "audio/2c/school-sch-nj-130__65.mp3", "t": "今五藏皆衰，"}, {"f": "audio/2c/school-sch-nj-130__66.mp3", "t": "筋骨解堕，"}, {"f": "audio/2c/school-sch-nj-130__67.mp3", "t": "天癸尽矣，"}, {"f": "audio/2c/school-sch-nj-130__68.mp3", "t": "故发鬓白，"}, {"f": "audio/2c/school-sch-nj-130__69.mp3", "t": "身体重，"}, {"f": "audio/2c/school-sch-nj-130__70.mp3", "t": "行步不正，"}, {"f": "audio/2c/school-sch-nj-130__71.mp3", "t": "而无子耳。"}], "school-sch-nj-131": [{"f": "audio/5c/school-sch-nj-131__0.mp3", "t": "黄帝曰："}, {"f": "audio/5c/school-sch-nj-131__1.mp3", "t": "余闻上古有真人者，"}, {"f": "audio/5c/school-sch-nj-131__2.mp3", "t": "提挈天地，"}, {"f": "audio/5c/school-sch-nj-131__3.mp3", "t": "把握阴阳，"}, {"f": "audio/5c/school-sch-nj-131__4.mp3", "t": "呼吸精气，"}, {"f": "audio/5c/school-sch-nj-131__5.mp3", "t": "独立守神，"}, {"f": "audio/5c/school-sch-nj-131__6.mp3", "t": "肌肉若一，"}, {"f": "audio/5c/school-sch-nj-131__7.mp3", "t": "故能寿敝天地，"}, {"f": "audio/5c/school-sch-nj-131__8.mp3", "t": "无有终时，"}, {"f": "audio/5c/school-sch-nj-131__9.mp3", "t": "此其道生。"}, {"f": "audio/5c/school-sch-nj-131__10.mp3", "t": "中古之时，"}, {"f": "audio/5c/school-sch-nj-131__11.mp3", "t": "有至人者，"}, {"f": "audio/5c/school-sch-nj-131__12.mp3", "t": "淳德全道，"}, {"f": "audio/5c/school-sch-nj-131__13.mp3", "t": "和于阴阳，"}, {"f": "audio/5c/school-sch-nj-131__14.mp3", "t": "调于四时，"}, {"f": "audio/5c/school-sch-nj-131__15.mp3", "t": "去世离俗，"}, {"f": "audio/5c/school-sch-nj-131__16.mp3", "t": "积精全神，"}, {"f": "audio/5c/school-sch-nj-131__17.mp3", "t": "游行天地之间，"}, {"f": "audio/5c/school-sch-nj-131__18.mp3", "t": "视听八达之外，"}, {"f": "audio/5c/school-sch-nj-131__19.mp3", "t": "此盖益其寿命而强者也，"}, {"f": "audio/5c/school-sch-nj-131__20.mp3", "t": "亦归于真人。"}, {"f": "audio/5c/school-sch-nj-131__21.mp3", "t": "其次，"}, {"f": "audio/5c/school-sch-nj-131__22.mp3", "t": "有圣人者，"}, {"f": "audio/5c/school-sch-nj-131__23.mp3", "t": "处天地之和，"}, {"f": "audio/5c/school-sch-nj-131__24.mp3", "t": "从八风之理，"}, {"f": "audio/5c/school-sch-nj-131__25.mp3", "t": "适嗜欲于世俗之间，"}, {"f": "audio/5c/school-sch-nj-131__26.mp3", "t": "无恚嗔之心，"}, {"f": "audio/5c/school-sch-nj-131__27.mp3", "t": "行不欲离于世，"}, {"f": "audio/5c/school-sch-nj-131__28.mp3", "t": "举不欲观于俗，"}, {"f": "audio/5c/school-sch-nj-131__29.mp3", "t": "外不劳形于事，"}, {"f": "audio/5c/school-sch-nj-131__30.mp3", "t": "内无思想之患，"}, {"f": "audio/5c/school-sch-nj-131__31.mp3", "t": "以恬愉为务，"}, {"f": "audio/5c/school-sch-nj-131__32.mp3", "t": "以自得为功，"}, {"f": "audio/5c/school-sch-nj-131__33.mp3", "t": "形体不敝，"}, {"f": "audio/5c/school-sch-nj-131__34.mp3", "t": "精神不散，"}, {"f": "audio/5c/school-sch-nj-131__35.mp3", "t": "亦可以百数。"}, {"f": "audio/5c/school-sch-nj-131__36.mp3", "t": "其次，"}, {"f": "audio/5c/school-sch-nj-131__37.mp3", "t": "有贤人者，"}, {"f": "audio/5c/school-sch-nj-131__38.mp3", "t": "法则天地，"}, {"f": "audio/5c/school-sch-nj-131__39.mp3", "t": "象似日月，"}, {"f": "audio/5c/school-sch-nj-131__40.mp3", "t": "辨列星辰，"}, {"f": "audio/5c/school-sch-nj-131__41.mp3", "t": "逆从阴阳，"}, {"f": "audio/5c/school-sch-nj-131__42.mp3", "t": "分别四时，"}, {"f": "audio/5c/school-sch-nj-131__43.mp3", "t": "将从上古，"}, {"f": "audio/5c/school-sch-nj-131__44.mp3", "t": "合同于道，"}, {"f": "audio/5c/school-sch-nj-131__45.mp3", "t": "亦可使益寿而有极时。"}], "school-sch-nj-132": [{"f": "audio/3d/school-sch-nj-132__0.mp3", "t": "春三月，"}, {"f": "audio/3d/school-sch-nj-132__1.mp3", "t": "此谓发陈。"}, {"f": "audio/3d/school-sch-nj-132__2.mp3", "t": "天地俱生，"}, {"f": "audio/3d/school-sch-nj-132__3.mp3", "t": "万物以荣，"}, {"f": "audio/3d/school-sch-nj-132__4.mp3", "t": "夜卧早起，"}, {"f": "audio/3d/school-sch-nj-132__5.mp3", "t": "广步于庭，"}, {"f": "audio/3d/school-sch-nj-132__6.mp3", "t": "被发缓形，"}, {"f": "audio/3d/school-sch-nj-132__7.mp3", "t": "以使志生，"}, {"f": "audio/3d/school-sch-nj-132__8.mp3", "t": "生而勿杀，"}, {"f": "audio/3d/school-sch-nj-132__9.mp3", "t": "予而勿夺，"}, {"f": "audio/3d/school-sch-nj-132__10.mp3", "t": "赏而勿罚，"}, {"f": "audio/3d/school-sch-nj-132__11.mp3", "t": "此春气之应，"}, {"f": "audio/3d/school-sch-nj-132__12.mp3", "t": "养生之道也。"}, {"f": "audio/3d/school-sch-nj-132__13.mp3", "t": "逆之则伤肝，"}, {"f": "audio/3d/school-sch-nj-132__14.mp3", "t": "夏为寒变，"}, {"f": "audio/3d/school-sch-nj-132__15.mp3", "t": "奉长者少。"}, {"f": "audio/3d/school-sch-nj-132__16.mp3", "t": "夏三月，"}, {"f": "audio/3d/school-sch-nj-132__17.mp3", "t": "此为蕃秀。"}, {"f": "audio/3d/school-sch-nj-132__18.mp3", "t": "天地气交，"}, {"f": "audio/3d/school-sch-nj-132__19.mp3", "t": "万物华实，"}, {"f": "audio/3d/school-sch-nj-132__20.mp3", "t": "夜卧早起，"}, {"f": "audio/3d/school-sch-nj-132__21.mp3", "t": "无厌于日，"}, {"f": "audio/3d/school-sch-nj-132__22.mp3", "t": "使志无怒，"}, {"f": "audio/3d/school-sch-nj-132__23.mp3", "t": "使华英成秀，"}, {"f": "audio/3d/school-sch-nj-132__24.mp3", "t": "使气得泄，"}, {"f": "audio/3d/school-sch-nj-132__25.mp3", "t": "若所爱在外，"}, {"f": "audio/3d/school-sch-nj-132__26.mp3", "t": "此夏气之应，"}, {"f": "audio/3d/school-sch-nj-132__27.mp3", "t": "养长之道也。"}, {"f": "audio/3d/school-sch-nj-132__28.mp3", "t": "逆之则伤心，"}, {"f": "audio/3d/school-sch-nj-132__29.mp3", "t": "秋为痎疟，"}, {"f": "audio/3d/school-sch-nj-132__30.mp3", "t": "奉收者少，"}, {"f": "audio/3d/school-sch-nj-132__31.mp3", "t": "冬至重病。"}, {"f": "audio/3d/school-sch-nj-132__32.mp3", "t": "秋三月，"}, {"f": "audio/3d/school-sch-nj-132__33.mp3", "t": "此谓容平。"}, {"f": "audio/3d/school-sch-nj-132__34.mp3", "t": "天气以急，"}, {"f": "audio/3d/school-sch-nj-132__35.mp3", "t": "地气以明，"}, {"f": "audio/3d/school-sch-nj-132__36.mp3", "t": "早卧早起，"}, {"f": "audio/3d/school-sch-nj-132__37.mp3", "t": "与鸡俱兴，"}, {"f": "audio/3d/school-sch-nj-132__38.mp3", "t": "使志安宁，"}, {"f": "audio/3d/school-sch-nj-132__39.mp3", "t": "以缓秋刑，"}, {"f": "audio/3d/school-sch-nj-132__40.mp3", "t": "收敛神气，"}, {"f": "audio/3d/school-sch-nj-132__41.mp3", "t": "使秋气平，"}, {"f": "audio/3d/school-sch-nj-132__42.mp3", "t": "无外其志，"}, {"f": "audio/3d/school-sch-nj-132__43.mp3", "t": "使肺气清。"}, {"f": "audio/3d/school-sch-nj-132__44.mp3", "t": "此秋气之应，"}, {"f": "audio/3d/school-sch-nj-132__45.mp3", "t": "养收之道也。"}, {"f": "audio/3d/school-sch-nj-132__46.mp3", "t": "逆之则伤肺，"}, {"f": "audio/3d/school-sch-nj-132__47.mp3", "t": "冬为飧泄，"}, {"f": "audio/3d/school-sch-nj-132__48.mp3", "t": "奉藏者少。"}, {"f": "audio/3d/school-sch-nj-132__49.mp3", "t": "冬三月，"}, {"f": "audio/3d/school-sch-nj-132__50.mp3", "t": "此谓闭藏。"}, {"f": "audio/3d/school-sch-nj-132__51.mp3", "t": "水冰地坼，"}, {"f": "audio/3d/school-sch-nj-132__52.mp3", "t": "无扰乎阳，"}, {"f": "audio/3d/school-sch-nj-132__53.mp3", "t": "早卧晚起，"}, {"f": "audio/3d/school-sch-nj-132__54.mp3", "t": "必待日光，"}, {"f": "audio/3d/school-sch-nj-132__55.mp3", "t": "使志若伏若匿，"}, {"f": "audio/3d/school-sch-nj-132__56.mp3", "t": "若有私意，"}, {"f": "audio/3d/school-sch-nj-132__57.mp3", "t": "若已有得，"}, {"f": "audio/3d/school-sch-nj-132__58.mp3", "t": "去寒就温，"}, {"f": "audio/3d/school-sch-nj-132__59.mp3", "t": "无泄皮肤，"}, {"f": "audio/3d/school-sch-nj-132__60.mp3", "t": "使气亟夺。"}, {"f": "audio/3d/school-sch-nj-132__61.mp3", "t": "此冬气之应，"}, {"f": "audio/3d/school-sch-nj-132__62.mp3", "t": "养藏之道也。"}, {"f": "audio/3d/school-sch-nj-132__63.mp3", "t": "逆之则伤肾，"}, {"f": "audio/3d/school-sch-nj-132__64.mp3", "t": "春为痿厥，"}, {"f": "audio/3d/school-sch-nj-132__65.mp3", "t": "奉生者少。"}], "school-sch-nj-133": [{"f": "audio/d0/school-sch-nj-133__0.mp3", "t": "天气清净光明者也，"}, {"f": "audio/d0/school-sch-nj-133__1.mp3", "t": "藏德不止，"}, {"f": "audio/d0/school-sch-nj-133__2.mp3", "t": "故不下也。"}, {"f": "audio/d0/school-sch-nj-133__3.mp3", "t": "天明则日月不明。"}, {"f": "audio/d0/school-sch-nj-133__4.mp3", "t": "邪害空窍。"}, {"f": "audio/d0/school-sch-nj-133__5.mp3", "t": "阳气者闭塞，"}, {"f": "audio/d0/school-sch-nj-133__6.mp3", "t": "地气者冒明，"}, {"f": "audio/d0/school-sch-nj-133__7.mp3", "t": "云雾不精，"}, {"f": "audio/d0/school-sch-nj-133__8.mp3", "t": "则上应白露不下。"}, {"f": "audio/d0/school-sch-nj-133__9.mp3", "t": "交通不表，"}, {"f": "audio/d0/school-sch-nj-133__10.mp3", "t": "万物命故不施，"}, {"f": "audio/d0/school-sch-nj-133__11.mp3", "t": "不施则名木多死；"}, {"f": "audio/d0/school-sch-nj-133__12.mp3", "t": "恶气不发，"}, {"f": "audio/d0/school-sch-nj-133__13.mp3", "t": "风雨不节，"}, {"f": "audio/d0/school-sch-nj-133__14.mp3", "t": "白露不下，"}, {"f": "audio/d0/school-sch-nj-133__15.mp3", "t": "则菀稿不荣。"}, {"f": "audio/d0/school-sch-nj-133__16.mp3", "t": "贼风数至，"}, {"f": "audio/d0/school-sch-nj-133__17.mp3", "t": "暴雨数起，"}, {"f": "audio/d0/school-sch-nj-133__18.mp3", "t": "天地四时不相保，"}, {"f": "audio/d0/school-sch-nj-133__19.mp3", "t": "与道相失，"}, {"f": "audio/d0/school-sch-nj-133__20.mp3", "t": "则未央绝灭。"}, {"f": "audio/d0/school-sch-nj-133__21.mp3", "t": "唯圣人从之，"}, {"f": "audio/d0/school-sch-nj-133__22.mp3", "t": "故身无奇病，"}, {"f": "audio/d0/school-sch-nj-133__23.mp3", "t": "万物不失，"}, {"f": "audio/d0/school-sch-nj-133__24.mp3", "t": "生气不竭。"}], "school-sch-nj-134": [{"f": "audio/22/school-sch-nj-134__0.mp3", "t": "逆春气则少阳不生，"}, {"f": "audio/22/school-sch-nj-134__1.mp3", "t": "肝气内变；"}, {"f": "audio/22/school-sch-nj-134__2.mp3", "t": "逆夏气则太阳不长，"}, {"f": "audio/22/school-sch-nj-134__3.mp3", "t": "心气内洞；"}, {"f": "audio/22/school-sch-nj-134__4.mp3", "t": "逆秋气则太阴不收，"}, {"f": "audio/22/school-sch-nj-134__5.mp3", "t": "肺气焦满；"}, {"f": "audio/22/school-sch-nj-134__6.mp3", "t": "逆冬气则少阴不藏，"}, {"f": "audio/22/school-sch-nj-134__7.mp3", "t": "肾气独沉。"}], "school-sch-nj-135": [{"f": "audio/59/school-sch-nj-135__0.mp3", "t": "夫四时阴阳者，"}, {"f": "audio/59/school-sch-nj-135__1.mp3", "t": "万物之根本也。"}, {"f": "audio/59/school-sch-nj-135__2.mp3", "t": "所以圣人春夏养阳，"}, {"f": "audio/59/school-sch-nj-135__3.mp3", "t": "秋冬养阴，"}, {"f": "audio/59/school-sch-nj-135__4.mp3", "t": "以从其根；"}, {"f": "audio/59/school-sch-nj-135__5.mp3", "t": "故与万物沉浮于生长之门。"}, {"f": "audio/59/school-sch-nj-135__6.mp3", "t": "逆其根则伐其本，"}, {"f": "audio/59/school-sch-nj-135__7.mp3", "t": "坏其真矣。"}, {"f": "audio/59/school-sch-nj-135__8.mp3", "t": "故阴阳四时者，"}, {"f": "audio/59/school-sch-nj-135__9.mp3", "t": "万物之终始也，"}, {"f": "audio/59/school-sch-nj-135__10.mp3", "t": "死生之本也。"}, {"f": "audio/59/school-sch-nj-135__11.mp3", "t": "逆之则灾害生，"}, {"f": "audio/59/school-sch-nj-135__12.mp3", "t": "从之则苛疾不起，"}, {"f": "audio/59/school-sch-nj-135__13.mp3", "t": "是谓得道。"}, {"f": "audio/59/school-sch-nj-135__14.mp3", "t": "道者，"}, {"f": "audio/59/school-sch-nj-135__15.mp3", "t": "圣人行之，"}, {"f": "audio/59/school-sch-nj-135__16.mp3", "t": "愚者佩之。"}, {"f": "audio/59/school-sch-nj-135__17.mp3", "t": "从阴阳则生，"}, {"f": "audio/59/school-sch-nj-135__18.mp3", "t": "逆之则死，"}, {"f": "audio/59/school-sch-nj-135__19.mp3", "t": "从之则治，"}, {"f": "audio/59/school-sch-nj-135__20.mp3", "t": "逆之则乱。"}, {"f": "audio/59/school-sch-nj-135__21.mp3", "t": "反顺为逆，"}, {"f": "audio/59/school-sch-nj-135__22.mp3", "t": "是谓内格。"}], "school-sch-nj-136": [{"f": "audio/85/school-sch-nj-136__0.mp3", "t": "是故圣人不治已病治未病，"}, {"f": "audio/85/school-sch-nj-136__1.mp3", "t": "不治已乱治未乱，"}, {"f": "audio/85/school-sch-nj-136__2.mp3", "t": "此之谓也。"}, {"f": "audio/85/school-sch-nj-136__3.mp3", "t": "夫病已成而后药之，"}, {"f": "audio/85/school-sch-nj-136__4.mp3", "t": "乱已成而后治之，"}, {"f": "audio/85/school-sch-nj-136__5.mp3", "t": "譬犹渴而穿井，"}, {"f": "audio/85/school-sch-nj-136__6.mp3", "t": "斗而铸锥，"}, {"f": "audio/85/school-sch-nj-136__7.mp3", "t": "不亦晚乎？"}]};
